-- Seed the recipes catalogue.
-- Generated from the recipe cards already rendered across the app, so every card
-- image on /recipes matches the hero image on its detail page.
-- Re-runnable: ON CONFLICT (slug) refreshes the row in place.

INSERT INTO public.recipes (slug, title, description, image, image_alt, creator_name, creator_handle, creator_image, creator_alt, prep_time, cook_time, total_time, prep_minutes, cook_minutes, total_minutes, servings, difficulty, cuisine, meal_type, category, tags, rating, reviews, cooks, calories, protein, carbs, fat, fiber, ingredients, steps, notes, tips, allergens) VALUES
('smash-burger-tacos', 'Smash Burger Tacos', 'Everything you love about a smash burger, pressed straight into a flour tortilla so the crust forms on the taco itself. Twenty minutes, one skillet, absurdly good.', 'https://img.rocket.new/generatedImages/rocket_gen_img_1acf3cb0a-1772799442431.png', 'Smash burger patty folded in a crispy taco shell with cheese and toppings', 'Jake Torres', '@jaketorrescooks', 'https://images.unsplash.com/photo-1572015837827-01671d41e102', 'Portrait of food creator Jake Torres', '8 min', '12 min', '20 min', 8, 12, 20, 4, 'Easy', 'American', 'Dinner', 'Main Course', ARRAY['Beef','Street Food','Quick','Crowd Pleaser']::TEXT[], 4.5, 1287, 923, 612, 31, 38, 37, 3, '[{"amount":"1","unit":"lb","item":"ground beef (80/20)"},{"amount":"8","unit":"","item":"small flour tortillas"},{"amount":"8","unit":"slices","item":"American cheese"},{"amount":"1","unit":"small","item":"white onion, finely diced"},{"amount":"2","unit":"tbsp","item":"yellow mustard"},{"amount":"4","unit":"tbsp","item":"burger sauce (mayo, ketchup, pickle relish)"},{"amount":"1","unit":"cup","item":"shredded iceberg lettuce"},{"amount":"16","unit":"slices","item":"dill pickle"},{"amount":"1","unit":"tbsp","item":"neutral oil"},{"amount":"","unit":"","item":"Salt and coarse black pepper"}]'::JSONB, '[{"step":1,"title":"Portion the beef","instruction":"Divide the beef into 8 loose 2 oz balls. Do not compact them — a loose ball spreads thinner and crusts better. Keep them cold until the pan is ready.","tip":"Cold, loosely packed beef is the whole trick. Squeezing it makes the taco dense."},{"step":2,"title":"Get the pan screaming","instruction":"Heat a cast iron skillet or flat griddle over medium-high with the oil until it just begins to smoke. You want the surface hot enough that the beef sizzles hard on contact."},{"step":3,"title":"Smash onto the tortilla","instruction":"Lay a tortilla in the pan and put a beef ball on top. Press down hard with a sturdy spatula until the beef spreads to the tortilla edges — about 10 seconds of firm pressure. Season with salt and pepper.","tip":"Press once and commit. Repeated pressing squeezes out the juice."},{"step":4,"title":"Cook and flip","instruction":"Cook 2 minutes until the beef edges are deep brown and lacy. Brush with mustard, scatter diced onion, then flip so the beef faces down. Cook 45 seconds more."},{"step":5,"title":"Melt and fold","instruction":"Flip back tortilla-side down, lay on a slice of cheese, and cover for 30 seconds to melt. Slide out, add lettuce, pickles, and burger sauce, then fold and serve immediately."}]'::JSONB, 'These are best eaten within a minute of leaving the pan — the crisp beef crust softens as it sits. Cook in batches rather than crowding the skillet; two tacos at a time keeps the surface hot enough to crust properly.', ARRAY['Swap: Ground turkey or a plant-based patty mix works, but add an extra teaspoon of oil since neither renders much fat.','Make-ahead: Portion the beef balls and mix the burger sauce up to a day ahead, then keep both covered in the fridge.','Upgrade: A pinch of MSG in with the salt takes the beefy flavour up noticeably.']::TEXT[], ARRAY['Gluten','Dairy','Egg']::TEXT[]),
('one-pan-lemon-orzo', 'One-Pan Lemon Orzo', 'Orzo toasted in butter then simmered right in its own broth until creamy, finished with lemon, spinach, and a snowfall of parmesan. One pan, thirty minutes, no draining.', 'https://images.unsplash.com/photo-1485921325833-c519f76c4927', 'Creamy lemon orzo pasta with spinach and parmesan in a cast iron pan', 'Sofia Patel', '@sofiapatelkitchen', 'https://images.unsplash.com/photo-1716947674021-1b8b696325c7', 'Portrait of food creator Sofia Patel', '10 min', '20 min', '30 min', 10, 20, 30, 4, 'Easy', 'Mediterranean', 'Dinner', 'Main Course', ARRAY['Vegetarian','One-Pan','Comfort','Quick']::TEXT[], 5.0, 1412, 820, 438, 15, 58, 16, 4, '[{"amount":"1.5","unit":"cups","item":"dry orzo"},{"amount":"3","unit":"tbsp","item":"unsalted butter"},{"amount":"1","unit":"small","item":"yellow onion, finely diced"},{"amount":"4","unit":"cloves","item":"garlic, minced"},{"amount":"3","unit":"cups","item":"vegetable or chicken stock, warm"},{"amount":"5","unit":"oz","item":"baby spinach"},{"amount":"1","unit":"large","item":"lemon (zest and juice)"},{"amount":"0.75","unit":"cup","item":"grated parmesan"},{"amount":"0.25","unit":"cup","item":"heavy cream"},{"amount":"","unit":"","item":"Salt and black pepper"},{"amount":"","unit":"","item":"Fresh dill or parsley to finish"}]'::JSONB, '[{"step":1,"title":"Toast the orzo","instruction":"Melt 2 tbsp butter in a wide skillet over medium heat. Add the orzo and stir constantly for 3 minutes until the grains smell nutty and turn golden at the edges. Tip it onto a plate.","tip":"Toasting is what keeps the orzo from turning to mush later. Do not skip it."},{"step":2,"title":"Soften the aromatics","instruction":"Add the remaining butter to the pan with the onion and a pinch of salt. Cook 4 minutes until translucent, then add the garlic and cook 30 seconds more until fragrant."},{"step":3,"title":"Simmer","instruction":"Return the orzo to the pan and pour in the warm stock. Bring to a gentle simmer, then cook uncovered for 9–11 minutes, stirring often, until the orzo is al dente and the liquid has thickened around it.","tip":"Stir often — the starch releasing from the orzo is what makes the sauce creamy."},{"step":4,"title":"Wilt the spinach","instruction":"Add the spinach a handful at a time, stirring until each addition collapses into the pan. It looks like far too much and then it is not."},{"step":5,"title":"Finish off the heat","instruction":"Take the pan off the heat. Stir in the cream, parmesan, lemon zest, and half the lemon juice. Taste and add more lemon, salt, and pepper. Rest 2 minutes to thicken, then top with herbs."}]'::JSONB, 'Orzo keeps drinking liquid as it cools, so pull it from the heat when it still looks a touch loose — it firms up to exactly right by the time it reaches the table. Leftovers thicken into a solid block; loosen with a splash of stock when reheating.', ARRAY['Swap: Use nutritional yeast and olive oil in place of the parmesan, cream, and butter for a dairy-free version.','Add protein: Stir in shredded rotisserie chicken or a tin of drained white beans with the spinach.','Make-ahead: Not a great candidate for making ahead, but the aromatics can be softened a day early.']::TEXT[], ARRAY['Gluten','Dairy']::TEXT[]),
('korean-corn-dogs', 'Korean Corn Dogs', 'Half hot dog, half mozzarella, jacketed in sweet yeasted batter, rolled in panko, fried to a crackle and dusted with sugar. The pull is the whole point.', 'https://img.rocket.new/generatedImages/rocket_gen_img_1eead6026-1771887177210.png', 'Korean-style corn dogs coated in crispy batter with sugar and ketchup drizzle', 'Yuna Kim', '@yunakimkitchen', '', '', '20 min', '15 min', '35 min', 20, 15, 35, 6, 'Medium', 'Korean', 'Snack', 'Snack', ARRAY['Street Food','Fried','Cheesy','Party Food']::TEXT[], 5.0, 1097, 7273, 498, 19, 52, 24, 2, '[{"amount":"6","unit":"","item":"hot dogs, halved crosswise"},{"amount":"6","unit":"oz","item":"low-moisture mozzarella, cut into 3-inch batons"},{"amount":"2","unit":"cups","item":"all-purpose flour"},{"amount":"2","unit":"tbsp","item":"granulated sugar"},{"amount":"2.25","unit":"tsp","item":"instant yeast"},{"amount":"1","unit":"tsp","item":"salt"},{"amount":"1","unit":"large","item":"egg"},{"amount":"0.75","unit":"cup","item":"whole milk, warm"},{"amount":"3","unit":"cups","item":"panko breadcrumbs"},{"amount":"","unit":"","item":"Neutral oil for frying"},{"amount":"","unit":"","item":"Extra sugar for dusting"},{"amount":"","unit":"","item":"Ketchup and mustard to serve"},{"amount":"12","unit":"","item":"wooden skewers"}]'::JSONB, '[{"step":1,"title":"Make the batter","instruction":"Whisk the flour, sugar, yeast, and salt together. Add the egg and warm milk and mix to a very thick, sticky dough — closer to paste than batter. Cover and rest 45 minutes until visibly puffed.","tip":"The dough must be thick enough to cling to a vertical skewer. If it slides off, work in another spoonful of flour."},{"step":2,"title":"Skewer","instruction":"Thread each skewer with either a half hot dog, a mozzarella baton, or one of each stacked end to end. Pat everything completely dry."},{"step":3,"title":"Coat","instruction":"Transfer the risen dough to a tall glass or jar. Dip each skewer straight down, twisting as you pull it out so the dough wraps evenly. Immediately roll in panko, pressing firmly so it sticks.","tip":"A tall narrow container gives a far cleaner coat than trying to spread the dough by hand."},{"step":4,"title":"Fry","instruction":"Heat 3 inches of oil to 340°F (170°C). Fry two at a time for 3–4 minutes, rotating constantly, until deep golden. Keep the temperature steady — too hot and the outside burns before the cheese melts."},{"step":5,"title":"Sugar and serve","instruction":"Drain briefly on a rack, then roll in granulated sugar while still hot. Zigzag with ketchup and mustard and eat right away, while the cheese still pulls."}]'::JSONB, 'Cheese leaks if the dough coat has any gaps, so check each skewer before it goes in the oil and patch thin spots by dipping again. Use low-moisture mozzarella — fresh mozzarella carries too much water and will burst.', ARRAY['Classic variation: Press cubed par-cooked potato into the panko layer for the potato-crusted version.','Make-ahead: Skewer the hot dogs and cheese the day before and keep them chilled; make the dough fresh.','Reheat: Only the air fryer brings these back — 350°F for 4 minutes. A microwave turns them to rubber.']::TEXT[], ARRAY['Gluten','Dairy','Egg','Soy']::TEXT[]),
('mango-coconut-chia-pudding', 'Mango Coconut Chia Pudding', 'Chia seeds set overnight in coconut milk, layered with mango purée. Five minutes of actual work for a breakfast that feels like dessert.', 'https://images.unsplash.com/photo-1629180050285-7c56c6671f19', 'Layered mango coconut chia pudding in a glass jar topped with fresh mango slices', 'Priya Nair', '@priyanairkitchen', '', '', '10 min', '—', '10 min', 10, 0, 10, 2, 'Easy', 'Tropical', 'Breakfast', 'Breakfast', ARRAY['Vegan','Gluten-Free','Make-Ahead','No-Cook']::TEXT[], 4.9, 1407, 2715, 352, 7, 39, 20, 12, '[{"amount":"0.33","unit":"cup","item":"chia seeds"},{"amount":"1.25","unit":"cups","item":"full-fat coconut milk"},{"amount":"2","unit":"tbsp","item":"maple syrup"},{"amount":"0.5","unit":"tsp","item":"vanilla extract"},{"amount":"","unit":"","item":"Pinch of salt"},{"amount":"2","unit":"large","item":"ripe mangoes, peeled and cubed"},{"amount":"1","unit":"tbsp","item":"lime juice"},{"amount":"2","unit":"tbsp","item":"toasted coconut flakes"},{"amount":"","unit":"","item":"Fresh mint to garnish"}]'::JSONB, '[{"step":1,"title":"Mix the base","instruction":"Whisk the coconut milk, maple syrup, vanilla, and salt together until smooth, then whisk in the chia seeds."},{"step":2,"title":"Break up the clumps","instruction":"Let it sit 10 minutes, then whisk hard a second time. Chia clumps the moment it hits liquid and this second whisk is what gives you an even, custardy set.","tip":"Skipping the second whisk is the single most common reason chia pudding comes out lumpy."},{"step":3,"title":"Chill","instruction":"Cover and refrigerate at least 4 hours, ideally overnight, until thick enough to hold a spoon upright."},{"step":4,"title":"Purée the mango","instruction":"Blend three-quarters of the mango with the lime juice until completely smooth. Keep the rest cubed for the top."},{"step":5,"title":"Layer and serve","instruction":"Spoon alternating layers of pudding and mango purée into two glasses. Top with cubed mango, toasted coconut flakes, and mint."}]'::JSONB, 'The pudding keeps for 4 days covered in the fridge, and the texture actually improves on day two. If it sets firmer than you like, loosen it with a splash of coconut milk and stir.', ARRAY['Swap: Any milk works — oat and almond both set fine, though neither is as rich as full-fat coconut.','Lower sugar: Very ripe mango is sweet enough that you can cut the maple syrup to a teaspoon or drop it entirely.','Meal prep: Make four jars at once on Sunday; they are ready to grab straight from the fridge all week.']::TEXT[], ARRAY['Coconut']::TEXT[]),
('garlic-butter-shrimp-pasta', 'Garlic Butter Shrimp Pasta', 'Shrimp seared hard and fast, then folded through linguine in a garlic butter pan sauce loosened with pasta water. Twenty minutes from cold pan to the table.', 'https://img.rocket.new/generatedImages/rocket_gen_img_1f19f6fbe-1775504653966.png', 'Garlic butter shrimp tossed with linguine pasta and fresh parsley', 'Marco Rossi', '@marcorossicucina', '', '', '8 min', '12 min', '20 min', 8, 12, 20, 4, 'Easy', 'Italian', 'Dinner', 'Main Course', ARRAY['Seafood','Quick','Date Night','Pasta']::TEXT[], 4.2, 520, 1118, 586, 34, 62, 22, 3, '[{"amount":"12","unit":"oz","item":"linguine"},{"amount":"1","unit":"lb","item":"large shrimp, peeled and deveined"},{"amount":"6","unit":"tbsp","item":"unsalted butter"},{"amount":"2","unit":"tbsp","item":"olive oil"},{"amount":"8","unit":"cloves","item":"garlic, thinly sliced"},{"amount":"0.5","unit":"tsp","item":"red pepper flakes"},{"amount":"0.5","unit":"cup","item":"dry white wine"},{"amount":"1","unit":"large","item":"lemon (zest and juice)"},{"amount":"0.5","unit":"cup","item":"chopped flat-leaf parsley"},{"amount":"0.25","unit":"cup","item":"grated parmesan"},{"amount":"","unit":"","item":"Salt and black pepper"}]'::JSONB, '[{"step":1,"title":"Boil the pasta","instruction":"Cook the linguine in well-salted water until one minute short of al dente. Reserve 1.5 cups of pasta water before draining — you will need more of it than you expect.","tip":"The pasta water is the sauce. Reserve it before you drain, every time."},{"step":2,"title":"Sear the shrimp","instruction":"Pat the shrimp bone dry and season with salt and pepper. Sear in the olive oil over high heat, 90 seconds per side, until just pink and opaque. Remove immediately to a plate.","tip":"Shrimp go from perfect to rubbery in about thirty seconds. Pull them early — they finish in the sauce."},{"step":3,"title":"Build the garlic butter","instruction":"Lower the heat to medium. Add the butter and sliced garlic and cook gently for 2 minutes until the garlic is pale gold and fragrant. Do not let it brown or the sauce turns bitter."},{"step":4,"title":"Deglaze","instruction":"Add the red pepper flakes and white wine. Scrape the pan and simmer 2 minutes until reduced by half."},{"step":5,"title":"Bring it together","instruction":"Add the drained pasta and a cup of pasta water. Toss hard over medium heat for a minute or two — the sauce will go from watery to glossy as the starch emulsifies with the butter. Add more water as needed.","tip":"Keep tossing. The emulsion only forms with vigorous movement."},{"step":6,"title":"Finish","instruction":"Return the shrimp with any resting juices. Off the heat, add the lemon zest, juice, parsley, and parmesan. Toss and serve at once."}]'::JSONB, 'Shrimp continue cooking in the residual heat of the pasta, which is why they come out at 90 seconds a side. Frozen shrimp work perfectly well — thaw them fully and dry them thoroughly, since surface water prevents any sear from forming.', ARRAY['Swap: Skip the wine and use stock plus an extra squeeze of lemon.','Dairy-free: Use good olive oil in place of the butter and leave out the parmesan; the sauce is looser but still excellent.','Scale up: Use two pans rather than crowding one — shrimp steam instead of searing when packed in.']::TEXT[], ARRAY['Shellfish','Gluten','Dairy']::TEXT[]),
('avocado-toast-poached-egg', 'Avocado Toast with Poached Egg', 'Thick sourdough, properly seasoned smashed avocado, and a poached egg with a liquid yolk. Simple enough that every detail shows.', 'https://img.rocket.new/generatedImages/rocket_gen_img_18e6c1a9c-1772204197800.png', 'Thick sourdough toast topped with smashed avocado and a perfectly poached egg', 'Emma Walsh', '@emmawalshbakes', '', '', '5 min', '10 min', '15 min', 5, 10, 15, 2, 'Easy', 'American', 'Breakfast', 'Breakfast', ARRAY['Vegetarian','Quick','Healthy','Brunch']::TEXT[], 4.6, 1476, 6956, 412, 16, 34, 25, 9, '[{"amount":"2","unit":"thick slices","item":"sourdough bread"},{"amount":"2","unit":"large","item":"ripe avocados"},{"amount":"2","unit":"large","item":"eggs"},{"amount":"1","unit":"tbsp","item":"white vinegar"},{"amount":"1","unit":"tbsp","item":"lemon juice"},{"amount":"1","unit":"clove","item":"garlic, halved"},{"amount":"0.25","unit":"tsp","item":"red pepper flakes"},{"amount":"1","unit":"tbsp","item":"olive oil"},{"amount":"","unit":"","item":"Flaky sea salt and black pepper"},{"amount":"","unit":"","item":"Microgreens or fresh dill to finish"}]'::JSONB, '[{"step":1,"title":"Toast hard","instruction":"Toast the sourdough until it is genuinely crisp and deeply coloured, not just warm. Rub the cut side of the garlic clove across the hot surface and drizzle with olive oil.","tip":"A soft slice collapses under the avocado. Toast it further than feels necessary."},{"step":2,"title":"Season the avocado properly","instruction":"Mash the avocado in a bowl with the lemon juice, a generous pinch of flaky salt, and black pepper. Taste it. Unseasoned avocado is the reason most versions of this are bland."},{"step":3,"title":"Set up the poach","instruction":"Bring a wide pan of water to a bare simmer — small bubbles on the base, no rolling boil. Add the vinegar. Crack each egg into a fine sieve first and let the loose watery white drain away.","tip":"Sieving the egg is what gives you a tidy poach instead of a cloud of white strands."},{"step":4,"title":"Poach","instruction":"Slide the eggs gently into the water and cook 3 minutes for a set white and fully runny yolk. Lift out with a slotted spoon onto kitchen paper to drain."},{"step":5,"title":"Assemble","instruction":"Spread the avocado thickly over the toast, top with a poached egg, and finish with red pepper flakes, flaky salt, cracked pepper, and greens."}]'::JSONB, 'Fresher eggs poach into tighter rounds because the white is firmer; older eggs spread. If your eggs are not fresh, the sieve step matters even more. Water at a hard boil will shred the whites — keep it at a lazy simmer throughout.', ARRAY['Swap: A soft-boiled egg (6.5 minutes from boiling, then iced) gives the same yolk with far less fuss.','Add protein: Smoked salmon, crumbled feta, or a spoonful of cottage cheese under the avocado all work well.','Make-ahead: Poach the eggs up to a day ahead, keep them in cold water, and reheat for 30 seconds in hot water.']::TEXT[], ARRAY['Gluten','Egg']::TEXT[]),
('spicy-peanut-noodles', 'Spicy Peanut Noodles', 'Cold noodles in a chilli-peanut sauce sharp with vinegar and loose enough to actually coat. Better after an hour in the fridge, which makes it ideal for lunches.', 'https://images.unsplash.com/photo-1626066014976-cd53fe450b3e', 'Cold spicy peanut noodles garnished with cucumber, scallions, and sesame seeds', 'Lin Wei', '@linweiwok', '', '', '15 min', '10 min', '25 min', 15, 10, 25, 4, 'Easy', 'Chinese', 'Lunch', 'Main Course', ARRAY['Vegan-Adaptable','Cold Dish','Meal Prep','Spicy']::TEXT[], 4.8, 1336, 4310, 524, 18, 64, 23, 5, '[{"amount":"12","unit":"oz","item":"wheat noodles or spaghetti"},{"amount":"0.5","unit":"cup","item":"smooth peanut butter"},{"amount":"3","unit":"tbsp","item":"soy sauce"},{"amount":"2","unit":"tbsp","item":"rice vinegar"},{"amount":"2","unit":"tbsp","item":"chilli crisp"},{"amount":"1","unit":"tbsp","item":"toasted sesame oil"},{"amount":"1","unit":"tbsp","item":"maple syrup or honey"},{"amount":"3","unit":"cloves","item":"garlic, grated"},{"amount":"1","unit":"inch","item":"ginger, grated"},{"amount":"0.5","unit":"cup","item":"hot water"},{"amount":"1","unit":"large","item":"cucumber, julienned"},{"amount":"4","unit":"","item":"scallions, sliced"},{"amount":"0.33","unit":"cup","item":"roasted peanuts, crushed"},{"amount":"","unit":"","item":"Fresh cilantro"}]'::JSONB, '[{"step":1,"title":"Cook and cool the noodles","instruction":"Boil the noodles until just al dente, then drain and rinse under cold running water until completely cool. Toss with a teaspoon of sesame oil so they do not clump.","tip":"Rinsing washes off surface starch. Without it, cold noodles glue themselves into a solid mass."},{"step":2,"title":"Build the sauce","instruction":"Whisk the peanut butter, soy sauce, rice vinegar, chilli crisp, sesame oil, maple syrup, garlic, and ginger together. It will seize into a stiff paste — this is expected."},{"step":3,"title":"Loosen it","instruction":"Add the hot water a tablespoon at a time, whisking continuously, until the sauce is pourable and glossy — roughly the consistency of double cream. Taste and adjust: more vinegar for sharpness, more chilli crisp for heat.","tip":"Add water gradually. Dumping it in at once leaves a split, grainy sauce."},{"step":4,"title":"Toss","instruction":"Pour the sauce over the cold noodles and toss thoroughly with tongs until every strand is coated."},{"step":5,"title":"Top and rest","instruction":"Fold through the cucumber and half the scallions. Rest 20 minutes for the flavours to settle, then top with peanuts, remaining scallions, and cilantro."}]'::JSONB, 'The noodles keep absorbing sauce as they sit, so hold back a few tablespoons to loosen them before serving the next day. Keeps 4 days refrigerated and travels well.', ARRAY['Swap: Tahini or sunflower seed butter make a nut-free version with the same texture.','Add protein: Shredded poached chicken, crisped tofu, or edamame all fold in without changing the sauce.','Heat control: Chilli crisp brands vary enormously in strength — start with one tablespoon and build up.']::TEXT[], ARRAY['Peanut','Soy','Gluten','Sesame']::TEXT[]),
('sheet-pan-fajitas', 'Sheet Pan Fajitas', 'Chicken and peppers roasted hot on a single tray until the edges char, then piled into warm tortillas. One pan in, one pan out.', 'https://images.unsplash.com/photo-1679060301613-2ff2050db858', 'Colorful bell peppers and chicken strips roasted on a sheet pan for fajitas', 'Carlos Mendez', '@carlosmendezcooks', '', '', '12 min', '18 min', '30 min', 12, 18, 30, 4, 'Easy', 'Mexican', 'Dinner', 'Main Course', ARRAY['One-Pan','Weeknight','Family','Gluten-Free-Adaptable']::TEXT[], 4.8, 981, 7264, 478, 38, 41, 17, 6, '[{"amount":"1.5","unit":"lb","item":"chicken breast or thigh, sliced into strips"},{"amount":"3","unit":"large","item":"bell peppers (mixed colours), sliced"},{"amount":"1","unit":"large","item":"red onion, sliced"},{"amount":"3","unit":"tbsp","item":"olive oil"},{"amount":"2","unit":"tsp","item":"chilli powder"},{"amount":"2","unit":"tsp","item":"ground cumin"},{"amount":"1","unit":"tsp","item":"smoked paprika"},{"amount":"1","unit":"tsp","item":"garlic powder"},{"amount":"0.5","unit":"tsp","item":"dried oregano"},{"amount":"1","unit":"tsp","item":"salt"},{"amount":"1","unit":"","item":"lime, juiced"},{"amount":"8","unit":"","item":"flour or corn tortillas"},{"amount":"","unit":"","item":"Sour cream, guacamole, and cilantro to serve"}]'::JSONB, '[{"step":1,"title":"Heat the oven and the tray","instruction":"Preheat to 425°F (220°C) with the empty sheet pan inside. A hot tray sears the chicken on contact instead of letting it steam.","tip":"Preheating the pan is the difference between charred fajitas and grey, watery ones."},{"step":2,"title":"Season everything together","instruction":"Toss the chicken, peppers, and onion with the oil and all the spices until evenly coated. Use your hands — a spoon leaves clumps of spice."},{"step":3,"title":"Spread in one layer","instruction":"Tip onto the hot pan and spread out so nothing overlaps. Use two pans if it looks crowded; crowding is what causes steaming."},{"step":4,"title":"Roast","instruction":"Roast 18–20 minutes, tossing once at the halfway mark, until the chicken is cooked through and the pepper edges are blistered and blackening in spots."},{"step":5,"title":"Finish and serve","instruction":"Squeeze the lime over the hot pan and toss. Warm the tortillas directly over a gas flame or in a dry skillet, then serve with sour cream, guacamole, and cilantro."}]'::JSONB, 'Chicken thigh stays juicier than breast at this temperature and is more forgiving if the pan runs a few minutes long. Cook to 165°F (74°C) internal. Any leftovers make excellent quesadilla filling.', ARRAY['Swap: Skirt steak works beautifully — roast 12 minutes only and slice against the grain.','Vegetarian: Portobello mushrooms and courgette in place of the chicken, roasted 15 minutes.','Make-ahead: Slice and season everything up to 24 hours ahead and keep it covered in the fridge.']::TEXT[], ARRAY['Gluten']::TEXT[]),
('caprese-salad', 'Caprese Salad', 'Three ingredients and nowhere to hide. Ripe tomatoes, real mozzarella, torn basil, good oil, flaky salt.', 'https://images.unsplash.com/photo-1725464781841-2d6f9ac10fb2', 'Classic caprese salad with fresh mozzarella, tomatoes, basil and balsamic glaze', 'Sofia Romano', '@sofiaromanoeats', '', '', '10 min', '—', '10 min', 10, 0, 10, 4, 'Easy', 'Italian', 'Lunch', 'Appetizer', ARRAY['Vegetarian','No-Cook','Summer','Gluten-Free']::TEXT[], 4.4, 1347, 9260, 286, 14, 8, 23, 2, '[{"amount":"1.5","unit":"lb","item":"ripe tomatoes (mixed varieties), sliced thick"},{"amount":"12","unit":"oz","item":"fresh mozzarella di bufala, torn"},{"amount":"1","unit":"large bunch","item":"fresh basil"},{"amount":"3","unit":"tbsp","item":"extra virgin olive oil"},{"amount":"1","unit":"tbsp","item":"aged balsamic vinegar"},{"amount":"","unit":"","item":"Flaky sea salt"},{"amount":"","unit":"","item":"Coarsely cracked black pepper"}]'::JSONB, '[{"step":1,"title":"Bring everything to room temperature","instruction":"Take the tomatoes and mozzarella out of the fridge 30 minutes ahead. Cold flattens tomato flavour completely and firms the cheese into rubber.","tip":"Never build this straight from the fridge. Room temperature is not optional here."},{"step":2,"title":"Salt the tomatoes first","instruction":"Slice the tomatoes about half an inch thick, lay them out, and salt them. Leave 10 minutes — they release liquid and season through rather than just tasting salty on the surface."},{"step":3,"title":"Tear, do not slice","instruction":"Tear the mozzarella into rough pieces by hand. The ragged surface holds oil far better than a clean knife cut, and it looks better too."},{"step":4,"title":"Layer","instruction":"Arrange tomatoes and mozzarella on a wide platter, overlapping loosely. Tuck whole basil leaves between the layers rather than scattering them on top."},{"step":5,"title":"Dress at the last moment","instruction":"Drizzle generously with olive oil and lightly with balsamic. Finish with flaky salt and cracked pepper. Serve within a few minutes."}]'::JSONB, 'This lives or dies on tomato quality — out of season, use the best cherry tomatoes you can find rather than pale beefsteaks. The liquid pooling on the platter is the best part; serve with bread to mop it up.', ARRAY['Swap: Burrata in place of mozzarella turns this into something considerably more decadent.','Vegan: Marinated firm tofu or a cashew mozzarella both work; keep the tomatoes and oil generous.','Do not make ahead: Assembled caprese weeps within twenty minutes. Prep the components, combine at the table.']::TEXT[], ARRAY['Dairy']::TEXT[]),
('egg-fried-rice', 'Egg Fried Rice', 'Day-old rice, screaming hot wok, egg cooked in two stages so you get both silky ribbons and coated grains. Fifteen minutes.', 'https://img.rocket.new/generatedImages/rocket_gen_img_14631f803-1772367083673.png', 'Wok-tossed egg fried rice with vegetables and soy sauce in a bowl', 'Lin Wei', '@linweiwok', '', '', '8 min', '7 min', '15 min', 8, 7, 15, 4, 'Easy', 'Chinese', 'Dinner', 'Main Course', ARRAY['Quick','Leftovers','Budget','Vegetarian-Adaptable']::TEXT[], 4.7, 1840, 7510, 396, 13, 54, 14, 2, '[{"amount":"4","unit":"cups","item":"cooked jasmine rice, cold (day-old)"},{"amount":"4","unit":"large","item":"eggs, beaten"},{"amount":"3","unit":"tbsp","item":"neutral oil"},{"amount":"4","unit":"","item":"scallions, whites and greens separated"},{"amount":"3","unit":"cloves","item":"garlic, minced"},{"amount":"1","unit":"cup","item":"frozen peas and carrots"},{"amount":"2","unit":"tbsp","item":"light soy sauce"},{"amount":"1","unit":"tsp","item":"dark soy sauce"},{"amount":"1","unit":"tsp","item":"toasted sesame oil"},{"amount":"0.5","unit":"tsp","item":"white pepper"},{"amount":"","unit":"","item":"Salt"}]'::JSONB, '[{"step":1,"title":"Break up the rice","instruction":"Work through the cold rice with wet hands until every clump is separated into individual grains. Cold day-old rice is essential — fresh rice steams and turns to porridge.","tip":"If you only have fresh rice, spread it on a tray and freeze for 30 minutes to dry the surface."},{"step":2,"title":"Scramble half the egg","instruction":"Heat 1 tbsp oil in a wok over high heat. Pour in half the beaten egg, let it set for 10 seconds, then scramble into large soft curds. Remove while still slightly underdone."},{"step":3,"title":"Fry the aromatics","instruction":"Add the remaining oil, then the scallion whites and garlic. Stir-fry 30 seconds until fragrant, then add the peas and carrots and cook 1 minute more."},{"step":4,"title":"Fry the rice","instruction":"Add the rice and press it against the hot surface of the wok, then toss. Keep pressing and tossing for 3–4 minutes until the grains dance and pop and start to colour lightly.","tip":"Keep the heat at maximum the whole time. Low heat steams the rice instead of frying it."},{"step":5,"title":"Add the second egg","instruction":"Push the rice to one side, pour the remaining beaten egg into the empty space, and stir it rapidly into the rice as it sets so it coats the grains in a thin golden film."},{"step":6,"title":"Season and finish","instruction":"Add both soy sauces around the rim of the wok so they sizzle before hitting the rice. Toss with the sesame oil, white pepper, reserved scrambled egg, and scallion greens."}]'::JSONB, 'The two-stage egg method is what separates restaurant fried rice from home fried rice — the first batch gives you tender curds, the second coats each grain. Add soy sauce around the edge of the pan rather than into the middle so it caramelises instead of pooling.', ARRAY['Add protein: Char siu, shrimp, or diced spam all work; cook them first and fold back in at the end.','Vegan: Omit the egg and add crumbled firm tofu fried until golden.','Do not crowd: Cook in two batches if your burner is weak — a lukewarm wok gives soggy rice every time.']::TEXT[], ARRAY['Egg','Soy','Sesame']::TEXT[]),
('chicken-tikka-masala', 'Chicken Tikka Masala', 'Yoghurt-marinated chicken charred under the grill, then simmered into a tomato and cream gravy built on properly bloomed spices.', 'https://images.unsplash.com/photo-1657205937641-01d8c906274f', 'Rich and creamy chicken tikka masala in a bowl with naan bread on the side', 'Aisha Sharma', '@aishasharmaspice', '', '', '25 min', '25 min', '50 min', 25, 25, 50, 6, 'Medium', 'Indian', 'Dinner', 'Main Course', ARRAY['Curry','Comfort','Crowd Pleaser','Gluten-Free']::TEXT[], 4.4, 1574, 9262, 562, 42, 18, 36, 3, '[{"amount":"2","unit":"lb","item":"boneless chicken thighs, cut into chunks"},{"amount":"1","unit":"cup","item":"plain full-fat yoghurt"},{"amount":"2","unit":"tbsp","item":"lemon juice"},{"amount":"2","unit":"tbsp","item":"garam masala"},{"amount":"1","unit":"tbsp","item":"ground cumin"},{"amount":"1","unit":"tbsp","item":"ground coriander"},{"amount":"2","unit":"tsp","item":"turmeric"},{"amount":"2","unit":"tsp","item":"smoked paprika"},{"amount":"1","unit":"tsp","item":"cayenne"},{"amount":"6","unit":"cloves","item":"garlic, minced"},{"amount":"2","unit":"inch","item":"ginger, grated"},{"amount":"4","unit":"tbsp","item":"ghee or butter"},{"amount":"1","unit":"large","item":"onion, finely diced"},{"amount":"28","unit":"oz","item":"crushed tomatoes"},{"amount":"1","unit":"cup","item":"heavy cream"},{"amount":"1","unit":"tsp","item":"sugar"},{"amount":"","unit":"","item":"Salt to taste"},{"amount":"","unit":"","item":"Fresh cilantro and rice to serve"}]'::JSONB, '[{"step":1,"title":"Marinate","instruction":"Combine the yoghurt, lemon juice, half the garlic and ginger, and half of each ground spice. Coat the chicken thoroughly and refrigerate at least 4 hours, ideally overnight.","tip":"The yoghurt acid tenderises the thighs and the marinade is where most of the depth comes from. Four hours minimum."},{"step":2,"title":"Char the chicken","instruction":"Spread the chicken on a foil-lined tray and grill on the highest setting, 6 inches from the element, for 12–15 minutes until blackened in patches. You want char, not just cooked.","tip":"Those blackened edges are the \"tikka\" in tikka masala. Pale chicken makes a flat curry."},{"step":3,"title":"Bloom the spices","instruction":"Melt the ghee in a heavy pot over medium heat. Cook the onion 8 minutes until soft and golden, then add the remaining garlic, ginger, and spices. Stir constantly for 60 seconds until intensely fragrant.","tip":"Frying the spices in fat rather than adding them to liquid is what unlocks them. Sixty seconds, stirring, no longer or they burn."},{"step":4,"title":"Build the sauce","instruction":"Add the crushed tomatoes and sugar. Simmer uncovered for 20 minutes, stirring occasionally, until noticeably darkened and thickened and the oil begins to separate at the edges."},{"step":5,"title":"Combine","instruction":"Add the charred chicken along with every drop of juice from the tray. Simmer 10 minutes so the flavours marry."},{"step":6,"title":"Finish with cream","instruction":"Lower the heat, stir in the cream, and warm through without boiling. Season with salt, top with cilantro, and serve with rice."}]'::JSONB, 'Chicken thigh is strongly preferred over breast here — it survives both the grill and the simmer without drying out. The curry improves overnight as the spices settle, so it is an excellent make-ahead dish. Cook chicken to 165°F (74°C).', ARRAY['Swap: Full-fat coconut milk in place of cream and oil in place of ghee gives a very good dairy-free version.','Vegetarian: Paneer or roasted cauliflower, added at the final simmer rather than grilled.','Heat: Cayenne carries the heat here. Halve it for mild, double it if you want it to bite.']::TEXT[], ARRAY['Dairy']::TEXT[]),
('beef-pho', 'Beef Pho', 'A clear, deeply aromatic broth built over hours from charred aromatics, toasted spice, and beef bones. Not quick, and entirely worth it.', 'https://images.unsplash.com/photo-1707153438523-3d32f2bed0f3', 'Steaming bowl of Vietnamese beef pho with rice noodles, herbs, and bean sprouts', 'Nguyen Lan', '@nguyenlanpho', '', '', '40 min', '2.3 hrs', '3 hrs', 40, 140, 180, 6, 'Hard', 'Vietnamese', 'Lunch', 'Main Course', ARRAY['Soup','Weekend Project','Comfort','Gluten-Free-Adaptable']::TEXT[], 4.3, 710, 4208, 486, 34, 58, 12, 3, '[{"amount":"4","unit":"lb","item":"beef bones (marrow and knuckle)"},{"amount":"1","unit":"lb","item":"beef brisket"},{"amount":"2","unit":"large","item":"onions, halved"},{"amount":"4","unit":"inch","item":"ginger, halved lengthways"},{"amount":"6","unit":"","item":"star anise"},{"amount":"1","unit":"","item":"cinnamon stick"},{"amount":"6","unit":"","item":"cloves"},{"amount":"1","unit":"tbsp","item":"coriander seeds"},{"amount":"3","unit":"","item":"cardamom pods"},{"amount":"0.25","unit":"cup","item":"fish sauce"},{"amount":"1","unit":"oz","item":"rock sugar"},{"amount":"1","unit":"lb","item":"dried flat rice noodles"},{"amount":"8","unit":"oz","item":"beef sirloin, sliced paper-thin"},{"amount":"","unit":"","item":"Bean sprouts, Thai basil, lime, and chillies to serve"},{"amount":"","unit":"","item":"Salt"}]'::JSONB, '[{"step":1,"title":"Parboil the bones","instruction":"Cover the bones with cold water, bring to a hard boil for 10 minutes, then drain and rinse each bone under running water. Scrub the pot clean before continuing.","tip":"This step is what makes the broth clear rather than cloudy and scummy. Do not skip it."},{"step":2,"title":"Char the aromatics","instruction":"Blacken the onion and ginger halves directly over a gas flame or under a hot grill until the cut faces are genuinely charred, about 8 minutes. Scrape off the loose ash.","tip":"Charring builds the smoky base note that defines pho. Softly browned is not enough."},{"step":3,"title":"Toast the spices","instruction":"Dry-toast the star anise, cinnamon, cloves, coriander seeds, and cardamom in a pan over medium heat for 2 minutes until fragrant, then tie them in a spice bag or muslin."},{"step":4,"title":"Simmer long and low","instruction":"Return the bones to the clean pot with the brisket, charred aromatics, and spice bag. Cover with 6 quarts cold water. Bring to a bare simmer and hold it there for 3 hours, skimming the surface regularly.","tip":"Never let it boil. A rolling boil emulsifies the fat and turns the broth cloudy and greasy."},{"step":5,"title":"Season the broth","instruction":"Remove the brisket after 90 minutes, cool, and slice thinly. At the 3-hour mark, strain the broth through a fine sieve and season with fish sauce, rock sugar, and salt until it tastes rounded and savoury."},{"step":6,"title":"Assemble","instruction":"Soak and cook the rice noodles per packet. Divide between bowls, top with sliced brisket and raw sirloin, then ladle over broth at a full rolling boil — it cooks the raw beef in the bowl. Serve with the herb plate."}]'::JSONB, 'The broth is the entire dish. Season it more aggressively than seems right when tasting alone, because the noodles and garnishes dilute it considerably. Broth freezes beautifully for 3 months. Slice the raw sirloin while partially frozen to get it truly thin.', ARRAY['Shortcut: A pressure cooker gets you a respectable broth in 90 minutes, though slightly less clear.','Gluten-free: Naturally so, as long as your fish sauce and hoisin are certified.','Make-ahead: Make the broth entirely in advance — it deepens over two or three days in the fridge.']::TEXT[], ARRAY['Fish','Soy']::TEXT[]),
('shakshuka', 'Shakshuka', 'Eggs poached into a spiced tomato and pepper sauce, straight from the pan with bread. Breakfast, lunch, or a completely legitimate dinner.', 'https://img.rocket.new/generatedImages/rocket_gen_img_1e54a3842-1783627091192.png', 'Eggs poached in spiced tomato and pepper sauce in a cast iron skillet', 'Leila Hassan', '@leilahassantable', '', '', '10 min', '15 min', '25 min', 10, 15, 25, 4, 'Easy', 'Middle Eastern', 'Breakfast', 'Breakfast', ARRAY['Vegetarian','One-Pan','Brunch','Gluten-Free-Adaptable']::TEXT[], 4.4, 814, 8801, 318, 17, 22, 19, 5, '[{"amount":"3","unit":"tbsp","item":"olive oil"},{"amount":"1","unit":"large","item":"onion, diced"},{"amount":"2","unit":"large","item":"red bell peppers, sliced"},{"amount":"4","unit":"cloves","item":"garlic, sliced"},{"amount":"2","unit":"tsp","item":"ground cumin"},{"amount":"2","unit":"tsp","item":"sweet paprika"},{"amount":"0.5","unit":"tsp","item":"cayenne"},{"amount":"28","unit":"oz","item":"crushed tomatoes"},{"amount":"1","unit":"tsp","item":"sugar"},{"amount":"6","unit":"large","item":"eggs"},{"amount":"4","unit":"oz","item":"feta, crumbled"},{"amount":"","unit":"","item":"Salt and black pepper"},{"amount":"","unit":"","item":"Fresh parsley and cilantro"},{"amount":"","unit":"","item":"Crusty bread or pita to serve"}]'::JSONB, '[{"step":1,"title":"Soften the vegetables","instruction":"Heat the oil in a wide oven-safe skillet over medium. Cook the onion and peppers for 12 minutes until genuinely soft and beginning to caramelise at the edges. Do not rush this.","tip":"Twelve minutes feels long, but sweet, collapsed peppers are what balance the acidity of the tomatoes."},{"step":2,"title":"Bloom the spices","instruction":"Add the garlic, cumin, paprika, and cayenne. Stir constantly for 45 seconds until the pan smells strongly of toasted spice."},{"step":3,"title":"Simmer the sauce","instruction":"Add the tomatoes and sugar, season well, and simmer for 15 minutes until thick enough that a spoon dragged through leaves a channel that holds for a second.","tip":"A watery sauce cannot hold the eggs in place. Reduce it further than you think."},{"step":4,"title":"Make wells","instruction":"Use the back of a spoon to hollow out six wells in the sauce. Crack an egg into each one and season the yolks lightly."},{"step":5,"title":"Poach","instruction":"Cover and cook over low heat 8–10 minutes, until the whites are set and the yolks still wobble. Check at 8 minutes — they carry on cooking off the heat."},{"step":6,"title":"Finish","instruction":"Scatter over the feta and herbs and bring the pan straight to the table with plenty of bread."}]'::JSONB, 'Residual heat keeps cooking the yolks after the pan leaves the stove, so pull it while they still look slightly underdone. The sauce alone keeps 5 days in the fridge and freezes well — poach fresh eggs into reheated sauce for a ten-minute meal.', ARRAY['Add protein: Sliced merguez or chorizo browned before the onions adds a lot of depth.','Vegan: Skip the eggs and feta and add a tin of chickpeas plus a swirl of tahini.','Green version: Swap the tomatoes for wilted spinach, chard, and herbs with a splash of cream.']::TEXT[], ARRAY['Egg','Dairy']::TEXT[]),
('tacos-al-pastor', 'Tacos al Pastor', 'Pork marinated in guajillo chillies, achiote, and pineapple, stacked and roasted until the edges crisp, then shaved into warm corn tortillas.', 'https://img.rocket.new/generatedImages/rocket_gen_img_1f6aa0250-1772893483543.png', 'Authentic tacos al pastor with marinated pork, pineapple, cilantro, and onion', 'Rosa Gutierrez', '@rosagutierrezcocina', '', '', '40 min', '1.5 hrs', '2.2 hrs', 40, 90, 130, 6, 'Easy', 'Mexican', 'Dinner', 'Main Course', ARRAY['Pork','Weekend Project','Street Food','Gluten-Free']::TEXT[], 4.7, 1028, 9247, 532, 34, 42, 24, 5, '[{"amount":"3","unit":"lb","item":"pork shoulder, sliced into 1/4-inch steaks"},{"amount":"6","unit":"","item":"guajillo chillies, stemmed and seeded"},{"amount":"3","unit":"","item":"ancho chillies, stemmed and seeded"},{"amount":"2","unit":"tbsp","item":"achiote paste"},{"amount":"0.5","unit":"cup","item":"pineapple juice"},{"amount":"0.25","unit":"cup","item":"white vinegar"},{"amount":"6","unit":"cloves","item":"garlic"},{"amount":"1","unit":"tsp","item":"dried oregano"},{"amount":"1","unit":"tsp","item":"ground cumin"},{"amount":"1","unit":"tsp","item":"salt"},{"amount":"1","unit":"","item":"fresh pineapple, peeled and sliced thick"},{"amount":"18","unit":"","item":"corn tortillas"},{"amount":"1","unit":"large","item":"white onion, finely diced"},{"amount":"","unit":"","item":"Cilantro, lime wedges, and salsa verde to serve"}]'::JSONB, '[{"step":1,"title":"Rehydrate the chillies","instruction":"Toast the guajillo and ancho chillies in a dry pan for 30 seconds a side until fragrant, then cover with boiling water and soak 20 minutes until pliable.","tip":"Toast them only until they smell sweet. Burnt chillies make the whole marinade bitter."},{"step":2,"title":"Blend the adobo","instruction":"Blend the drained chillies with the achiote, pineapple juice, vinegar, garlic, oregano, cumin, and salt until completely smooth. It should be thick enough to cling to a spoon."},{"step":3,"title":"Marinate","instruction":"Coat the pork steaks thoroughly in the adobo, layering them in a container. Refrigerate at least 6 hours, ideally overnight."},{"step":4,"title":"Build the stack","instruction":"Preheat the oven to 350°F (175°C). Thread the marinated steaks onto two long skewers set upright in a loaf tin, or simply stack them tightly on a rack over a roasting tray. Top the stack with a thick slice of pineapple.","tip":"The pineapple on top drips enzymes and sugar down through the stack as it roasts — that is the al pastor signature."},{"step":5,"title":"Roast","instruction":"Roast 75–90 minutes until the pork reaches 190°F (88°C) and the outside is dark and lacquered. Grill the remaining pineapple slices alongside until charred."},{"step":6,"title":"Shave and serve","instruction":"Rest 15 minutes, then shave thin slices off the outside of the stack with a sharp knife. Crisp the shavings in a hot dry skillet for a minute. Serve in warm tortillas with diced pineapple, onion, cilantro, and lime."}]'::JSONB, 'Crisping the shaved pork in a hot pan before serving is the step most home versions skip, and it is what gives you the crunchy-edged texture from a proper trompo. Cook the pork to 190°F, not 145°F — you want it tender and shreddable, not merely safe.', ARRAY['Shortcut: Cube the pork and roast it spread on a tray at 425°F for 30 minutes; less authentic, still excellent.','Make-ahead: Marinate up to 2 days ahead. Roasted pork reheats well in a skillet.','Chicken version: Thighs marinated the same way roast in 35 minutes.']::TEXT[], ARRAY[]::TEXT[]),
('pad-thai', 'Pad Thai', 'Rice noodles tossed in a tamarind, palm sugar, and fish sauce glaze, with egg, shrimp, and crushed peanuts. Sauce made ahead, cooked in six minutes.', 'https://images.unsplash.com/photo-1663905494561-f70d406eff0d', 'Classic pad thai noodles with shrimp, bean sprouts, peanuts, and lime wedge', 'Somchai Wongsa', '@somchaiwongsathai', '', '', '20 min', '10 min', '30 min', 20, 10, 30, 4, 'Medium', 'Thai', 'Dinner', 'Main Course', ARRAY['Noodles','Seafood','Quick-Cook','Gluten-Free-Adaptable']::TEXT[], 5.0, 928, 8647, 548, 26, 71, 18, 4, '[{"amount":"10","unit":"oz","item":"dried flat rice noodles"},{"amount":"3","unit":"tbsp","item":"tamarind concentrate"},{"amount":"3","unit":"tbsp","item":"fish sauce"},{"amount":"3","unit":"tbsp","item":"palm sugar or brown sugar"},{"amount":"3","unit":"tbsp","item":"neutral oil"},{"amount":"12","unit":"oz","item":"large shrimp, peeled"},{"amount":"6","unit":"oz","item":"firm tofu, cubed"},{"amount":"3","unit":"cloves","item":"garlic, minced"},{"amount":"2","unit":"tbsp","item":"dried shrimp, chopped"},{"amount":"2","unit":"large","item":"eggs, beaten"},{"amount":"2","unit":"cups","item":"bean sprouts"},{"amount":"4","unit":"","item":"scallions, cut into batons"},{"amount":"0.5","unit":"cup","item":"roasted peanuts, crushed"},{"amount":"","unit":"","item":"Lime wedges and chilli flakes to serve"}]'::JSONB, '[{"step":1,"title":"Soak the noodles","instruction":"Soak the rice noodles in warm — not boiling — water for 30 minutes until pliable but still firm with a white core. Drain well.","tip":"Boiling the noodles is the classic mistake. They finish cooking in the wok; boiled noodles turn to paste."},{"step":2,"title":"Mix the sauce","instruction":"Stir the tamarind, fish sauce, and sugar together until the sugar fully dissolves. Taste — it should be aggressively sour, salty, and sweet all at once. Adjust before it goes near the pan.","tip":"Get the sauce right in the bowl. There is no time to fix it once the wok is going."},{"step":3,"title":"Sear the protein","instruction":"Heat 2 tbsp oil in a wok over high heat. Fry the tofu until golden on all sides, then add the shrimp and cook 90 seconds until just pink. Remove both."},{"step":4,"title":"Start the noodles","instruction":"Add the remaining oil, then the garlic and dried shrimp for 20 seconds. Add the drained noodles and the sauce. Toss constantly for 2–3 minutes until the noodles absorb the sauce and turn glossy amber."},{"step":5,"title":"Add the egg","instruction":"Push the noodles aside, pour the beaten egg into the empty space, let it set for 15 seconds, then scramble roughly and fold through the noodles."},{"step":6,"title":"Finish fast","instruction":"Return the shrimp and tofu, add the bean sprouts and scallions, and toss for 45 seconds — the sprouts should stay crunchy. Serve with peanuts, lime, and chilli flakes."}]'::JSONB, 'Everything must be prepped and within arm''s reach before the wok gets hot; the entire cook is under six minutes and there is no pausing. If your noodles clump, a splash of water and continuous tossing will separate them.', ARRAY['Vegetarian: Use soy sauce plus a teaspoon of miso in place of fish sauce, and skip the dried shrimp.','Tamarind: Concentrate strengths vary hugely. Start with two tablespoons and taste up.','Batch size: Cook no more than two portions at a time or the wok cools and the noodles steam.']::TEXT[], ARRAY['Shellfish','Fish','Egg','Peanut','Soy']::TEXT[]),
('bibimbap', 'Bibimbap', 'Warm rice under separately seasoned vegetables, marinated beef, and a fried egg, with gochujang stirred through at the table.', 'https://images.unsplash.com/photo-1733231323270-82dd8a5efe4b', 'Colorful Korean bibimbap bowl with rice, vegetables, egg, and gochujang sauce', 'Min-Jun Oh', '@minjunohkitchen', '', '', '35 min', '25 min', '1 hr', 35, 25, 60, 4, 'Easy', 'Korean', 'Lunch', 'Main Course', ARRAY['Rice Bowl','Vegetable-Forward','Meal Prep','Balanced']::TEXT[], 4.2, 1470, 1817, 612, 31, 72, 22, 7, '[{"amount":"4","unit":"cups","item":"cooked short-grain rice, warm"},{"amount":"8","unit":"oz","item":"beef sirloin, thinly sliced"},{"amount":"3","unit":"tbsp","item":"soy sauce"},{"amount":"1","unit":"tbsp","item":"brown sugar"},{"amount":"1","unit":"tbsp","item":"toasted sesame oil"},{"amount":"4","unit":"cloves","item":"garlic, minced"},{"amount":"6","unit":"oz","item":"spinach"},{"amount":"2","unit":"large","item":"carrots, julienned"},{"amount":"6","unit":"oz","item":"bean sprouts"},{"amount":"6","unit":"oz","item":"shiitake mushrooms, sliced"},{"amount":"1","unit":"","item":"courgette, julienned"},{"amount":"4","unit":"large","item":"eggs"},{"amount":"4","unit":"tbsp","item":"gochujang"},{"amount":"1","unit":"tbsp","item":"rice vinegar"},{"amount":"2","unit":"tbsp","item":"toasted sesame seeds"},{"amount":"","unit":"","item":"Neutral oil and salt"}]'::JSONB, '[{"step":1,"title":"Marinate the beef","instruction":"Combine the soy sauce, brown sugar, sesame oil, and half the garlic. Toss with the sliced beef and leave 20 minutes while you prepare the vegetables."},{"step":2,"title":"Season each vegetable separately","instruction":"Blanch the spinach 30 seconds, squeeze dry, and dress with sesame oil, garlic, and salt. Separately stir-fry the carrots, courgette, mushrooms, and sprouts, each for 2 minutes with a pinch of salt.","tip":"Cooking each vegetable on its own is the entire point of bibimbap. Thrown together they become a single muddy stir-fry."},{"step":3,"title":"Cook the beef","instruction":"Sear the marinated beef in a hot pan for 2 minutes until caramelised at the edges and just cooked through."},{"step":4,"title":"Mix the sauce","instruction":"Stir the gochujang with the rice vinegar, a teaspoon of sesame oil, and a tablespoon of water until pourable."},{"step":5,"title":"Fry the eggs","instruction":"Fry the eggs in hot oil until the whites are crisp and lacy at the edges and the yolks still run."},{"step":6,"title":"Build the bowls","instruction":"Spoon warm rice into four bowls. Arrange each vegetable and the beef in separate wedges on top, place an egg in the centre, and add a spoon of sauce. Stir everything together vigorously at the table."}]'::JSONB, 'Serve in a hot stone bowl (dolsot) if you have one — the rice against the hot surface forms a crisp golden crust that is the best part of the dish. A heavy cast iron pan, preheated well, gets you most of the way there.', ARRAY['Vegetarian: Drop the beef and add extra mushrooms marinated in the same soy mixture.','Meal prep: Everything except the egg keeps 4 days; store components separately and assemble to order.','Gluten-free: Use tamari and confirm your gochujang is wheat-free.']::TEXT[], ARRAY['Soy','Egg','Sesame','Gluten']::TEXT[]),
('rainbow-buddha-bowl', 'Rainbow Buddha Bowl', 'Roasted vegetables, quinoa, and greens under a lemony tahini dressing. Built to be assembled once and eaten all week.', 'https://img.rocket.new/generatedImages/rocket_gen_img_13da08aa3-1772139613628.png', 'Colorful buddha bowl with roasted vegetables, quinoa, and tahini dressing', 'Priya Nair', '@priyanairkitchen', '', '', '15 min', '5 min', '20 min', 15, 5, 20, 4, 'Easy', 'Modern', 'Lunch', 'Main Course', ARRAY['Vegan','Gluten-Free','Meal Prep','Healthy']::TEXT[], 4.3, 980, 5351, 524, 17, 62, 24, 13, '[{"amount":"1","unit":"cup","item":"dry quinoa, rinsed"},{"amount":"1","unit":"large","item":"sweet potato, cubed"},{"amount":"1","unit":"can","item":"chickpeas, drained and dried"},{"amount":"1","unit":"","item":"red onion, wedged"},{"amount":"2","unit":"cups","item":"broccoli florets"},{"amount":"3","unit":"tbsp","item":"olive oil"},{"amount":"1","unit":"tsp","item":"smoked paprika"},{"amount":"1","unit":"tsp","item":"ground cumin"},{"amount":"4","unit":"cups","item":"baby kale or spinach"},{"amount":"1","unit":"","item":"avocado, sliced"},{"amount":"0.33","unit":"cup","item":"tahini"},{"amount":"2","unit":"tbsp","item":"lemon juice"},{"amount":"1","unit":"tbsp","item":"maple syrup"},{"amount":"1","unit":"clove","item":"garlic, grated"},{"amount":"4","unit":"tbsp","item":"warm water"},{"amount":"","unit":"","item":"Salt and pepper"},{"amount":"2","unit":"tbsp","item":"pumpkin seeds"}]'::JSONB, '[{"step":1,"title":"Roast the vegetables","instruction":"Preheat to 425°F (220°C). Toss the sweet potato, chickpeas, onion, and broccoli with the oil, paprika, cumin, salt, and pepper. Spread across two trays so nothing overlaps.","tip":"Two trays, not one. Crowded vegetables steam and never get the browned edges that make this bowl worth eating."},{"step":2,"title":"Roast until charred at the edges","instruction":"Roast 25 minutes, tossing once, until the sweet potato is tender and the chickpeas have started to crisp and split."},{"step":3,"title":"Cook the quinoa","instruction":"Simmer the rinsed quinoa in 2 cups water for 15 minutes, then rest covered off the heat for 5 minutes and fluff with a fork.","tip":"Rinsing removes the saponin coating — unrinsed quinoa tastes soapy and bitter."},{"step":4,"title":"Make the dressing","instruction":"Whisk the tahini, lemon juice, maple syrup, and garlic together. It will seize solid; add the warm water a tablespoon at a time until it becomes a pourable cream. Season well."},{"step":5,"title":"Assemble","instruction":"Divide the greens between four bowls. Add quinoa, then the roasted vegetables in sections, then avocado. Spoon over the dressing and finish with pumpkin seeds."}]'::JSONB, 'Store the components separately rather than assembled — dressed greens go limp within hours. Everything except the avocado holds for 4 days, and the roasted chickpeas re-crisp in an air fryer for 3 minutes.', ARRAY['Swap: Any hardy roasting vegetable works — beets, cauliflower, and butternut all fit.','Nut-free: Tahini is sesame, not nut, but sunflower seed butter substitutes cleanly if needed.','Add protein: Baked tofu or a soft-boiled egg both suit the dressing.']::TEXT[], ARRAY['Sesame']::TEXT[]),
('zucchini-noodles-pesto', 'Zucchini Noodles with Pesto', 'Spiralised courgette dressed raw in fresh basil pesto with blistered tomatoes. The trick is never cooking the noodles.', 'https://img.rocket.new/generatedImages/rocket_gen_img_19ed2983c-1768144943727.png', 'Spiralized zucchini noodles tossed with fresh basil pesto and cherry tomatoes', 'Emma Walsh', '@emmawalshbakes', '', '', '15 min', '—', '15 min', 15, 0, 15, 4, 'Easy', 'Italian', 'Dinner', 'Main Course', ARRAY['Low Carb','Vegetarian','Gluten-Free','Quick']::TEXT[], 4.8, 1689, 5576, 312, 9, 14, 26, 4, '[{"amount":"4","unit":"medium","item":"courgettes, spiralised"},{"amount":"2","unit":"cups","item":"fresh basil leaves"},{"amount":"0.33","unit":"cup","item":"pine nuts, toasted"},{"amount":"2","unit":"cloves","item":"garlic"},{"amount":"0.5","unit":"cup","item":"grated parmesan"},{"amount":"0.5","unit":"cup","item":"extra virgin olive oil"},{"amount":"1","unit":"tbsp","item":"lemon juice"},{"amount":"2","unit":"cups","item":"cherry tomatoes"},{"amount":"","unit":"","item":"Salt and black pepper"},{"amount":"","unit":"","item":"Extra parmesan to serve"}]'::JSONB, '[{"step":1,"title":"Salt and drain the courgette","instruction":"Spiralise the courgettes, toss with a teaspoon of salt, and leave in a colander for 20 minutes. Then squeeze firmly in a clean tea towel. You will be surprised how much water comes out.","tip":"This is the whole recipe. Unsalted courgette noodles release water onto the plate and turn the pesto into soup."},{"step":2,"title":"Blister the tomatoes","instruction":"Sear the cherry tomatoes in a dry hot pan for 4 minutes until the skins split and blacken in places. Set aside."},{"step":3,"title":"Make the pesto","instruction":"Pulse the basil, pine nuts, and garlic in a processor until coarsely chopped. Add the parmesan, then stream in the olive oil with the motor running. Finish with lemon juice, salt, and pepper.","tip":"Pulse rather than blend continuously — over-processing bruises the basil and turns pesto dark and bitter."},{"step":4,"title":"Dress raw","instruction":"Toss the drained courgette noodles with the pesto in a large bowl until fully coated. Do not cook them; they are perfect raw and turn to mush with heat."},{"step":5,"title":"Serve","instruction":"Fold through the blistered tomatoes, top with extra parmesan and cracked pepper, and serve immediately."}]'::JSONB, 'This does not keep — courgette continues to weep even after salting, so dress it within a few minutes of serving. The pesto itself keeps a week under a layer of oil in the fridge, or freezes in ice cube trays.', ARRAY['Vegan: Nutritional yeast plus a little white miso in place of the parmesan.','Nut-free: Sunflower seeds or toasted pumpkin seeds in place of pine nuts.','Half and half: Mixing the courgette with real pasta gives a more substantial dinner while keeping it light.']::TEXT[], ARRAY['Dairy','Tree Nut']::TEXT[]),
('grilled-chicken-quinoa', 'Grilled Chicken & Quinoa', 'Brined and grilled chicken over herbed quinoa with roasted vegetables. High protein, genuinely good cold the next day.', 'https://img.rocket.new/generatedImages/rocket_gen_img_1105e39ee-1784981318339.png', 'Grilled chicken breast sliced over fluffy quinoa with roasted vegetables', 'Sofia Patel', '@sofiapatelkitchen', 'https://images.unsplash.com/photo-1716947674021-1b8b696325c7', 'Portrait of food creator Sofia Patel', '15 min', '15 min', '30 min', 15, 15, 30, 4, 'Easy', 'Mediterranean', 'Dinner', 'Main Course', ARRAY['High Protein','Meal Prep','Gluten-Free','Healthy']::TEXT[], 4.7, 617, 956, 512, 45, 44, 17, 6, '[{"amount":"4","unit":"","item":"chicken breasts"},{"amount":"4","unit":"cups","item":"water"},{"amount":"3","unit":"tbsp","item":"salt"},{"amount":"1","unit":"cup","item":"dry quinoa, rinsed"},{"amount":"2","unit":"cups","item":"chicken stock"},{"amount":"2","unit":"tbsp","item":"olive oil"},{"amount":"1","unit":"tsp","item":"dried oregano"},{"amount":"1","unit":"tsp","item":"smoked paprika"},{"amount":"1","unit":"","item":"lemon (zest and juice)"},{"amount":"1","unit":"","item":"red pepper, chopped"},{"amount":"1","unit":"","item":"courgette, sliced"},{"amount":"0.5","unit":"cup","item":"chopped parsley"},{"amount":"0.25","unit":"cup","item":"chopped mint"},{"amount":"","unit":"","item":"Salt and black pepper"}]'::JSONB, '[{"step":1,"title":"Brine the chicken","instruction":"Dissolve 3 tbsp salt in 4 cups cold water and submerge the chicken breasts for 30 minutes. Rinse and pat completely dry.","tip":"Thirty minutes of brining is the difference between juicy grilled chicken breast and the dry version everyone expects."},{"step":2,"title":"Cook the quinoa","instruction":"Simmer the rinsed quinoa in the stock for 15 minutes, then rest covered for 5 minutes off the heat and fluff."},{"step":3,"title":"Season and grill","instruction":"Rub the dried chicken with olive oil, oregano, paprika, and pepper. Grill over medium-high for 6–7 minutes a side until it reaches 165°F (74°C) internal.","tip":"Use a thermometer. Cutting into the breast to check is how it dries out."},{"step":4,"title":"Char the vegetables","instruction":"Grill the pepper and courgette alongside for 4 minutes a side until marked and tender."},{"step":5,"title":"Rest the chicken","instruction":"Rest the chicken 5 minutes before slicing so the juices redistribute rather than running onto the board."},{"step":6,"title":"Assemble","instruction":"Fold the lemon zest, juice, parsley, and mint through the warm quinoa. Season, top with the vegetables and sliced chicken, and finish with a drizzle of olive oil."}]'::JSONB, 'Everything here holds up in the fridge for 4 days, and the quinoa actually tastes better once the herbs have had a night to infuse. Slice the chicken only when you are ready to eat; sliced chicken dries out much faster than whole.', ARRAY['Swap: Thighs are more forgiving and need 5 minutes a side.','Vegetarian: Halloumi or marinated tempeh, grilled 3 minutes a side.','Make-ahead: Brine the chicken the night before and leave it uncovered in the fridge for a drier surface and better char.']::TEXT[], ARRAY[]::TEXT[]),
('berry-smoothie-bowl', 'Berry Smoothie Bowl', 'A frozen berry base blended thick enough to hold toppings, not a smoothie in a bowl pretending. Ten minutes.', 'https://images.unsplash.com/photo-1623783398179-078261d586d3', 'Thick acai smoothie bowl topped with fresh berries, granola, and coconut flakes', 'Aisha Sharma', '@aishasharmaspice', '', '', '10 min', '—', '10 min', 10, 0, 10, 2, 'Easy', 'Modern', 'Breakfast', 'Breakfast', ARRAY['Vegan-Adaptable','Gluten-Free','No-Cook','Healthy']::TEXT[], 4.4, 837, 1653, 378, 9, 58, 14, 11, '[{"amount":"2","unit":"cups","item":"frozen mixed berries"},{"amount":"1","unit":"","item":"frozen banana"},{"amount":"0.33","unit":"cup","item":"Greek or coconut yoghurt"},{"amount":"2","unit":"tbsp","item":"almond butter"},{"amount":"3","unit":"tbsp","item":"milk of choice"},{"amount":"1","unit":"tbsp","item":"maple syrup"},{"amount":"0.25","unit":"cup","item":"granola"},{"amount":"0.5","unit":"cup","item":"fresh berries"},{"amount":"1","unit":"tbsp","item":"chia seeds"},{"amount":"1","unit":"tbsp","item":"coconut flakes"}]'::JSONB, '[{"step":1,"title":"Use frozen fruit only","instruction":"All the fruit going into the blender must be frozen solid. Fresh fruit plus ice gives you a watery, separating base that will not hold a single topping.","tip":"Freeze the banana in chunks the night before. This is the one thing that has to be planned."},{"step":2,"title":"Blend with almost no liquid","instruction":"Add the frozen berries, banana, yoghurt, almond butter, maple syrup, and just 3 tablespoons of milk to a high-powered blender."},{"step":3,"title":"Use the tamper, not more liquid","instruction":"Blend on high, stopping to scrape down and push the mixture into the blades with a tamper or spatula. Resist adding liquid — it should move like soft-serve, not pour.","tip":"Every extra splash of milk costs you thickness. Be patient with the scraping instead."},{"step":4,"title":"Spoon and smooth","instruction":"Spoon into two chilled bowls and smooth the surface flat with the back of a spoon."},{"step":5,"title":"Top immediately","instruction":"Arrange the granola, fresh berries, chia seeds, and coconut flakes on top and eat straight away, before it starts to melt."}]'::JSONB, 'Chilling the bowls in the freezer for ten minutes beforehand buys you several extra minutes before the base softens. If your blender struggles, let the frozen fruit sit out for exactly three minutes — no longer.', ARRAY['Vegan: Coconut yoghurt and any plant milk; the result is if anything creamier.','Nut-free: Sunflower seed butter or tahini in place of almond butter.','Protein boost: A scoop of vanilla protein powder blends in without thinning the base.']::TEXT[], ARRAY['Tree Nut']::TEXT[])
