INSERT INTO public.recipes (slug, title, description, image, image_alt, creator_name, creator_handle, creator_image, creator_alt, prep_time, cook_time, total_time, prep_minutes, cook_minutes, total_minutes, servings, difficulty, cuisine, meal_type, category, tags, rating, reviews, cooks, calories, protein, carbs, fat, fiber, ingredients, steps, notes, tips, allergens) VALUES
('salmon-avocado-salad', 'Salmon & Avocado Salad', 'Flaked roast salmon over greens with avocado and a sharp lemon vinaigrette. Light but genuinely filling.', 'https://img.rocket.new/generatedImages/rocket_gen_img_1300967e4-1773173912136.png', 'Fresh salmon salad with avocado, mixed greens, and lemon vinaigrette', 'Maria Chen', '@mariachencooks', 'https://images.unsplash.com/photo-1677229888051-211da3f34219', 'Portrait of food creator Maria Chen', '10 min', '10 min', '20 min', 10, 10, 20, 4, 'Easy', 'Modern', 'Lunch', 'Salad', ARRAY['Seafood','High Protein','Gluten-Free','Healthy']::TEXT[], 4.6, 1385, 5201, 432, 31, 12, 30, 7, '[{"amount":"4","unit":"fillets","item":"salmon (5 oz each)"},{"amount":"6","unit":"cups","item":"mixed salad greens"},{"amount":"2","unit":"","item":"avocados, sliced"},{"amount":"1","unit":"","item":"cucumber, sliced"},{"amount":"1","unit":"cup","item":"cherry tomatoes, halved"},{"amount":"0.25","unit":"","item":"red onion, thinly sliced"},{"amount":"4","unit":"tbsp","item":"extra virgin olive oil"},{"amount":"2","unit":"tbsp","item":"lemon juice"},{"amount":"1","unit":"tsp","item":"Dijon mustard"},{"amount":"1","unit":"tsp","item":"honey"},{"amount":"","unit":"","item":"Salt and black pepper"},{"amount":"2","unit":"tbsp","item":"fresh dill"}]'::JSONB, '[{"step":1,"title":"Roast the salmon","instruction":"Heat the oven to 400°F (205°C). Season the salmon, place skin-side down on a lined tray, and roast 12 minutes until it flakes at the thickest point.","tip":"Pull it at 125°F internal — it carries on cooking as it rests."},{"step":2,"title":"Rest and flake","instruction":"Rest 5 minutes, then break into large flakes with a fork. Large pieces keep the salad from turning into mush."},{"step":3,"title":"Whisk the dressing","instruction":"Whisk the oil, lemon juice, Dijon, and honey with salt and pepper until it thickens and stops separating."},{"step":4,"title":"Dress the greens only","instruction":"Toss the greens, cucumber, tomatoes, and onion with two-thirds of the dressing. Dress the leaves, not the salmon."},{"step":5,"title":"Assemble","instruction":"Top with the salmon flakes and avocado, spoon over the remaining dressing, and finish with dill and cracked pepper."}]'::JSONB, 'Salmon is just as good cold here, so leftover roast salmon from another meal works perfectly. Add the avocado at the last moment or it browns and softens against the dressing.', ARRAY['Swap: Hot-smoked salmon or tinned salmon both work with no cooking at all.','Make-ahead: Roast the salmon and mix the dressing up to 2 days ahead; assemble to order.','Add substance: A cup of cooked quinoa or a handful of croutons turns this into a full dinner.']::TEXT[], ARRAY['Fish','Mustard']::TEXT[]),
('lentil-soup', 'Lentil Soup', 'Red lentils simmered with cumin and turmeric until they collapse into a thick, golden soup. Finished with lemon, which is what makes it.', 'https://img.rocket.new/generatedImages/rocket_gen_img_1a176c584-1782375166859.png', 'Hearty red lentil soup with cumin, turmeric, and fresh lemon in a bowl', 'Leila Hassan', '@leilahassantable', '', '', '10 min', '25 min', '35 min', 10, 25, 35, 6, 'Easy', 'Middle Eastern', 'Lunch', 'Soup', ARRAY['Vegan','Gluten-Free','Budget','Freezer-Friendly']::TEXT[], 4.3, 1890, 2768, 286, 15, 42, 7, 12, '[{"amount":"1.5","unit":"cups","item":"red lentils, rinsed"},{"amount":"3","unit":"tbsp","item":"olive oil"},{"amount":"1","unit":"large","item":"onion, diced"},{"amount":"2","unit":"","item":"carrots, diced"},{"amount":"4","unit":"cloves","item":"garlic, minced"},{"amount":"2","unit":"tsp","item":"ground cumin"},{"amount":"1","unit":"tsp","item":"turmeric"},{"amount":"1","unit":"tsp","item":"ground coriander"},{"amount":"0.5","unit":"tsp","item":"cayenne"},{"amount":"6","unit":"cups","item":"vegetable stock"},{"amount":"1","unit":"large","item":"lemon, juiced"},{"amount":"","unit":"","item":"Salt and black pepper"},{"amount":"","unit":"","item":"Fresh cilantro and olive oil to finish"}]'::JSONB, '[{"step":1,"title":"Build the base","instruction":"Heat the oil and cook the onion and carrot for 8 minutes until soft and lightly golden. Add the garlic for 30 seconds."},{"step":2,"title":"Bloom the spices","instruction":"Add the cumin, turmeric, coriander, and cayenne and stir for 45 seconds in the hot oil until fragrant.","tip":"Frying the spices in oil rather than dropping them into the stock is what gives the soup its depth."},{"step":3,"title":"Simmer","instruction":"Add the rinsed lentils and stock. Bring to a boil, then simmer partly covered for 25 minutes until the lentils have completely broken down."},{"step":4,"title":"Adjust the texture","instruction":"Blend roughly with a stick blender for a thicker soup, or leave it as is. Loosen with hot water if it has gone too thick."},{"step":5,"title":"Finish with acid","instruction":"Off the heat, stir in the lemon juice and season generously. Taste — if it seems flat, it needs more lemon, not more salt.","tip":"Lemon at the end transforms this soup. Do not skip it."}]'::JSONB, 'Red lentils need no soaking and collapse on their own, which is why this works in 35 minutes. It thickens considerably in the fridge — loosen with stock when reheating. Freezes for 3 months.', ARRAY['Swap: Brown or green lentils hold their shape and need about 40 minutes instead.','Richer version: A swirl of coconut milk or yoghurt at the table.','Make-ahead: Better on day two once the spices settle.']::TEXT[], ARRAY[]::TEXT[]),
('sunday-pot-roast', 'Sunday Pot Roast', 'Chuck roast braised low with root vegetables until it falls apart under a fork, with gravy made from the braising liquid.', 'https://img.rocket.new/generatedImages/rocket_gen_img_118501734-1771898937177.png', 'Slow-cooked pot roast with root vegetables in a Dutch oven', 'Marco Rossi', '@marcorossicucina', '', '', '25 min', '2.6 hrs', '3 hrs', 25, 155, 180, 6, 'Medium', 'American', 'Dinner', 'Main Course', ARRAY['Comfort','Family','Slow-Cooked','One-Pot']::TEXT[], 4.5, 1006, 8494, 648, 48, 34, 34, 5, '[{"amount":"4","unit":"lb","item":"beef chuck roast"},{"amount":"2","unit":"tbsp","item":"neutral oil"},{"amount":"2","unit":"large","item":"onions, quartered"},{"amount":"4","unit":"","item":"carrots, cut into chunks"},{"amount":"1.5","unit":"lb","item":"baby potatoes"},{"amount":"4","unit":"cloves","item":"garlic, smashed"},{"amount":"3","unit":"tbsp","item":"tomato paste"},{"amount":"1","unit":"cup","item":"red wine"},{"amount":"3","unit":"cups","item":"beef stock"},{"amount":"3","unit":"sprigs","item":"fresh thyme"},{"amount":"2","unit":"","item":"bay leaves"},{"amount":"2","unit":"tbsp","item":"all-purpose flour"},{"amount":"","unit":"","item":"Salt and coarse black pepper"}]'::JSONB, '[{"step":1,"title":"Season hard and early","instruction":"Pat the roast dry and season aggressively with salt and pepper on all sides. If you have time, do this the night before and leave it uncovered in the fridge.","tip":"A dry, well-salted surface is what lets you build a proper crust."},{"step":2,"title":"Sear","instruction":"Heat the oil in a Dutch oven over high heat and sear the roast 4 minutes per side until deeply browned all over. Remove to a plate.","tip":"Do not rush the sear. That crust is most of the flavour in the finished gravy."},{"step":3,"title":"Build the braise","instruction":"Lower the heat, cook the onions 5 minutes, then stir in the tomato paste and cook 2 minutes until it darkens. Add the wine and scrape every browned bit off the base."},{"step":4,"title":"Braise low","instruction":"Return the roast with the stock, garlic, thyme, and bay. Cover and cook at 325°F (165°C) for 2.5 hours."},{"step":5,"title":"Add the vegetables","instruction":"Add the carrots and potatoes and cook 45 minutes more, until the beef pulls apart with no resistance at all.","tip":"The beef is not done at \"tender\" — wait for \"falls apart\"."},{"step":6,"title":"Make the gravy","instruction":"Lift out the meat and vegetables. Skim the fat, whisk the flour into a little of it, then whisk back into the liquid and simmer 5 minutes until thickened. Season and serve."}]'::JSONB, 'Chuck is the right cut because its connective tissue melts into gelatin over a long braise — leaner cuts just dry out. The whole thing is better made a day ahead: cool it in the liquid, then reheat gently.', ARRAY['Swap: Brisket or short rib both braise well on the same timeline.','No wine: Use extra stock plus a tablespoon of balsamic vinegar.','Slow cooker: 8 hours on low, but sear the meat in a pan first regardless.']::TEXT[], ARRAY['Gluten']::TEXT[]),
('grandmas-chicken-soup', 'Grandma''s Chicken Soup', 'A whole chicken simmered into its own broth with vegetables and noodles. The version that actually helps when you are ill.', 'https://images.unsplash.com/photo-1727417376054-a3a6d6f31999', 'Hearty homemade chicken noodle soup with vegetables in a white bowl', 'Rosa Gutierrez', '@rosagutierrezcocina', '', '', '20 min', '1.2 hrs', '1.5 hrs', 20, 70, 90, 6, 'Easy', 'American', 'Lunch', 'Soup', ARRAY['Comfort','Family','From Scratch','Freezer-Friendly']::TEXT[], 4.2, 124, 6689, 412, 34, 38, 12, 4, '[{"amount":"1","unit":"","item":"whole chicken (4 lb)"},{"amount":"3","unit":"","item":"carrots, sliced"},{"amount":"3","unit":"stalks","item":"celery, sliced"},{"amount":"2","unit":"","item":"onions, quartered"},{"amount":"4","unit":"cloves","item":"garlic, smashed"},{"amount":"3","unit":"sprigs","item":"fresh thyme"},{"amount":"2","unit":"","item":"bay leaves"},{"amount":"10","unit":"cups","item":"cold water"},{"amount":"8","unit":"oz","item":"egg noodles"},{"amount":"0.25","unit":"cup","item":"chopped parsley"},{"amount":"1","unit":"tbsp","item":"lemon juice"},{"amount":"","unit":"","item":"Salt and black pepper"}]'::JSONB, '[{"step":1,"title":"Start in cold water","instruction":"Put the whole chicken in a stockpot with the onions, garlic, thyme, bay, and half the carrot and celery. Cover with cold water.","tip":"Cold water draws flavour out of the bird. Starting hot seals it in and gives you a weaker broth."},{"step":2,"title":"Simmer, never boil","instruction":"Bring slowly to a bare simmer and hold it there for 75 minutes, skimming the grey foam off the top for the first 15 minutes.","tip":"Boiling makes the broth cloudy and the meat stringy. Bare simmer throughout."},{"step":3,"title":"Pull the chicken","instruction":"Lift the chicken out and let it cool enough to handle. Strain the broth and discard the spent vegetables."},{"step":4,"title":"Shred","instruction":"Pull the meat off the bones in large shreds, discarding skin and bones. You should get about 4 cups."},{"step":5,"title":"Finish the soup","instruction":"Return the broth to the pot with the remaining carrot and celery. Simmer 10 minutes, add the noodles and cook until just tender, then return the chicken."},{"step":6,"title":"Season properly","instruction":"Add the parsley and lemon juice, then salt generously — home-made broth needs far more salt than people expect. Taste and keep adjusting."}]'::JSONB, 'Cook the noodles separately if you plan on leftovers; left in the broth they swell overnight and drink all the liquid. Broth alone freezes for 3 months.', ARRAY['Shortcut: Bone-in thighs instead of a whole bird cuts the simmer to 45 minutes.','Gluten-free: Rice or gluten-free pasta, cooked separately and added per bowl.','Extra body: Simmer the stripped carcass another hour for a richer second batch of broth.']::TEXT[], ARRAY['Gluten','Egg','Celery']::TEXT[]),
('classic-lasagna', 'Classic Lasagna', 'Slow meat ragù layered with béchamel and pasta, baked until the top blisters. A two-hour project that feeds a crowd.', 'https://img.rocket.new/generatedImages/rocket_gen_img_18ea24141-1772646976917.png', 'Layered classic lasagna with meat sauce and bubbling mozzarella cheese', 'Maria Chen', '@mariachencooks', 'https://images.unsplash.com/photo-1677229888051-211da3f34219', 'Portrait of food creator Maria Chen', '35 min', '1.4 hrs', '2 hrs', 35, 85, 120, 8, 'Medium', 'Italian', 'Dinner', 'Main Course', ARRAY['Comfort','Family','Make-Ahead','Crowd Pleaser']::TEXT[], 4.4, 440, 4587, 682, 38, 52, 36, 4, '[{"amount":"1","unit":"lb","item":"ground beef"},{"amount":"0.5","unit":"lb","item":"Italian sausage, casings removed"},{"amount":"1","unit":"","item":"onion, finely diced"},{"amount":"3","unit":"cloves","item":"garlic, minced"},{"amount":"2","unit":"tbsp","item":"tomato paste"},{"amount":"28","unit":"oz","item":"crushed tomatoes"},{"amount":"0.5","unit":"cup","item":"red wine"},{"amount":"1","unit":"tsp","item":"dried oregano"},{"amount":"4","unit":"tbsp","item":"butter"},{"amount":"4","unit":"tbsp","item":"all-purpose flour"},{"amount":"3","unit":"cups","item":"whole milk, warm"},{"amount":"","unit":"","item":"Pinch of nutmeg"},{"amount":"12","unit":"","item":"lasagna sheets"},{"amount":"2","unit":"cups","item":"grated mozzarella"},{"amount":"1","unit":"cup","item":"grated parmesan"},{"amount":"","unit":"","item":"Salt and black pepper"}]'::JSONB, '[{"step":1,"title":"Brown the meat properly","instruction":"Brown the beef and sausage in a wide pan over high heat without stirring for the first 3 minutes, so it crusts rather than steams. Break up and continue until no pink remains.","tip":"Crowding the pan or stirring constantly gives you grey, boiled mince and a flat ragù."},{"step":2,"title":"Build the ragù","instruction":"Add the onion and cook 5 minutes, then the garlic and tomato paste for 2 minutes. Add the wine, reduce by half, then the tomatoes and oregano. Simmer at least 45 minutes, uncovered, until thick."},{"step":3,"title":"Make the béchamel","instruction":"Melt the butter, whisk in the flour, and cook 2 minutes. Add the warm milk in stages, whisking hard after each addition, until smooth and thick enough to coat a spoon. Season with salt and nutmeg.","tip":"Warm milk added gradually is the whole secret to a lump-free béchamel."},{"step":4,"title":"Layer","instruction":"In a deep dish, spread a thin layer of ragù, then pasta, then ragù, then béchamel, then a scatter of both cheeses. Repeat for four layers, finishing with béchamel and cheese."},{"step":5,"title":"Bake covered, then uncovered","instruction":"Bake at 375°F (190°C) covered with foil for 30 minutes, then uncover and bake 20 minutes more until the top is browned and bubbling."},{"step":6,"title":"Rest properly","instruction":"Rest at least 25 minutes before cutting. Cut it hot and it slides apart onto the plate.","tip":"The rest is not optional. It is what lets you serve neat squares."}]'::JSONB, 'The ragù can simmer for 3 hours if you have them, and it is noticeably better for it. Assembled unbaked lasagna keeps 2 days in the fridge or 3 months frozen — bake from frozen at 350°F for 90 minutes, covered.', ARRAY['Vegetarian: Lentils and finely chopped mushrooms in place of the meat, browned the same way.','No-boil sheets: Work fine, but add half a cup of water to the ragù since they absorb more liquid.','Make-ahead: Assemble a day ahead — the layers set and cut far more cleanly.']::TEXT[], ARRAY['Gluten','Dairy','Egg']::TEXT[]),
('apple-pie-scratch', 'Apple Pie from Scratch', 'All-butter lattice crust over spiced apples cooked down first so the filling never leaves a gap under the lid.', 'https://images.unsplash.com/photo-1638329261528-1932b0e63212', 'Golden homemade apple pie with lattice crust cooling on a wooden table', 'Emma Walsh', '@emmawalshbakes', '', '', '45 min', '1.8 hrs', '2.5 hrs', 45, 105, 150, 8, 'Medium', 'American', 'Dessert', 'Dessert', ARRAY['Baking','From Scratch','Holiday','Vegetarian']::TEXT[], 4.4, 1616, 1761, 452, 5, 62, 21, 4, '[{"amount":"2.5","unit":"cups","item":"all-purpose flour"},{"amount":"1","unit":"cup","item":"cold unsalted butter, cubed"},{"amount":"1","unit":"tsp","item":"salt"},{"amount":"1","unit":"tbsp","item":"sugar"},{"amount":"6","unit":"tbsp","item":"ice water"},{"amount":"3","unit":"lb","item":"baking apples, peeled and sliced"},{"amount":"0.75","unit":"cup","item":"brown sugar"},{"amount":"2","unit":"tbsp","item":"lemon juice"},{"amount":"2","unit":"tsp","item":"ground cinnamon"},{"amount":"0.25","unit":"tsp","item":"nutmeg"},{"amount":"3","unit":"tbsp","item":"cornstarch"},{"amount":"2","unit":"tbsp","item":"butter for the filling"},{"amount":"1","unit":"","item":"egg, beaten"},{"amount":"","unit":"","item":"Demerara sugar for the top"}]'::JSONB, '[{"step":1,"title":"Keep everything cold","instruction":"Rub the cold cubed butter into the flour, salt, and sugar until you have pieces ranging from breadcrumb to pea size. Add ice water a tablespoon at a time until it just holds together.","tip":"Visible butter pieces are what create flaky layers. A smooth, uniform dough bakes up short and crumbly."},{"step":2,"title":"Chill the dough","instruction":"Divide in two, flatten into discs, wrap, and refrigerate at least 1 hour."},{"step":3,"title":"Pre-cook the filling","instruction":"Cook the apples with the brown sugar, lemon, cinnamon, nutmeg, and butter over medium heat for 10 minutes until they soften and release liquid. Stir in the cornstarch and cook 2 minutes more, then cool completely.","tip":"Raw apples shrink as they bake and leave a hollow dome. Cooking them first solves this entirely."},{"step":4,"title":"Line the tin","instruction":"Roll one disc and line a 9-inch pie dish, leaving an overhang. Fill with the cooled apples, mounding slightly."},{"step":5,"title":"Lattice","instruction":"Roll the second disc, cut into strips, and weave over the top. Trim, fold the overhang under, and crimp the edge firmly."},{"step":6,"title":"Bake hot then moderate","instruction":"Brush with egg and scatter demerara. Bake at 425°F (220°C) for 20 minutes, then reduce to 375°F (190°C) for 35–40 minutes until deep golden and bubbling at the centre."}]'::JSONB, 'Use a mix of firm tart apples (Granny Smith, Bramley) and sweeter ones (Honeycrisp, Braeburn) — a single variety gives a one-note filling. Cool at least 3 hours before slicing; warm pie will run.', ARRAY['Make-ahead: Dough keeps 3 days chilled or 3 months frozen.','Soggy base: Bake on a preheated baking sheet on the lowest oven rack.','Vegan: A good block vegan butter works in the crust; use plant milk for the wash.']::TEXT[], ARRAY['Gluten','Dairy','Egg']::TEXT[]),
('beef-stew', 'Beef Stew', 'Beef browned in batches then braised with red wine and root vegetables until the sauce turns glossy and thick.', 'https://images.unsplash.com/photo-1517847043-aa5de082df8a', 'Rich beef stew with carrots, potatoes, and herbs in a deep pot', 'Jake Torres', '@jaketorrescooks', 'https://images.unsplash.com/photo-1572015837827-01671d41e102', 'Portrait of food creator Jake Torres', '25 min', '1.6 hrs', '2 hrs', 25, 95, 120, 6, 'Medium', 'American', 'Dinner', 'Main Course', ARRAY['Comfort','Slow-Cooked','One-Pot','Freezer-Friendly']::TEXT[], 5.0, 401, 1407, 572, 42, 32, 26, 5, '[{"amount":"3","unit":"lb","item":"beef chuck, cut into 2-inch cubes"},{"amount":"3","unit":"tbsp","item":"all-purpose flour"},{"amount":"3","unit":"tbsp","item":"neutral oil"},{"amount":"2","unit":"","item":"onions, diced"},{"amount":"3","unit":"","item":"carrots, chunked"},{"amount":"2","unit":"stalks","item":"celery, sliced"},{"amount":"4","unit":"cloves","item":"garlic, minced"},{"amount":"2","unit":"tbsp","item":"tomato paste"},{"amount":"1.5","unit":"cups","item":"red wine"},{"amount":"4","unit":"cups","item":"beef stock"},{"amount":"1.5","unit":"lb","item":"potatoes, chunked"},{"amount":"3","unit":"sprigs","item":"thyme"},{"amount":"2","unit":"","item":"bay leaves"},{"amount":"","unit":"","item":"Salt and black pepper"},{"amount":"","unit":"","item":"Chopped parsley to finish"}]'::JSONB, '[{"step":1,"title":"Dry and dredge","instruction":"Pat the beef completely dry, season well, and toss in the flour. Wet meat will not brown, and the flour also thickens the finished sauce."},{"step":2,"title":"Brown in batches","instruction":"Sear the beef in the oil over high heat in three separate batches, 4 minutes per batch, until dark brown. Never crowd the pot.","tip":"Three batches feels tedious and it is the single biggest factor in how good the stew tastes."},{"step":3,"title":"Soften the aromatics","instruction":"Cook the onion, carrot, and celery in the same pot for 6 minutes, then add the garlic and tomato paste for 2 minutes until darkened."},{"step":4,"title":"Deglaze","instruction":"Pour in the wine and scrape the base clean. Reduce by half, about 5 minutes."},{"step":5,"title":"Braise","instruction":"Return the beef with the stock, thyme, and bay. Cover and cook at 325°F (165°C) for 90 minutes."},{"step":6,"title":"Add potatoes and finish","instruction":"Add the potatoes and cook 40 minutes more uncovered, until the beef shreds easily and the sauce has thickened. Season, top with parsley."}]'::JSONB, 'If the sauce is still thin at the end, lift out the solids and reduce the liquid hard for 10 minutes. Like most braises this is better the next day, and it freezes for 3 months.', ARRAY['No wine: Extra stock plus a tablespoon of Worcestershire sauce.','Gluten-free: Cornstarch slurry at the end instead of dredging in flour.','Deeper flavour: A parmesan rind or an anchovy dropped into the braise adds savoury depth nobody will identify.']::TEXT[], ARRAY['Gluten','Celery']::TEXT[]),
('roast-chicken', 'Roast Chicken', 'Dry-brined bird roasted hot for crisp skin, rested properly. The technique that makes every other roast chicken seem wet.', 'https://images.unsplash.com/photo-1602534923950-d2c7e6be0ca0', 'Golden roast chicken with crispy skin and herbs on a roasting pan', 'Sofia Romano', '@sofiaromanoeats', '', '', '15 min', '1.3 hrs', '1.5 hrs', 15, 75, 90, 4, 'Easy', 'American', 'Dinner', 'Main Course', ARRAY['Classic','Family','Gluten-Free','One-Pan']::TEXT[], 4.7, 719, 6154, 548, 46, 6, 38, 1, '[{"amount":"1","unit":"","item":"whole chicken (4 lb)"},{"amount":"1","unit":"tbsp","item":"salt"},{"amount":"1","unit":"tsp","item":"black pepper"},{"amount":"3","unit":"tbsp","item":"softened butter"},{"amount":"1","unit":"","item":"lemon, halved"},{"amount":"1","unit":"","item":"head garlic, halved crosswise"},{"amount":"4","unit":"sprigs","item":"thyme"},{"amount":"1","unit":"","item":"onion, thickly sliced"},{"amount":"2","unit":"","item":"carrots, chunked"},{"amount":"2","unit":"tbsp","item":"olive oil"}]'::JSONB, '[{"step":1,"title":"Dry-brine the day before","instruction":"Pat the chicken dry, salt it all over including inside the cavity, and leave uncovered on a rack in the fridge overnight.","tip":"Overnight uncovered is what dries the skin out enough to crisp. This one step outweighs everything else."},{"step":2,"title":"Bring to room temperature","instruction":"Take the bird out 45 minutes before roasting. A fridge-cold chicken cooks unevenly."},{"step":3,"title":"Butter under the skin","instruction":"Loosen the breast skin with your fingers and push the softened butter underneath. Rub the outside with olive oil and pepper."},{"step":4,"title":"Stuff and truss","instruction":"Put the lemon, garlic, and thyme in the cavity. Tie the legs together and tuck the wing tips under."},{"step":5,"title":"Roast hot","instruction":"Set the chicken on the onion and carrot in a roasting tin. Roast at 425°F (220°C) for 55–65 minutes, until the thickest part of the thigh reads 165°F (74°C).","tip":"Use a thermometer in the thigh, not the breast. Thigh is always the last part to cook."},{"step":6,"title":"Rest 20 minutes","instruction":"Rest on a board for a full 20 minutes before carving. Carve too early and the juices end up on the board rather than in the meat."}]'::JSONB, 'The vegetables underneath soak up the drippings and become the side dish. If the skin browns too fast, tent loosely with foil for the last 15 minutes rather than lowering the oven.', ARRAY['Spatchcock: Remove the backbone and flatten to cut roasting to 45 minutes with even crisper skin.','Gravy: Deglaze the tin with a splash of wine and stock, then simmer and strain.','Leftovers: The carcass makes excellent stock; simmer 2 hours with the spent aromatics.']::TEXT[], ARRAY['Dairy']::TEXT[]),
('fluffy-buttermilk-pancakes', 'Fluffy Buttermilk Pancakes', 'Tall, tender pancakes from a lumpy batter that rests. Two rules: do not overmix, do not press them.', 'https://img.rocket.new/generatedImages/rocket_gen_img_1c1966aab-1767129915183.png', 'Stack of fluffy golden buttermilk pancakes with maple syrup and fresh berries', 'Emma Walsh', '@emmawalshbakes', '', '', '10 min', '10 min', '20 min', 10, 10, 20, 4, 'Easy', 'American', 'Breakfast', 'Breakfast', ARRAY['Vegetarian','Family','Brunch','Quick']::TEXT[], 4.9, 1736, 769, 438, 12, 58, 17, 2, '[{"amount":"2","unit":"cups","item":"all-purpose flour"},{"amount":"2","unit":"tbsp","item":"sugar"},{"amount":"2","unit":"tsp","item":"baking powder"},{"amount":"0.5","unit":"tsp","item":"baking soda"},{"amount":"0.5","unit":"tsp","item":"salt"},{"amount":"2","unit":"cups","item":"buttermilk"},{"amount":"2","unit":"large","item":"eggs"},{"amount":"4","unit":"tbsp","item":"melted butter"},{"amount":"1","unit":"tsp","item":"vanilla extract"},{"amount":"","unit":"","item":"Butter for the pan"},{"amount":"","unit":"","item":"Maple syrup and berries to serve"}]'::JSONB, '[{"step":1,"title":"Whisk the dry ingredients","instruction":"Whisk the flour, sugar, baking powder, baking soda, and salt together thoroughly so the raising agents are evenly distributed."},{"step":2,"title":"Combine wet separately","instruction":"Whisk the buttermilk, eggs, melted butter, and vanilla in a second bowl."},{"step":3,"title":"Mix badly, on purpose","instruction":"Pour the wet into the dry and fold just until no dry flour remains. The batter should be visibly lumpy. Stop there.","tip":"Every extra stir develops gluten. Lumps are what you want — smooth batter makes flat, chewy pancakes."},{"step":4,"title":"Rest the batter","instruction":"Leave it 10 minutes. The flour hydrates and the baking powder starts working, and you can see the batter puff slightly."},{"step":5,"title":"Cook on medium-low","instruction":"Cook in a buttered pan over medium-low heat. Pour a scant half cup per pancake and wait until bubbles form and the edges look dry, about 3 minutes, before flipping.","tip":"Medium-low. Too hot and the outside burns before the middle sets."},{"step":6,"title":"Never press down","instruction":"Flip once and cook 2 minutes more. Do not press the pancake with the spatula — that squeezes out all the air you just built."}]'::JSONB, 'Buttermilk reacting with baking soda is what gives the lift; a substitute of milk plus a tablespoon of lemon juice, left 10 minutes, works nearly as well. Hold cooked pancakes in a 200°F oven on a rack rather than stacked, so they stay crisp-edged.', ARRAY['Make-ahead: Cooked pancakes freeze well between parchment; reheat in a toaster.','Dairy-free: Plant milk with lemon juice, and oil in place of butter.','Add-ins: Scatter blueberries or chocolate chips onto the wet side after pouring, not into the batter.']::TEXT[], ARRAY['Gluten','Dairy','Egg']::TEXT[]),
('eggs-benedict', 'Eggs Benedict', 'Poached eggs and ham on a toasted muffin under blender hollandaise — the version that does not split.', 'https://img.rocket.new/generatedImages/rocket_gen_img_1890ea5f7-1772766498216.png', 'Classic eggs benedict with hollandaise sauce on toasted English muffin', 'Marco Rossi', '@marcorossicucina', '', '', '15 min', '10 min', '25 min', 15, 10, 25, 4, 'Medium', 'American', 'Breakfast', 'Breakfast', ARRAY['Brunch','Classic','Weekend']::TEXT[], 4.8, 834, 5435, 592, 26, 28, 43, 2, '[{"amount":"4","unit":"","item":"English muffins, split"},{"amount":"8","unit":"slices","item":"good ham or back bacon"},{"amount":"8","unit":"large","item":"eggs, for poaching"},{"amount":"3","unit":"large","item":"egg yolks"},{"amount":"1","unit":"cup","item":"unsalted butter, melted and hot"},{"amount":"1","unit":"tbsp","item":"lemon juice"},{"amount":"1","unit":"tsp","item":"Dijon mustard"},{"amount":"","unit":"","item":"Pinch of cayenne"},{"amount":"2","unit":"tbsp","item":"white vinegar"},{"amount":"","unit":"","item":"Salt"},{"amount":"","unit":"","item":"Chives to finish"}]'::JSONB, '[{"step":1,"title":"Make hollandaise in a blender","instruction":"Blend the yolks, lemon juice, Dijon, cayenne, and a pinch of salt for 15 seconds. With the motor running, pour the hot melted butter in a very thin, steady stream.","tip":"Thin stream, hot butter, motor running. Pouring too fast is the only way this splits."},{"step":2,"title":"Hold it warm","instruction":"Pour into a bowl and cover; it stays fluid for about 30 minutes in a warm spot. If it thickens, whisk in a teaspoon of warm water."},{"step":3,"title":"Set up the poaching water","instruction":"Bring a wide pan of water to a bare simmer with the vinegar. Crack each egg into a fine sieve first to drain off the loose white."},{"step":4,"title":"Poach","instruction":"Slide the eggs in and cook 3 minutes for runny yolks. Lift out with a slotted spoon onto kitchen paper."},{"step":5,"title":"Toast and crisp","instruction":"Toast the muffins until well coloured and warm the ham in a dry pan until the edges curl."},{"step":6,"title":"Assemble fast","instruction":"Muffin, ham, egg, a generous spoon of hollandaise, chives, and cracked pepper. Serve immediately — this is not a dish that waits."}]'::JSONB, 'If the hollandaise splits, blend in a fresh yolk with a teaspoon of warm water and stream the broken sauce back in. Eggs can be poached ahead, held in cold water, and reheated for 30 seconds in hot water — a genuine lifesaver when cooking for four.', ARRAY['Royale: Smoked salmon in place of the ham.','Florentine: Wilted, well-squeezed spinach for a vegetarian version.','Make-ahead: Poach the eggs the day before; make the hollandaise no more than an hour ahead.']::TEXT[], ARRAY['Egg','Dairy','Gluten']::TEXT[]),
('overnight-oats', 'Overnight Oats', 'Five minutes of stirring at night for a cold, creamy breakfast waiting in the morning.', 'https://img.rocket.new/generatedImages/rocket_gen_img_13d3c8d39-1772083435970.png', 'Creamy overnight oats in a mason jar topped with fresh fruit and nuts', 'Priya Nair', '@priyanairkitchen', '', '', '5 min', '—', '5 min', 5, 0, 5, 2, 'Easy', 'Modern', 'Breakfast', 'Breakfast', ARRAY['Make-Ahead','No-Cook','Healthy','Meal Prep']::TEXT[], 4.2, 1368, 724, 368, 14, 52, 12, 8, '[{"amount":"1","unit":"cup","item":"rolled oats"},{"amount":"1","unit":"cup","item":"milk of choice"},{"amount":"0.5","unit":"cup","item":"Greek yoghurt"},{"amount":"2","unit":"tbsp","item":"chia seeds"},{"amount":"2","unit":"tbsp","item":"maple syrup"},{"amount":"0.5","unit":"tsp","item":"vanilla extract"},{"amount":"","unit":"","item":"Pinch of salt"},{"amount":"2","unit":"tbsp","item":"almond butter"},{"amount":"","unit":"","item":"Fresh fruit and nuts to top"}]'::JSONB, '[{"step":1,"title":"Use rolled, not instant","instruction":"Rolled oats hold their texture overnight. Instant oats dissolve into paste and steel-cut stay unpleasantly hard.","tip":"This is the only ingredient choice that really matters here."},{"step":2,"title":"Mix the base","instruction":"Stir the oats, milk, yoghurt, chia seeds, maple syrup, vanilla, and salt together in a jar until evenly combined."},{"step":3,"title":"Get the ratio right","instruction":"Aim for roughly equal parts oats and liquid by volume. Too little and it sets stodgy; too much and it never thickens."},{"step":4,"title":"Chill overnight","instruction":"Seal and refrigerate at least 6 hours. The chia continues thickening for the first couple of hours."},{"step":5,"title":"Top in the morning","instruction":"Stir, loosen with a splash of milk if needed, then add the almond butter, fruit, and nuts just before eating."}]'::JSONB, 'Keeps 4 days refrigerated, so make four jars at once. Add fruit only on the morning you eat it — berries stirred in the night before bleed and go soft.', ARRAY['Vegan: Coconut or soy yoghurt and any plant milk.','Higher protein: A scoop of protein powder, with an extra splash of milk to compensate.','Warm version: Microwave 90 seconds for something closer to porridge.']::TEXT[], ARRAY['Dairy','Tree Nut']::TEXT[]),
('french-toast', 'French Toast', 'Thick, slightly stale bread soaked properly and fried in butter until the outside caramelises and the centre turns to custard.', 'https://images.unsplash.com/photo-1623375477518-9d04f307e82b', 'Golden thick-cut French toast dusted with powdered sugar and fresh strawberries', 'Sofia Patel', '@sofiapatelkitchen', 'https://images.unsplash.com/photo-1716947674021-1b8b696325c7', 'Portrait of food creator Sofia Patel', '10 min', '5 min', '15 min', 10, 5, 15, 4, 'Easy', 'American', 'Breakfast', 'Breakfast', ARRAY['Brunch','Vegetarian','Quick','Family']::TEXT[], 4.7, 380, 5116, 462, 15, 52, 21, 2, '[{"amount":"8","unit":"thick slices","item":"day-old brioche or challah"},{"amount":"4","unit":"large","item":"eggs"},{"amount":"1","unit":"cup","item":"whole milk"},{"amount":"0.25","unit":"cup","item":"heavy cream"},{"amount":"3","unit":"tbsp","item":"sugar"},{"amount":"2","unit":"tsp","item":"vanilla extract"},{"amount":"1","unit":"tsp","item":"ground cinnamon"},{"amount":"","unit":"","item":"Pinch of salt"},{"amount":"4","unit":"tbsp","item":"butter for frying"},{"amount":"","unit":"","item":"Maple syrup, powdered sugar, and berries to serve"}]'::JSONB, '[{"step":1,"title":"Use stale bread","instruction":"Day-old bread cut thick — at least an inch — is essential. Fresh bread falls apart in the custard.","tip":"If your bread is fresh, dry the slices in a 300°F oven for 8 minutes first."},{"step":2,"title":"Whisk the custard smooth","instruction":"Whisk the eggs first on their own until completely uniform, then add the milk, cream, sugar, vanilla, cinnamon, and salt. Streaks of unbeaten white cook into rubbery patches."},{"step":3,"title":"Soak, do not dunk","instruction":"Soak each slice 20 seconds per side. It should be saturated but still hold its shape when lifted.","tip":"Under-soaked is dry bread; over-soaked collapses in the pan. Twenty seconds a side."},{"step":4,"title":"Fry on medium","instruction":"Melt butter in a pan over medium heat and cook 3 minutes per side until deep golden and slightly puffed."},{"step":5,"title":"Rest briefly","instruction":"Rest 1 minute on a rack — not a plate — so the underside does not steam soft, then serve with syrup and berries."}]'::JSONB, 'Wipe the pan between batches; burnt butter solids from the first round will make the later slices taste bitter. Hold finished slices in a 200°F oven on a rack.', ARRAY['Baked version: Soak overnight in a dish and bake at 350°F for 40 minutes for a casserole.','Dairy-free: Oat milk and coconut cream work well; fry in oil.','Savoury: Skip the sugar and cinnamon, add black pepper, and top with a fried egg.']::TEXT[], ARRAY['Gluten','Dairy','Egg']::TEXT[]),
('breakfast-burrito', 'Breakfast Burrito', 'Soft scrambled eggs, crisp potato, cheese, and salsa rolled tight and seared in the pan so the seam holds.', 'https://img.rocket.new/generatedImages/rocket_gen_img_116ccbc83-1772393582608.png', 'Loaded breakfast burrito with scrambled eggs, cheese, salsa, and avocado', 'Carlos Mendez', '@carlosmendezcooks', '', '', '10 min', '10 min', '20 min', 10, 10, 20, 4, 'Easy', 'Mexican', 'Breakfast', 'Breakfast', ARRAY['Meal Prep','Family','Freezer-Friendly','Hearty']::TEXT[], 4.3, 55, 4836, 612, 27, 54, 32, 5, '[{"amount":"4","unit":"","item":"large flour tortillas"},{"amount":"8","unit":"large","item":"eggs"},{"amount":"2","unit":"tbsp","item":"butter"},{"amount":"2","unit":"","item":"potatoes, diced small"},{"amount":"8","unit":"oz","item":"breakfast sausage or chorizo"},{"amount":"1","unit":"cup","item":"grated cheddar"},{"amount":"1","unit":"","item":"avocado, sliced"},{"amount":"0.5","unit":"cup","item":"salsa"},{"amount":"2","unit":"tbsp","item":"neutral oil"},{"amount":"","unit":"","item":"Salt, pepper, and hot sauce"},{"amount":"","unit":"","item":"Cilantro"}]'::JSONB, '[{"step":1,"title":"Crisp the potatoes","instruction":"Fry the diced potato in the oil over medium-high heat for 12 minutes, turning rarely, until crisp and golden. Season and set aside.","tip":"Leave them alone between turns. Constant stirring gives soft, pale potato."},{"step":2,"title":"Brown the sausage","instruction":"Cook the sausage in the same pan, breaking it up, until browned. Remove."},{"step":3,"title":"Scramble low and slow","instruction":"Melt the butter over low heat, add the beaten eggs, and stir constantly with a spatula, pulling them off the heat every so often. Take them off while still glossy and slightly underdone.","tip":"Low heat and constant movement gives soft curds. High heat gives rubber."},{"step":4,"title":"Warm the tortillas","instruction":"Heat each tortilla directly over a flame or in a dry pan for 15 seconds a side until pliable. Cold tortillas crack when rolled."},{"step":5,"title":"Fill and roll tight","instruction":"Lay the filling in a line slightly below centre, leaving clear margins. Fold in the sides, then roll up firmly, tucking as you go."},{"step":6,"title":"Sear the seam","instruction":"Place seam-side down in a dry hot pan for 90 seconds a side. This seals it shut and adds a crisp exterior."}]'::JSONB, 'Let everything cool before rolling if you are making these to freeze — trapped steam makes the tortilla soggy. Wrapped in foil they freeze for 2 months; reheat from frozen at 350°F for 30 minutes.', ARRAY['Vegetarian: Black beans and sautéed peppers in place of the sausage.','Meal prep: Make eight at once on Sunday; they reheat better than almost any other breakfast.','Keep it dry: Salsa goes on the side for freezer burritos, or the tortilla turns to mush.']::TEXT[], ARRAY['Egg','Dairy','Gluten']::TEXT[]),
('acai-bowl', 'Acai Bowl', 'Frozen açaí blended thick with banana, built to hold its toppings rather than drown them.', 'https://images.unsplash.com/photo-1455099797519-a70bccc199c1', 'Vibrant purple acai bowl topped with granola, banana slices, and honey drizzle', 'Aisha Sharma', '@aishasharmaspice', '', '', '10 min', '—', '10 min', 10, 0, 10, 2, 'Easy', 'Brazilian', 'Breakfast', 'Breakfast', ARRAY['Vegan-Adaptable','Gluten-Free','No-Cook','Healthy']::TEXT[], 5.0, 1345, 4879, 396, 8, 62, 15, 10, '[{"amount":"2","unit":"packs","item":"frozen unsweetened açaí purée (100g each)"},{"amount":"1","unit":"","item":"frozen banana"},{"amount":"0.5","unit":"cup","item":"frozen mixed berries"},{"amount":"3","unit":"tbsp","item":"apple juice or plant milk"},{"amount":"1","unit":"tbsp","item":"almond butter"},{"amount":"1","unit":"tbsp","item":"honey or agave"},{"amount":"0.5","unit":"cup","item":"granola"},{"amount":"1","unit":"","item":"fresh banana, sliced"},{"amount":"2","unit":"tbsp","item":"coconut flakes"},{"amount":"1","unit":"tbsp","item":"cacao nibs"}]'::JSONB, '[{"step":1,"title":"Break up the açaí","instruction":"Run the sealed frozen packs under warm water for 10 seconds, then snap them into pieces before they go in the blender. Solid blocks just spin uselessly."},{"step":2,"title":"Blend with minimal liquid","instruction":"Add the açaí, frozen banana, berries, almond butter, honey, and only 3 tablespoons of liquid."},{"step":3,"title":"Scrape, do not pour","instruction":"Blend on low, stopping repeatedly to scrape the sides down. The mixture should move like soft-serve and hold a peak.","tip":"Every extra splash of liquid costs thickness. Patience with the scraping is the whole technique."},{"step":4,"title":"Bowl it","instruction":"Spoon into two chilled bowls and flatten the surface with the back of a spoon."},{"step":5,"title":"Top and serve","instruction":"Arrange the granola, banana, coconut, and cacao nibs in rows and eat immediately."}]'::JSONB, 'Unsweetened açaí packs are quite tart on their own, which is what the banana and honey are balancing. Chilling the bowls in the freezer beforehand buys several extra minutes before it melts.', ARRAY['Vegan: Use agave in place of honey.','Nut-free: Sunflower seed butter and a nut-free granola.','Thicker still: Add half an avocado — it does not taste of anything here but makes the texture noticeably creamier.']::TEXT[], ARRAY['Tree Nut']::TEXT[]),
('cacio-e-pepe', 'Cacio e Pepe', 'Pasta, pecorino, and black pepper. Four ingredients, one difficult technique, and no way to hide a mistake.', 'https://img.rocket.new/generatedImages/rocket_gen_img_1e568055d-1772085885754.png', 'Creamy cacio e pepe pasta with black pepper and pecorino romano cheese', 'Sofia Romano', '@sofiaromanoeats', '', '', '5 min', '15 min', '20 min', 5, 15, 20, 4, 'Medium', 'Italian', 'Dinner', 'Main Course', ARRAY['Vegetarian','Classic','Quick','Minimal Ingredients']::TEXT[], 4.5, 185, 3683, 512, 21, 68, 17, 3, '[{"amount":"1","unit":"lb","item":"tonnarelli or spaghetti"},{"amount":"2","unit":"cups","item":"finely grated pecorino romano"},{"amount":"2","unit":"tbsp","item":"whole black peppercorns"},{"amount":"2","unit":"tbsp","item":"olive oil"},{"amount":"","unit":"","item":"Salt for the pasta water"}]'::JSONB, '[{"step":1,"title":"Use less water than usual","instruction":"Cook the pasta in a wide pan with just enough water to cover. Less water means far starchier water, and the starch is what makes the sauce work.","tip":"This is the trick nobody mentions. Starchy water is non-negotiable."},{"step":2,"title":"Toast the pepper","instruction":"Coarsely crush the peppercorns and toast them in a dry pan for 60 seconds until fragrant. Add the olive oil and a ladle of pasta water and let it bubble."},{"step":3,"title":"Grate finely and let it warm","instruction":"Grate the pecorino as finely as you can and let it come to room temperature. Cold, coarsely grated cheese seizes into strings instantly."},{"step":4,"title":"Make a cheese paste","instruction":"Mix the pecorino with a few tablespoons of warm — not boiling — pasta water in a bowl until it forms a smooth, thick paste.","tip":"Boiling water will scramble the cheese. Let the water cool for 30 seconds first."},{"step":5,"title":"Combine off the heat","instruction":"Drain the pasta 1 minute early and add it to the pepper pan off the heat. Add the cheese paste and toss hard, adding pasta water bit by bit, until a glossy sauce coats every strand."},{"step":6,"title":"Serve at once","instruction":"Plate immediately with more pepper and pecorino. It stiffens as it cools and cannot really be rescued."}]'::JSONB, 'The two failure modes are clumping (cheese too cold, or water too hot) and wateriness (not enough starch, or not tossed hard enough). If it clumps, take the pan fully off the heat, add a splash of cool pasta water, and keep tossing.', ARRAY['Do not substitute: Parmesan behaves differently and gives a grainier sauce; pecorino romano is the right cheese.','Insurance: A teaspoon of cornstarch whisked into the cheese paste makes the emulsion far more forgiving.','Scale carefully: This is much harder to make for eight than for four. Cook two separate batches.']::TEXT[], ARRAY['Gluten','Dairy']::TEXT[]),
('pesto-gnocchi', 'Pesto Gnocchi', 'Soft potato gnocchi in fresh basil pesto, with a quick pan-crisp that gives them a golden edge.', 'https://img.rocket.new/generatedImages/rocket_gen_img_1a38c4769-1784801278829.png', 'Pillowy gnocchi tossed in vibrant green basil pesto with pine nuts', 'Marco Rossi', '@marcorossicucina', '', '', '10 min', '15 min', '25 min', 10, 15, 25, 4, 'Easy', 'Italian', 'Dinner', 'Main Course', ARRAY['Vegetarian','Quick','Comfort']::TEXT[], 4.9, 983, 6291, 548, 16, 62, 27, 4, '[{"amount":"2","unit":"lb","item":"potato gnocchi"},{"amount":"3","unit":"cups","item":"fresh basil leaves"},{"amount":"0.5","unit":"cup","item":"pine nuts, toasted"},{"amount":"3","unit":"cloves","item":"garlic"},{"amount":"0.75","unit":"cup","item":"grated parmesan"},{"amount":"0.66","unit":"cup","item":"extra virgin olive oil"},{"amount":"1","unit":"tbsp","item":"lemon juice"},{"amount":"2","unit":"tbsp","item":"butter"},{"amount":"1","unit":"cup","item":"cherry tomatoes, halved"},{"amount":"","unit":"","item":"Salt and black pepper"}]'::JSONB, '[{"step":1,"title":"Make the pesto","instruction":"Pulse the basil, pine nuts, and garlic to a coarse crumb, add the parmesan, then stream in the oil. Finish with lemon juice, salt, and pepper.","tip":"Pulse in bursts. Continuous blending heats and bruises the basil, turning the pesto dark."},{"step":2,"title":"Boil briefly","instruction":"Drop the gnocchi into well-salted boiling water. They are done the moment they float, about 2 minutes. Scoop them out with a slotted spoon and save a cup of the water.","tip":"Floating means done. Leaving them in longer turns them to paste."},{"step":3,"title":"Crisp in butter","instruction":"Melt the butter in a wide pan and fry the drained gnocchi in a single layer for 3 minutes without moving them, until one side is golden."},{"step":4,"title":"Blister the tomatoes","instruction":"Add the cherry tomatoes and cook 2 minutes until the skins split."},{"step":5,"title":"Dress off the heat","instruction":"Take the pan off the heat before adding the pesto with a splash of the cooking water, tossing until glossy. Heat dulls fresh pesto and turns it grey."}]'::JSONB, 'Shop-bought gnocchi is fine here and cooks in two minutes. The pan-crisping step is optional but it changes the dish considerably — the contrast between crisp edge and pillowy centre is the best part.', ARRAY['Vegan: Nutritional yeast and a little white miso in place of the parmesan.','Nut-free: Toasted sunflower or pumpkin seeds instead of pine nuts.','Make-ahead: Pesto keeps a week under a layer of oil, or freezes in ice cube trays.']::TEXT[], ARRAY['Gluten','Dairy','Tree Nut','Egg']::TEXT[]),
('pasta-arrabbiata', 'Pasta Arrabbiata', 'Angry tomato sauce — garlic and dried chilli fried slowly in good oil, then simmered with tomatoes until sweet.', 'https://img.rocket.new/generatedImages/rocket_gen_img_156bff04d-1772207897368.png', 'Spicy arrabbiata pasta with tomato sauce, garlic, and red chili flakes', 'Sofia Romano', '@sofiaromanoeats', '', '', '5 min', '15 min', '20 min', 5, 15, 20, 4, 'Easy', 'Italian', 'Dinner', 'Main Course', ARRAY['Vegan','Spicy','Quick','Budget']::TEXT[], 4.6, 1202, 2517, 468, 14, 76, 12, 6, '[{"amount":"1","unit":"lb","item":"penne rigate"},{"amount":"0.33","unit":"cup","item":"extra virgin olive oil"},{"amount":"6","unit":"cloves","item":"garlic, thinly sliced"},{"amount":"2","unit":"tsp","item":"dried chilli flakes"},{"amount":"28","unit":"oz","item":"tinned San Marzano tomatoes, crushed by hand"},{"amount":"1","unit":"tsp","item":"salt"},{"amount":"","unit":"","item":"Handful of fresh parsley"},{"amount":"","unit":"","item":"Pecorino to serve (optional)"}]'::JSONB, '[{"step":1,"title":"Infuse the oil gently","instruction":"Put the oil, sliced garlic, and chilli flakes in a cold pan and bring them up to medium heat together. Cook 4 minutes until the garlic is pale gold.","tip":"Starting cold draws the flavour out slowly. Garlic dropped into hot oil burns in seconds and turns the whole sauce bitter."},{"step":2,"title":"Crush the tomatoes by hand","instruction":"Squeeze the tomatoes between your fingers into the pan rather than blending them. Hand-crushed gives a rustic texture that clings to the pasta."},{"step":3,"title":"Simmer down","instruction":"Add salt and simmer 20 minutes, stirring occasionally, until the sauce darkens and the oil separates out at the edges.","tip":"The oil rising to the surface is the sign the sauce is properly reduced."},{"step":4,"title":"Undercook the pasta","instruction":"Boil the penne 2 minutes short of the packet time and reserve a cup of the water."},{"step":5,"title":"Finish in the pan","instruction":"Add the drained pasta to the sauce with a splash of pasta water and toss hard over the heat for 90 seconds, so the pasta finishes cooking in the sauce and absorbs it."},{"step":6,"title":"Serve","instruction":"Off the heat, add the parsley and a final drizzle of raw olive oil."}]'::JSONB, 'The quality of the tinned tomatoes is essentially the quality of the dish — this is worth spending on. Traditionally served without cheese, but nobody will stop you.', ARRAY['Heat: Two teaspoons of chilli is properly arrabbiata. Halve it if you want it mild.','Add protein: A tin of drained tuna or some crumbled sausage folded in at the end.','Make-ahead: The sauce keeps 5 days and freezes for 3 months.']::TEXT[], ARRAY['Gluten']::TEXT[]),
('mushroom-risotto', 'Mushroom Risotto', 'Arborio stirred with hot stock into something creamy without cream, with mushrooms browned hard and folded through.', 'https://images.unsplash.com/photo-1680420574628-225def8eea0a', 'Creamy mushroom risotto with parmesan cheese and fresh thyme garnish', 'Maria Chen', '@mariachencooks', 'https://images.unsplash.com/photo-1677229888051-211da3f34219', 'Portrait of food creator Maria Chen', '15 min', '25 min', '40 min', 15, 25, 40, 4, 'Medium', 'Italian', 'Dinner', 'Main Course', ARRAY['Vegetarian','Comfort','Gluten-Free','Date Night']::TEXT[], 4.7, 1358, 2837, 512, 15, 68, 19, 4, '[{"amount":"1.5","unit":"cups","item":"arborio or carnaroli rice"},{"amount":"1","unit":"lb","item":"mixed mushrooms, sliced"},{"amount":"6","unit":"cups","item":"vegetable stock, kept hot"},{"amount":"1","unit":"","item":"onion, very finely diced"},{"amount":"3","unit":"cloves","item":"garlic, minced"},{"amount":"0.5","unit":"cup","item":"dry white wine"},{"amount":"4","unit":"tbsp","item":"butter"},{"amount":"3","unit":"tbsp","item":"olive oil"},{"amount":"0.75","unit":"cup","item":"grated parmesan"},{"amount":"2","unit":"sprigs","item":"fresh thyme"},{"amount":"","unit":"","item":"Salt and black pepper"},{"amount":"","unit":"","item":"Chopped parsley"}]'::JSONB, '[{"step":1,"title":"Brown the mushrooms separately","instruction":"Fry the mushrooms in the olive oil over high heat in two batches, undisturbed for 3 minutes per batch, until deeply browned. Season and set aside.","tip":"Mushrooms added raw to the risotto release water and steam everything. Brown them first, always."},{"step":2,"title":"Keep the stock hot","instruction":"Hold the stock at a bare simmer in a separate pan. Cold stock added to the rice stops the cooking and gives an uneven, chalky result."},{"step":3,"title":"Toast the rice","instruction":"Soften the onion in 2 tbsp butter for 5 minutes, add the garlic, then the rice. Stir for 2 minutes until the grains turn translucent at the edges with a white dot at the centre."},{"step":4,"title":"Deglaze","instruction":"Add the wine and stir until it has fully absorbed."},{"step":5,"title":"Add stock a ladle at a time","instruction":"Add one ladle of hot stock, stir until almost fully absorbed, then add the next. Keep going for 18–20 minutes. The rice should be tender with a slight bite at the core.","tip":"Stir often but not frantically. The friction between grains is what releases the starch that makes it creamy."},{"step":6,"title":"Mantecare","instruction":"Off the heat, beat in the remaining butter and the parmesan vigorously. Fold in the mushrooms and thyme, cover, and rest 2 minutes before serving."}]'::JSONB, 'Correct risotto spreads slowly when spooned onto a warm plate — if it holds a mound, it is too thick, so loosen it with more stock. Never rinse risotto rice; the surface starch is the entire point.', ARRAY['Vegan: Olive oil in place of butter, nutritional yeast for the parmesan.','Deeper flavour: Soak a handful of dried porcini in hot water and use the strained liquid as part of the stock.','Leftovers: Roll cold risotto into balls, crumb, and fry for arancini.']::TEXT[], ARRAY['Dairy']::TEXT[]),
('baked-mac-cheese', 'Baked Mac & Cheese', 'A proper béchamel-based cheese sauce, not a tinned one, baked under a buttered breadcrumb crust.', 'https://img.rocket.new/generatedImages/rocket_gen_img_1beb1562f-1772222748789.png', 'Golden baked macaroni and cheese with crispy breadcrumb topping', 'Jake Torres', '@jaketorrescooks', 'https://images.unsplash.com/photo-1572015837827-01671d41e102', 'Portrait of food creator Jake Torres', '15 min', '30 min', '45 min', 15, 30, 45, 6, 'Easy', 'American', 'Dinner', 'Main Course', ARRAY['Comfort','Family','Vegetarian','Crowd Pleaser']::TEXT[], 4.5, 1182, 6152, 682, 28, 58, 38, 3, '[{"amount":"1","unit":"lb","item":"elbow macaroni"},{"amount":"6","unit":"tbsp","item":"butter"},{"amount":"6","unit":"tbsp","item":"all-purpose flour"},{"amount":"4","unit":"cups","item":"whole milk, warm"},{"amount":"3","unit":"cups","item":"grated sharp cheddar"},{"amount":"1","unit":"cup","item":"grated gruyere"},{"amount":"1","unit":"tsp","item":"Dijon mustard"},{"amount":"0.5","unit":"tsp","item":"smoked paprika"},{"amount":"0.25","unit":"tsp","item":"nutmeg"},{"amount":"1","unit":"cup","item":"panko breadcrumbs"},{"amount":"2","unit":"tbsp","item":"melted butter for the top"},{"amount":"","unit":"","item":"Salt and white pepper"}]'::JSONB, '[{"step":1,"title":"Undercook the pasta","instruction":"Boil the macaroni 2 minutes short of al dente. It absorbs more sauce and continues cooking in the oven.","tip":"Fully cooked pasta turns to mush after 25 minutes of baking."},{"step":2,"title":"Make the roux","instruction":"Melt the butter, whisk in the flour, and cook 2 minutes until it smells biscuity but has not coloured."},{"step":3,"title":"Build the béchamel","instruction":"Add the warm milk in four stages, whisking hard until smooth after each. Simmer 5 minutes until it thickly coats a spoon."},{"step":4,"title":"Melt the cheese off the heat","instruction":"Take the pan off the heat before adding the cheese in handfuls, stirring until each melts. Add the Dijon, paprika, nutmeg, salt, and white pepper.","tip":"Cheese added to a boiling sauce splits and goes grainy. Off the heat, every time."},{"step":5,"title":"Combine and top","instruction":"Fold the pasta into the sauce — it should look far too saucy — and tip into a buttered dish. Toss the panko with melted butter and scatter over."},{"step":6,"title":"Bake","instruction":"Bake at 375°F (190°C) for 25 minutes until bubbling at the edges and deep golden on top. Rest 10 minutes before serving."}]'::JSONB, 'Grate the cheese yourself; pre-grated cheese is coated in anti-caking starch that makes the sauce gritty. The mixture should look distinctly loose going into the oven, since the pasta drinks a lot of it as it bakes.', ARRAY['Add-ins: Crisp bacon, roasted broccoli, or caramelised onion all work folded in.','Make-ahead: Assemble a day ahead and bake from cold, adding 10 minutes.','Extra crunch: Mix grated parmesan into the panko topping.']::TEXT[], ARRAY['Gluten','Dairy']::TEXT[]),
('spaghetti-bolognese', 'Spaghetti Bolognese', 'A long-simmered meat ragù with milk and wine, closer to the Bolognese original than the tomato-heavy version.', 'https://images.unsplash.com/photo-1634838512151-0773b35c91ee', 'Classic spaghetti bolognese with rich meat sauce and parmesan cheese', 'Marco Rossi', '@marcorossicucina', '', '', '20 min', '40 min', '1 hr', 20, 40, 60, 6, 'Medium', 'Italian', 'Dinner', 'Main Course', ARRAY['Comfort','Family','Slow-Cooked','Freezer-Friendly']::TEXT[], 4.2, 923, 8585, 628, 34, 68, 24, 5, '[{"amount":"1","unit":"lb","item":"ground beef"},{"amount":"0.5","unit":"lb","item":"ground pork"},{"amount":"4","unit":"oz","item":"pancetta, finely diced"},{"amount":"1","unit":"","item":"onion, finely diced"},{"amount":"1","unit":"","item":"carrot, finely diced"},{"amount":"1","unit":"stalk","item":"celery, finely diced"},{"amount":"3","unit":"tbsp","item":"tomato paste"},{"amount":"1","unit":"cup","item":"whole milk"},{"amount":"1","unit":"cup","item":"dry white wine"},{"amount":"14","unit":"oz","item":"crushed tomatoes"},{"amount":"2","unit":"cups","item":"beef stock"},{"amount":"1","unit":"lb","item":"spaghetti or tagliatelle"},{"amount":"","unit":"","item":"Salt and black pepper"},{"amount":"","unit":"","item":"Parmesan to serve"}]'::JSONB, '[{"step":1,"title":"Soffritto first","instruction":"Cook the pancetta until its fat renders, then add the onion, carrot, and celery and cook gently for 10 minutes until completely soft and sweet.","tip":"Ten slow minutes here builds the sweet base that a long simmer needs."},{"step":2,"title":"Brown the meat hard","instruction":"Raise the heat, add the beef and pork, and leave them undisturbed for 3 minutes to crust before breaking up. Continue until all the liquid has cooked off and the meat starts frying."},{"step":3,"title":"Milk first, then wine","instruction":"Add the milk and simmer until it has almost fully evaporated. Then add the wine and do the same.","tip":"Milk before wine is the traditional order — the milk tenderises the meat before the acid hits it."},{"step":4,"title":"Add tomato","instruction":"Stir in the tomato paste and cook 2 minutes, then add the crushed tomatoes and stock."},{"step":5,"title":"Simmer for hours","instruction":"Simmer uncovered on the lowest heat for at least 2 hours, topping up with water if it gets too dry. It should end up thick, dark, and glossy rather than red and soupy."},{"step":6,"title":"Toss, do not ladle","instruction":"Cook the pasta, drain it 1 minute early, and toss it in the pan with the ragù and a splash of pasta water. Serve with parmesan."}]'::JSONB, 'This is one of the few dishes that genuinely rewards three or four hours of simmering. It freezes for 3 months and improves for two days in the fridge. Traditionally served with tagliatelle, which holds the sauce better than spaghetti.', ARRAY['No wine: Extra stock plus a splash of red wine vinegar at the end.','Vegetarian: Finely chopped mushrooms and brown lentils, browned the same way.','Batch it: Double the recipe — the cooking time is identical.']::TEXT[], ARRAY['Gluten','Dairy','Celery']::TEXT[])
