INSERT INTO public.recipes (slug, title, description, image, image_alt, creator_name, creator_handle, creator_image, creator_alt, prep_time, cook_time, total_time, prep_minutes, cook_minutes, total_minutes, servings, difficulty, cuisine, meal_type, category, tags, rating, reviews, cooks, calories, protein, carbs, fat, fiber, ingredients, steps, notes, tips, allergens) VALUES
('bbq-baby-back-ribs', 'BBQ Baby Back Ribs', 'Ribs with the membrane pulled, dry-rubbed, cooked low and slow, then glazed and finished hot.', 'https://img.rocket.new/generatedImages/rocket_gen_img_1c57cdb81-1770832572556.png', 'Smoky BBQ baby back ribs with caramelized sauce on a wooden board', 'Jake Torres', '@jaketorrescooks', 'https://images.unsplash.com/photo-1572015837827-01671d41e102', 'Portrait of food creator Jake Torres', '20 min', '2.7 hrs', '3 hrs', 20, 160, 180, 4, 'Medium', 'American', 'Dinner', 'Main Course', ARRAY['BBQ','Slow-Cooked','Weekend Project','Crowd Pleaser']::TEXT[], 4.4, 509, 4184, 742, 48, 32, 48, 1, '[{"amount":"2","unit":"racks","item":"baby back ribs"},{"amount":"3","unit":"tbsp","item":"brown sugar"},{"amount":"2","unit":"tbsp","item":"smoked paprika"},{"amount":"1","unit":"tbsp","item":"salt"},{"amount":"1","unit":"tbsp","item":"black pepper"},{"amount":"2","unit":"tsp","item":"garlic powder"},{"amount":"2","unit":"tsp","item":"onion powder"},{"amount":"1","unit":"tsp","item":"cayenne"},{"amount":"1","unit":"tsp","item":"ground cumin"},{"amount":"1","unit":"cup","item":"BBQ sauce"},{"amount":"0.25","unit":"cup","item":"apple cider vinegar"},{"amount":"","unit":"","item":"Apple juice for spritzing"}]'::JSONB, '[{"step":1,"title":"Remove the membrane","instruction":"Slide a knife under the silverskin on the bone side, grip it with kitchen paper, and pull the whole sheet off in one piece.","tip":"Leaving the membrane on gives you rubbery ribs that will not take smoke or rub. This step is mandatory."},{"step":2,"title":"Rub and rest","instruction":"Mix all the dry spices and coat both racks heavily. Leave at least an hour, ideally overnight in the fridge."},{"step":3,"title":"Cook low","instruction":"Cook at 275°F (135°C) — oven or smoker — bone-side down for 2 hours, spritzing with apple juice every 45 minutes."},{"step":4,"title":"Wrap","instruction":"Wrap each rack tightly in foil with a splash of vinegar and cook another 45 minutes. This steams them through the stall and tenderises."},{"step":5,"title":"Glaze and finish hot","instruction":"Unwrap, brush generously with BBQ sauce, and cook uncovered at 400°F (205°C) for 15 minutes until the glaze sets and tacks up.","tip":"Sauce goes on at the end only. Applied early, the sugar burns black over three hours."},{"step":6,"title":"Check by bend, not clock","instruction":"Pick the rack up with tongs at one end — it should bend sharply and the surface should crack. Rest 10 minutes, then cut between the bones."}]'::JSONB, 'The bend test is far more reliable than time or temperature. Ribs that fall completely off the bone are technically overcooked, though plenty of people prefer them that way. Cook until it suits you.', ARRAY['Smoker: Add hickory or apple wood for the first 2 hours; the method is otherwise identical.','Make-ahead: Cook through step 4 a day ahead, then glaze and finish just before serving.','Spare ribs: Larger and fattier — add about an hour to the low phase.']::TEXT[], ARRAY[]::TEXT[]),
('grilled-corn', 'Grilled Corn on the Cob', 'Corn charred directly on the grate, then rolled in chilli-lime butter. Mexican street corn, minus the mayonnaise.', 'https://images.unsplash.com/photo-1570716774271-ab30ad4924a8', 'Charred grilled corn on the cob with butter, lime, and chili powder', 'Carlos Mendez', '@carlosmendezcooks', '', '', '5 min', '10 min', '15 min', 5, 10, 15, 4, 'Easy', 'Mexican', 'Snack', 'Side Dish', ARRAY['Vegetarian','BBQ','Gluten-Free','Summer']::TEXT[], 4.3, 1357, 383, 218, 5, 28, 12, 4, '[{"amount":"4","unit":"","item":"ears of corn, husked"},{"amount":"4","unit":"tbsp","item":"softened butter"},{"amount":"1","unit":"tsp","item":"chilli powder"},{"amount":"0.5","unit":"tsp","item":"smoked paprika"},{"amount":"1","unit":"","item":"lime (zest and wedges)"},{"amount":"0.25","unit":"cup","item":"crumbled cotija or feta"},{"amount":"2","unit":"tbsp","item":"chopped cilantro"},{"amount":"","unit":"","item":"Salt"}]'::JSONB, '[{"step":1,"title":"Grill it dry and naked","instruction":"Put the husked corn straight onto a hot grill with no oil. Turn every 2 minutes for 10–12 minutes total, until charred in patches all the way round.","tip":"Blackened kernels are flavour, not damage. Take it further than looks comfortable."},{"step":2,"title":"Mix the butter","instruction":"Mash the softened butter with the chilli powder, paprika, lime zest, and a good pinch of salt."},{"step":3,"title":"Butter while blazing hot","instruction":"Roll each ear in the compound butter the moment it comes off the grill, so it melts into the kernels rather than sitting on top."},{"step":4,"title":"Finish","instruction":"Scatter over the cheese and cilantro and serve with lime wedges to squeeze."}]'::JSONB, 'Soaking corn in water before grilling is a common instruction and it works against you here — it steams the kernels and prevents any real char. Dry corn, hot grate, frequent turns.', ARRAY['No grill: A dry cast iron pan over high heat, or 8 minutes under a hot broiler.','Vegan: Plant butter and nutritional yeast in place of the cheese.','Off the cob: Cut the charred kernels off and toss with the butter as a salad.']::TEXT[], ARRAY['Dairy']::TEXT[]),
('smoked-brisket', 'Smoked Brisket', 'A full packer brisket smoked for eight hours, wrapped through the stall, and rested for hours before slicing.', 'https://images.unsplash.com/photo-1614231558486-b5bc24dd2d84', 'Thick sliced smoked brisket with dark bark and pink smoke ring', 'Jake Torres', '@jaketorrescooks', 'https://images.unsplash.com/photo-1572015837827-01671d41e102', 'Portrait of food creator Jake Torres', '30 min', '7.5 hrs', '8 hrs', 30, 450, 480, 10, 'Hard', 'American', 'Dinner', 'Main Course', ARRAY['BBQ','Weekend Project','Low and Slow','Gluten-Free']::TEXT[], 4.7, 1778, 2641, 612, 52, 2, 44, 0, '[{"amount":"12","unit":"lb","item":"whole packer brisket"},{"amount":"0.5","unit":"cup","item":"coarse black pepper"},{"amount":"0.5","unit":"cup","item":"kosher salt"},{"amount":"2","unit":"tbsp","item":"garlic powder"},{"amount":"","unit":"","item":"Post oak or hickory wood"},{"amount":"","unit":"","item":"Beef tallow for wrapping"},{"amount":"","unit":"","item":"Butcher paper"}]'::JSONB, '[{"step":1,"title":"Trim the fat cap","instruction":"Trim the fat cap down to a quarter inch and remove the hard deckle fat between the point and flat. Round off any thin edges that would burn.","tip":"Quarter inch. Thicker never renders, thinner leaves the meat unprotected."},{"step":2,"title":"Rub simply","instruction":"Mix the salt, pepper, and garlic powder and coat every surface heavily. Texas-style brisket needs nothing more than salt and pepper."},{"step":3,"title":"Smoke at 250°F","instruction":"Smoke fat-side up at 250°F (120°C) with post oak. Do not open the lid for the first 4 hours."},{"step":4,"title":"Ride out the stall","instruction":"At around 165°F internal the temperature will stop climbing for hours. This is evaporative cooling and it is normal.","tip":"Do not raise the heat during the stall. Wait it out or wrap."},{"step":5,"title":"Wrap in butcher paper","instruction":"Once the bark is dark and firm, wrap tightly in butcher paper with a little tallow and return to the smoker."},{"step":6,"title":"Cook to feel, not temperature","instruction":"Continue to around 203°F internal, but judge by probe feel — a skewer should slide into the flat like room-temperature butter with no resistance at all."},{"step":7,"title":"Rest for hours","instruction":"Rest wrapped in a cooler for at least 2 hours, ideally 4. Then slice against the grain, pencil-thick.","tip":"The long rest is as important as the cook. Slicing early loses all the juice."}]'::JSONB, 'The grain direction changes between the point and the flat — separate the two muscles before slicing and cut each against its own grain. Foil works instead of butcher paper but softens the bark noticeably.', ARRAY['Oven version: 250°F oven, wrapped in foil after the bark sets. No smoke ring, but genuinely tender.','Leftovers: Chop the point into burnt ends, or use slices for sandwiches.','Plan backwards: Count back from serving time and add three hours of buffer. Brisket is never in a hurry.']::TEXT[], ARRAY[]::TEXT[]),
('grilled-veggie-skewers', 'Grilled Veggie Skewers', 'Vegetables cut to cook at the same rate, marinated in herby oil, and charred over high heat.', 'https://images.unsplash.com/photo-1635882686740-edfc701b48ae', 'Colorful grilled vegetable skewers with zucchini, peppers, and mushrooms', 'Priya Nair', '@priyanairkitchen', '', '', '15 min', '5 min', '20 min', 15, 5, 20, 4, 'Easy', 'Mediterranean', 'Dinner', 'Side Dish', ARRAY['Vegan','Gluten-Free','BBQ','Healthy']::TEXT[], 4.4, 753, 6414, 186, 4, 18, 12, 5, '[{"amount":"2","unit":"","item":"courgettes, thick-sliced"},{"amount":"2","unit":"","item":"bell peppers, cut into squares"},{"amount":"1","unit":"","item":"red onion, wedged"},{"amount":"8","unit":"oz","item":"button mushrooms"},{"amount":"1","unit":"cup","item":"cherry tomatoes"},{"amount":"4","unit":"tbsp","item":"olive oil"},{"amount":"2","unit":"tbsp","item":"balsamic vinegar"},{"amount":"3","unit":"cloves","item":"garlic, minced"},{"amount":"1","unit":"tbsp","item":"dried oregano"},{"amount":"1","unit":"tsp","item":"smoked paprika"},{"amount":"","unit":"","item":"Salt and black pepper"},{"amount":"8","unit":"","item":"skewers"}]'::JSONB, '[{"step":1,"title":"Cut for even cooking","instruction":"Cut everything to roughly the same size — about an inch. Mixed sizes mean the small pieces burn while the large ones stay raw.","tip":"This is the only thing that really determines whether skewers work."},{"step":2,"title":"Marinate 30 minutes","instruction":"Whisk the oil, balsamic, garlic, oregano, paprika, salt, and pepper and toss the vegetables in it. Leave 30 minutes, no longer — the salt starts drawing out water after that."},{"step":3,"title":"Group like with like","instruction":"Thread each skewer with a single vegetable type rather than alternating. Mushrooms and courgettes cook at completely different rates."},{"step":4,"title":"Grill hot","instruction":"Grill over high heat, turning every 3 minutes, for 10–12 minutes total until charred at the edges and tender through."},{"step":5,"title":"Finish","instruction":"Brush with any leftover marinade off the heat and add flaky salt."}]'::JSONB, 'Soak wooden skewers for 30 minutes first or they burn through. Grouping vegetables by type looks less colourful on the skewer but means everything is actually cooked properly — rearrange on the platter afterwards if presentation matters.', ARRAY['Add halloumi: Cubes of halloumi on their own skewer, 2 minutes a side.','Oven: 425°F for 20 minutes on a rack, turning once.','Make-ahead: Cut and marinate in the morning; thread just before grilling.']::TEXT[], ARRAY[]::TEXT[]),
('pulled-pork-sandwiches', 'Pulled Pork Sandwiches', 'Pork shoulder cooked six hours until it shreds under a fork, tossed in vinegar sauce and piled onto brioche with slaw.', 'https://img.rocket.new/generatedImages/rocket_gen_img_1557b105b-1773111482327.png', 'Tender pulled pork piled high on a brioche bun with coleslaw', 'Carlos Mendez', '@carlosmendezcooks', '', '', '20 min', '5.7 hrs', '6 hrs', 20, 340, 360, 8, 'Medium', 'American', 'Dinner', 'Main Course', ARRAY['BBQ','Slow-Cooked','Crowd Pleaser','Make-Ahead']::TEXT[], 4.4, 844, 8999, 688, 42, 52, 34, 3, '[{"amount":"5","unit":"lb","item":"boneless pork shoulder"},{"amount":"3","unit":"tbsp","item":"brown sugar"},{"amount":"2","unit":"tbsp","item":"smoked paprika"},{"amount":"1","unit":"tbsp","item":"salt"},{"amount":"1","unit":"tbsp","item":"black pepper"},{"amount":"2","unit":"tsp","item":"garlic powder"},{"amount":"1","unit":"tsp","item":"cayenne"},{"amount":"1","unit":"cup","item":"apple cider vinegar"},{"amount":"0.5","unit":"cup","item":"BBQ sauce"},{"amount":"1","unit":"tbsp","item":"Dijon mustard"},{"amount":"8","unit":"","item":"brioche buns"},{"amount":"4","unit":"cups","item":"shredded cabbage"},{"amount":"3","unit":"tbsp","item":"mayonnaise"},{"amount":"1","unit":"tbsp","item":"sugar"}]'::JSONB, '[{"step":1,"title":"Rub the night before","instruction":"Mix the sugar, paprika, salt, pepper, garlic powder, and cayenne and coat the pork thoroughly. Refrigerate overnight uncovered."},{"step":2,"title":"Cook low and long","instruction":"Cook at 300°F (150°C) in a covered pot with half the vinegar for 5–6 hours, until the internal temperature reaches 200°F (93°C).","tip":"Pull it at 200°F, not 145°F. Below 195°F the collagen has not broken down and it will not shred."},{"step":3,"title":"Rest before shredding","instruction":"Rest 30 minutes in the pot. Shredding straight away loses a great deal of juice."},{"step":4,"title":"Shred and sauce","instruction":"Pull the meat apart with two forks, discarding large fat pieces. Toss with the remaining vinegar, BBQ sauce, Dijon, and a few ladles of the defatted cooking liquid.","tip":"Adding cooking liquid back is what keeps it from drying out. Be generous."},{"step":5,"title":"Make quick slaw","instruction":"Toss the cabbage with the mayonnaise, sugar, a splash of vinegar, salt, and pepper."},{"step":6,"title":"Build","instruction":"Toast the buns, pile high with pork, top with slaw, and press the lid down."}]'::JSONB, 'Cooked pulled pork keeps 4 days refrigerated and freezes for 3 months. Freeze it in its liquid rather than drained, or it reheats dry. The slaw on top is not a garnish — the acid and crunch cut the richness.', ARRAY['Slow cooker: 8 hours on low. Reduce the liquid on the stovetop afterwards.','Smoker: 250°F for 8 hours gives a bark that the oven cannot match.','Vinegar sauce: For Carolina style, skip the BBQ sauce and use vinegar, chilli flakes, and a little sugar.']::TEXT[], ARRAY['Gluten','Egg','Mustard']::TEXT[]),
('grilled-salmon-fillet', 'Grilled Salmon Fillet', 'Salmon grilled skin-side down on a clean hot grate so the skin crisps and the fillet lifts off in one piece.', 'https://images.unsplash.com/photo-1693164224779-9a7a8fc7b6d2', 'Perfectly grilled salmon fillet with lemon and herbs on a grill', 'Maria Chen', '@mariachencooks', 'https://images.unsplash.com/photo-1677229888051-211da3f34219', 'Portrait of food creator Maria Chen', '8 min', '12 min', '20 min', 8, 12, 20, 4, 'Easy', 'Modern', 'Dinner', 'Main Course', ARRAY['Seafood','Gluten-Free','Healthy','BBQ']::TEXT[], 4.3, 1301, 1573, 386, 38, 3, 24, 0, '[{"amount":"4","unit":"fillets","item":"salmon, skin on (6 oz each)"},{"amount":"2","unit":"tbsp","item":"olive oil"},{"amount":"1","unit":"","item":"lemon, sliced"},{"amount":"2","unit":"cloves","item":"garlic, minced"},{"amount":"1","unit":"tbsp","item":"chopped dill"},{"amount":"1","unit":"tbsp","item":"chopped parsley"},{"amount":"","unit":"","item":"Flaky salt and black pepper"}]'::JSONB, '[{"step":1,"title":"Clean and oil the grate","instruction":"Scrub the grate hot, then wipe it with an oiled cloth held in tongs. Salmon sticks to anything less than a spotless, oiled surface.","tip":"Sticking is not a salmon problem, it is a grate problem. Clean and oil it properly."},{"step":2,"title":"Dry the fish","instruction":"Pat the fillets completely dry and rub with oil, garlic, salt, and pepper. Surface moisture prevents any crust forming."},{"step":3,"title":"Skin-side down first","instruction":"Lay the fillets skin-side down over direct medium-high heat and close the lid. Cook 6 minutes without touching them."},{"step":4,"title":"Let it release","instruction":"The fish will release from the grate on its own when the skin has crisped. If it resists when you try to lift it, give it another minute.","tip":"Never force it. Forcing tears the skin and leaves half the fillet behind."},{"step":5,"title":"Finish briefly","instruction":"Flip and cook 2 minutes more, to 125°F internal for medium. Rest 3 minutes, then top with herbs and grilled lemon."}]'::JSONB, 'Salmon keeps cooking off the heat, so 125°F on the grill gives you a moist medium on the plate. A thick centre-cut fillet is far more forgiving than a thin tail piece.', ARRAY['No grill: A cast iron pan, skin-side down, same timings.','Cedar plank: Soak the plank an hour, cook 15 minutes with the lid down for a smokier result.','Skinless: Use a grill basket or foil — skinless fillets will stick regardless.']::TEXT[], ARRAY['Fish']::TEXT[]),
('sourdough-bread', 'Sourdough Bread', 'A naturally leavened loaf over 24 hours — mix, fold, cold-proof overnight, bake in a Dutch oven.', 'https://images.unsplash.com/photo-1658695985093-86cccecf81a5', 'Rustic sourdough loaf with scored crust cooling on a wire rack', 'Emma Walsh', '@emmawalshbakes', '', '', '1 hr', '23 hrs', '24 hrs', 60, 1380, 1440, 10, 'Hard', 'Artisan', 'Snack', 'Bread', ARRAY['Baking','From Scratch','Vegan','Weekend Project']::TEXT[], 4.5, 1445, 1706, 186, 6, 38, 1, 2, '[{"amount":"500","unit":"g","item":"bread flour"},{"amount":"350","unit":"g","item":"water (70%)"},{"amount":"100","unit":"g","item":"active sourdough starter"},{"amount":"10","unit":"g","item":"salt"},{"amount":"","unit":"","item":"Rice flour for dusting"}]'::JSONB, '[{"step":1,"title":"Check your starter floats","instruction":"Use starter 4–6 hours after feeding, when it has doubled and a spoonful floats in water. Sluggish starter is the reason most loaves come out dense.","tip":"The float test is the single best predictor of whether the loaf will rise."},{"step":2,"title":"Autolyse","instruction":"Mix the flour and water only and rest 1 hour. The flour hydrates and gluten begins forming with no kneading at all."},{"step":3,"title":"Add starter and salt","instruction":"Pinch the starter and salt through the dough until fully incorporated, about 3 minutes of squeezing and folding."},{"step":4,"title":"Stretch and fold","instruction":"Over the next 4 hours, perform a set of four stretch-and-folds every 45 minutes. The dough should go from shaggy to smooth, jiggly, and noticeably stronger.","tip":"Watch the dough, not the clock. It is ready when it has risen 50% and holds a dome."},{"step":5,"title":"Shape and cold-proof","instruction":"Shape into a tight round on an unfloured surface, place seam-up in a rice-floured banneton, and refrigerate 12–16 hours."},{"step":6,"title":"Bake in a Dutch oven","instruction":"Preheat the Dutch oven at 500°F (260°C) for 45 minutes. Turn the cold dough out, score it decisively, and bake covered 20 minutes, then uncovered at 450°F (230°C) for 25 minutes until deep brown."},{"step":7,"title":"Cool completely","instruction":"Cool on a rack at least 2 hours before cutting. The crumb is still setting inside and cutting hot leaves it gummy.","tip":"Two hours. Cutting early ruins the texture of the entire loaf."}]'::JSONB, 'Timings vary enormously with kitchen temperature — bulk fermentation at 68°F might take 6 hours, at 78°F only 3.5. Judge by the dough''s rise and jiggle rather than the schedule. The cold overnight proof both develops flavour and makes scoring far easier.', ARRAY['Starter: If yours is new, give it two weeks of daily feeding before attempting a loaf.','Hydration: Drop to 65% water if the dough feels unmanageable; it is much easier to handle.','Storage: Cut-side down on a board for 2 days, or sliced and frozen.']::TEXT[], ARRAY['Gluten']::TEXT[]),
('chocolate-lava-cake', 'Chocolate Lava Cake', 'Individual cakes pulled while the centre is still liquid. The whole dish is a timing exercise.', 'https://img.rocket.new/generatedImages/rocket_gen_img_19e43404e-1773176612518.png', 'Warm chocolate lava cake with molten center and powdered sugar dusting', 'Sofia Romano', '@sofiaromanoeats', '', '', '15 min', '10 min', '25 min', 15, 10, 25, 4, 'Medium', 'French', 'Dessert', 'Dessert', ARRAY['Baking','Date Night','Vegetarian','Quick']::TEXT[], 5.0, 1001, 8395, 512, 8, 42, 35, 3, '[{"amount":"6","unit":"oz","item":"dark chocolate (70%), chopped"},{"amount":"0.5","unit":"cup","item":"unsalted butter"},{"amount":"2","unit":"large","item":"eggs"},{"amount":"2","unit":"large","item":"egg yolks"},{"amount":"0.33","unit":"cup","item":"granulated sugar"},{"amount":"","unit":"","item":"Pinch of salt"},{"amount":"3","unit":"tbsp","item":"all-purpose flour"},{"amount":"1","unit":"tsp","item":"vanilla extract"},{"amount":"","unit":"","item":"Butter and cocoa powder for the ramekins"},{"amount":"","unit":"","item":"Ice cream to serve"}]'::JSONB, '[{"step":1,"title":"Prepare the ramekins properly","instruction":"Butter four ramekins thoroughly, then dust with cocoa powder rather than flour, tapping out the excess. Any missed patch will make the cake stick.","tip":"Cocoa, not flour — flour leaves a pale ring on a chocolate dessert."},{"step":2,"title":"Melt gently","instruction":"Melt the chocolate and butter together over a pan of barely simmering water, stirring until smooth. Let it cool for 5 minutes."},{"step":3,"title":"Whip for volume","instruction":"Beat the eggs, yolks, sugar, and salt for 4 minutes until pale, thick, and tripled in volume. This aeration is what gives the cake structure."},{"step":4,"title":"Fold, do not stir","instruction":"Fold the cooled chocolate into the eggs in three additions, then fold in the flour and vanilla just until combined."},{"step":5,"title":"Chill the batter","instruction":"Divide between the ramekins and refrigerate at least 30 minutes. Cold batter is much more reliable — the outside sets before the centre does.","tip":"Chilling the filled ramekins is the trick that makes the molten centre repeatable."},{"step":6,"title":"Bake short and hot","instruction":"Bake at 425°F (220°C) for exactly 12 minutes. The edges should be set and the centre should still wobble distinctly when nudged."},{"step":7,"title":"Turn out fast","instruction":"Rest 1 minute, run a knife round the edge, invert onto a plate, and lift the ramekin. Serve immediately with ice cream."}]'::JSONB, 'Ovens vary, so bake one test cake first if you can. At 11 minutes it may collapse; at 14 it is a very good chocolate cake with no lava. The wobble in the centre is the only reliable indicator.', ARRAY['Make-ahead: Filled ramekins keep 2 days in the fridge — bake from cold, adding 1 minute.','Surprise centre: Push a square of chocolate or a spoon of salted caramel into the middle before baking.','Gluten-free: Almond flour substitutes directly for the 3 tablespoons.']::TEXT[], ARRAY['Gluten','Dairy','Egg']::TEXT[]),
('banana-bread', 'Banana Bread', 'The blackest bananas you own, melted butter rather than creamed, and a batter barely mixed.', 'https://img.rocket.new/generatedImages/rocket_gen_img_12da978a7-1778500554885.png', 'Moist golden banana bread loaf with walnuts on a cutting board', 'Priya Nair', '@priyanairkitchen', '', '', '15 min', '45 min', '1 hr', 15, 45, 60, 10, 'Easy', 'American', 'Snack', 'Baked Goods', ARRAY['Baking','Vegetarian','Family','Freezer-Friendly']::TEXT[], 5.0, 1663, 7707, 312, 5, 44, 14, 2, '[{"amount":"4","unit":"","item":"very ripe bananas, mashed"},{"amount":"0.5","unit":"cup","item":"melted butter"},{"amount":"0.75","unit":"cup","item":"brown sugar"},{"amount":"2","unit":"large","item":"eggs"},{"amount":"1","unit":"tsp","item":"vanilla extract"},{"amount":"1.75","unit":"cups","item":"all-purpose flour"},{"amount":"1","unit":"tsp","item":"baking soda"},{"amount":"0.5","unit":"tsp","item":"salt"},{"amount":"1","unit":"tsp","item":"ground cinnamon"},{"amount":"0.5","unit":"cup","item":"chopped walnuts"},{"amount":"0.25","unit":"cup","item":"sour cream"}]'::JSONB, '[{"step":1,"title":"Use blackened bananas","instruction":"The skins should be mostly black. Yellow bananas have neither the sugar nor the flavour and produce a bland, cakey loaf.","tip":"If yours are underripe, bake them in the skins at 300°F for 20 minutes and cool."},{"step":2,"title":"Melt, do not cream","instruction":"Whisk the melted butter into the brown sugar, then the eggs, vanilla, sour cream, and mashed banana. Melted butter gives a denser, moister crumb than creaming."},{"step":3,"title":"Combine dry separately","instruction":"Whisk the flour, baking soda, salt, and cinnamon together before adding, so the soda is evenly distributed."},{"step":4,"title":"Mix minimally","instruction":"Fold the dry into the wet until just a few streaks of flour remain, then fold in the walnuts. Overmixing makes it tough and gives it a tunnelled crumb.","tip":"Stop while it still looks slightly underdone. Ten seconds too long changes the texture."},{"step":5,"title":"Bake low and long","instruction":"Bake at 350°F (175°C) for 60–65 minutes until a skewer comes out with a few moist crumbs. Tent with foil if the top darkens too fast."},{"step":6,"title":"Cool in the tin","instruction":"Cool 15 minutes in the tin, then turn out onto a rack. It slices much more cleanly once completely cool."}]'::JSONB, 'The sour cream is what keeps this moist for four days rather than two. Freezes well whole or sliced for 3 months. It tastes noticeably better on day two once the banana flavour settles.', ARRAY['Swap: Chocolate chips instead of walnuts, or both.','Vegan: Flax eggs and plant butter work; the crumb is slightly denser.','Muffins: Same batter, 20 minutes at 375°F, makes 12.']::TEXT[], ARRAY['Gluten','Dairy','Egg','Tree Nut']::TEXT[]),
('cinnamon-rolls', 'Cinnamon Rolls', 'Enriched dough rolled tight around cinnamon butter, proved twice, baked soft, and finished with cream cheese frosting.', 'https://img.rocket.new/generatedImages/rocket_gen_img_1aecd958f-1772207180241.png', 'Freshly baked cinnamon rolls with cream cheese frosting in a baking pan', 'Emma Walsh', '@emmawalshbakes', '', '', '40 min', '1.3 hrs', '2 hrs', 40, 80, 120, 12, 'Medium', 'American', 'Breakfast', 'Baked Goods', ARRAY['Baking','Brunch','Weekend','Vegetarian']::TEXT[], 4.6, 1367, 570, 428, 7, 58, 19, 2, '[{"amount":"4","unit":"cups","item":"all-purpose flour"},{"amount":"2.25","unit":"tsp","item":"instant yeast"},{"amount":"1","unit":"cup","item":"warm milk"},{"amount":"0.33","unit":"cup","item":"granulated sugar"},{"amount":"2","unit":"large","item":"eggs"},{"amount":"0.33","unit":"cup","item":"softened butter"},{"amount":"1","unit":"tsp","item":"salt"},{"amount":"0.75","unit":"cup","item":"brown sugar"},{"amount":"3","unit":"tbsp","item":"ground cinnamon"},{"amount":"0.5","unit":"cup","item":"very soft butter for filling"},{"amount":"4","unit":"oz","item":"cream cheese"},{"amount":"3","unit":"tbsp","item":"butter for frosting"},{"amount":"1.5","unit":"cups","item":"powdered sugar"},{"amount":"1","unit":"tsp","item":"vanilla extract"}]'::JSONB, '[{"step":1,"title":"Check the milk temperature","instruction":"The milk should be warm to the touch, around 110°F. Hotter kills the yeast; colder and it never activates properly."},{"step":2,"title":"Knead well","instruction":"Mix everything for the dough and knead 8 minutes until smooth and elastic. It should pass the windowpane test — a stretched piece goes translucent without tearing.","tip":"Enriched dough needs proper kneading. Under-kneaded rolls come out dense and crumbly."},{"step":3,"title":"First rise","instruction":"Cover and prove 1 hour until doubled."},{"step":4,"title":"Roll and fill","instruction":"Roll into a 16x12-inch rectangle. Spread the very soft butter right to the edges, then scatter the brown sugar and cinnamon evenly over it."},{"step":5,"title":"Roll tight and cut with floss","instruction":"Roll up firmly from the long edge. Cut into 12 rolls using a length of dental floss slid underneath and pulled crosswise — a knife squashes them flat.","tip":"Floss gives perfectly round rolls. This genuinely makes a visible difference."},{"step":6,"title":"Second rise","instruction":"Arrange in a buttered dish with space between, cover, and prove 45 minutes until puffy and touching."},{"step":7,"title":"Bake and frost warm","instruction":"Bake at 350°F (175°C) for 25 minutes until golden. Beat the cream cheese, butter, powdered sugar, and vanilla and spread over while the rolls are still warm but not hot."}]'::JSONB, 'For morning rolls, complete through shaping, then refrigerate overnight and let them come to room temperature for an hour before baking. Frosting a scorching hot tray makes it slide off entirely; warm is right.', ARRAY['Extra gooey: Pour a quarter cup of cream over the rolls just before baking.','Make-ahead: Baked rolls freeze for 2 months; reheat covered at 300°F.','Dairy-free: Plant milk, vegan butter, and dairy-free cream cheese all substitute directly.']::TEXT[], ARRAY['Gluten','Dairy','Egg']::TEXT[]),
('blueberry-muffins', 'Blueberry Muffins', 'Bakery-style domed muffins — a thick batter, a hot start, and berries tossed in flour so they stay put.', 'https://images.unsplash.com/photo-1558303420-f814d8a590f5', 'Golden blueberry muffins with sugar crumble topping in a muffin tin', 'Aisha Sharma', '@aishasharmaspice', '', '', '15 min', '20 min', '35 min', 15, 20, 35, 12, 'Easy', 'American', 'Breakfast', 'Baked Goods', ARRAY['Baking','Vegetarian','Family','Quick']::TEXT[], 4.9, 314, 1251, 284, 5, 42, 11, 2, '[{"amount":"2.5","unit":"cups","item":"all-purpose flour"},{"amount":"1","unit":"cup","item":"granulated sugar"},{"amount":"2.5","unit":"tsp","item":"baking powder"},{"amount":"0.5","unit":"tsp","item":"salt"},{"amount":"2","unit":"large","item":"eggs"},{"amount":"1","unit":"cup","item":"whole milk"},{"amount":"0.5","unit":"cup","item":"melted butter"},{"amount":"2","unit":"tsp","item":"vanilla extract"},{"amount":"2","unit":"cups","item":"fresh blueberries"},{"amount":"2","unit":"tbsp","item":"flour for tossing"},{"amount":"","unit":"","item":"Demerara sugar for the tops"}]'::JSONB, '[{"step":1,"title":"Toss the berries in flour","instruction":"Coat the blueberries in 2 tablespoons of flour. This stops them sinking to the bottom of every muffin.","tip":"A dry coating gives the batter something to grip. It works, and it takes ten seconds."},{"step":2,"title":"Keep the batter thick","instruction":"Whisk the dry ingredients, then fold in the combined wet ingredients until just barely mixed. The batter should be thick enough to hold a spoon upright — thin batter spreads flat instead of doming."},{"step":3,"title":"Do not overmix","instruction":"Lumps are fine. Stirring until smooth develops gluten and gives you chewy, tough muffins."},{"step":4,"title":"Fill to the top","instruction":"Fold in the floured berries and fill the muffin cases right to the brim. Underfilled cases cannot produce a dome."},{"step":5,"title":"Start hot, then drop","instruction":"Bake at 425°F (220°C) for 5 minutes, then reduce to 375°F (190°C) without opening the door and bake 15 minutes more.","tip":"The initial blast of heat causes a rapid rise that sets the dome before the crumb firms up."},{"step":6,"title":"Cool briefly","instruction":"Sprinkle with demerara before baking, and cool 5 minutes in the tin before moving to a rack."}]'::JSONB, 'Frozen blueberries work but do not thaw them, and expect some purple streaking. Resting the batter 30 minutes before scooping gives slightly taller muffins if you have the time.', ARRAY['Streusel: Rub together flour, butter, and brown sugar for a crumble top.','Lemon: A tablespoon of lemon zest in the batter suits the blueberries well.','Freezer: Freeze baked muffins for 2 months; 30 seconds in the microwave brings them back.']::TEXT[], ARRAY['Gluten','Dairy','Egg']::TEXT[]),
('cheesecake', 'Cheesecake', 'A dense New York cheesecake baked in a water bath and cooled slowly, so it sets without a crack down the middle.', 'https://img.rocket.new/generatedImages/rocket_gen_img_1e366641f-1772871592638.png', 'Creamy New York style cheesecake with graham cracker crust and berry topping', 'Sofia Patel', '@sofiapatelkitchen', 'https://images.unsplash.com/photo-1716947674021-1b8b696325c7', 'Portrait of food creator Sofia Patel', '30 min', '3.5 hrs', '4 hrs', 30, 210, 240, 12, 'Medium', 'American', 'Dessert', 'Dessert', ARRAY['Baking','Make-Ahead','Vegetarian','Crowd Pleaser']::TEXT[], 4.5, 1470, 8951, 512, 9, 42, 35, 1, '[{"amount":"2","unit":"cups","item":"graham cracker crumbs"},{"amount":"6","unit":"tbsp","item":"melted butter"},{"amount":"2","unit":"lb","item":"full-fat cream cheese, room temperature"},{"amount":"1.25","unit":"cups","item":"granulated sugar"},{"amount":"4","unit":"large","item":"eggs, room temperature"},{"amount":"1","unit":"cup","item":"sour cream"},{"amount":"2","unit":"tsp","item":"vanilla extract"},{"amount":"2","unit":"tbsp","item":"all-purpose flour"},{"amount":"1","unit":"tbsp","item":"lemon juice"},{"amount":"","unit":"","item":"Pinch of salt"},{"amount":"","unit":"","item":"Berry compote to serve"}]'::JSONB, '[{"step":1,"title":"Everything at room temperature","instruction":"Cream cheese and eggs must be fully at room temperature. Cold cream cheese never smooths out and leaves lumps you cannot beat away later.","tip":"Take them out two hours ahead. This is the most common cheesecake mistake."},{"step":2,"title":"Press the base firmly","instruction":"Mix the crumbs and butter and press hard into a lined 9-inch springform, using a flat glass. Bake at 350°F (175°C) for 10 minutes and cool."},{"step":3,"title":"Beat on low","instruction":"Beat the cream cheese and sugar on low speed until smooth, scraping down often. Beating fast whips in air, and air bubbles are what cause cracks and a soufflé-like rise.","tip":"Low speed throughout. You are combining, not aerating."},{"step":4,"title":"Add eggs one at a time","instruction":"Add each egg on low speed, mixing only until it disappears. Then mix in the sour cream, vanilla, flour, lemon, and salt."},{"step":5,"title":"Water bath","instruction":"Wrap the tin base in two layers of foil, set it in a roasting pan, and pour in boiling water halfway up the sides. The steam keeps the surface from drying and cracking."},{"step":6,"title":"Bake and cool slowly","instruction":"Bake at 325°F (160°C) for 70 minutes. The centre 3 inches should still wobble. Turn the oven off, prop the door open, and leave it inside for 1 hour.","tip":"The slow cool is what prevents cracking. A sudden temperature drop splits the surface every time."},{"step":7,"title":"Chill overnight","instruction":"Refrigerate at least 8 hours, ideally overnight, before releasing the tin."}]'::JSONB, 'A cheesecake that looks done in the oven is overbaked — it firms up entirely during chilling. Run a thin knife around the edge before the first chill so the cake can contract without tearing itself.', ARRAY['No springform: A deep cake tin lined with a parchment sling works.','Cracks: Cover them with sour cream topping or compote. Nobody will know.','Make-ahead: Better on day two, and keeps 5 days. Freezes whole for 2 months.']::TEXT[], ARRAY['Gluten','Dairy','Egg']::TEXT[]),
('air-fryer-chicken-wings', 'Air Fryer Chicken Wings', 'Baking powder on dry wings gives shatteringly crisp skin with no oil and no deep fryer.', 'https://img.rocket.new/generatedImages/rocket_gen_img_1dc41e977-1772091572034.png', 'Crispy air fryer chicken wings with buffalo sauce and blue cheese dip', 'Jake Torres', '@jaketorrescooks', 'https://images.unsplash.com/photo-1572015837827-01671d41e102', 'Portrait of food creator Jake Torres', '10 min', '15 min', '25 min', 10, 15, 25, 4, 'Easy', 'American', 'Snack', 'Appetizer', ARRAY['Air Fryer','Gluten-Free','Party Food','High Protein']::TEXT[], 4.4, 66, 5973, 462, 34, 4, 34, 0, '[{"amount":"2","unit":"lb","item":"chicken wings, split into flats and drumettes"},{"amount":"1","unit":"tbsp","item":"baking powder (not baking soda)"},{"amount":"1","unit":"tsp","item":"salt"},{"amount":"1","unit":"tsp","item":"garlic powder"},{"amount":"0.5","unit":"tsp","item":"black pepper"},{"amount":"4","unit":"tbsp","item":"butter, melted"},{"amount":"0.33","unit":"cup","item":"hot sauce"},{"amount":"1","unit":"tbsp","item":"honey"},{"amount":"","unit":"","item":"Blue cheese dip and celery to serve"}]'::JSONB, '[{"step":1,"title":"Dry the wings thoroughly","instruction":"Pat every wing completely dry with kitchen paper. If you have time, leave them uncovered in the fridge for a few hours.","tip":"Moisture is the enemy of crisp skin. Dry wings, every time."},{"step":2,"title":"Use baking powder, not soda","instruction":"Toss the wings with the baking powder, salt, garlic powder, and pepper. Baking powder raises the skin pH so it browns and blisters. Baking soda will make them taste soapy.","tip":"Check the tub carefully. Powder, not soda — they are not interchangeable here."},{"step":3,"title":"Single layer, no crowding","instruction":"Arrange in the basket in one layer with space between each wing. Cook in batches if needed; stacked wings steam."},{"step":4,"title":"Cook in two stages","instruction":"Air fry at 250°F (120°C) for 12 minutes to render the fat, then raise to 400°F (205°C) for 12 minutes more, flipping once, until deep golden and crackling.","tip":"The low first stage renders the fat out; the high second stage crisps the skin. Both matter."},{"step":5,"title":"Sauce at the end","instruction":"Whisk the melted butter, hot sauce, and honey. Toss the hot wings in it and serve immediately with dip."}]'::JSONB, 'Sauced wings soften within minutes, so toss them just before they hit the table. Unsauced, they hold their crunch in a low oven for about 20 minutes.', ARRAY['Oven: 250°F for 30 minutes then 425°F for 20 minutes on a rack.','Dry rub: Skip the sauce and toss with lemon pepper or Cajun seasoning instead.','Make-ahead: Cook through the low stage a day early, then finish hot before serving.']::TEXT[], ARRAY['Dairy']::TEXT[]),
('air-fryer-french-fries', 'Air Fryer French Fries', 'Soaked, dried, and double-cooked in the air fryer — crisp outside, fluffy inside, barely any oil.', 'https://images.unsplash.com/photo-1601592430325-e0e1551b48ef', 'Golden crispy air fryer french fries with sea salt in a paper cone', 'Carlos Mendez', '@carlosmendezcooks', '', '', '15 min', '5 min', '20 min', 15, 5, 20, 4, 'Easy', 'American', 'Snack', 'Side Dish', ARRAY['Air Fryer','Vegan','Gluten-Free','Budget']::TEXT[], 4.9, 1400, 9375, 242, 5, 42, 6, 4, '[{"amount":"2","unit":"lb","item":"russet potatoes, cut into 1/4-inch batons"},{"amount":"1","unit":"tbsp","item":"neutral oil"},{"amount":"1","unit":"tsp","item":"salt"},{"amount":"0.5","unit":"tsp","item":"garlic powder"},{"amount":"0.5","unit":"tsp","item":"smoked paprika"},{"amount":"","unit":"","item":"Flaky salt to finish"}]'::JSONB, '[{"step":1,"title":"Soak to remove starch","instruction":"Soak the cut potatoes in cold water for at least 30 minutes, changing the water once. The water will turn cloudy — that is surface starch that would otherwise make them gluey.","tip":"Thirty minutes minimum. This step separates real fries from soft potato sticks."},{"step":2,"title":"Dry completely","instruction":"Drain and dry the batons thoroughly in a clean tea towel. Any remaining water steams them instead of crisping."},{"step":3,"title":"Oil lightly","instruction":"Toss with just one tablespoon of oil plus the salt, garlic powder, and paprika. More oil makes them heavy rather than crisper."},{"step":4,"title":"Cook low first","instruction":"Air fry at 300°F (150°C) for 12 minutes, shaking twice. They will look pale and unappealing — this stage cooks the interior."},{"step":5,"title":"Then blast hot","instruction":"Raise to 400°F (205°C) for 8–10 minutes, shaking twice, until deep golden and crisp at the edges.","tip":"The two-temperature method is exactly what double frying does in oil, without the oil."},{"step":6,"title":"Salt immediately","instruction":"Tip into a bowl and toss with flaky salt while still blazing hot, so it sticks."}]'::JSONB, 'Russets are essential — waxy potatoes stay dense and never fluff inside. Cook in two batches rather than filling the basket; a crowded basket is the most common reason air fryer chips come out limp.', ARRAY['Wedges: Cut thicker and add 5 minutes to the high stage.','Make-ahead: Soaked, dried potatoes keep in the fridge overnight covered in a damp cloth.','Seasoning: Toss with grated parmesan and parsley in the final bowl.']::TEXT[], ARRAY[]::TEXT[]),
('air-fryer-salmon', 'Air Fryer Salmon', 'Twelve minutes from fridge to plate, with a lacquered top and a moist centre.', 'https://img.rocket.new/generatedImages/rocket_gen_img_13cb601db-1782924149319.png', 'Perfectly cooked air fryer salmon with lemon and dill garnish', 'Maria Chen', '@mariachencooks', 'https://images.unsplash.com/photo-1677229888051-211da3f34219', 'Portrait of food creator Maria Chen', '5 min', '7 min', '12 min', 5, 7, 12, 2, 'Easy', 'Modern', 'Dinner', 'Main Course', ARRAY['Air Fryer','Seafood','Quick','Gluten-Free']::TEXT[], 4.8, 1793, 3344, 368, 36, 6, 22, 0, '[{"amount":"2","unit":"fillets","item":"salmon (6 oz each)"},{"amount":"1","unit":"tbsp","item":"olive oil"},{"amount":"1","unit":"tsp","item":"garlic powder"},{"amount":"1","unit":"tsp","item":"smoked paprika"},{"amount":"1","unit":"tbsp","item":"honey"},{"amount":"1","unit":"tsp","item":"Dijon mustard"},{"amount":"1","unit":"","item":"lemon"},{"amount":"1","unit":"tbsp","item":"chopped dill"},{"amount":"","unit":"","item":"Salt and pepper"}]'::JSONB, '[{"step":1,"title":"Preheat the basket","instruction":"Run the air fryer empty at 400°F (205°C) for 3 minutes. A cold basket gives the salmon a slow, grey start."},{"step":2,"title":"Dry and season","instruction":"Pat the fillets completely dry, rub with oil, and season with garlic powder, paprika, salt, and pepper."},{"step":3,"title":"Cook skin-side down","instruction":"Air fry at 400°F (205°C) for 8 minutes. Do not flip — the circulating air cooks the top without needing it.","tip":"No flipping. Turning salmon in an air fryer is how it breaks apart."},{"step":4,"title":"Glaze and finish","instruction":"Mix the honey and Dijon, brush over the fillets, and cook 2 minutes more until it bubbles and tacks up."},{"step":5,"title":"Rest","instruction":"Rest 3 minutes — it should reach about 130°F internal — then finish with lemon and dill."}]'::JSONB, 'Thickness drives the timing far more than weight: a thick centre-cut fillet needs the full 10 minutes, a thin tail piece only 7. Check the thickest part flakes with gentle pressure.', ARRAY['Frozen: Cook straight from frozen at 390°F for 14 minutes, glazing in the last 3.','Teriyaki: Swap the honey-Dijon for teriyaki sauce.','Vegetables: Asparagus in the basket alongside cooks in the same time.']::TEXT[], ARRAY['Fish']::TEXT[]),
('air-fryer-donuts', 'Air Fryer Donuts', 'Tinned biscuit dough cut into rings and air fried into hot, sugared doughnuts in under ten minutes.', 'https://images.unsplash.com/photo-1606312618872-929717f93c21', 'Fluffy air fryer donuts with glaze and colorful sprinkles', 'Emma Walsh', '@emmawalshbakes', '', '', '10 min', '10 min', '20 min', 10, 10, 20, 8, 'Easy', 'American', 'Dessert', 'Dessert', ARRAY['Air Fryer','Quick','Family','Vegetarian']::TEXT[], 4.7, 431, 6217, 268, 4, 38, 11, 1, '[{"amount":"1","unit":"can","item":"refrigerated biscuit dough (8 count)"},{"amount":"3","unit":"tbsp","item":"melted butter"},{"amount":"0.5","unit":"cup","item":"granulated sugar"},{"amount":"1","unit":"tbsp","item":"ground cinnamon"},{"amount":"1","unit":"cup","item":"powdered sugar"},{"amount":"2","unit":"tbsp","item":"milk"},{"amount":"0.5","unit":"tsp","item":"vanilla extract"},{"amount":"","unit":"","item":"Sprinkles"}]'::JSONB, '[{"step":1,"title":"Cut the rings","instruction":"Separate the biscuits and cut a hole from the centre of each with a small round cutter or a bottle cap. Keep the holes — they cook in 3 minutes."},{"step":2,"title":"Do not crowd","instruction":"Place 3–4 rings in the basket with clear space between. They expand a lot and will fuse together if touching.","tip":"Half a basket at a time. They roughly double in size."},{"step":3,"title":"Air fry","instruction":"Cook at 350°F (175°C) for 5–6 minutes, flipping at the halfway point, until puffed and golden on both sides."},{"step":4,"title":"Butter and coat while hot","instruction":"Brush immediately with melted butter and roll in the cinnamon sugar. The butter is what makes the sugar stick.","tip":"Coat them straight out of the basket. Cooled doughnuts will not take the sugar."},{"step":5,"title":"Or glaze","instruction":"For a glazed version, whisk the powdered sugar, milk, and vanilla and dip the tops once the doughnuts have cooled for 2 minutes, then add sprinkles."}]'::JSONB, 'These are best within about ten minutes of cooking and genuinely poor an hour later, so make them to order rather than in advance. Homemade yeasted dough works too but needs a 40-minute prove.', ARRAY['Filled: Skip the hole, air fry whole, then pipe in jam or custard with a nozzle.','Chocolate glaze: Melted chocolate thinned with a little cream.','Doughnut holes: The cut-out centres cook in 3 minutes and children prefer them.']::TEXT[], ARRAY['Gluten','Dairy']::TEXT[]),
('air-fryer-vegetables', 'Air Fryer Vegetables', 'Any hardy vegetable, cut evenly, tossed in oil and cooked hot until the edges blacken.', 'https://img.rocket.new/generatedImages/rocket_gen_img_1b3a1542b-1772084616223.png', 'Crispy roasted air fryer vegetables with olive oil and herbs', 'Priya Nair', '@priyanairkitchen', '', '', '10 min', '5 min', '15 min', 10, 5, 15, 4, 'Easy', 'Modern', 'Dinner', 'Side Dish', ARRAY['Air Fryer','Vegan','Gluten-Free','Healthy']::TEXT[], 4.4, 1293, 6396, 162, 4, 18, 9, 5, '[{"amount":"1","unit":"","item":"broccoli head, in florets"},{"amount":"2","unit":"","item":"carrots, thick-sliced"},{"amount":"1","unit":"","item":"red pepper, chunked"},{"amount":"1","unit":"","item":"courgette, thick-sliced"},{"amount":"1","unit":"","item":"red onion, wedged"},{"amount":"2","unit":"tbsp","item":"olive oil"},{"amount":"1","unit":"tsp","item":"garlic powder"},{"amount":"1","unit":"tsp","item":"dried Italian herbs"},{"amount":"0.5","unit":"tsp","item":"smoked paprika"},{"amount":"","unit":"","item":"Salt and black pepper"},{"amount":"","unit":"","item":"Lemon to finish"}]'::JSONB, '[{"step":1,"title":"Cut to matching sizes","instruction":"Cut everything to roughly the same thickness. Dense vegetables like carrot should be cut thinner than soft ones like courgette so they finish together.","tip":"Uneven cutting is why air-fried vegetables come out half burnt and half raw."},{"step":2,"title":"Use enough oil","instruction":"Toss with the full two tablespoons of oil and all the seasoning. Under-oiled vegetables dry out and go leathery rather than caramelising."},{"step":3,"title":"Shake the basket","instruction":"Cook at 380°F (195°C) for 15–18 minutes, shaking the basket firmly every 5 minutes."},{"step":4,"title":"Cook in batches if needed","instruction":"A single layer browns; a piled basket steams. Two batches is faster than one bad one."},{"step":5,"title":"Finish bright","instruction":"Tip into a bowl and add a squeeze of lemon and a final pinch of flaky salt while hot."}]'::JSONB, 'Timings by type: broccoli and courgette 12 minutes, peppers and onion 15, carrots and potato 20. If mixing very different vegetables, add the quicker ones partway through.', ARRAY['Parmesan: Toss with grated parmesan in the last 2 minutes.','Frozen: Works without thawing; add 5 minutes and expect slightly less browning.','Meal prep: Cook a large batch and reheat 3 minutes at 400°F to re-crisp.']::TEXT[], ARRAY[]::TEXT[]),
('air-fryer-steak', 'Air Fryer Steak', 'A thick steak air fried hot and finished with herb butter. Reliable, if not quite a cast iron sear.', 'https://img.rocket.new/generatedImages/rocket_gen_img_1db10218f-1772446279214.png', 'Perfectly seared air fryer steak with herb butter on a cast iron plate', 'Jake Torres', '@jaketorrescooks', 'https://images.unsplash.com/photo-1572015837827-01671d41e102', 'Portrait of food creator Jake Torres', '5 min', '10 min', '15 min', 5, 10, 15, 2, 'Medium', 'American', 'Dinner', 'Main Course', ARRAY['Air Fryer','High Protein','Gluten-Free','Quick']::TEXT[], 4.9, 1558, 7368, 612, 48, 2, 46, 0, '[{"amount":"2","unit":"","item":"ribeye or sirloin steaks, 1.5 inches thick"},{"amount":"1","unit":"tbsp","item":"neutral oil"},{"amount":"1","unit":"tsp","item":"salt"},{"amount":"1","unit":"tsp","item":"coarse black pepper"},{"amount":"3","unit":"tbsp","item":"softened butter"},{"amount":"1","unit":"clove","item":"garlic, grated"},{"amount":"1","unit":"tbsp","item":"chopped parsley"},{"amount":"0.5","unit":"tsp","item":"chopped thyme"}]'::JSONB, '[{"step":1,"title":"Temper the steak","instruction":"Take the steaks out 40 minutes ahead. A fridge-cold steak cooks unevenly, leaving a grey band around a cold centre."},{"step":2,"title":"Dry and season heavily","instruction":"Pat completely dry, rub with oil, and season far more aggressively with salt and pepper than feels right.","tip":"Dry surface, heavy seasoning. Both matter more in an air fryer than in a pan."},{"step":3,"title":"Preheat properly","instruction":"Run the air fryer at 400°F (205°C) for 5 minutes before the steak goes in. This is not optional if you want any browning."},{"step":4,"title":"Cook by thickness","instruction":"Air fry at 400°F, flipping once at the halfway point: 8 minutes total for rare, 10 for medium-rare, 12 for medium on a 1.5-inch steak."},{"step":5,"title":"Check the temperature","instruction":"Pull at 125°F for medium-rare — it climbs another 5 degrees while resting."},{"step":6,"title":"Rest and butter","instruction":"Rest 8 minutes on a warm plate. Mash the butter with garlic and herbs and put a spoonful on top to melt over.","tip":"Eight minutes of rest. Cutting early loses the juice onto the board."}]'::JSONB, 'An air fryer will not match a screaming cast iron pan for crust, but it is far more forgiving and produces no smoke. For the best of both, air fry to 115°F then sear 45 seconds a side in a very hot pan.', ARRAY['Thin steaks: Under an inch, use 400°F for 6 minutes total and watch closely.','Frozen: 360°F for 20 minutes, flipping twice; season halfway once the surface thaws.','Slice against the grain, always — especially with sirloin.']::TEXT[], ARRAY['Dairy']::TEXT[]),
('stuffed-bell-peppers', 'Stuffed Bell Peppers', 'Peppers par-roasted first, then filled with spiced rice and meat and baked until the tops brown.', 'https://images.unsplash.com/photo-1706222173694-5264de2d23d9', 'Colorful stuffed bell peppers filled with rice, vegetables, and melted cheese', 'Leila Hassan', '@leilahassantable', '', '', '20 min', '25 min', '45 min', 20, 25, 45, 6, 'Easy', 'Mediterranean', 'Dinner', 'Main Course', ARRAY['Family','Make-Ahead','Gluten-Free','Balanced']::TEXT[], 4.7, 987, 5227, 412, 24, 38, 18, 5, '[{"amount":"6","unit":"large","item":"bell peppers, tops cut and seeded"},{"amount":"1","unit":"lb","item":"ground beef or lamb"},{"amount":"1.5","unit":"cups","item":"cooked rice"},{"amount":"1","unit":"","item":"onion, diced"},{"amount":"3","unit":"cloves","item":"garlic, minced"},{"amount":"14","unit":"oz","item":"crushed tomatoes"},{"amount":"1","unit":"tsp","item":"ground cumin"},{"amount":"1","unit":"tsp","item":"smoked paprika"},{"amount":"0.5","unit":"tsp","item":"cinnamon"},{"amount":"1","unit":"cup","item":"grated cheese"},{"amount":"2","unit":"tbsp","item":"olive oil"},{"amount":"0.25","unit":"cup","item":"chopped parsley"},{"amount":"","unit":"","item":"Salt and black pepper"}]'::JSONB, '[{"step":1,"title":"Par-roast the peppers","instruction":"Rub the hollow peppers with oil and roast cut-side down at 400°F (205°C) for 15 minutes. This softens them and drives off water that would otherwise pool in the dish.","tip":"Skipping this leaves you with crunchy peppers and a watery bake."},{"step":2,"title":"Brown the meat","instruction":"Brown the meat hard in a pan, then add the onion for 5 minutes and the garlic for 30 seconds."},{"step":3,"title":"Build the filling","instruction":"Add the cumin, paprika, cinnamon, and half the tomatoes. Simmer 5 minutes, then fold through the cooked rice and parsley and season well."},{"step":4,"title":"Fill and top","instruction":"Spread the remaining tomatoes in a baking dish, stand the peppers upright, and pack the filling in firmly. Top with cheese."},{"step":5,"title":"Bake covered then open","instruction":"Bake covered at 375°F (190°C) for 25 minutes, then uncover for 15 minutes until the cheese browns."}]'::JSONB, 'Standing peppers wobble — trim a sliver off the base to flatten them, being careful not to cut through. Assembled unbaked peppers keep 2 days in the fridge.', ARRAY['Vegetarian: Lentils or black beans and mushrooms in place of the meat.','Grain swap: Quinoa, couscous, or cauliflower rice all work.','Freezer: Freeze filled and unbaked for 2 months; bake from frozen, covered, for 60 minutes.']::TEXT[], ARRAY['Dairy']::TEXT[]),
('vegetable-curry', 'Vegetable Curry', 'Chickpeas and vegetables in a coconut and tomato sauce built on spices bloomed in oil.', 'https://images.unsplash.com/photo-1585034888529-0898b2145847', 'Fragrant vegetable curry with chickpeas, spinach, and coconut milk', 'Aisha Sharma', '@aishasharmaspice', '', '', '15 min', '20 min', '35 min', 15, 20, 35, 6, 'Easy', 'Indian', 'Dinner', 'Main Course', ARRAY['Vegan','Gluten-Free','Budget','Freezer-Friendly']::TEXT[], 5.0, 1790, 1706, 368, 12, 42, 18, 11, '[{"amount":"3","unit":"tbsp","item":"coconut oil"},{"amount":"1","unit":"","item":"onion, diced"},{"amount":"4","unit":"cloves","item":"garlic, minced"},{"amount":"2","unit":"inch","item":"ginger, grated"},{"amount":"2","unit":"tsp","item":"ground cumin"},{"amount":"2","unit":"tsp","item":"ground coriander"},{"amount":"1","unit":"tsp","item":"turmeric"},{"amount":"1","unit":"tsp","item":"garam masala"},{"amount":"0.5","unit":"tsp","item":"cayenne"},{"amount":"14","unit":"oz","item":"crushed tomatoes"},{"amount":"14","unit":"oz","item":"full-fat coconut milk"},{"amount":"1","unit":"can","item":"chickpeas, drained"},{"amount":"1","unit":"","item":"cauliflower, in florets"},{"amount":"5","unit":"oz","item":"spinach"},{"amount":"1","unit":"","item":"lime, juiced"},{"amount":"","unit":"","item":"Salt"},{"amount":"","unit":"","item":"Cilantro and rice to serve"}]'::JSONB, '[{"step":1,"title":"Soften the base","instruction":"Cook the onion in the coconut oil for 8 minutes until soft and golden, then add the garlic and ginger for 1 minute."},{"step":2,"title":"Bloom the spices in oil","instruction":"Add all the ground spices and stir constantly for 60 seconds until intensely aromatic and slightly darkened.","tip":"Spices need fat and direct heat to release their flavour. Added to liquid they stay raw and dusty."},{"step":3,"title":"Reduce the tomatoes","instruction":"Add the tomatoes and cook 8 minutes until thickened and the oil starts to separate at the edges."},{"step":4,"title":"Simmer the vegetables","instruction":"Add the coconut milk, chickpeas, and cauliflower. Simmer 15 minutes until the cauliflower is tender but not collapsing."},{"step":5,"title":"Wilt and brighten","instruction":"Stir in the spinach until wilted, then add the lime juice and salt off the heat. Taste and add more lime if it seems flat.","tip":"Acid at the end lifts the whole curry. Without it, coconut curries taste heavy."}]'::JSONB, 'Full-fat coconut milk is important — the light version splits and gives a thin, watery sauce. This freezes well for 3 months, though the cauliflower softens on reheating.', ARRAY['Vegetables: Sweet potato, green beans, peas, and aubergine all work; adjust the simmer to suit.','Add protein: Fried paneer or crisped tofu folded in at the end.','Heat: Cayenne carries it. Halve for mild, or add a sliced green chilli with the garlic.']::TEXT[], ARRAY['Coconut']::TEXT[])
