INSERT INTO public.recipes (slug, title, description, image, image_alt, creator_name, creator_handle, creator_image, creator_alt, prep_time, cook_time, total_time, prep_minutes, cook_minutes, total_minutes, servings, difficulty, cuisine, meal_type, category, tags, rating, reviews, cooks, calories, protein, carbs, fat, fiber, ingredients, steps, notes, tips, allergens) VALUES
('caprese-pasta', 'Caprese Pasta', 'Hot pasta tossed with raw tomatoes, torn mozzarella, and basil, so the cheese melts just enough.', 'https://images.unsplash.com/photo-1610817153377-e54299ffdb1e', 'Fresh caprese pasta with cherry tomatoes, mozzarella, and basil', 'Sofia Romano', '@sofiaromanoeats', '', '', '10 min', '10 min', '20 min', 10, 10, 20, 4, 'Easy', 'Italian', 'Dinner', 'Main Course', ARRAY['Vegetarian','Quick','Summer','No-Cook Sauce']::TEXT[], 4.5, 763, 5558, 548, 22, 68, 22, 4, '[{"amount":"1","unit":"lb","item":"short pasta (fusilli or penne)"},{"amount":"1.5","unit":"lb","item":"ripe cherry tomatoes, halved"},{"amount":"12","unit":"oz","item":"fresh mozzarella, torn"},{"amount":"1","unit":"large bunch","item":"fresh basil, torn"},{"amount":"5","unit":"tbsp","item":"extra virgin olive oil"},{"amount":"3","unit":"cloves","item":"garlic, grated"},{"amount":"1","unit":"tbsp","item":"balsamic vinegar"},{"amount":"","unit":"","item":"Salt and black pepper"}]'::JSONB, '[{"step":1,"title":"Macerate the tomatoes","instruction":"Toss the halved tomatoes with the olive oil, grated garlic, balsamic, a teaspoon of salt, and pepper. Leave at room temperature for at least 30 minutes.","tip":"The tomatoes release their juice and that juice is the entire sauce. Give it the full half hour."},{"step":2,"title":"Cook the pasta","instruction":"Boil the pasta in well-salted water until al dente and reserve half a cup of the water."},{"step":3,"title":"Toss hot into cold","instruction":"Add the drained hot pasta straight into the bowl of tomatoes and toss vigorously. The heat softens the tomatoes and emulsifies the oil and juice into a light sauce."},{"step":4,"title":"Add cheese off the heat","instruction":"Fold in the torn mozzarella so it goes soft and stringy at the edges without fully melting. Add a splash of pasta water if it looks dry.","tip":"Torn, not cubed — ragged edges catch the sauce."},{"step":5,"title":"Finish with basil","instruction":"Fold through the basil last, off the heat, and serve warm rather than hot."}]'::JSONB, 'This is equally good at room temperature, which makes it a good dish to bring somewhere. It does not reheat well — the mozzarella turns rubbery — so make what you will eat.', ARRAY['Burrata: Torn over the top instead of mixed through is even better.','Vegan: Use a plant mozzarella, or skip the cheese and add toasted pine nuts and capers.','Add protein: Grilled chicken or white beans both suit it.']::TEXT[], ARRAY['Gluten','Dairy']::TEXT[]),
('falafel-wrap', 'Falafel Wrap', 'Falafel made from soaked dried chickpeas — never tinned — fried crisp and wrapped with hummus and pickles.', 'https://images.unsplash.com/photo-1636168655089-5e625a233354', 'Crispy falafel wrap with hummus, vegetables, and tahini sauce', 'Leila Hassan', '@leilahassantable', '', '', '25 min', '5 min', '30 min', 25, 5, 30, 4, 'Medium', 'Middle Eastern', 'Lunch', 'Main Course', ARRAY['Vegan-Adaptable','Street Food','High Fibre']::TEXT[], 4.2, 1161, 5975, 582, 19, 68, 26, 12, '[{"amount":"1.5","unit":"cups","item":"dried chickpeas, soaked 24 hours"},{"amount":"1","unit":"","item":"onion, roughly chopped"},{"amount":"4","unit":"cloves","item":"garlic"},{"amount":"1","unit":"cup","item":"fresh parsley"},{"amount":"0.5","unit":"cup","item":"fresh cilantro"},{"amount":"2","unit":"tsp","item":"ground cumin"},{"amount":"1","unit":"tsp","item":"ground coriander"},{"amount":"1","unit":"tsp","item":"salt"},{"amount":"0.5","unit":"tsp","item":"baking powder"},{"amount":"2","unit":"tbsp","item":"flour"},{"amount":"","unit":"","item":"Oil for frying"},{"amount":"4","unit":"","item":"large flatbreads"},{"amount":"0.5","unit":"cup","item":"hummus"},{"amount":"0.33","unit":"cup","item":"tahini sauce"},{"amount":"","unit":"","item":"Tomato, cucumber, pickles, and lettuce"}]'::JSONB, '[{"step":1,"title":"Use soaked dried chickpeas","instruction":"Soak dried chickpeas for a full 24 hours but do not cook them. Tinned chickpeas contain far too much water and the falafel will disintegrate in the oil.","tip":"This is absolute. Tinned chickpeas cannot make falafel."},{"step":2,"title":"Process to a coarse crumb","instruction":"Pulse the drained chickpeas with the onion, garlic, herbs, and spices until it resembles coarse couscous. Do not make a smooth paste."},{"step":3,"title":"Rest the mixture","instruction":"Stir in the salt, baking powder, and flour and refrigerate 1 hour. This helps the mixture bind."},{"step":4,"title":"Shape and test one","instruction":"Form into small balls or patties. Fry one first at 350°F (175°C) — if it falls apart, work in another tablespoon of flour.","tip":"Always test one. It saves the whole batch."},{"step":5,"title":"Fry until deep brown","instruction":"Fry in batches for 3–4 minutes until dark golden and crisp. Drain on a rack, not paper, so the bases stay crisp."},{"step":6,"title":"Build the wrap","instruction":"Spread hummus over each warm flatbread, add falafel, salad, and pickles, drizzle with tahini sauce, and roll tightly."}]'::JSONB, 'The mixture can be made a day ahead and holds better for it. Uncooked shaped falafel freezes for 2 months and fries from frozen with an extra minute.', ARRAY['Baked: 400°F for 25 minutes, sprayed with oil. Less crisp but much lighter.','Air fryer: 375°F for 15 minutes, turning once.','Gluten-free: Chickpea flour in place of the flour, served in lettuce cups or GF flatbread.']::TEXT[], ARRAY['Gluten','Sesame']::TEXT[]),
('margherita-pizza', 'Margherita Pizza', 'A slow-fermented base baked as hot as the oven will go, with San Marzano tomatoes, mozzarella, and basil.', 'https://images.unsplash.com/photo-1703784022146-b72677752ce5', 'Classic margherita pizza with fresh mozzarella, tomato sauce, and basil leaves', 'Marco Rossi', '@marcorossicucina', '', '', '30 min', '—', '30 min', 30, 0, 30, 4, 'Medium', 'Italian', 'Dinner', 'Main Course', ARRAY['Vegetarian','Baking','Classic','Weekend']::TEXT[], 4.6, 241, 7071, 612, 24, 78, 22, 4, '[{"amount":"500","unit":"g","item":"00 flour or bread flour"},{"amount":"325","unit":"g","item":"water"},{"amount":"10","unit":"g","item":"salt"},{"amount":"2","unit":"g","item":"instant yeast"},{"amount":"14","unit":"oz","item":"tinned San Marzano tomatoes"},{"amount":"12","unit":"oz","item":"fresh mozzarella, torn and drained"},{"amount":"","unit":"","item":"Fresh basil leaves"},{"amount":"3","unit":"tbsp","item":"extra virgin olive oil"},{"amount":"","unit":"","item":"Semolina for dusting"}]'::JSONB, '[{"step":1,"title":"Ferment slowly","instruction":"Mix the flour, water, salt, and yeast into a rough dough, knead 5 minutes, then refrigerate 24–72 hours. The long cold ferment is where all the flavour comes from.","tip":"A same-day dough will taste flat. Twenty-four hours minimum, and 48 is better."},{"step":2,"title":"Divide and ball","instruction":"Divide into four balls, cover, and let them come to room temperature for 2 hours before shaping."},{"step":3,"title":"Get the oven as hot as possible","instruction":"Preheat a pizza steel or stone at maximum temperature for a full hour. Domestic ovens rarely exceed 550°F, and every degree helps.","tip":"One hour of preheating. The stone needs to be saturated with heat, not just hot."},{"step":4,"title":"Crush, do not cook, the sauce","instruction":"Crush the tinned tomatoes by hand with a pinch of salt. Neapolitan pizza sauce is raw — cooking it first makes it taste jammy."},{"step":5,"title":"Shape by hand","instruction":"Press each ball out from the centre with your fingertips, leaving a thick rim. Never use a rolling pin, which crushes out all the gas."},{"step":6,"title":"Top lightly and bake fast","instruction":"Spread a thin layer of sauce, scatter the drained mozzarella, and slide onto the stone. Bake 6–8 minutes until the crust is blistered and the cheese bubbling. Add basil and oil on the way out.","tip":"Overloading is the most common home mistake. Less topping bakes better."}]'::JSONB, 'Drain the torn mozzarella on paper for 20 minutes first — fresh mozzarella carries enough water to flood the base. If you have a broiler, switch it on for the final 90 seconds to char the rim.', ARRAY['No stone: An upturned heavy baking tray, preheated the same way, works surprisingly well.','Make-ahead: Dough balls keep 3 days refrigerated and freeze for a month.','Toppings: Whatever you add, use half of what you think you need.']::TEXT[], ARRAY['Gluten','Dairy']::TEXT[]),
('mushroom-tacos', 'Mushroom Tacos', 'Mushrooms roasted hard until they crisp at the edges, with chipotle crema and pickled onion.', 'https://images.unsplash.com/photo-1721001309902-939443092f13', 'Savory mushroom tacos with chipotle sauce, avocado, and pickled onions', 'Rosa Gutierrez', '@rosagutierrezcocina', '', '', '15 min', '5 min', '20 min', 15, 5, 20, 4, 'Easy', 'Mexican', 'Dinner', 'Main Course', ARRAY['Vegetarian','Quick','Gluten-Free-Adaptable']::TEXT[], 4.3, 1005, 6172, 342, 11, 38, 17, 6, '[{"amount":"1.5","unit":"lb","item":"mixed mushrooms, torn"},{"amount":"3","unit":"tbsp","item":"olive oil"},{"amount":"2","unit":"tsp","item":"chilli powder"},{"amount":"1","unit":"tsp","item":"ground cumin"},{"amount":"1","unit":"tsp","item":"smoked paprika"},{"amount":"3","unit":"cloves","item":"garlic, minced"},{"amount":"0.5","unit":"cup","item":"sour cream"},{"amount":"2","unit":"","item":"chipotles in adobo, minced"},{"amount":"1","unit":"","item":"lime, juiced"},{"amount":"1","unit":"","item":"red onion, thinly sliced"},{"amount":"0.5","unit":"cup","item":"white vinegar"},{"amount":"1","unit":"tsp","item":"sugar"},{"amount":"12","unit":"","item":"corn tortillas"},{"amount":"1","unit":"","item":"avocado, sliced"},{"amount":"","unit":"","item":"Cilantro and salt"}]'::JSONB, '[{"step":1,"title":"Quick-pickle the onion","instruction":"Cover the sliced onion with the vinegar, sugar, and a teaspoon of salt. Leave 20 minutes — it turns bright pink and loses its harshness."},{"step":2,"title":"Tear, do not slice","instruction":"Tear the mushrooms into rough pieces by hand. Ragged edges crisp far better than clean-cut ones.","tip":"Torn mushrooms brown much better. It looks messy and tastes better."},{"step":3,"title":"Roast hot and spread out","instruction":"Toss with the oil, spices, and salt and spread over two trays. Roast at 425°F (220°C) for 25 minutes, tossing once, until browned and crisp at the edges.","tip":"Two trays. Crowded mushrooms release water and stew in it."},{"step":4,"title":"Add garlic late","instruction":"Stir the garlic through for the final 5 minutes only, so it does not burn."},{"step":5,"title":"Make the crema","instruction":"Stir the sour cream with the chipotle and lime juice, plus a splash of water to loosen."},{"step":6,"title":"Assemble","instruction":"Warm the tortillas over a flame, fill with mushrooms, and top with crema, pickled onion, avocado, and cilantro."}]'::JSONB, 'A mix of mushroom types gives more interesting texture than one alone — oyster and maitake crisp especially well. The pickled onions keep two weeks in the fridge and improve almost anything.', ARRAY['Vegan: Cashew cream or a plant yoghurt in place of the sour cream.','Gluten-free: Corn tortillas are naturally so; check the adobo label.','Meal prep: Roast the mushrooms and pickle the onions ahead; assemble to order.']::TEXT[], ARRAY['Dairy']::TEXT[]),
('tomato-bisque', 'Tomato Bisque', 'Tinned tomatoes roasted first to concentrate them, blended smooth with cream and finished with basil.', 'https://images.unsplash.com/photo-1616537380218-372f4d2830ee', 'Creamy roasted tomato bisque with fresh basil and a swirl of cream', 'Emma Walsh', '@emmawalshbakes', '', '', '10 min', '20 min', '30 min', 10, 20, 30, 4, 'Easy', 'American', 'Lunch', 'Soup', ARRAY['Vegetarian','Comfort','Gluten-Free','Quick']::TEXT[], 4.4, 1338, 5950, 286, 6, 26, 18, 4, '[{"amount":"28","unit":"oz","item":"tinned whole tomatoes, drained"},{"amount":"3","unit":"tbsp","item":"olive oil"},{"amount":"1","unit":"","item":"onion, diced"},{"amount":"4","unit":"cloves","item":"garlic, smashed"},{"amount":"2","unit":"tbsp","item":"tomato paste"},{"amount":"2","unit":"cups","item":"vegetable stock"},{"amount":"0.5","unit":"cup","item":"heavy cream"},{"amount":"1","unit":"tsp","item":"sugar"},{"amount":"0.5","unit":"tsp","item":"smoked paprika"},{"amount":"0.5","unit":"cup","item":"fresh basil"},{"amount":"","unit":"","item":"Salt and black pepper"}]'::JSONB, '[{"step":1,"title":"Roast the tomatoes","instruction":"Spread the drained tomatoes on a tray with the garlic, a drizzle of oil, salt, and sugar. Roast at 425°F (220°C) for 25 minutes until they caramelise and blacken at the edges.","tip":"Roasting concentrates the tomatoes and adds sweetness a straight simmer never will."},{"step":2,"title":"Soften the onion","instruction":"Cook the onion in the remaining oil for 8 minutes until soft, then add the tomato paste and cook 2 minutes until it darkens."},{"step":3,"title":"Simmer together","instruction":"Add the roasted tomatoes and garlic with the stock and paprika. Simmer 15 minutes."},{"step":4,"title":"Blend thoroughly","instruction":"Blend until completely smooth — a full two minutes in a jug blender. Undermixed bisque has a grainy texture. Pass through a sieve if you want it truly silky."},{"step":5,"title":"Finish off the heat","instruction":"Stir in the cream and torn basil off the heat, then season. Do not boil after the cream goes in or it can split."}]'::JSONB, 'Tinned whole tomatoes are better than fresh here for most of the year, since they are picked ripe. If your soup tastes sharp, a pinch more sugar balances it faster than more cream.', ARRAY['Vegan: Coconut cream or a cashew cream in place of the dairy.','Grilled cheese: Non-negotiable accompaniment, cut into soldiers for dipping.','Make-ahead: Keeps 5 days; freeze before adding the cream and stir it in on reheating.']::TEXT[], ARRAY['Dairy']::TEXT[]),
('french-onion-soup', 'French Onion Soup', 'Onions cooked down for the better part of an hour until they turn to jam, in beef broth under a gruyere crouton.', 'https://img.rocket.new/generatedImages/rocket_gen_img_13b832fd6-1772088178489.png', 'Classic French onion soup with caramelized onions and melted gruyere crouton', 'Sofia Romano', '@sofiaromanoeats', '', '', '15 min', '45 min', '1 hr', 15, 45, 60, 4, 'Medium', 'French', 'Lunch', 'Soup', ARRAY['Comfort','Classic','Weekend']::TEXT[], 4.7, 1000, 1863, 486, 22, 42, 25, 4, '[{"amount":"3","unit":"lb","item":"yellow onions, thinly sliced"},{"amount":"4","unit":"tbsp","item":"butter"},{"amount":"2","unit":"tbsp","item":"olive oil"},{"amount":"1","unit":"tsp","item":"sugar"},{"amount":"1","unit":"tsp","item":"salt"},{"amount":"0.5","unit":"cup","item":"dry white wine"},{"amount":"2","unit":"tbsp","item":"all-purpose flour"},{"amount":"6","unit":"cups","item":"beef stock"},{"amount":"2","unit":"sprigs","item":"thyme"},{"amount":"1","unit":"","item":"bay leaf"},{"amount":"1","unit":"tbsp","item":"sherry vinegar"},{"amount":"8","unit":"slices","item":"baguette"},{"amount":"2","unit":"cups","item":"grated gruyere"},{"amount":"","unit":"","item":"Black pepper"}]'::JSONB, '[{"step":1,"title":"Commit to the caramelisation","instruction":"Cook the sliced onions in the butter and oil over medium-low heat with the sugar and salt for 45–55 minutes, stirring every few minutes. They should reduce to a deep brown jam.","tip":"There is no shortcut. Onions caramelised in fifteen minutes are just browned onions and the soup will taste thin."},{"step":2,"title":"Deglaze repeatedly","instruction":"Whenever a brown crust builds on the base of the pan, add a splash of water and scrape it up. Each time you do this the onions get darker."},{"step":3,"title":"Wine and flour","instruction":"Add the wine and reduce until nearly dry. Stir in the flour and cook 2 minutes."},{"step":4,"title":"Simmer the soup","instruction":"Add the stock, thyme, and bay. Simmer 30 minutes, then season and add the sherry vinegar.","tip":"The vinegar at the end cuts the sweetness and makes the whole thing taste less flat."},{"step":5,"title":"Toast the croutons","instruction":"Toast the baguette slices until dry and hard, so they float rather than dissolve."},{"step":6,"title":"Grill the tops","instruction":"Ladle into oven-safe bowls, float two croutons on each, pile with gruyere, and grill until bubbling and browned in patches."}]'::JSONB, 'Use a wide pan so the onions have surface area — a narrow pot steams them and doubles the time. The soup base alone is better made a day ahead and keeps 4 days.', ARRAY['Vegetarian: A good mushroom stock with a splash of soy sauce carries surprising depth.','No oven-safe bowls: Grill the cheese on the croutons separately and float them on top.','Freezer: The soup base freezes for 3 months; add fresh croutons and cheese on serving.']::TEXT[], ARRAY['Gluten','Dairy']::TEXT[]),
('ramen-from-scratch', 'Ramen from Scratch', 'A three-hour tonkotsu-style broth, tare, chashu, and a marinated egg. A full weekend project done properly.', 'https://img.rocket.new/generatedImages/rocket_gen_img_16fa22663-1772767892756.png', 'Rich tonkotsu ramen with chashu pork, soft-boiled egg, and nori', 'Yuna Kim', '@yunakimkitchen', '', '', '45 min', '2.3 hrs', '3 hrs', 45, 135, 180, 4, 'Hard', 'Japanese', 'Dinner', 'Main Course', ARRAY['Weekend Project','Soup','From Scratch']::TEXT[], 4.3, 579, 7455, 742, 42, 78, 28, 4, '[{"amount":"3","unit":"lb","item":"pork bones (trotter and neck)"},{"amount":"1","unit":"lb","item":"pork belly, rolled and tied"},{"amount":"1","unit":"","item":"onion, halved"},{"amount":"1","unit":"","item":"head garlic, halved"},{"amount":"3","unit":"inch","item":"ginger, sliced"},{"amount":"0.5","unit":"cup","item":"soy sauce"},{"amount":"0.25","unit":"cup","item":"mirin"},{"amount":"2","unit":"tbsp","item":"sake"},{"amount":"1","unit":"tbsp","item":"sugar"},{"amount":"4","unit":"","item":"eggs"},{"amount":"4","unit":"portions","item":"fresh ramen noodles"},{"amount":"4","unit":"","item":"scallions, sliced"},{"amount":"2","unit":"sheets","item":"nori, halved"},{"amount":"","unit":"","item":"Bamboo shoots and white pepper"}]'::JSONB, '[{"step":1,"title":"Parboil the bones","instruction":"Cover the bones with cold water, boil hard for 10 minutes, then drain and scrub each one clean. Wash the pot too.","tip":"This removes the scum and blood that would otherwise make the broth grey and gritty."},{"step":2,"title":"Boil hard for the broth","instruction":"Return the bones with fresh water, the onion, garlic, and ginger. Unlike most stocks, tonkotsu wants a rolling boil — that is what emulsifies the fat and collagen into a white, creamy broth. Boil 3 hours, topping up water.","tip":"Rolling boil, not a simmer. This is the opposite of every other stock."},{"step":3,"title":"Braise the chashu","instruction":"Simmer the rolled pork belly in the soy sauce, mirin, sake, sugar, and a cup of water for 90 minutes, turning occasionally. Cool in the liquid, then chill before slicing."},{"step":4,"title":"Make the tare and eggs","instruction":"Reserve half a cup of the chashu braising liquid as tare. Soft-boil the eggs for 6.5 minutes, ice them, peel, and marinate in the rest of the liquid for at least 4 hours."},{"step":5,"title":"Strain and season","instruction":"Strain the broth. Season each bowl individually with 2–3 tablespoons of tare rather than salting the whole pot.","tip":"Tare in the bowl, not the pot — that is how ramen shops control seasoning."},{"step":6,"title":"Assemble fast","instruction":"Cook the noodles for 90 seconds, drain very well, and put them into bowls with tare and hot broth. Top with sliced chashu, halved egg, scallions, bamboo, and nori. Serve immediately."}]'::JSONB, 'Timing matters more than anything at the end — noodles go soft within a couple of minutes, so have every bowl and topping laid out before they go in the water. The broth and chashu can both be made two days ahead, which makes this far more manageable.', ARRAY['Shortcut: A good chicken stock enriched with a spoonful of miso gets you a decent bowl in 30 minutes.','Vegetarian: Shiitake and kombu dashi with a miso tare.','Freeze: Broth freezes for 3 months in portions.']::TEXT[], ARRAY['Gluten','Soy','Egg']::TEXT[]),
('minestrone', 'Minestrone', 'A soffritto-based vegetable soup with beans and pasta, thickened by the starch rather than by cream.', 'https://img.rocket.new/generatedImages/rocket_gen_img_1e2f801ab-1773084071073.png', 'Hearty Italian minestrone soup with vegetables, beans, and pasta', 'Marco Rossi', '@marcorossicucina', '', '', '20 min', '25 min', '45 min', 20, 25, 45, 6, 'Easy', 'Italian', 'Lunch', 'Soup', ARRAY['Vegetarian','Budget','Freezer-Friendly','Healthy']::TEXT[], 4.7, 549, 6349, 326, 13, 48, 9, 9, '[{"amount":"3","unit":"tbsp","item":"olive oil"},{"amount":"1","unit":"","item":"onion, diced"},{"amount":"2","unit":"","item":"carrots, diced"},{"amount":"2","unit":"stalks","item":"celery, diced"},{"amount":"3","unit":"cloves","item":"garlic, minced"},{"amount":"2","unit":"tbsp","item":"tomato paste"},{"amount":"14","unit":"oz","item":"crushed tomatoes"},{"amount":"6","unit":"cups","item":"vegetable stock"},{"amount":"1","unit":"can","item":"cannellini beans, drained"},{"amount":"1","unit":"","item":"courgette, diced"},{"amount":"1","unit":"cup","item":"green beans, cut"},{"amount":"1","unit":"cup","item":"small pasta"},{"amount":"1","unit":"","item":"parmesan rind"},{"amount":"2","unit":"cups","item":"shredded kale"},{"amount":"","unit":"","item":"Salt, pepper, and pesto to serve"}]'::JSONB, '[{"step":1,"title":"Build the soffritto slowly","instruction":"Cook the onion, carrot, and celery in the oil over medium-low heat for 12 minutes until soft and sweet, not browned.","tip":"The soffritto is the foundation. Rushing it gives you vegetable water instead of soup."},{"step":2,"title":"Deepen with tomato paste","instruction":"Add the garlic and tomato paste and cook 2 minutes until the paste darkens to brick red."},{"step":3,"title":"Simmer with the rind","instruction":"Add the tomatoes, stock, beans, and parmesan rind. Simmer 20 minutes.","tip":"The parmesan rind adds savoury depth for free. Save them in the freezer for exactly this."},{"step":4,"title":"Add vegetables by cooking time","instruction":"Add the green beans and courgette and cook 8 minutes, then the pasta for its packet time, then the kale for the final 3 minutes."},{"step":5,"title":"Season and finish","instruction":"Remove the rind, season generously, and serve with a spoonful of pesto stirred into each bowl."}]'::JSONB, 'Cook and store the pasta separately if you want leftovers — left in the soup it swells overnight and absorbs most of the broth. The soup base itself freezes for 3 months.', ARRAY['Vegan: Skip the parmesan rind and use a vegan pesto; add a spoonful of miso for depth.','Seasonal: Use whatever vegetables you have — this recipe is a template, not a rule.','Thicker: Blend a ladleful of the beans and stir back in.']::TEXT[], ARRAY['Gluten','Dairy','Celery']::TEXT[]),
('clam-chowder', 'Clam Chowder', 'New England style — clams, bacon, and potato in a broth thickened with a roux and finished with cream.', 'https://img.rocket.new/generatedImages/rocket_gen_img_166dafed2-1773214700374.png', 'Creamy New England clam chowder with potatoes and crispy bacon bits', 'Maria Chen', '@mariachencooks', 'https://images.unsplash.com/photo-1677229888051-211da3f34219', 'Portrait of food creator Maria Chen', '20 min', '20 min', '40 min', 20, 20, 40, 6, 'Medium', 'American', 'Lunch', 'Soup', ARRAY['Seafood','Comfort','Classic']::TEXT[], 5.0, 1241, 3022, 482, 24, 34, 27, 3, '[{"amount":"3","unit":"lb","item":"fresh clams, scrubbed"},{"amount":"6","unit":"slices","item":"bacon, diced"},{"amount":"2","unit":"tbsp","item":"butter"},{"amount":"1","unit":"","item":"onion, diced"},{"amount":"2","unit":"stalks","item":"celery, diced"},{"amount":"3","unit":"tbsp","item":"all-purpose flour"},{"amount":"1.5","unit":"lb","item":"potatoes, diced"},{"amount":"2","unit":"cups","item":"clam juice"},{"amount":"1.5","unit":"cups","item":"heavy cream"},{"amount":"1","unit":"cup","item":"whole milk"},{"amount":"2","unit":"","item":"bay leaves"},{"amount":"1","unit":"tsp","item":"fresh thyme"},{"amount":"","unit":"","item":"Salt, white pepper, and chives"}]'::JSONB, '[{"step":1,"title":"Steam the clams","instruction":"Steam the clams in a covered pot with a cup of water for 6–8 minutes until they open. Discard any that stay shut. Strain and keep the liquor.","tip":"That strained clam liquor is the best flavour in the dish. Do not pour it away."},{"step":2,"title":"Chop the clams","instruction":"Pull the meat from the shells and chop roughly. Set aside — they go back in at the very end."},{"step":3,"title":"Render the bacon","instruction":"Cook the bacon until crisp, then remove, leaving the fat behind."},{"step":4,"title":"Make the roux","instruction":"Add the butter, onion, and celery to the bacon fat and cook 6 minutes. Stir in the flour and cook 2 minutes."},{"step":5,"title":"Simmer the potatoes","instruction":"Add the clam liquor, clam juice, potatoes, bay, and thyme. Simmer 15 minutes until the potatoes are tender."},{"step":6,"title":"Finish gently","instruction":"Stir in the cream and milk and warm through without boiling. Add the chopped clams and bacon and heat for 2 minutes only.","tip":"Clams go rubbery in seconds with heat. In at the end, off the heat quickly."}]'::JSONB, 'Tinned clams work perfectly well — use their liquid as part of the clam juice and skip the steaming step. Chowder thickens considerably overnight; loosen with milk when reheating, and never let it boil.', ARRAY['Thicker: Mash a few of the cooked potato cubes against the side of the pot.','Manhattan style: Skip the dairy, add tomatoes and extra stock.','Serve: Oyster crackers, or in a hollowed sourdough loaf.']::TEXT[], ARRAY['Shellfish','Dairy','Gluten']::TEXT[]),
('miso-soup', 'Miso Soup', 'Dashi from kombu and bonito, with miso whisked in off the heat so it never boils.', 'https://img.rocket.new/generatedImages/rocket_gen_img_19eb07291-1773191218850.png', 'Traditional Japanese miso soup with tofu, wakame seaweed, and green onions', 'Yuki Tanaka', '@yukitanakaumami', '', '', '5 min', '5 min', '10 min', 5, 5, 10, 4, 'Easy', 'Japanese', 'Lunch', 'Soup', ARRAY['Quick','Light','Gluten-Free-Adaptable']::TEXT[], 4.8, 1375, 9172, 86, 6, 8, 3, 1, '[{"amount":"4","unit":"cups","item":"water"},{"amount":"1","unit":"piece","item":"kombu (4 inch)"},{"amount":"0.5","unit":"cup","item":"bonito flakes"},{"amount":"4","unit":"tbsp","item":"white miso paste"},{"amount":"7","unit":"oz","item":"silken tofu, cubed"},{"amount":"2","unit":"tbsp","item":"dried wakame"},{"amount":"2","unit":"","item":"scallions, thinly sliced"}]'::JSONB, '[{"step":1,"title":"Steep the kombu","instruction":"Put the kombu in cold water and heat slowly to just below a simmer over 10 minutes. Remove it the moment small bubbles appear at the edge.","tip":"Boiling kombu makes the dashi bitter and slimy. Pull it before it simmers."},{"step":2,"title":"Add bonito","instruction":"Turn off the heat, add the bonito flakes, and let them steep 3 minutes until they sink. Strain through a fine sieve without pressing."},{"step":3,"title":"Rehydrate the wakame","instruction":"Soak the dried wakame in cold water for 5 minutes, then drain. It expands considerably, so use less than looks right."},{"step":4,"title":"Warm the tofu","instruction":"Return the dashi to a gentle heat and add the tofu and wakame. Warm through for 2 minutes."},{"step":5,"title":"Whisk in the miso off the heat","instruction":"Take the pan off the heat. Ladle a little broth into a bowl, whisk the miso into it until smooth, then stir that back into the pot.","tip":"Never boil miso. It kills the aroma and the live cultures, and the flavour goes flat immediately."},{"step":6,"title":"Serve","instruction":"Top with scallions and serve straight away."}]'::JSONB, 'Miso brands vary a lot in saltiness — start with three tablespoons and taste. White miso is mild and sweet; red is much stronger and you would want less.', ARRAY['Vegan: Skip the bonito and use a kombu and dried shiitake dashi.','Gluten-free: Check the miso, as some contain barley.','Additions: Clams, enoki mushrooms, or spinach all suit it.']::TEXT[], ARRAY['Soy','Fish']::TEXT[]),
('birria-tacos', 'Birria Tacos', 'Beef braised in a dried chilli adobo for three hours, then folded into tortillas dipped in the fat and crisped, with consommé for dunking.', 'https://images.unsplash.com/photo-1674277196243-ff6fc26e837c', 'Crispy birria tacos dipped in rich consommé with melted cheese and cilantro', 'Rosa Gutierrez', '@rosagutierrezcocina', '', '', '30 min', '2.5 hrs', '3 hrs', 30, 150, 180, 6, 'Medium', 'Mexican', 'Dinner', 'Main Course', ARRAY['Weekend Project','Street Food','Crowd Pleaser','Gluten-Free']::TEXT[], 4.9, 1292, 5627, 682, 44, 38, 40, 5, '[{"amount":"4","unit":"lb","item":"beef chuck, in large chunks"},{"amount":"6","unit":"","item":"guajillo chillies, stemmed and seeded"},{"amount":"4","unit":"","item":"ancho chillies, stemmed and seeded"},{"amount":"2","unit":"","item":"chipotles in adobo"},{"amount":"1","unit":"","item":"onion, quartered"},{"amount":"6","unit":"cloves","item":"garlic"},{"amount":"2","unit":"","item":"tomatoes"},{"amount":"1","unit":"tbsp","item":"dried oregano"},{"amount":"1","unit":"tsp","item":"ground cumin"},{"amount":"2","unit":"","item":"bay leaves"},{"amount":"1","unit":"","item":"cinnamon stick"},{"amount":"2","unit":"tbsp","item":"apple cider vinegar"},{"amount":"4","unit":"cups","item":"beef stock"},{"amount":"18","unit":"","item":"corn tortillas"},{"amount":"3","unit":"cups","item":"grated Oaxaca or mozzarella"},{"amount":"","unit":"","item":"Diced onion, cilantro, and lime to serve"}]'::JSONB, '[{"step":1,"title":"Toast and soak the chillies","instruction":"Toast the dried chillies in a dry pan for 30 seconds a side until fragrant, then soak in boiling water for 20 minutes.","tip":"Toast only until they smell sweet — a few seconds too long and the whole adobo turns bitter."},{"step":2,"title":"Blend the adobo","instruction":"Blend the soaked chillies with the chipotles, onion, garlic, tomatoes, oregano, cumin, and vinegar until completely smooth. Strain it for a silkier sauce."},{"step":3,"title":"Sear the beef","instruction":"Season and sear the chuck hard on all sides in a heavy pot."},{"step":4,"title":"Braise long","instruction":"Pour over the adobo and stock, add the bay and cinnamon, cover, and cook at 325°F (165°C) for 3–3.5 hours until the beef shreds with no resistance."},{"step":5,"title":"Separate the fat","instruction":"Lift out the beef and shred it. Let the liquid settle and skim the brilliant red fat off the top into a bowl — this is what the tortillas get dipped in.","tip":"That red fat layer is the entire point of birria tacos. Save every spoonful."},{"step":6,"title":"Fry the tacos","instruction":"Dip each tortilla in the red fat, lay in a hot skillet, add cheese and shredded beef, fold, and fry 2 minutes a side until crisp."},{"step":7,"title":"Serve with consommé","instruction":"Serve the remaining braising liquid in small bowls with onion, cilantro, and lime for dipping."}]'::JSONB, 'The braise is genuinely better made a day ahead — the fat solidifies on top overnight and lifts off in one clean piece, which makes the whole process easier. Beef cheek or short rib both work in place of chuck.', ARRAY['Pressure cooker: 60 minutes at high pressure instead of the oven braise.','Heat: Guajillo and ancho are mild; the chipotles carry the heat. Adjust those.','Leftovers: The meat freezes for 3 months; freeze it in its consommé.']::TEXT[], ARRAY['Dairy']::TEXT[]),
('viral-feta-pasta', 'Viral Feta Pasta', 'A block of feta and cherry tomatoes roasted in one dish, then mashed into a sauce with the hot pasta.', 'https://images.unsplash.com/photo-1493151333614-26ed2c07f9c6', 'Baked feta pasta with cherry tomatoes and fresh basil in a baking dish', 'Emma Walsh', '@emmawalshbakes', '', '', '5 min', '35 min', '40 min', 5, 35, 40, 4, 'Easy', 'Mediterranean', 'Dinner', 'Main Course', ARRAY['Vegetarian','One-Pan','Easy','Viral']::TEXT[], 4.9, 221, 1777, 582, 22, 72, 24, 5, '[{"amount":"1","unit":"block","item":"feta (7 oz)"},{"amount":"1.5","unit":"lb","item":"cherry tomatoes"},{"amount":"0.33","unit":"cup","item":"olive oil"},{"amount":"4","unit":"cloves","item":"garlic, whole"},{"amount":"1","unit":"tsp","item":"dried oregano"},{"amount":"0.5","unit":"tsp","item":"chilli flakes"},{"amount":"1","unit":"lb","item":"short pasta"},{"amount":"","unit":"","item":"Fresh basil"},{"amount":"","unit":"","item":"Salt and black pepper"}]'::JSONB, '[{"step":1,"title":"Use block feta in brine","instruction":"A brined block melts into a creamy sauce. Pre-crumbled feta is drier and stays grainy no matter how much you mash it.","tip":"Block feta, not crumbled. This is the one thing that determines whether it works."},{"step":2,"title":"Build the dish","instruction":"Put the tomatoes in a baking dish, nestle the feta block in the centre, add the whole garlic cloves, and pour the olive oil over everything. Season with oregano, chilli, salt, and pepper."},{"step":3,"title":"Roast hard","instruction":"Roast at 400°F (205°C) for 35 minutes until the tomatoes have burst and collapsed and the feta is soft and browned at the edges."},{"step":4,"title":"Cook the pasta","instruction":"Boil the pasta to al dente in the last 12 minutes and reserve a cup of the water."},{"step":5,"title":"Mash into a sauce","instruction":"Mash the feta, tomatoes, and softened garlic together in the hot dish with a fork until it comes together as a creamy, streaky sauce."},{"step":6,"title":"Toss with pasta water","instruction":"Add the drained pasta and a good splash of pasta water and toss until glossy and coated. Finish with torn basil.","tip":"The pasta water is what turns it from a lumpy mash into an actual sauce."}]'::JSONB, 'The full third of a cup of oil sounds like a lot and it is doing real work — it emulsifies with the pasta water and tomato juice into the sauce. Reducing it gives a dry, claggy result.', ARRAY['Add protein: Roast chunks of chicken or a tin of chickpeas in the dish alongside.','Vegan: A block of plant feta works, though it does not brown as well.','Spinach: Stir a few handfuls through the hot dish before adding the pasta.']::TEXT[], ARRAY['Dairy','Gluten']::TEXT[]),
('butter-board', 'Butter Board', 'Good softened butter spread across a board and scattered with honey, herbs, and flaky salt. Assembly, not cooking.', 'https://images.unsplash.com/photo-1589310209417-a496eea2eac0', 'Whipped butter spread on a wooden board with honey, herbs, and edible flowers', 'Sofia Romano', '@sofiaromanoeats', '', '', '10 min', '—', '10 min', 10, 0, 10, 6, 'Easy', 'Modern', 'Snack', 'Appetizer', ARRAY['Vegetarian','No-Cook','Party Food','Quick']::TEXT[], 4.8, 1499, 3212, 286, 3, 18, 23, 1, '[{"amount":"8","unit":"oz","item":"good cultured butter, very soft"},{"amount":"2","unit":"tbsp","item":"honey"},{"amount":"1","unit":"tbsp","item":"chopped chives"},{"amount":"1","unit":"tbsp","item":"chopped dill"},{"amount":"1","unit":"tsp","item":"lemon zest"},{"amount":"2","unit":"tbsp","item":"toasted pistachios, crushed"},{"amount":"0.5","unit":"tsp","item":"chilli flakes"},{"amount":"","unit":"","item":"Flaky sea salt"},{"amount":"1","unit":"","item":"crusty baguette, sliced"}]'::JSONB, '[{"step":1,"title":"Soften properly","instruction":"Leave the butter out for 2 hours until genuinely spreadable. Microwaving it makes it greasy and it will not hold the swoops.","tip":"Room temperature, not melted. This takes planning and nothing else."},{"step":2,"title":"Spread with a swoop","instruction":"Spread the butter across a wooden board in an uneven layer about a quarter inch thick, dragging the back of a spoon to create ridges and valleys that catch the toppings."},{"step":3,"title":"Layer flavours","instruction":"Drizzle the honey over first, then scatter the herbs, lemon zest, pistachios, and chilli flakes."},{"step":4,"title":"Salt last","instruction":"Finish with a generous scatter of flaky salt right before serving, so it stays crunchy rather than dissolving."},{"step":5,"title":"Serve with warm bread","instruction":"Serve immediately with warm, crusty bread for scraping."}]'::JSONB, 'Use the best butter you can find — with this few ingredients it is most of what you taste. Cultured or European-style butter has noticeably more flavour than standard.', ARRAY['Savoury: Roasted garlic, anchovy, and parsley instead of honey and herbs.','Sweet: Cinnamon, brown sugar, and orange zest with toasted bread.','Food safety: Do not leave it out more than 2 hours.']::TEXT[], ARRAY['Dairy','Gluten','Tree Nut']::TEXT[]),
('crispy-rice-salad', 'Crispy Rice Salad', 'Cold rice crisped in a hot pan until it crackles, then tossed with herbs and a sharp lime dressing.', 'https://images.unsplash.com/photo-1719910327777-a2489921021a', 'Crispy fried rice topped with fresh vegetables and sesame dressing in a bowl', 'Maria Chen', '@mariachencooks', 'https://images.unsplash.com/photo-1677229888051-211da3f34219', 'Portrait of food creator Maria Chen', '15 min', '10 min', '25 min', 15, 10, 25, 4, 'Easy', 'Thai', 'Lunch', 'Salad', ARRAY['Gluten-Free-Adaptable','Leftovers','Fresh','Crunchy']::TEXT[], 4.3, 1250, 7461, 412, 9, 58, 16, 4, '[{"amount":"3","unit":"cups","item":"cooked jasmine rice, cold"},{"amount":"3","unit":"tbsp","item":"neutral oil"},{"amount":"3","unit":"tbsp","item":"lime juice"},{"amount":"2","unit":"tbsp","item":"fish sauce"},{"amount":"1","unit":"tbsp","item":"palm sugar"},{"amount":"1","unit":"","item":"red chilli, sliced"},{"amount":"2","unit":"cloves","item":"garlic, grated"},{"amount":"1","unit":"cup","item":"fresh mint"},{"amount":"1","unit":"cup","item":"fresh cilantro"},{"amount":"4","unit":"","item":"scallions, sliced"},{"amount":"1","unit":"","item":"cucumber, diced"},{"amount":"0.33","unit":"cup","item":"roasted peanuts, crushed"},{"amount":"4","unit":"","item":"shallots, thinly sliced and fried"}]'::JSONB, '[{"step":1,"title":"Use cold, dry rice","instruction":"Day-old refrigerated rice is essential. Fresh rice is too moist and will steam into a sticky mass instead of crisping.","tip":"Cold day-old rice, broken up with wet hands before it goes near the pan."},{"step":2,"title":"Press and leave alone","instruction":"Heat the oil in a wide pan until shimmering, add the rice in an even layer, and press it down. Leave it completely untouched for 5 minutes.","tip":"Do not stir. The crust only forms if the rice sits still against the hot pan."},{"step":3,"title":"Break and repeat","instruction":"Break the crust up, press the rice down again, and cook another 4 minutes. Repeat once more until much of the rice is golden and audibly crunchy."},{"step":4,"title":"Mix the dressing","instruction":"Whisk the lime juice, fish sauce, palm sugar, chilli, and garlic until the sugar dissolves. It should be sharp, salty, and slightly sweet."},{"step":5,"title":"Toss just before serving","instruction":"Combine the crisp rice, herbs, scallions, and cucumber, pour over the dressing, and toss. Top with peanuts and fried shallots.","tip":"Dress at the last moment — the rice softens within a few minutes of meeting the dressing."}]'::JSONB, 'Serve this within five minutes of dressing it. Everything can be prepared in advance and combined at the table, which is how it is best handled for guests.', ARRAY['Vegan: Soy sauce plus a teaspoon of miso in place of the fish sauce.','Add protein: Crisp pork mince or fried tofu are both traditional partners.','Nut-free: Toasted sesame seeds instead of peanuts.']::TEXT[], ARRAY['Fish','Peanut']::TEXT[]),
('marry-me-chicken', 'Marry Me Chicken', 'Seared chicken in a sun-dried tomato cream sauce with parmesan and basil. Thirty minutes, one pan.', 'https://img.rocket.new/generatedImages/rocket_gen_img_1f79e6ddb-1772630172931.png', 'Creamy sun-dried tomato chicken in a cast iron skillet with fresh basil', 'Sofia Patel', '@sofiapatelkitchen', 'https://images.unsplash.com/photo-1716947674021-1b8b696325c7', 'Portrait of food creator Sofia Patel', '8 min', '22 min', '30 min', 8, 22, 30, 4, 'Easy', 'Italian', 'Dinner', 'Main Course', ARRAY['Date Night','One-Pan','Quick','Gluten-Free']::TEXT[], 4.8, 618, 4874, 612, 46, 12, 42, 2, '[{"amount":"4","unit":"","item":"chicken breasts, halved horizontally"},{"amount":"2","unit":"tbsp","item":"olive oil"},{"amount":"3","unit":"cloves","item":"garlic, minced"},{"amount":"0.5","unit":"cup","item":"sun-dried tomatoes in oil, chopped"},{"amount":"1","unit":"cup","item":"chicken stock"},{"amount":"1","unit":"cup","item":"heavy cream"},{"amount":"0.75","unit":"cup","item":"grated parmesan"},{"amount":"1","unit":"tsp","item":"dried oregano"},{"amount":"0.5","unit":"tsp","item":"chilli flakes"},{"amount":"0.5","unit":"cup","item":"fresh basil, torn"},{"amount":"","unit":"","item":"Salt and black pepper"}]'::JSONB, '[{"step":1,"title":"Halve the breasts","instruction":"Slice each breast horizontally into two thin cutlets. Thin cutlets cook in 4 minutes a side and stay juicy; whole breasts overcook on the outside before the centre is done.","tip":"Halving them is the single biggest improvement to this dish."},{"step":2,"title":"Sear hard","instruction":"Season and sear in hot oil for 4 minutes a side until deeply golden. Remove to a plate — they finish in the sauce."},{"step":3,"title":"Build the sauce base","instruction":"Lower the heat, add the garlic and sun-dried tomatoes, and cook 1 minute in the residual oil."},{"step":4,"title":"Deglaze and reduce","instruction":"Add the stock and scrape the base clean. Simmer 3 minutes to reduce slightly, then add the cream, oregano, and chilli flakes."},{"step":5,"title":"Melt the parmesan off the boil","instruction":"Lower the heat and stir in the parmesan until smooth. A boiling sauce will make it split and go grainy."},{"step":6,"title":"Return and finish","instruction":"Return the chicken with its resting juices and simmer 4 minutes until cooked through (165°F). Add the basil off the heat."}]'::JSONB, 'Use sun-dried tomatoes packed in oil rather than dry ones, and use a spoonful of that oil for the sear. The sauce thickens on standing, so loosen with a splash of stock if reheating.', ARRAY['Serve with: Pasta, mashed potato, or bread — the sauce needs something to soak into.','Dairy-free: Full-fat coconut milk and nutritional yeast; different, but good.','Thighs: Boneless thighs work well and need 6 minutes a side.']::TEXT[], ARRAY['Dairy']::TEXT[]),
('cottage-cheese-flatbread', 'Cottage Cheese Flatbread', 'Two ingredients blended and baked into a high-protein flatbread with no flour at all.', 'https://images.unsplash.com/photo-1696189052117-e40ac954a754', 'Golden cottage cheese flatbread with herbs and toppings on a baking sheet', 'Priya Nair', '@priyanairkitchen', '', '', '5 min', '15 min', '20 min', 5, 15, 20, 2, 'Easy', 'Modern', 'Snack', 'Bread', ARRAY['High Protein','Gluten-Free','Low Carb','Quick']::TEXT[], 4.4, 1754, 1579, 186, 22, 6, 8, 0, '[{"amount":"1","unit":"cup","item":"cottage cheese"},{"amount":"2","unit":"large","item":"eggs"},{"amount":"1","unit":"tsp","item":"Italian herbs"},{"amount":"0.5","unit":"tsp","item":"garlic powder"},{"amount":"","unit":"","item":"Salt and black pepper"},{"amount":"","unit":"","item":"Everything bagel seasoning (optional)"}]'::JSONB, '[{"step":1,"title":"Blend completely smooth","instruction":"Blend the cottage cheese and eggs until there is no curd texture left at all — a good 60 seconds. Any lumps remaining will show up as rubbery patches.","tip":"Blend it far longer than seems necessary. Smooth is the whole thing."},{"step":2,"title":"Season the batter","instruction":"Stir in the herbs, garlic powder, salt, and pepper."},{"step":3,"title":"Spread thin on parchment","instruction":"Pour onto a parchment-lined tray and spread into a thin rectangle, about an eighth of an inch. Thicker and it stays eggy and soft."},{"step":4,"title":"Bake until dry","instruction":"Bake at 350°F (175°C) for 35–40 minutes until fully set, dry to the touch, and golden at the edges.","tip":"Underbaking is the most common failure — it should feel dry, not tacky."},{"step":5,"title":"Cool before moving","instruction":"Cool 10 minutes on the tray before lifting; it firms up considerably as it cools."}]'::JSONB, 'Full-fat cottage cheese gives a much better texture than low-fat, which bakes up watery. Use it as a wrap, a pizza base (add toppings and grill for 5 minutes), or cut into crackers.', ARRAY['Pizza base: Bake as above, add sauce and cheese, then grill 5 minutes.','Crisper: Return to a 400°F oven for 5 minutes after cooling.','Storage: Keeps 3 days refrigerated; re-crisp in a dry pan.']::TEXT[], ARRAY['Dairy','Egg']::TEXT[]),
('cucumber-salad', 'Cucumber Salad', 'Smashed cucumbers salted to draw out water, then dressed in rice vinegar, sesame, and chilli.', 'https://img.rocket.new/generatedImages/rocket_gen_img_18fa09647-1765898626493.png', 'Refreshing cucumber salad with rice vinegar, sesame oil, and chili flakes', 'Yuna Kim', '@yunakimkitchen', '', '', '15 min', '—', '15 min', 15, 0, 15, 4, 'Easy', 'Chinese', 'Lunch', 'Salad', ARRAY['Vegan','No-Cook','Quick','Fresh']::TEXT[], 4.5, 1552, 3557, 98, 2, 8, 6, 2, '[{"amount":"2","unit":"large","item":"cucumbers"},{"amount":"1","unit":"tsp","item":"salt"},{"amount":"3","unit":"tbsp","item":"rice vinegar"},{"amount":"2","unit":"tbsp","item":"soy sauce"},{"amount":"1","unit":"tbsp","item":"toasted sesame oil"},{"amount":"1","unit":"tbsp","item":"chilli crisp"},{"amount":"1","unit":"tsp","item":"sugar"},{"amount":"3","unit":"cloves","item":"garlic, grated"},{"amount":"1","unit":"tbsp","item":"toasted sesame seeds"},{"amount":"","unit":"","item":"Cilantro"}]'::JSONB, '[{"step":1,"title":"Smash, do not slice","instruction":"Lay the cucumbers on a board and whack them with the flat of a heavy knife until they split, then tear into rough chunks. The jagged surfaces hold dressing far better than clean slices.","tip":"Smashing is not just for show — the torn edges are what make the dressing cling."},{"step":2,"title":"Salt and drain","instruction":"Toss the chunks with the salt and leave in a colander for 15 minutes. A surprising amount of water drains out.","tip":"Skipping this gives you a diluted, watery dressing within minutes."},{"step":3,"title":"Mix the dressing","instruction":"Whisk the vinegar, soy sauce, sesame oil, chilli crisp, sugar, and garlic together until the sugar dissolves."},{"step":4,"title":"Dress and rest briefly","instruction":"Pat the cucumbers dry, toss with the dressing, and leave 5 minutes for the flavours to take."},{"step":5,"title":"Serve","instruction":"Top with sesame seeds and cilantro and serve cold."}]'::JSONB, 'This is at its best within an hour of dressing. Beyond that the cucumbers keep releasing water and go limp, though it is still perfectly good the next day.', ARRAY['Cucumber choice: Persian or English cucumbers have fewer seeds and less water.','Heat: Chilli crisp brands vary hugely — start with a teaspoon if unsure.','Add: Thin slices of raw garlic or a spoonful of black vinegar for depth.']::TEXT[], ARRAY['Soy','Sesame']::TEXT[]),
('whipped-feta-dip', 'Whipped Feta Dip', 'Feta and Greek yoghurt whipped until light, topped with honey, olive oil, and herbs.', 'https://images.unsplash.com/photo-1646587433838-0159a05ba4d7', 'Creamy whipped feta dip with olive oil, honey, and fresh herbs on a plate', 'Leila Hassan', '@leilahassantable', '', '', '10 min', '—', '10 min', 10, 0, 10, 6, 'Easy', 'Greek', 'Snack', 'Appetizer', ARRAY['Vegetarian','No-Cook','Party Food','Quick']::TEXT[], 5.0, 419, 4093, 212, 9, 8, 17, 0, '[{"amount":"8","unit":"oz","item":"block feta, crumbled"},{"amount":"0.5","unit":"cup","item":"Greek yoghurt"},{"amount":"3","unit":"tbsp","item":"olive oil"},{"amount":"1","unit":"tbsp","item":"lemon juice"},{"amount":"1","unit":"clove","item":"garlic"},{"amount":"2","unit":"tbsp","item":"honey"},{"amount":"1","unit":"tsp","item":"chilli flakes"},{"amount":"2","unit":"tbsp","item":"chopped dill"},{"amount":"2","unit":"tbsp","item":"toasted pistachios"},{"amount":"","unit":"","item":"Warm pita and vegetables to serve"}]'::JSONB, '[{"step":1,"title":"Use brined block feta","instruction":"Block feta whips into something creamy; pre-crumbled feta is dry and stays grainy however long you blend it."},{"step":2,"title":"Blend long","instruction":"Blend the feta, yoghurt, olive oil, lemon juice, and garlic for a full 2 minutes, scraping down twice, until completely smooth and noticeably lighter in colour.","tip":"Two minutes. Most people stop at thirty seconds and end up with feta paste."},{"step":3,"title":"Check the consistency","instruction":"It should hold soft peaks. Add a tablespoon of water or more yoghurt if it is too stiff to swoop."},{"step":4,"title":"Swoop into a bowl","instruction":"Spread into a shallow bowl, using the back of a spoon to make ridges for the toppings to pool in."},{"step":5,"title":"Top generously","instruction":"Drizzle with honey and more olive oil, then scatter the chilli flakes, dill, and pistachios. Serve with warm pita."}]'::JSONB, 'Feta varies in saltiness, so taste before adding any salt — most need none. The dip keeps 4 days refrigerated but firms up considerably; let it sit out for 20 minutes and stir before serving.', ARRAY['Roasted version: Blend in a roasted red pepper or a head of roasted garlic.','Hot honey: Warm the honey with the chilli flakes before drizzling.','Vegan: A firm plant feta with cashew cream in place of the yoghurt.']::TEXT[], ARRAY['Dairy']::TEXT[]),
('baked-oats', 'Baked Oats', 'Blended oats baked into something between a muffin and a bowl of porridge, ready in 25 minutes.', 'https://images.unsplash.com/photo-1582215580615-063d79c2cc34', 'Baked oats with banana, chocolate chips, and peanut butter in a ramekin', 'Emma Walsh', '@emmawalshbakes', '', '', '5 min', '20 min', '25 min', 5, 20, 25, 2, 'Easy', 'Modern', 'Breakfast', 'Breakfast', ARRAY['Vegetarian','Meal Prep','Healthy','Family']::TEXT[], 4.7, 1684, 3161, 412, 14, 58, 14, 7, '[{"amount":"1","unit":"cup","item":"rolled oats"},{"amount":"1","unit":"","item":"ripe banana"},{"amount":"1","unit":"","item":"egg"},{"amount":"0.5","unit":"cup","item":"milk of choice"},{"amount":"1","unit":"tsp","item":"baking powder"},{"amount":"2","unit":"tbsp","item":"maple syrup"},{"amount":"1","unit":"tsp","item":"vanilla extract"},{"amount":"","unit":"","item":"Pinch of salt"},{"amount":"3","unit":"tbsp","item":"chocolate chips"},{"amount":"2","unit":"tbsp","item":"peanut butter"}]'::JSONB, '[{"step":1,"title":"Blend the oats to flour","instruction":"Blend the oats alone first until they resemble a coarse flour. Blending everything together at once leaves a gritty texture.","tip":"Oats first, on their own. It takes ten seconds and changes the result completely."},{"step":2,"title":"Add the wet ingredients","instruction":"Add the banana, egg, milk, baking powder, maple syrup, vanilla, and salt and blend until smooth and pourable."},{"step":3,"title":"Fill and top","instruction":"Pour into two greased ramekins, filling two-thirds. Push the chocolate chips in and swirl the peanut butter across the top."},{"step":4,"title":"Bake","instruction":"Bake at 350°F (175°C) for 22–25 minutes until risen and set with a slight wobble at the very centre."},{"step":5,"title":"Rest briefly","instruction":"Rest 5 minutes — it firms up considerably — then eat straight from the ramekin."}]'::JSONB, 'The banana must be properly ripe or the whole thing tastes bland and needs more syrup. Bakes well in a muffin tin too: fill eight cups and bake 18 minutes.', ARRAY['Vegan: A flax egg works; the texture is slightly denser.','Meal prep: Bake six at once and reheat for 45 seconds in the microwave.','Flavours: Blueberry and lemon zest, or apple and cinnamon.']::TEXT[], ARRAY['Gluten','Dairy','Egg','Peanut']::TEXT[]),
('pasta-chips', 'Pasta Chips', 'Boiled pasta tossed in oil and parmesan then air fried until it puffs and crackles.', 'https://images.unsplash.com/photo-1485921325833-c519f76c4927', 'Crispy air-fried pasta chips with parmesan and marinara dipping sauce', 'Marco Rossi', '@marcorossicucina', '', '', '5 min', '15 min', '20 min', 5, 15, 20, 4, 'Easy', 'Italian', 'Snack', 'Snack', ARRAY['Air Fryer','Vegetarian','Party Food','Viral']::TEXT[], 4.9, 396, 8500, 286, 10, 42, 9, 2, '[{"amount":"8","unit":"oz","item":"rigatoni or farfalle"},{"amount":"2","unit":"tbsp","item":"olive oil"},{"amount":"0.33","unit":"cup","item":"grated parmesan"},{"amount":"1","unit":"tsp","item":"garlic powder"},{"amount":"1","unit":"tsp","item":"dried Italian herbs"},{"amount":"0.5","unit":"tsp","item":"paprika"},{"amount":"","unit":"","item":"Salt and black pepper"},{"amount":"1","unit":"cup","item":"marinara for dipping"}]'::JSONB, '[{"step":1,"title":"Boil to just al dente","instruction":"Cook the pasta to al dente, no further. Overcooked pasta collapses instead of crisping."},{"step":2,"title":"Dry it well","instruction":"Drain and spread on a tea towel for a few minutes. Surface water steams in the air fryer and prevents any crunch.","tip":"Dry pasta is the whole trick. Wet pasta comes out chewy."},{"step":3,"title":"Coat generously","instruction":"Toss with the oil, parmesan, garlic powder, herbs, paprika, salt, and pepper until every piece is well covered."},{"step":4,"title":"Air fry in a single layer","instruction":"Cook at 400°F (205°C) for 10–12 minutes, shaking every 4 minutes, until deeply golden and audibly crisp. Work in batches."},{"step":5,"title":"Serve hot","instruction":"Toss with extra parmesan and serve immediately with warm marinara."}]'::JSONB, 'These lose their crunch within about twenty minutes, so make them right before serving. Shapes with ridges and hollows — rigatoni, farfalle, shells — crisp far better than smooth ones.', ARRAY['Oven: 425°F on a tray for 20 minutes, tossing twice.','Vegan: Nutritional yeast in place of the parmesan.','Flavours: Cajun seasoning, or cinnamon sugar for a sweet version.']::TEXT[], ARRAY['Gluten','Dairy']::TEXT[])
