INSERT INTO public.recipes (slug, title, description, image, image_alt, creator_name, creator_handle, creator_image, creator_alt, prep_time, cook_time, total_time, prep_minutes, cook_minutes, total_minutes, servings, difficulty, cuisine, meal_type, category, tags, rating, reviews, cooks, calories, protein, carbs, fat, fiber, ingredients, steps, notes, tips, allergens) VALUES
('cloud-bread', 'Cloud Bread', 'Whipped egg whites folded with cream cheese and baked into airy, carb-free rounds.', 'https://img.rocket.new/generatedImages/rocket_gen_img_19a6c3662-1785351135381.png', 'Fluffy cloud bread rounds made with eggs and cream cheese on a baking sheet', 'Sofia Patel', '@sofiapatelkitchen', 'https://images.unsplash.com/photo-1716947674021-1b8b696325c7', 'Portrait of food creator Sofia Patel', '10 min', '20 min', '30 min', 10, 20, 30, 6, 'Easy', 'Modern', 'Snack', 'Bread', ARRAY['Low Carb','Gluten-Free','Keto','Vegetarian']::TEXT[], 4.5, 795, 1514, 86, 4, 1, 7, 0, '[{"amount":"3","unit":"large","item":"eggs, separated"},{"amount":"3","unit":"oz","item":"cream cheese, softened"},{"amount":"0.25","unit":"tsp","item":"cream of tartar"},{"amount":"1","unit":"tsp","item":"sugar or sweetener"},{"amount":"","unit":"","item":"Pinch of salt"}]'::JSONB, '[{"step":1,"title":"Separate cleanly","instruction":"Separate the eggs carefully. Any trace of yolk in the whites will stop them whipping to stiff peaks.","tip":"One drop of yolk ruins the whole batch. Separate each egg into a small bowl first."},{"step":2,"title":"Whip to stiff peaks","instruction":"Beat the whites with the cream of tartar until they hold stiff, glossy peaks that stand upright when the beater is lifted."},{"step":3,"title":"Smooth the yolk mixture","instruction":"Beat the yolks with the cream cheese, sugar, and salt until completely smooth with no lumps."},{"step":4,"title":"Fold gently","instruction":"Fold the yolk mixture into the whites in three additions with a spatula, cutting down and turning over. Stirring knocks all the air out.","tip":"Fold, do not stir. The air you whipped in is the entire structure."},{"step":5,"title":"Bake low","instruction":"Spoon six mounds onto a lined tray and bake at 300°F (150°C) for 25–30 minutes until golden and dry to the touch. Cool on the tray."}]'::JSONB, 'Cloud bread is best on the day it is made — it softens overnight, though it holds up reasonably in an airtight container for two days. Use it for sandwiches or as a burger bun replacement.', ARRAY['Savoury: Add garlic powder and herbs to the yolk mixture.','Sweet: Vanilla and a little more sweetener, served with berries.','Crisper: Leave in the switched-off oven for 10 minutes after baking.']::TEXT[], ARRAY['Egg','Dairy']::TEXT[]),
('salmon-rice-bowl', 'Salmon Rice Bowl', 'Flaked salmon over warm rice with spicy mayo, cucumber, and avocado. Fifteen minutes.', 'https://img.rocket.new/generatedImages/rocket_gen_img_1900c313c-1772799440716.png', 'Spicy salmon rice bowl with cucumber, avocado, and sriracha mayo', 'Yuna Kim', '@yunakimkitchen', '', '', '10 min', '5 min', '15 min', 10, 5, 15, 2, 'Easy', 'Japanese', 'Dinner', 'Main Course', ARRAY['Seafood','Quick','Meal Prep','Balanced']::TEXT[], 4.3, 1770, 6370, 648, 38, 62, 28, 4, '[{"amount":"2","unit":"fillets","item":"salmon (5 oz each)"},{"amount":"2","unit":"cups","item":"cooked sushi rice, warm"},{"amount":"3","unit":"tbsp","item":"mayonnaise"},{"amount":"1","unit":"tbsp","item":"sriracha"},{"amount":"1","unit":"tsp","item":"toasted sesame oil"},{"amount":"1","unit":"tbsp","item":"soy sauce"},{"amount":"1","unit":"","item":"avocado, sliced"},{"amount":"1","unit":"","item":"cucumber, thinly sliced"},{"amount":"2","unit":"","item":"scallions, sliced"},{"amount":"1","unit":"tbsp","item":"toasted sesame seeds"},{"amount":"1","unit":"sheet","item":"nori, shredded"}]'::JSONB, '[{"step":1,"title":"Cook the salmon hot","instruction":"Season the fillets and sear skin-side down in a hot pan for 4 minutes, then flip for 2 minutes more, until just cooked at the centre."},{"step":2,"title":"Flake it large","instruction":"Break the salmon into big flakes with a fork, discarding the skin or crisping it separately. Large flakes hold their texture; shredded salmon turns pasty."},{"step":3,"title":"Mix the spicy mayo","instruction":"Stir the mayonnaise, sriracha, and sesame oil together until smooth, loosening with a teaspoon of water."},{"step":4,"title":"Season the rice","instruction":"Fold the soy sauce through the warm rice so it is seasoned before anything else goes on top.","tip":"Seasoning the rice, not just the toppings, is what makes the bowl taste finished."},{"step":5,"title":"Build","instruction":"Divide the rice between two bowls, arrange the salmon, avocado, and cucumber in sections, then drizzle with spicy mayo and top with scallions, sesame seeds, and nori."}]'::JSONB, 'Leftover cooked salmon is ideal for this, hot or cold. If you want the crispy-rice version, press the rice into a hot oiled pan for five minutes before building the bowl.', ARRAY['Baked version: 400°F for 12 minutes if you would rather not use the hob.','Vegan: Marinated crisped tofu or roasted sweet potato.','Meal prep: Everything keeps 3 days; store the avocado separately.']::TEXT[], ARRAY['Fish','Egg','Soy','Sesame']::TEXT[]),
('tortilla-quiche', 'Tortilla Quiche', 'A tortilla pressed into a tin as the crust, filled with egg custard and baked. All the quiche, none of the pastry.', 'https://images.unsplash.com/photo-1667499707432-0524fcfb63ba', 'Easy tortilla quiche with spinach, cheese, and eggs in a crispy shell', 'Emma Walsh', '@emmawalshbakes', '', '', '10 min', '25 min', '35 min', 10, 25, 35, 4, 'Easy', 'Modern', 'Breakfast', 'Breakfast', ARRAY['Quick','Family','Vegetarian-Adaptable']::TEXT[], 4.2, 1172, 7751, 362, 19, 22, 22, 2, '[{"amount":"2","unit":"","item":"large flour tortillas"},{"amount":"6","unit":"large","item":"eggs"},{"amount":"0.75","unit":"cup","item":"whole milk"},{"amount":"0.5","unit":"cup","item":"heavy cream"},{"amount":"1.5","unit":"cups","item":"grated cheddar or gruyere"},{"amount":"4","unit":"oz","item":"spinach, wilted and squeezed dry"},{"amount":"4","unit":"slices","item":"bacon, cooked and chopped"},{"amount":"2","unit":"","item":"scallions, sliced"},{"amount":"","unit":"","item":"Salt, pepper, and nutmeg"}]'::JSONB, '[{"step":1,"title":"Line the tin","instruction":"Press the tortillas into a greased 9-inch pie dish, overlapping to cover the base and sides. Snip and patch any gaps."},{"step":2,"title":"Blind-bake the tortilla","instruction":"Bake the empty tortilla shell at 375°F (190°C) for 8 minutes until it firms up and starts to colour.","tip":"This stops the tortilla going soggy under the custard. It is a two-minute step that matters."},{"step":3,"title":"Dry the fillings","instruction":"Squeeze every drop of water out of the wilted spinach. Wet fillings are the reason quiches turn watery."},{"step":4,"title":"Mix the custard","instruction":"Whisk the eggs, milk, cream, salt, pepper, and a scrape of nutmeg until fully uniform."},{"step":5,"title":"Layer and bake","instruction":"Scatter the fillings and cheese into the shell, pour the custard over, and bake 30 minutes until puffed and just set with a slight wobble at the centre."},{"step":6,"title":"Rest","instruction":"Rest 10 minutes before slicing — it firms up and cuts far more cleanly."}]'::JSONB, 'Pull it while the very centre still wobbles; residual heat finishes the custard and an overbaked quiche goes rubbery and weeps. Keeps 3 days and reheats well at 325°F.', ARRAY['Vegetarian: Roasted peppers, mushrooms, or caramelised onion in place of the bacon.','Crustless: Skip the tortillas entirely and bake in a greased dish.','Muffin tin: Cut tortilla rounds and make individual quiches, 20 minutes.']::TEXT[], ARRAY['Gluten','Egg','Dairy']::TEXT[]),
('chili-oil-eggs', 'Chili Oil Eggs', 'Eggs fried hard in hot oil until the edges go lacy and brown, spooned over rice with chilli oil and soy.', 'https://img.rocket.new/generatedImages/rocket_gen_img_13bbb7ba5-1772058485902.png', 'Fried eggs drizzled with homemade chili oil and scallions over rice', 'Lin Wei', '@linweiwok', '', '', '5 min', '5 min', '10 min', 5, 5, 10, 2, 'Easy', 'Chinese', 'Breakfast', 'Breakfast', ARRAY['Quick','Spicy','Budget','Vegetarian']::TEXT[], 4.3, 644, 1371, 432, 16, 42, 22, 2, '[{"amount":"4","unit":"large","item":"eggs"},{"amount":"3","unit":"tbsp","item":"neutral oil"},{"amount":"2","unit":"tbsp","item":"chilli crisp"},{"amount":"1","unit":"tbsp","item":"soy sauce"},{"amount":"1","unit":"tsp","item":"black vinegar or rice vinegar"},{"amount":"1","unit":"tsp","item":"toasted sesame oil"},{"amount":"2","unit":"cups","item":"hot steamed rice"},{"amount":"2","unit":"","item":"scallions, sliced"},{"amount":"","unit":"","item":"Toasted sesame seeds"}]'::JSONB, '[{"step":1,"title":"Get the oil properly hot","instruction":"Heat the oil in a small pan until it shimmers and a drop of water spits violently. Timid heat gives you a soft fried egg, not this.","tip":"The oil must be hot enough to make the whites bubble the instant they hit it."},{"step":2,"title":"Crack and stand back","instruction":"Crack the eggs in one at a time. The edges will bubble up furiously and turn brown and lacy within 30 seconds."},{"step":3,"title":"Baste the tops","instruction":"Tilt the pan and spoon the hot oil over the whites repeatedly for 60 seconds, until they set but the yolks stay completely liquid.","tip":"Basting sets the top without flipping, which keeps the yolk runny."},{"step":4,"title":"Mix the sauce","instruction":"Stir the soy sauce, vinegar, and sesame oil together."},{"step":5,"title":"Assemble","instruction":"Spoon the rice into bowls, slide the eggs on top, then add the chilli crisp, the soy mixture, scallions, and sesame seeds. Break the yolks into the rice."}]'::JSONB, 'The crisp brown edge is the point of the dish, so do not be tempted to lower the heat when it starts spitting. A splatter guard is genuinely useful here.', ARRAY['Add greens: Wilted bok choy or spinach under the egg.','Vegan: Crisped silken tofu slices in place of the eggs.','Noodles: Works just as well over instant noodles as over rice.']::TEXT[], ARRAY['Egg','Soy','Sesame']::TEXT[]),
('stuffed-dates', 'Stuffed Dates', 'Medjool dates filled with nut butter or cheese and topped with sea salt. Three minutes, no cooking.', 'https://images.unsplash.com/photo-1619046212867-9b0cfaa37186', 'Medjool dates stuffed with almond butter and topped with sea salt flakes', 'Leila Hassan', '@leilahassantable', '', '', '10 min', '—', '10 min', 10, 0, 10, 4, 'Easy', 'Middle Eastern', 'Snack', 'Snack', ARRAY['No-Cook','Gluten-Free','Quick','Party Food']::TEXT[], 4.6, 998, 2967, 212, 4, 32, 9, 3, '[{"amount":"12","unit":"","item":"Medjool dates"},{"amount":"6","unit":"tbsp","item":"almond butter"},{"amount":"2","unit":"oz","item":"goat cheese (optional)"},{"amount":"2","unit":"tbsp","item":"toasted pistachios, crushed"},{"amount":"2","unit":"oz","item":"dark chocolate, melted"},{"amount":"","unit":"","item":"Flaky sea salt"},{"amount":"","unit":"","item":"Orange zest"}]'::JSONB, '[{"step":1,"title":"Use Medjool","instruction":"Medjool dates are soft, large, and caramel-like. Deglet Noor are dry and small and make a disappointing version of this."},{"step":2,"title":"Pit carefully","instruction":"Slit each date lengthways along one side only and lift the stone out, keeping the date in one piece."},{"step":3,"title":"Fill generously","instruction":"Push a teaspoon of almond butter or a small piece of goat cheese into each cavity and press the sides gently closed."},{"step":4,"title":"Drizzle and top","instruction":"Drizzle the melted chocolate over, then scatter the pistachios, flaky salt, and a little orange zest while the chocolate is still wet.","tip":"Salt on top is what stops these being cloying. Be more generous than feels right."},{"step":5,"title":"Set","instruction":"Chill 10 minutes for the chocolate to firm, then serve."}]'::JSONB, 'These keep 5 days refrigerated, so they are a good thing to have on hand. Cheese-filled ones should be eaten within two days.', ARRAY['Nut-free: Sunflower seed butter or tahini.','Savoury: Goat cheese, a walnut half, and a wrap of prosciutto.','Bacon-wrapped: Wrap in bacon and bake 20 minutes at 400°F for a party version.']::TEXT[], ARRAY['Tree Nut','Dairy']::TEXT[]),
('dalgona-coffee', 'Dalgona Coffee', 'Instant coffee, sugar, and water whipped into a stiff caramel foam and floated over cold milk.', 'https://images.unsplash.com/photo-1590092783139-5db57ff2cd83', 'Whipped dalgona coffee foam over iced milk in a tall glass', 'Yuna Kim', '@yunakimkitchen', '', '', '10 min', '—', '10 min', 10, 0, 10, 2, 'Easy', 'Korean', 'Drink', 'Beverage', ARRAY['No-Cook','Viral','Vegetarian','Quick']::TEXT[], 4.9, 1199, 2704, 164, 5, 28, 4, 0, '[{"amount":"4","unit":"tbsp","item":"instant coffee granules"},{"amount":"4","unit":"tbsp","item":"granulated sugar"},{"amount":"4","unit":"tbsp","item":"boiling water"},{"amount":"2","unit":"cups","item":"cold milk"},{"amount":"","unit":"","item":"Ice cubes"},{"amount":"","unit":"","item":"Cocoa powder to dust"}]'::JSONB, '[{"step":1,"title":"Use instant coffee only","instruction":"It has to be instant. Ground coffee will not dissolve and never whips — the foam depends on the soluble solids in instant granules.","tip":"This is the one non-negotiable. Instant, not ground, not espresso."},{"step":2,"title":"Equal parts, all three","instruction":"Combine equal volumes of coffee, sugar, and boiling water in a deep bowl. The ratio is what makes it work."},{"step":3,"title":"Whip until stiff","instruction":"Beat with an electric whisk for 3–4 minutes. It goes from dark liquid to pale caramel and finally holds stiff peaks. By hand this takes about 10 minutes."},{"step":4,"title":"Check the peaks","instruction":"It is ready when a spoonful holds its shape without slumping back into the bowl."},{"step":5,"title":"Assemble","instruction":"Fill two glasses with ice and cold milk, spoon the foam on top, dust with cocoa, and stir before drinking."}]'::JSONB, 'The foam holds for about half an hour in the fridge before it starts weeping. Reducing the sugar sounds appealing but the sugar is structural — cut it and the foam will not hold.', ARRAY['Vegan: Any plant milk; oat milk works best for texture.','Hot version: Spoon the foam over hot milk instead.','Matcha: The same method does not work with matcha — it needs the coffee solids.']::TEXT[], ARRAY['Dairy']::TEXT[]),
('smoked-salmon-toast', 'Smoked Salmon Toast', 'Sourdough, cream cheese, cold-smoked salmon, capers, and dill. Assembly done properly.', 'https://images.unsplash.com/photo-1601261117161-9374344c2210', 'Sourdough toast with cream cheese, smoked salmon, and everything bagel seasoning', 'Maria Chen', '@mariachencooks', 'https://images.unsplash.com/photo-1677229888051-211da3f34219', 'Portrait of food creator Maria Chen', '10 min', '—', '10 min', 10, 0, 10, 2, 'Easy', 'Modern', 'Breakfast', 'Breakfast', ARRAY['Seafood','No-Cook','Brunch','Quick']::TEXT[], 4.3, 770, 2039, 428, 24, 34, 22, 2, '[{"amount":"4","unit":"slices","item":"sourdough bread"},{"amount":"6","unit":"oz","item":"cold-smoked salmon"},{"amount":"5","unit":"oz","item":"cream cheese, softened"},{"amount":"1","unit":"tbsp","item":"lemon juice"},{"amount":"1","unit":"tbsp","item":"capers, drained"},{"amount":"0.25","unit":"","item":"red onion, very thinly sliced"},{"amount":"2","unit":"tbsp","item":"fresh dill"},{"amount":"","unit":"","item":"Everything bagel seasoning"},{"amount":"","unit":"","item":"Black pepper and lemon wedges"}]'::JSONB, '[{"step":1,"title":"Toast dark","instruction":"Toast the sourdough until firmly crisp. A soft slice buckles under the weight of the toppings."},{"step":2,"title":"Season the cream cheese","instruction":"Beat the cream cheese with the lemon juice and black pepper until spreadable and slightly loosened.","tip":"Plain cream cheese straight from the tub tastes flat here. The lemon does a lot."},{"step":3,"title":"Spread thickly","instruction":"Spread a generous layer right to the edges of each slice."},{"step":4,"title":"Drape, do not flatten","instruction":"Lay the salmon in loose folds rather than flat sheets — it looks better and eats better."},{"step":5,"title":"Finish","instruction":"Scatter the capers, red onion, dill, and bagel seasoning. Serve with lemon wedges."}]'::JSONB, 'Take the salmon out of the fridge 10 minutes early; fridge-cold smoked salmon is firm and muted, and it tastes considerably better closer to room temperature.', ARRAY['Bagel: Same toppings on a toasted bagel.','Add: A soft-boiled or poached egg turns this into a full meal.','Dairy-free: Whipped avocado or a plant cream cheese.']::TEXT[], ARRAY['Fish','Gluten','Dairy']::TEXT[]),
('birria-ramen', 'Birria Ramen', 'Birria consommé and shredded beef over ramen noodles — the fusion that works better than it should.', 'https://images.unsplash.com/photo-1641642398311-45e905de2082', 'Fusion birria ramen with rich consommé broth, ramen noodles, and cheese', 'Rosa Gutierrez', '@rosagutierrezcocina', '', '', '30 min', '3 hrs', '3.5 hrs', 30, 180, 210, 6, 'Hard', 'Fusion', 'Dinner', 'Main Course', ARRAY['Weekend Project','Fusion','Spicy','Comfort']::TEXT[], 4.2, 847, 3363, 742, 46, 62, 34, 5, '[{"amount":"4","unit":"lb","item":"beef chuck, in chunks"},{"amount":"6","unit":"","item":"guajillo chillies, stemmed and seeded"},{"amount":"4","unit":"","item":"ancho chillies, stemmed and seeded"},{"amount":"2","unit":"","item":"chipotles in adobo"},{"amount":"1","unit":"","item":"onion, quartered"},{"amount":"6","unit":"cloves","item":"garlic"},{"amount":"2","unit":"","item":"tomatoes"},{"amount":"1","unit":"tbsp","item":"dried oregano"},{"amount":"1","unit":"tsp","item":"ground cumin"},{"amount":"1","unit":"","item":"cinnamon stick"},{"amount":"2","unit":"tbsp","item":"apple cider vinegar"},{"amount":"6","unit":"cups","item":"beef stock"},{"amount":"6","unit":"portions","item":"ramen noodles"},{"amount":"6","unit":"","item":"soft-boiled eggs"},{"amount":"","unit":"","item":"Cilantro, diced onion, lime, and sliced chilli to serve"}]'::JSONB, '[{"step":1,"title":"Toast and soak the chillies","instruction":"Toast the dried chillies 30 seconds a side until fragrant, then soak in boiling water for 20 minutes.","tip":"Stop toasting the moment they smell sweet. Burnt chillies make the whole broth bitter."},{"step":2,"title":"Blend and strain the adobo","instruction":"Blend the soaked chillies with the chipotles, onion, garlic, tomatoes, oregano, cumin, and vinegar. Strain it — a smooth broth matters more here than in tacos."},{"step":3,"title":"Sear and braise","instruction":"Sear the beef hard, then add the adobo, stock, and cinnamon. Cover and cook at 325°F (165°C) for 3 hours until the meat shreds easily."},{"step":4,"title":"Shred and skim","instruction":"Shred the beef. Skim the red fat from the surface and keep it — a spoonful goes on each bowl at the end."},{"step":5,"title":"Season the broth","instruction":"Taste the consommé and season hard with salt. It needs to be bolder than a normal soup, since noodles dilute it considerably.","tip":"Under-seasoned broth is the main way this goes wrong. Push the salt further than feels right."},{"step":6,"title":"Assemble","instruction":"Cook the noodles for 90 seconds and drain well. Divide between bowls, ladle over hot consommé, and top with beef, a halved egg, onion, cilantro, chilli, a spoon of red fat, and lime."}]'::JSONB, 'Make the braise a day ahead — the fat sets on top overnight and lifts off cleanly, giving you a better consommé and an easier assembly. Broth and meat freeze for 3 months.', ARRAY['Pressure cooker: 60 minutes high pressure replaces the 3-hour braise.','Quesabirria on the side: Use some of the beef and fat for dipping tacos.','Heat: Adjust with the chipotles; the dried chillies themselves are mild.']::TEXT[], ARRAY['Gluten','Egg']::TEXT[]),
('loaded-nachos', 'Loaded Nachos', 'Layered rather than piled, so every chip gets cheese instead of just the ones on top.', 'https://images.unsplash.com/photo-1601831132992-548e9366e073', 'Loaded nachos with melted cheese, jalapeños, sour cream, and guacamole', 'Carlos Mendez', '@carlosmendezcooks', '', '', '10 min', '10 min', '20 min', 10, 10, 20, 6, 'Easy', 'Mexican', 'Snack', 'Appetizer', ARRAY['Party Food','Family','Quick','Crowd Pleaser']::TEXT[], 4.8, 1526, 1189, 582, 24, 48, 34, 6, '[{"amount":"12","unit":"oz","item":"tortilla chips"},{"amount":"1","unit":"lb","item":"ground beef"},{"amount":"1","unit":"packet","item":"taco seasoning"},{"amount":"1","unit":"can","item":"black beans, drained"},{"amount":"3","unit":"cups","item":"grated cheddar and Monterey Jack"},{"amount":"1","unit":"cup","item":"pickled jalapeños"},{"amount":"1","unit":"cup","item":"salsa"},{"amount":"0.5","unit":"cup","item":"sour cream"},{"amount":"1","unit":"","item":"avocado, diced"},{"amount":"2","unit":"","item":"tomatoes, diced"},{"amount":"","unit":"","item":"Cilantro and lime"}]'::JSONB, '[{"step":1,"title":"Cook the beef","instruction":"Brown the beef, drain the fat, and stir in the taco seasoning with a splash of water. Simmer 3 minutes until thick, not wet.","tip":"Wet toppings make soggy nachos. Reduce the meat until it barely drips."},{"step":2,"title":"Layer, do not pile","instruction":"Spread a third of the chips on a lined tray, then a third of the beef, beans, and cheese. Repeat twice more.","tip":"Three thin layers, not one deep pile. This is the entire difference between good and bad nachos."},{"step":3,"title":"Bake hot and fast","instruction":"Bake at 400°F (205°C) for 10 minutes until the cheese is fully melted and bubbling at the edges."},{"step":4,"title":"Add cold toppings after","instruction":"Take the tray out before adding the salsa, sour cream, avocado, tomato, and cilantro. Baked sour cream splits and baked avocado turns grey."},{"step":5,"title":"Serve immediately","instruction":"Finish with jalapeños and lime and bring the tray straight to the table."}]'::JSONB, 'Grate your own cheese — pre-grated is coated in starch and melts poorly and greasily. Sturdy restaurant-style chips hold up far better than thin ones.', ARRAY['Vegetarian: Black beans and roasted sweet potato in place of the beef.','Make-ahead: Cook the beef up to 3 days ahead; assemble and bake to order.','Sheet pan: Use the largest tray you own so the layers stay shallow.']::TEXT[], ARRAY['Dairy','Gluten-Free-Adaptable']::TEXT[]),
('honey-garlic-salmon', 'Honey Garlic Salmon', 'Salmon seared crisp then glazed in a sticky honey garlic pan sauce. Twenty minutes.', 'https://img.rocket.new/generatedImages/rocket_gen_img_13581a46c-1772646980537.png', 'Glazed honey garlic salmon fillets with sesame seeds and green onions', 'Maria Chen', '@mariachencooks', 'https://images.unsplash.com/photo-1677229888051-211da3f34219', 'Portrait of food creator Maria Chen', '5 min', '15 min', '20 min', 5, 15, 20, 2, 'Easy', 'Asian Fusion', 'Dinner', 'Main Course', ARRAY['Seafood','Quick','Date Night','Gluten-Free-Adaptable']::TEXT[], 4.9, 745, 2025, 438, 38, 22, 22, 1, '[{"amount":"2","unit":"fillets","item":"salmon, skin on (6 oz each)"},{"amount":"3","unit":"tbsp","item":"honey"},{"amount":"4","unit":"cloves","item":"garlic, minced"},{"amount":"2","unit":"tbsp","item":"soy sauce"},{"amount":"1","unit":"tbsp","item":"rice vinegar"},{"amount":"1","unit":"tsp","item":"toasted sesame oil"},{"amount":"2","unit":"tbsp","item":"olive oil"},{"amount":"1","unit":"tsp","item":"cornstarch"},{"amount":"2","unit":"tbsp","item":"water"},{"amount":"","unit":"","item":"Salt and black pepper"},{"amount":"","unit":"","item":"Sesame seeds and scallions"}]'::JSONB, '[{"step":1,"title":"Dry the fish","instruction":"Pat the fillets completely dry and season both sides. Surface moisture is what prevents crisp skin.","tip":"Dry fish, crisp skin. There is no way around this step."},{"step":2,"title":"Mix the glaze first","instruction":"Whisk the honey, garlic, soy sauce, rice vinegar, and sesame oil together, and separately mix the cornstarch with the water."},{"step":3,"title":"Sear skin-side down","instruction":"Heat the olive oil until shimmering and lay the salmon skin-side down. Press gently for 30 seconds to stop it curling, then cook 4–5 minutes without moving it.","tip":"Do not move the fish. It releases from the pan by itself once the skin has crisped."},{"step":4,"title":"Flip and glaze","instruction":"Flip and cook 2 minutes, then pour the glaze around the fillets. Add the cornstarch slurry and let it bubble and thicken for 90 seconds, spooning it over the fish."},{"step":5,"title":"Rest and plate","instruction":"Rest 2 minutes, then plate skin-side up so it stays crisp. Spoon over the remaining glaze and finish with sesame seeds and scallions."}]'::JSONB, 'Salmon is done at 125°F for a moist medium — it carries on cooking as it rests. The glaze thickens fast, so have the slurry ready before you start.', ARRAY['Gluten-free: Use tamari in place of the soy sauce.','Swap: Works equally well with trout, arctic char, or thick cod.','Serve: Steamed rice and something green; the glaze needs a carrier.']::TEXT[], ARRAY['Fish','Soy','Sesame']::TEXT[]),
('teriyaki-chicken-bowl', 'Teriyaki Chicken Bowl', 'Chicken thighs glazed in a made-from-scratch teriyaki that reduces to a lacquer in the pan.', 'https://images.unsplash.com/photo-1634640848446-6d4d670b5142', 'Teriyaki glazed chicken over steamed rice with broccoli and sesame seeds', 'Yuki Tanaka', '@yukitanakaumami', '', '', '10 min', '15 min', '25 min', 10, 15, 25, 4, 'Easy', 'Japanese', 'Dinner', 'Main Course', ARRAY['Quick','Meal Prep','Family','Balanced']::TEXT[], 5.0, 1756, 3934, 568, 38, 62, 18, 3, '[{"amount":"1.5","unit":"lb","item":"boneless chicken thighs"},{"amount":"0.33","unit":"cup","item":"soy sauce"},{"amount":"0.25","unit":"cup","item":"mirin"},{"amount":"2","unit":"tbsp","item":"sake"},{"amount":"2","unit":"tbsp","item":"brown sugar"},{"amount":"1","unit":"tsp","item":"grated ginger"},{"amount":"1","unit":"clove","item":"garlic, grated"},{"amount":"1","unit":"tbsp","item":"neutral oil"},{"amount":"4","unit":"cups","item":"steamed rice"},{"amount":"2","unit":"cups","item":"steamed broccoli"},{"amount":"2","unit":"","item":"scallions, sliced"},{"amount":"","unit":"","item":"Sesame seeds"}]'::JSONB, '[{"step":1,"title":"Make real teriyaki","instruction":"Combine the soy sauce, mirin, sake, sugar, ginger, and garlic. Bottled teriyaki is mostly corn syrup; this takes one minute and tastes completely different."},{"step":2,"title":"Use thighs","instruction":"Thighs stay juicy through the high heat and reduction that this needs. Breast dries out before the glaze sets."},{"step":3,"title":"Sear hard","instruction":"Cook the thighs skin or presentation side down in the oil over medium-high heat for 6 minutes until deeply golden, then flip for 4 minutes."},{"step":4,"title":"Reduce the glaze","instruction":"Pour in the sauce and let it bubble for 3–4 minutes, turning the chicken to coat, until it thickens into a syrup that clings.","tip":"Watch it closely at the end — sugar goes from glossy to burnt in under a minute."},{"step":5,"title":"Rest and slice","instruction":"Rest the chicken 3 minutes, then slice and fan over rice with broccoli. Spoon over the pan glaze and top with scallions and sesame."}]'::JSONB, 'If the glaze thickens too far it turns tacky and bitter; a splash of water loosens it back. No sake or mirin? Use a tablespoon of rice vinegar and an extra teaspoon of sugar.', ARRAY['Salmon: The same glaze on salmon fillets, 4 minutes a side.','Meal prep: Keeps 4 days; store the rice and chicken together and the greens separately.','Gluten-free: Tamari in place of soy sauce.']::TEXT[], ARRAY['Soy','Sesame','Gluten']::TEXT[]),
('pesto-pasta', 'Pesto Pasta', 'Fresh basil pesto loosened with pasta water so it coats rather than clumps.', 'https://images.unsplash.com/photo-1689793601570-7980ac301eca', 'Fresh basil pesto pasta with cherry tomatoes and parmesan cheese', 'Sofia Romano', '@sofiaromanoeats', '', '', '10 min', '10 min', '20 min', 10, 10, 20, 4, 'Easy', 'Italian', 'Dinner', 'Main Course', ARRAY['Vegetarian','Quick','Classic','Family']::TEXT[], 5.0, 154, 3839, 612, 19, 68, 30, 4, '[{"amount":"1","unit":"lb","item":"spaghetti or trofie"},{"amount":"3","unit":"cups","item":"fresh basil leaves"},{"amount":"0.5","unit":"cup","item":"pine nuts, toasted"},{"amount":"3","unit":"cloves","item":"garlic"},{"amount":"0.75","unit":"cup","item":"grated parmesan"},{"amount":"0.66","unit":"cup","item":"extra virgin olive oil"},{"amount":"1","unit":"tbsp","item":"lemon juice"},{"amount":"1","unit":"cup","item":"cherry tomatoes, halved"},{"amount":"","unit":"","item":"Salt and black pepper"}]'::JSONB, '[{"step":1,"title":"Blanch the basil (optional but worth it)","instruction":"Dip the basil in boiling water for 10 seconds then straight into ice water. This keeps the pesto bright green for days rather than turning dark within the hour.","tip":"Skip it if you are eating immediately; do it if the colour matters."},{"step":2,"title":"Pulse, do not purée","instruction":"Pulse the basil, pine nuts, and garlic to a coarse crumb, add the parmesan, then stream in the oil with the motor running in short bursts.","tip":"Continuous blending heats the basil and turns pesto bitter and brown."},{"step":3,"title":"Season the pesto","instruction":"Add the lemon juice, salt, and pepper and taste. It should be punchy on its own, since the pasta will dilute it."},{"step":4,"title":"Save the pasta water","instruction":"Cook the pasta al dente and reserve a full cup of the water before draining."},{"step":5,"title":"Combine off the heat","instruction":"Toss the drained pasta with the pesto in a warm bowl — not over the flame — adding pasta water a splash at a time until it coats every strand.","tip":"Never cook pesto. Heat dulls the basil and separates the oil."},{"step":6,"title":"Finish","instruction":"Fold through the tomatoes and serve with extra parmesan."}]'::JSONB, 'Pesto keeps a week in the fridge under a thin layer of olive oil, or freezes in ice cube trays for three months. Traditionally the pasta is cooked with a few potato slices and green beans in Liguria — worth trying.', ARRAY['Nut-free: Toasted sunflower or pumpkin seeds.','Vegan: Nutritional yeast and a little white miso for the parmesan.','Variations: Rocket, walnut, or sun-dried tomato pesto all use the same method.']::TEXT[], ARRAY['Gluten','Dairy','Tree Nut']::TEXT[]),
('chocolate-mug-cake', 'Chocolate Mug Cake', 'A single-serving chocolate cake from the microwave in ninety seconds, with an actual gooey centre.', 'https://img.rocket.new/generatedImages/rocket_gen_img_11171b300-1772799441963.png', 'Warm chocolate mug cake with gooey center topped with ice cream', 'Emma Walsh', '@emmawalshbakes', '', '', '3 min', '2 min', '5 min', 3, 2, 5, 1, 'Easy', 'Modern', 'Dessert', 'Dessert', ARRAY['Quick','Single Serving','Vegetarian','No-Oven']::TEXT[], 5.0, 737, 1594, 462, 9, 58, 22, 3, '[{"amount":"4","unit":"tbsp","item":"all-purpose flour"},{"amount":"3","unit":"tbsp","item":"granulated sugar"},{"amount":"2","unit":"tbsp","item":"cocoa powder"},{"amount":"0.25","unit":"tsp","item":"baking powder"},{"amount":"","unit":"","item":"Pinch of salt"},{"amount":"1","unit":"","item":"egg"},{"amount":"3","unit":"tbsp","item":"milk"},{"amount":"2","unit":"tbsp","item":"melted butter"},{"amount":"0.5","unit":"tsp","item":"vanilla extract"},{"amount":"1","unit":"tbsp","item":"chocolate chips"}]'::JSONB, '[{"step":1,"title":"Mix dry in the mug","instruction":"Whisk the flour, sugar, cocoa, baking powder, and salt directly in a large mug with a fork until no cocoa lumps remain."},{"step":2,"title":"Add wet and beat smooth","instruction":"Add the egg, milk, melted butter, and vanilla and beat until completely smooth, scraping the bottom corners where dry flour hides."},{"step":3,"title":"Use a big enough mug","instruction":"The batter should fill no more than half the mug — it rises dramatically and will overflow otherwise."},{"step":4,"title":"Push chocolate into the centre","instruction":"Drop the chocolate chips into the middle of the batter without stirring, so they form a molten core."},{"step":5,"title":"Microwave short","instruction":"Microwave on full power for 70–90 seconds. Stop while the top still looks slightly wet — it firms up in seconds after.","tip":"Ten seconds too long turns this to rubber. Start at 70 seconds and add in 10-second bursts."},{"step":6,"title":"Rest","instruction":"Rest 1 minute before eating."}]'::JSONB, 'Microwave wattages vary a lot, so the first one is a calibration exercise. Note the time that worked and use it every time after.', ARRAY['Eggless: Skip the egg and add 2 more tablespoons of milk; slightly denser but fine.','Peanut butter: Push a teaspoon into the centre alongside the chocolate.','Serve: A scoop of ice cream on top while it is still hot.']::TEXT[], ARRAY['Gluten','Dairy','Egg']::TEXT[]),
('garlic-naan-pizza', 'Garlic Naan Pizza', 'Shop-bought naan as the base, blistered under a hot grill in fifteen minutes.', 'https://img.rocket.new/generatedImages/rocket_gen_img_163f55b55-1769407178742.png', 'Quick naan pizza with garlic butter, mozzarella, and fresh toppings', 'Aisha Sharma', '@aishasharmaspice', '', '', '5 min', '10 min', '15 min', 5, 10, 15, 2, 'Easy', 'Fusion', 'Dinner', 'Main Course', ARRAY['Quick','Vegetarian-Adaptable','Family','Budget']::TEXT[], 4.8, 943, 1571, 582, 24, 62, 26, 4, '[{"amount":"2","unit":"","item":"garlic naan breads"},{"amount":"0.5","unit":"cup","item":"passata or pizza sauce"},{"amount":"2","unit":"cups","item":"grated mozzarella"},{"amount":"2","unit":"tbsp","item":"olive oil"},{"amount":"2","unit":"cloves","item":"garlic, minced"},{"amount":"1","unit":"tsp","item":"dried oregano"},{"amount":"0.5","unit":"cup","item":"cherry tomatoes, halved"},{"amount":"","unit":"","item":"Fresh basil"},{"amount":"","unit":"","item":"Chilli flakes and black pepper"}]'::JSONB, '[{"step":1,"title":"Pre-crisp the naan","instruction":"Brush the naan with olive oil and bake at 450°F (230°C) for 4 minutes before topping.","tip":"Topping raw naan gives a soggy centre. Four minutes of pre-baking fixes it."},{"step":2,"title":"Keep the sauce thin","instruction":"Spread only a couple of tablespoons of sauce on each — naan is softer than pizza dough and cannot take much liquid."},{"step":3,"title":"Top lightly","instruction":"Scatter the mozzarella, garlic, oregano, and tomatoes. Resist overloading."},{"step":4,"title":"Bake hot","instruction":"Return to the oven for 8 minutes until the cheese is bubbling and browning in patches."},{"step":5,"title":"Finish fresh","instruction":"Add basil, chilli flakes, and pepper after it comes out, and a final drizzle of oil."}]'::JSONB, 'Pitta, flatbread, or tortillas all work with the same method; tortillas need only 5 minutes total. A pre-heated tray or stone under the naan gives a noticeably crisper base.', ARRAY['Add protein: Leftover chicken, pepperoni, or chickpeas.','Indian-style: Tikka sauce, paneer, and red onion instead of the Italian toppings.','Air fryer: 380°F for 6 minutes works well for one at a time.']::TEXT[], ARRAY['Gluten','Dairy']::TEXT[]),
('tuna-poke-bowl', 'Tuna Poke Bowl', 'Sashimi-grade tuna marinated briefly in soy and sesame, over sushi rice with avocado and edamame.', 'https://images.unsplash.com/photo-1597958792579-bd3517df6399', 'Fresh tuna poke bowl with sushi rice, edamame, avocado, and sesame dressing', 'Maria Chen', '@mariachencooks', 'https://images.unsplash.com/photo-1677229888051-211da3f34219', 'Portrait of food creator Maria Chen', '20 min', '—', '20 min', 20, 0, 20, 2, 'Easy', 'Hawaiian', 'Lunch', 'Main Course', ARRAY['Seafood','No-Cook','Fresh','High Protein']::TEXT[], 4.4, 1627, 9220, 582, 38, 62, 20, 6, '[{"amount":"12","unit":"oz","item":"sashimi-grade ahi tuna, cubed"},{"amount":"3","unit":"tbsp","item":"soy sauce"},{"amount":"1","unit":"tbsp","item":"toasted sesame oil"},{"amount":"1","unit":"tsp","item":"rice vinegar"},{"amount":"1","unit":"tsp","item":"grated ginger"},{"amount":"2","unit":"","item":"scallions, sliced"},{"amount":"2","unit":"cups","item":"cooked sushi rice"},{"amount":"1","unit":"","item":"avocado, sliced"},{"amount":"0.5","unit":"cup","item":"shelled edamame"},{"amount":"1","unit":"","item":"cucumber, diced"},{"amount":"2","unit":"tbsp","item":"toasted sesame seeds"},{"amount":"1","unit":"sheet","item":"nori, shredded"},{"amount":"","unit":"","item":"Pickled ginger"}]'::JSONB, '[{"step":1,"title":"Buy the right fish","instruction":"Use tuna sold specifically as sashimi or sushi grade from a fishmonger you trust. Standard tuna steak is not intended to be eaten raw.","tip":"This is a food safety point, not a quality one. Ask the counter directly."},{"step":2,"title":"Cut against the grain","instruction":"Cut the tuna into even three-quarter-inch cubes with a very sharp knife, slicing against the grain."},{"step":3,"title":"Marinate briefly","instruction":"Toss with the soy sauce, sesame oil, rice vinegar, ginger, and scallions. Marinate 10–15 minutes only.","tip":"Longer than fifteen minutes and the soy starts curing the fish, turning the texture firm and grey."},{"step":4,"title":"Season the rice","instruction":"Let the sushi rice cool to just warm. Hot rice will part-cook the tuna the moment they touch."},{"step":5,"title":"Build","instruction":"Divide the rice between bowls and arrange the tuna, avocado, edamame, and cucumber on top. Finish with sesame seeds, nori, and pickled ginger."}]'::JSONB, 'Eat within an hour of cutting the fish. Keep the tuna in the coldest part of the fridge until the moment you cube it, and keep everything else prepped and ready first.', ARRAY['Cooked version: Seared tuna, 30 seconds a side, if raw is not for you.','Salmon: Sashimi-grade salmon works identically.','Spicy: Add a spoonful of sriracha mayo over the top.']::TEXT[], ARRAY['Fish','Soy','Sesame']::TEXT[]),
('spicy-ramen', 'Spicy Ramen', 'Instant ramen upgraded with real aromatics, chilli, a soft egg, and proper toppings. Twenty minutes.', 'https://images.unsplash.com/photo-1710573558322-a8d98ecd5053', 'Spicy instant ramen upgraded with soft-boiled egg, nori, and chili oil', 'Yuna Kim', '@yunakimkitchen', '', '', '8 min', '12 min', '20 min', 8, 12, 20, 2, 'Easy', 'Japanese', 'Dinner', 'Main Course', ARRAY['Quick','Budget','Spicy','Comfort']::TEXT[], 4.3, 1226, 7250, 612, 22, 72, 26, 4, '[{"amount":"2","unit":"packs","item":"instant ramen (noodles only)"},{"amount":"2","unit":"tbsp","item":"neutral oil"},{"amount":"3","unit":"cloves","item":"garlic, minced"},{"amount":"1","unit":"inch","item":"ginger, grated"},{"amount":"2","unit":"tbsp","item":"gochujang or chilli paste"},{"amount":"1","unit":"tbsp","item":"miso paste"},{"amount":"4","unit":"cups","item":"chicken or vegetable stock"},{"amount":"1","unit":"tbsp","item":"soy sauce"},{"amount":"1","unit":"tsp","item":"toasted sesame oil"},{"amount":"2","unit":"","item":"eggs"},{"amount":"2","unit":"","item":"scallions, sliced"},{"amount":"1","unit":"sheet","item":"nori"},{"amount":"2","unit":"tbsp","item":"chilli crisp"},{"amount":"","unit":"","item":"Bok choy"}]'::JSONB, '[{"step":1,"title":"Bin the seasoning packet","instruction":"Discard the sachet and build a real broth instead. This is the only step that separates this from instant noodles."},{"step":2,"title":"Soft-boil the eggs","instruction":"Boil the eggs for exactly 6.5 minutes, then plunge into ice water and peel. The yolk should be jammy, not set."},{"step":3,"title":"Fry the aromatics","instruction":"Cook the garlic and ginger in the oil for 45 seconds, then add the gochujang and miso and fry for 1 minute until darkened and fragrant.","tip":"Frying the pastes rather than dissolving them is what gives the broth depth."},{"step":4,"title":"Build the broth","instruction":"Add the stock and soy sauce and simmer 5 minutes. Add the bok choy for the final 2 minutes. Finish with sesame oil off the heat."},{"step":5,"title":"Cook noodles separately","instruction":"Boil the noodles in a separate pan of water and drain. Cooking them in the broth releases starch and makes it cloudy and gluey.","tip":"Separate pan. It takes one extra pot and makes a real difference."},{"step":6,"title":"Assemble","instruction":"Divide the noodles between bowls, ladle over broth, and top with halved eggs, scallions, nori, and chilli crisp."}]'::JSONB, 'Do not boil the broth after the miso goes in — it flattens the flavour. Any leftover broth keeps 4 days and is better on the second day.', ARRAY['Add protein: Leftover chicken, crisped tofu, or sliced pork belly.','Vegan: Vegetable stock and skip the egg; add fried mushrooms.','Heat: Gochujang is moderate; add chilli oil at the table rather than in the pot.']::TEXT[], ARRAY['Gluten','Egg','Soy','Sesame']::TEXT[]),
('chicken-quesadilla', 'Chicken Quesadilla', 'Cheese on both sides of the filling so it glues shut, cooked slowly in a dry pan until the tortilla blisters.', 'https://images.unsplash.com/photo-1630914441316-6d95bbd00caf', 'Crispy chicken quesadilla with melted cheese, peppers, and sour cream', 'Carlos Mendez', '@carlosmendezcooks', '', '', '10 min', '10 min', '20 min', 10, 10, 20, 4, 'Easy', 'Mexican', 'Lunch', 'Main Course', ARRAY['Quick','Family','Budget','Kid Friendly']::TEXT[], 4.2, 48, 8507, 548, 34, 42, 26, 3, '[{"amount":"4","unit":"","item":"large flour tortillas"},{"amount":"2","unit":"cups","item":"cooked shredded chicken"},{"amount":"3","unit":"cups","item":"grated Monterey Jack and cheddar"},{"amount":"1","unit":"","item":"red pepper, sliced thin"},{"amount":"0.5","unit":"","item":"onion, sliced thin"},{"amount":"1","unit":"tsp","item":"chilli powder"},{"amount":"1","unit":"tsp","item":"ground cumin"},{"amount":"1","unit":"tbsp","item":"neutral oil"},{"amount":"","unit":"","item":"Sour cream, salsa, and guacamole to serve"}]'::JSONB, '[{"step":1,"title":"Cook the vegetables first","instruction":"Fry the pepper and onion in the oil for 5 minutes until softened, then toss with the chicken, chilli powder, and cumin. Raw vegetables release water inside the quesadilla."},{"step":2,"title":"Cheese on both sides","instruction":"Scatter cheese directly onto the tortilla, add the filling, then more cheese on top before folding. The cheese on both faces is what glues it shut.","tip":"Filling touching the tortilla is why quesadillas fall apart. Cheese first, cheese last."},{"step":3,"title":"Dry pan, medium heat","instruction":"Cook in a dry pan over medium heat — no oil. Oil makes the tortilla greasy rather than crisp."},{"step":4,"title":"Be patient","instruction":"Cook 4 minutes per side, pressing gently with a spatula, until the tortilla is browned in patches and the cheese has fully melted. High heat browns the outside before the cheese melts."},{"step":5,"title":"Rest before cutting","instruction":"Rest 2 minutes on a board before cutting into wedges, so the cheese sets enough to hold."}]'::JSONB, 'Grate the cheese yourself; the anti-caking starch on pre-grated cheese stops it melting smoothly. Rotisserie chicken makes this a genuine ten-minute meal.', ARRAY['Vegetarian: Black beans, corn, and roasted sweet potato.','Make-ahead: Assemble and refrigerate for a day, then cook from cold.','Freezer: Cooked and cooled quesadillas freeze well; reheat in a dry pan.']::TEXT[], ARRAY['Gluten','Dairy']::TEXT[]),
('avocado-egg-salad', 'Avocado Egg Salad', 'Hard-boiled eggs mashed with avocado instead of mayonnaise, sharpened with lemon and Dijon.', 'https://images.unsplash.com/photo-1659474687639-9572736365e4', 'Creamy avocado egg salad on toasted bread with microgreens', 'Emma Walsh', '@emmawalshbakes', '', '', '15 min', '—', '15 min', 15, 0, 15, 4, 'Easy', 'Modern', 'Lunch', 'Salad', ARRAY['Gluten-Free-Adaptable','High Protein','Quick','Healthy']::TEXT[], 4.9, 719, 5089, 286, 14, 8, 22, 5, '[{"amount":"6","unit":"large","item":"eggs"},{"amount":"2","unit":"","item":"ripe avocados"},{"amount":"1","unit":"tbsp","item":"lemon juice"},{"amount":"1","unit":"tsp","item":"Dijon mustard"},{"amount":"2","unit":"","item":"scallions, finely sliced"},{"amount":"2","unit":"tbsp","item":"chopped dill"},{"amount":"0.25","unit":"tsp","item":"smoked paprika"},{"amount":"","unit":"","item":"Salt and black pepper"},{"amount":"","unit":"","item":"Bread or lettuce cups to serve"}]'::JSONB, '[{"step":1,"title":"Boil and shock the eggs","instruction":"Lower the eggs into already-boiling water and cook 9 minutes, then plunge straight into ice water for 5 minutes.","tip":"The ice bath stops the cooking and makes them peel cleanly. Both matter."},{"step":2,"title":"Peel under water","instruction":"Crack and peel the eggs under running water — the water gets under the membrane and lifts the shell off in sheets."},{"step":3,"title":"Mash the avocado first","instruction":"Mash the avocado with the lemon juice, Dijon, salt, and pepper until it forms a creamy base. Taste and season before the eggs go in."},{"step":4,"title":"Chop, do not mash, the eggs","instruction":"Roughly chop the eggs and fold them through. Texture contrast is the point — mashing everything gives you a uniform paste.","tip":"Leave visible pieces of white. It makes the salad far better to eat."},{"step":5,"title":"Finish","instruction":"Fold in the scallions and dill, dust with paprika, and serve on toast or in lettuce cups."}]'::JSONB, 'Lemon juice slows the avocado browning but does not stop it — this is best eaten within a few hours. Press cling film directly onto the surface if storing.', ARRAY['Classic version: Swap half the avocado for mayonnaise if you want it richer.','Add: Crisp bacon, capers, or a spoonful of chilli crisp.','Gluten-free: Serve in lettuce cups or on GF toast.']::TEXT[], ARRAY['Egg','Mustard']::TEXT[]),
('lemon-butter-pasta', 'Lemon Butter Pasta', 'Butter, lemon, parmesan, and pasta water emulsified into a sauce with five ingredients.', 'https://img.rocket.new/generatedImages/rocket_gen_img_17e05496a-1771904964499.png', 'Simple lemon butter pasta with parmesan and fresh herbs', 'Marco Rossi', '@marcorossicucina', '', '', '5 min', '15 min', '20 min', 5, 15, 20, 4, 'Easy', 'Italian', 'Dinner', 'Main Course', ARRAY['Vegetarian','Quick','Minimal Ingredients','Budget']::TEXT[], 4.7, 843, 7555, 512, 15, 66, 21, 3, '[{"amount":"1","unit":"lb","item":"spaghetti or linguine"},{"amount":"6","unit":"tbsp","item":"unsalted butter"},{"amount":"2","unit":"large","item":"lemons (zest and juice)"},{"amount":"1","unit":"cup","item":"grated parmesan"},{"amount":"3","unit":"cloves","item":"garlic, thinly sliced"},{"amount":"0.5","unit":"cup","item":"chopped parsley"},{"amount":"","unit":"","item":"Salt and coarse black pepper"}]'::JSONB, '[{"step":1,"title":"Cook the pasta in less water","instruction":"Use a wide pan with just enough water to cover. Starchier water makes a far better emulsion.","tip":"Starchy pasta water is the sauce here. Less water, more starch."},{"step":2,"title":"Melt butter with garlic","instruction":"Melt the butter in a wide skillet over medium-low heat with the sliced garlic and cook 2 minutes until pale gold, not brown."},{"step":3,"title":"Add zest off the heat","instruction":"Take the pan off the heat and add the lemon zest. Zest cooked in hot butter turns bitter."},{"step":4,"title":"Emulsify","instruction":"Add the drained pasta with a cup of pasta water and toss hard over medium heat. Add the parmesan in handfuls, tossing continuously, until glossy and thickened.","tip":"Keep tossing. The emulsion only forms with constant movement — a still pan gives you buttery water."},{"step":5,"title":"Finish with juice","instruction":"Off the heat, add the lemon juice, parsley, and plenty of black pepper. Taste and add more lemon."}]'::JSONB, 'Add the juice at the very end rather than earlier — acid added to hot butter can cause the sauce to split. If it does split, a splash of cool pasta water and vigorous tossing will usually bring it back.', ARRAY['Add protein: Seared shrimp, flaked salmon, or roast chicken.','Vegan: Good olive oil, nutritional yeast, and a spoonful of white miso.','Greens: Wilt in a bag of spinach or some peas at the end.']::TEXT[], ARRAY['Gluten','Dairy']::TEXT[]),
('miso-glazed-eggplant', 'Miso Glazed Eggplant', 'Aubergine scored, roasted until collapsing, then glazed with sweet miso and grilled until blistered.', 'https://img.rocket.new/generatedImages/rocket_gen_img_1635683f8-1772057315477.png', 'Roasted eggplant with sweet miso glaze and sesame seeds', 'Yuki Tanaka', '@yukitanakaumami', '', '', '10 min', '15 min', '25 min', 10, 15, 25, 4, 'Easy', 'Japanese', 'Dinner', 'Side Dish', ARRAY['Vegan-Adaptable','Gluten-Free-Adaptable','Umami']::TEXT[], 4.6, 242, 8709, 212, 5, 22, 12, 6, '[{"amount":"2","unit":"large","item":"aubergines, halved lengthways"},{"amount":"3","unit":"tbsp","item":"white miso paste"},{"amount":"2","unit":"tbsp","item":"mirin"},{"amount":"1","unit":"tbsp","item":"sake"},{"amount":"1","unit":"tbsp","item":"sugar"},{"amount":"1","unit":"tsp","item":"toasted sesame oil"},{"amount":"2","unit":"tbsp","item":"neutral oil"},{"amount":"2","unit":"","item":"scallions, sliced"},{"amount":"1","unit":"tbsp","item":"toasted sesame seeds"}]'::JSONB, '[{"step":1,"title":"Score deeply","instruction":"Score the cut faces in a diamond pattern about half an inch deep, without cutting through the skin. This lets heat and glaze get into the flesh.","tip":"Deep scoring is what turns aubergine from rubbery to custardy."},{"step":2,"title":"Roast cut-side down first","instruction":"Brush with the neutral oil and roast cut-side down at 425°F (220°C) for 20 minutes. Face-down roasting steams the flesh soft."},{"step":3,"title":"Make the glaze","instruction":"Whisk the miso, mirin, sake, sugar, and sesame oil into a thick, spreadable paste."},{"step":4,"title":"Flip and glaze","instruction":"Turn the halves over, spread the glaze thickly across the scored faces, and return to the oven for 8 minutes."},{"step":5,"title":"Blister under the grill","instruction":"Switch to the grill for 3 minutes until the glaze bubbles and blackens in spots. Watch it — the sugar burns quickly.","tip":"Those charred patches are the best part, but they go from perfect to burnt in about thirty seconds."},{"step":6,"title":"Top","instruction":"Scatter with scallions and sesame seeds and serve hot."}]'::JSONB, 'Aubergine drinks oil, so brush rather than pour, and let the roasting do the softening instead. Salting beforehand is unnecessary with modern varieties.', ARRAY['Gluten-free: Check the miso, as some contain barley.','No sake or mirin: Rice vinegar plus an extra teaspoon of sugar.','As a main: Serve over rice with a soft-boiled egg.']::TEXT[], ARRAY['Soy','Sesame']::TEXT[])
