INSERT INTO public.recipes (slug, title, description, image, image_alt, creator_name, creator_handle, creator_image, creator_alt, prep_time, cook_time, total_time, prep_minutes, cook_minutes, total_minutes, servings, difficulty, cuisine, meal_type, category, tags, rating, reviews, cooks, calories, protein, carbs, fat, fiber, ingredients, steps, notes, tips, allergens) VALUES
('crispy-tofu-bowl', 'Crispy Tofu Bowl', 'Pressed tofu tossed in cornstarch and baked until genuinely crisp, over rice with peanut sauce.', 'https://images.unsplash.com/photo-1546069901-55d1670321aa', 'Crispy baked tofu over rice with peanut sauce and fresh vegetables', 'Lin Wei', '@linweiwok', '', '', '15 min', '15 min', '30 min', 15, 15, 30, 4, 'Easy', 'Asian Fusion', 'Dinner', 'Main Course', ARRAY['Vegan','High Protein','Meal Prep','Gluten-Free-Adaptable']::TEXT[], 4.7, 668, 2218, 548, 24, 58, 26, 7, '[{"amount":"14","unit":"oz","item":"extra-firm tofu"},{"amount":"3","unit":"tbsp","item":"cornstarch"},{"amount":"2","unit":"tbsp","item":"neutral oil"},{"amount":"1","unit":"tbsp","item":"soy sauce"},{"amount":"0.33","unit":"cup","item":"peanut butter"},{"amount":"2","unit":"tbsp","item":"soy sauce for the sauce"},{"amount":"1","unit":"tbsp","item":"rice vinegar"},{"amount":"1","unit":"tbsp","item":"maple syrup"},{"amount":"1","unit":"clove","item":"garlic, grated"},{"amount":"4","unit":"tbsp","item":"warm water"},{"amount":"4","unit":"cups","item":"cooked rice"},{"amount":"2","unit":"cups","item":"steamed broccoli"},{"amount":"1","unit":"","item":"carrot, julienned"},{"amount":"","unit":"","item":"Scallions and sesame seeds"}]'::JSONB, '[{"step":1,"title":"Press the tofu hard","instruction":"Wrap the block in a towel, put a heavy pan on top, and press for at least 20 minutes. Squeezing the water out is what allows it to crisp instead of steam.","tip":"Twenty minutes minimum. Unpressed tofu will never go crisp, whatever else you do."},{"step":2,"title":"Tear, do not cube","instruction":"Tear the pressed tofu into rough chunks rather than cutting neat cubes. The irregular surfaces catch the coating and crisp much better."},{"step":3,"title":"Coat in cornstarch","instruction":"Toss the pieces with the soy sauce first, then the cornstarch, until each piece is dusted evenly and looks dry."},{"step":4,"title":"Bake hot","instruction":"Spread on an oiled tray with space between pieces and bake at 425°F (220°C) for 30 minutes, flipping once, until deep golden and firm."},{"step":5,"title":"Make the peanut sauce","instruction":"Whisk the peanut butter, soy sauce, vinegar, maple syrup, and garlic. It will seize; add the warm water gradually until pourable."},{"step":6,"title":"Assemble","instruction":"Build bowls with rice, broccoli, carrot, and tofu, then spoon the sauce over and top with scallions and sesame seeds."}]'::JSONB, 'Sauce the tofu at the table rather than in the bowl if you want it to stay crisp. Baked tofu keeps 4 days and re-crisps in an air fryer for 4 minutes.', ARRAY['Air fryer: 400°F for 15 minutes, shaking twice.','Nut-free: Tahini or sunflower seed butter make the same sauce.','Gluten-free: Tamari in place of soy sauce.']::TEXT[], ARRAY['Soy','Peanut','Sesame']::TEXT[]),
('beef-bulgogi', 'Beef Bulgogi', 'Thin beef marinated in soy, pear, and sesame, then seared hard so it caramelises rather than stews.', 'https://img.rocket.new/generatedImages/rocket_gen_img_1f028ab6b-1779993139967.png', 'Marinated Korean beef bulgogi with sesame seeds and green onions over rice', 'Min-Jun Oh', '@minjunohkitchen', '', '', '20 min', '10 min', '30 min', 20, 10, 30, 4, 'Easy', 'Korean', 'Dinner', 'Main Course', ARRAY['Quick-Cook','High Protein','Family','Gluten-Free-Adaptable']::TEXT[], 4.9, 208, 7814, 486, 34, 24, 28, 2, '[{"amount":"1.5","unit":"lb","item":"ribeye or sirloin, sliced paper-thin"},{"amount":"0.33","unit":"cup","item":"soy sauce"},{"amount":"0.5","unit":"","item":"Asian pear, grated"},{"amount":"2","unit":"tbsp","item":"brown sugar"},{"amount":"2","unit":"tbsp","item":"toasted sesame oil"},{"amount":"6","unit":"cloves","item":"garlic, minced"},{"amount":"1","unit":"tbsp","item":"grated ginger"},{"amount":"1","unit":"","item":"onion, sliced"},{"amount":"4","unit":"","item":"scallions, cut into batons"},{"amount":"1","unit":"tbsp","item":"toasted sesame seeds"},{"amount":"2","unit":"tbsp","item":"neutral oil"},{"amount":"","unit":"","item":"Steamed rice and lettuce leaves to serve"}]'::JSONB, '[{"step":1,"title":"Freeze then slice","instruction":"Freeze the beef for 45 minutes until firm at the edges, then slice as thinly as you possibly can against the grain.","tip":"Partial freezing is the only realistic way to get paper-thin slices at home."},{"step":2,"title":"Grate the pear in","instruction":"Whisk the soy sauce, grated pear, sugar, sesame oil, garlic, and ginger. The pear enzymes tenderise the beef and add a clean sweetness sugar alone cannot."},{"step":3,"title":"Marinate 30 minutes to overnight","instruction":"Coat the beef and refrigerate at least 30 minutes. Overnight is better but do not go beyond 24 hours or the texture turns mushy."},{"step":4,"title":"Sear in batches on maximum heat","instruction":"Get a pan or griddle screaming hot and cook the beef in three thin batches, 90 seconds per batch, without stirring much.","tip":"Crowding the pan is fatal here. The marinade liquid pools and the beef boils grey instead of caramelising."},{"step":5,"title":"Add the onion at the end","instruction":"Add the onion and scallions for the final minute so they keep some bite."},{"step":6,"title":"Serve","instruction":"Top with sesame seeds and serve with rice and lettuce leaves for wrapping."}]'::JSONB, 'Many butchers will slice beef for bulgogi if you ask, and Korean grocers sell it pre-sliced. Ribeye has the fat marbling that makes this dish; leaner cuts are noticeably drier.', ARRAY['Gluten-free: Tamari in place of soy sauce.','No Asian pear: A grated kiwi (only 15 minutes marinating) or a regular pear.','Pork or chicken: Both work with the same marinade; chicken needs 4 minutes a side.']::TEXT[], ARRAY['Soy','Sesame']::TEXT[]),
('shrimp-tacos', 'Shrimp Tacos', 'Spiced shrimp seared for two minutes, with cabbage slaw and chipotle crema in warm tortillas.', 'https://img.rocket.new/generatedImages/rocket_gen_img_10219b7a4-1772055932983.png', 'Crispy shrimp tacos with cabbage slaw, avocado, and chipotle crema', 'Rosa Gutierrez', '@rosagutierrezcocina', '', '', '15 min', '5 min', '20 min', 15, 5, 20, 4, 'Easy', 'Mexican', 'Dinner', 'Main Course', ARRAY['Seafood','Quick','Fresh','Gluten-Free-Adaptable']::TEXT[], 4.5, 738, 1672, 462, 28, 42, 20, 5, '[{"amount":"1.5","unit":"lb","item":"large shrimp, peeled"},{"amount":"2","unit":"tsp","item":"chilli powder"},{"amount":"1","unit":"tsp","item":"smoked paprika"},{"amount":"1","unit":"tsp","item":"ground cumin"},{"amount":"2","unit":"tbsp","item":"olive oil"},{"amount":"3","unit":"cups","item":"shredded red cabbage"},{"amount":"0.25","unit":"","item":"red onion, thinly sliced"},{"amount":"1","unit":"","item":"lime, juiced"},{"amount":"0.5","unit":"cup","item":"sour cream"},{"amount":"2","unit":"tbsp","item":"mayonnaise"},{"amount":"2","unit":"","item":"chipotles in adobo, minced"},{"amount":"12","unit":"","item":"corn tortillas"},{"amount":"1","unit":"","item":"avocado, sliced"},{"amount":"","unit":"","item":"Cilantro and salt"}]'::JSONB, '[{"step":1,"title":"Dry the shrimp","instruction":"Pat the shrimp completely dry and toss with the chilli powder, paprika, cumin, and salt. Wet shrimp steam instead of searing."},{"step":2,"title":"Make the slaw","instruction":"Toss the cabbage and red onion with half the lime juice and a good pinch of salt. Leave 10 minutes — it softens slightly and seasons through."},{"step":3,"title":"Mix the crema","instruction":"Stir the sour cream, mayonnaise, chipotle, and remaining lime juice together, loosening with a splash of water."},{"step":4,"title":"Sear fast and hot","instruction":"Cook the shrimp in the oil over high heat for 90 seconds a side, until pink and just opaque. Remove immediately.","tip":"Shrimp overcook in seconds. Pull them the moment they curl into a loose C."},{"step":5,"title":"Warm the tortillas","instruction":"Char the tortillas directly over a flame or in a dry pan for 15 seconds a side."},{"step":6,"title":"Build","instruction":"Fill with slaw, shrimp, and avocado, then drizzle with crema and top with cilantro."}]'::JSONB, 'A shrimp curled into a tight O is overcooked; a loose C is right. Frozen shrimp work well — thaw fully and dry thoroughly, since surface water prevents any browning.', ARRAY['Grilled: Skewer and grill 2 minutes a side.','Fish tacos: Cod or tilapia, cut into strips, cooked the same way.','Dairy-free: Cashew crema or mashed avocado with lime.']::TEXT[], ARRAY['Shellfish','Dairy','Egg']::TEXT[]),
('stuffed-mushrooms', 'Stuffed Mushrooms', 'Mushroom caps pre-baked to drive off water, then filled with garlic, herbs, and cream cheese.', 'https://images.unsplash.com/photo-1578413092649-e4c1c42022de', 'Baked stuffed mushrooms with cream cheese, garlic, and herbs', 'Sofia Romano', '@sofiaromanoeats', '', '', '15 min', '15 min', '30 min', 15, 15, 30, 6, 'Easy', 'Italian', 'Snack', 'Appetizer', ARRAY['Vegetarian','Party Food','Gluten-Free-Adaptable']::TEXT[], 4.7, 1882, 5987, 212, 7, 9, 17, 1, '[{"amount":"24","unit":"","item":"button or cremini mushrooms, stems removed"},{"amount":"8","unit":"oz","item":"cream cheese, softened"},{"amount":"0.5","unit":"cup","item":"grated parmesan"},{"amount":"3","unit":"cloves","item":"garlic, minced"},{"amount":"0.33","unit":"cup","item":"panko breadcrumbs"},{"amount":"2","unit":"tbsp","item":"chopped parsley"},{"amount":"1","unit":"tbsp","item":"chopped thyme"},{"amount":"2","unit":"tbsp","item":"olive oil"},{"amount":"","unit":"","item":"Salt and black pepper"}]'::JSONB, '[{"step":1,"title":"Pre-bake the caps","instruction":"Brush the caps with oil and bake hollow-side down at 400°F (205°C) for 10 minutes. Pour off the liquid that collects.","tip":"Mushrooms are mostly water. Skipping this leaves you with filling floating in a puddle."},{"step":2,"title":"Use the stems","instruction":"Finely chop the reserved stems and fry them with the garlic for 4 minutes until the moisture has cooked off."},{"step":3,"title":"Mix the filling","instruction":"Beat the cream cheese with the parmesan, cooked stems, herbs, salt, and pepper."},{"step":4,"title":"Fill and top","instruction":"Turn the caps hollow-side up, mound the filling in generously, and press panko mixed with a little oil onto the tops."},{"step":5,"title":"Bake until golden","instruction":"Bake 18 minutes at 400°F until the filling is bubbling and the crumb topping is browned."}]'::JSONB, 'Do not wash mushrooms under the tap — they absorb the water. Brush them clean with a damp cloth instead. Assembled unbaked mushrooms keep a day in the fridge.', ARRAY['Add: Crumbled sausage, crab, or chopped spinach folded into the filling.','Gluten-free: Ground almonds or GF panko for the topping.','Larger: Portobello caps make a main course; bake 25 minutes.']::TEXT[], ARRAY['Dairy','Gluten']::TEXT[]),
('banana-nice-cream', 'Banana Nice Cream', 'Frozen bananas blended alone into something indistinguishable from soft-serve. One ingredient.', 'https://images.unsplash.com/photo-1455099797519-a70bccc199c1', 'Creamy one-ingredient banana nice cream in a bowl with toppings', 'Priya Nair', '@priyanairkitchen', '', '', '5 min', '—', '5 min', 5, 0, 5, 2, 'Easy', 'Modern', 'Dessert', 'Dessert', ARRAY['Vegan','Gluten-Free','No-Cook','Healthy']::TEXT[], 4.2, 199, 890, 186, 2, 46, 1, 5, '[{"amount":"4","unit":"","item":"very ripe bananas, sliced and frozen"},{"amount":"2","unit":"tbsp","item":"milk of choice (if needed)"},{"amount":"0.5","unit":"tsp","item":"vanilla extract"},{"amount":"","unit":"","item":"Toppings: berries, nuts, chocolate, nut butter"}]'::JSONB, '[{"step":1,"title":"Freeze ripe bananas sliced","instruction":"Slice the bananas into coins before freezing — whole frozen bananas will destroy a blender and cannot be processed.","tip":"Slice before freezing. This is the step people skip and regret."},{"step":2,"title":"Use spotty bananas","instruction":"The bananas should be well speckled before freezing. Underripe ones taste starchy and need added sweetener."},{"step":3,"title":"Blend and scrape","instruction":"Blend the frozen slices in a food processor. It goes through crumbly, then gluey, then suddenly smooth and creamy after 3–4 minutes of scraping down.","tip":"It will look wrong twice before it looks right. Keep going."},{"step":4,"title":"Add liquid only if stuck","instruction":"Add milk a teaspoon at a time only if the blender genuinely cannot move. Every addition makes it icier."},{"step":5,"title":"Serve immediately or firm up","instruction":"Eat straight away for soft-serve texture, or freeze 30 minutes for something scoopable."}]'::JSONB, 'Refrozen nice cream sets rock hard — let it sit out 15 minutes before scooping. It is best made fresh, which takes five minutes anyway.', ARRAY['Chocolate: Two tablespoons of cocoa powder blended in.','Peanut butter: A heaped tablespoon, added once it turns creamy.','Berry: A cup of frozen strawberries alongside the banana.']::TEXT[], ARRAY[]::TEXT[]),
('garlic-butter-steak-bites', 'Garlic Butter Steak Bites', 'Cubed steak seared hard in a screaming pan and finished with garlic butter. Fifteen minutes.', 'https://img.rocket.new/generatedImages/rocket_gen_img_1e6d3a8b3-1778761464840.png', 'Sizzling garlic butter steak bites with herbs in a cast iron pan', 'Jake Torres', '@jaketorrescooks', 'https://images.unsplash.com/photo-1572015837827-01671d41e102', 'Portrait of food creator Jake Torres', '8 min', '7 min', '15 min', 8, 7, 15, 4, 'Easy', 'American', 'Dinner', 'Main Course', ARRAY['High Protein','Quick','Gluten-Free','Low Carb']::TEXT[], 4.6, 1467, 3221, 486, 42, 3, 34, 0, '[{"amount":"2","unit":"lb","item":"sirloin or ribeye, cut into 1-inch cubes"},{"amount":"2","unit":"tbsp","item":"neutral oil"},{"amount":"4","unit":"tbsp","item":"butter"},{"amount":"6","unit":"cloves","item":"garlic, minced"},{"amount":"1","unit":"tbsp","item":"chopped rosemary"},{"amount":"1","unit":"tbsp","item":"chopped parsley"},{"amount":"","unit":"","item":"Salt and coarse black pepper"}]'::JSONB, '[{"step":1,"title":"Dry and temper","instruction":"Pat the cubes completely dry and let them sit out 30 minutes. Cold, wet meat will not sear.","tip":"Dry surface, room temperature. Both are required for a crust."},{"step":2,"title":"Season just before cooking","instruction":"Season heavily with salt and pepper right before the pan, not earlier — salt draws moisture to the surface if it sits."},{"step":3,"title":"Get the pan smoking","instruction":"Heat the oil in a cast iron pan over high heat until it genuinely smokes."},{"step":4,"title":"Sear in batches, do not stir","instruction":"Add a single layer of cubes with space between and leave them for 90 seconds before turning. Cook in three batches.","tip":"A crowded pan drops the temperature and the beef steams grey. Three batches, every time."},{"step":5,"title":"Butter at the end","instruction":"Return all the beef to the pan, lower the heat, and add the butter, garlic, and rosemary. Toss for 60 seconds, basting, then take it off.","tip":"Garlic goes in at the end only. Added earlier it burns black in the high heat."},{"step":6,"title":"Rest briefly","instruction":"Rest 3 minutes, then finish with parsley and the pan butter poured over."}]'::JSONB, 'Total cooking time per batch is under 4 minutes for medium-rare. Have everything ready before you start; there is no pause once the pan is hot. Use a strong extractor or open a window.', ARRAY['Serve: Mashed potato, rice, or just bread for the garlic butter.','Add: Halved mushrooms seared in the same pan after the beef.','Cheaper cut: Chuck works if cut small and cooked hot and fast.']::TEXT[], ARRAY['Dairy']::TEXT[]),
('watermelon-feta-salad', 'Watermelon Feta Salad', 'Cold watermelon, salty feta, mint, and a balsamic drizzle. Assembly, not cooking.', 'https://images.unsplash.com/photo-1597653291869-90564e44078f', 'Refreshing watermelon and feta salad with mint and balsamic glaze', 'Leila Hassan', '@leilahassantable', '', '', '10 min', '—', '10 min', 10, 0, 10, 6, 'Easy', 'Greek', 'Lunch', 'Salad', ARRAY['Vegetarian','No-Cook','Summer','Gluten-Free']::TEXT[], 5.0, 1030, 4186, 186, 6, 22, 9, 1, '[{"amount":"6","unit":"cups","item":"watermelon, cubed and chilled"},{"amount":"8","unit":"oz","item":"feta, cubed or crumbled"},{"amount":"1","unit":"cup","item":"fresh mint leaves"},{"amount":"0.25","unit":"","item":"red onion, very thinly sliced"},{"amount":"3","unit":"tbsp","item":"extra virgin olive oil"},{"amount":"2","unit":"tbsp","item":"balsamic glaze"},{"amount":"1","unit":"","item":"lime, juiced"},{"amount":"","unit":"","item":"Flaky sea salt and black pepper"}]'::JSONB, '[{"step":1,"title":"Chill the watermelon hard","instruction":"The watermelon must be properly cold. Room-temperature melon tastes flat and watery against the feta."},{"step":2,"title":"Drain the cubes","instruction":"Cut the watermelon and let it drain in a colander for 10 minutes. That juice would otherwise flood the plate.","tip":"Ten minutes of draining keeps the salad from turning into a puddle."},{"step":3,"title":"Soak the onion briefly","instruction":"Cover the sliced onion with cold water for 5 minutes to take the raw edge off, then drain and pat dry."},{"step":4,"title":"Layer, do not toss","instruction":"Arrange the watermelon and feta loosely on a platter rather than mixing in a bowl — tossing crushes the melon and crumbles the cheese into dust."},{"step":5,"title":"Dress at the last moment","instruction":"Scatter the mint and onion, drizzle with oil, balsamic glaze, and lime, then finish with flaky salt and pepper. Serve straight away."}]'::JSONB, 'Feta is salty enough that this usually needs no added salt beyond a light finishing scatter. Assemble within minutes of serving; it weeps quickly.', ARRAY['Add: Cucumber, toasted pistachios, or a drizzle of hot honey.','Vegan: A plant feta, or skip the cheese and add olives for saltiness.','Basil: Works as well as mint, or use both.']::TEXT[], ARRAY['Dairy']::TEXT[]),
('chicken-shawarma', 'Chicken Shawarma', 'Thighs marinated in warm spices and yoghurt, roasted hard until the edges char, then carved into flatbread.', 'https://img.rocket.new/generatedImages/rocket_gen_img_1444be92e-1767548001932.png', 'Spiced chicken shawarma wrap with garlic sauce and pickled vegetables', 'Leila Hassan', '@leilahassantable', '', '', '20 min', '10 min', '30 min', 20, 10, 30, 6, 'Medium', 'Middle Eastern', 'Dinner', 'Main Course', ARRAY['Street Food','Make-Ahead','High Protein','Family']::TEXT[], 4.5, 607, 8584, 612, 42, 48, 28, 5, '[{"amount":"2.5","unit":"lb","item":"boneless chicken thighs"},{"amount":"0.75","unit":"cup","item":"plain yoghurt"},{"amount":"4","unit":"tbsp","item":"olive oil"},{"amount":"2","unit":"tbsp","item":"lemon juice"},{"amount":"2","unit":"tsp","item":"ground cumin"},{"amount":"2","unit":"tsp","item":"ground coriander"},{"amount":"2","unit":"tsp","item":"smoked paprika"},{"amount":"1","unit":"tsp","item":"turmeric"},{"amount":"1","unit":"tsp","item":"cinnamon"},{"amount":"0.5","unit":"tsp","item":"cayenne"},{"amount":"6","unit":"cloves","item":"garlic, minced"},{"amount":"","unit":"","item":"Salt and black pepper"},{"amount":"6","unit":"","item":"flatbreads"},{"amount":"0.5","unit":"cup","item":"tahini sauce"},{"amount":"","unit":"","item":"Tomato, cucumber, pickles, and parsley"}]'::JSONB, '[{"step":1,"title":"Marinate overnight","instruction":"Combine the yoghurt, oil, lemon juice, all the spices, and garlic. Coat the thighs and refrigerate at least 4 hours, ideally overnight.","tip":"The yoghurt acid tenderises and the spices need time. Overnight makes a visible difference."},{"step":2,"title":"Use thighs, not breast","instruction":"Thighs have the fat to survive high-heat roasting. Breast dries out long before the edges char."},{"step":3,"title":"Stack for roasting","instruction":"Pile the marinated thighs tightly on top of each other on a tray, or press them into a loaf tin, to mimic a vertical spit. This keeps the interior moist while the outside chars."},{"step":4,"title":"Roast hot","instruction":"Roast at 425°F (220°C) for 35–40 minutes until the top is blackened in patches and the internal temperature reaches 175°F."},{"step":5,"title":"Rest and slice thin","instruction":"Rest 10 minutes, then slice thinly across the stack so every slice has some charred edge."},{"step":6,"title":"Crisp the slices","instruction":"Toss the slices in a hot dry pan for 2 minutes to crisp the edges further, then pile into flatbreads with tahini, salad, and pickles.","tip":"This final crisping is what makes it taste like it came off a real spit."}]'::JSONB, 'The marinade keeps 3 days and the cooked chicken keeps 4, reheating well in a pan. Freeze the raw marinated thighs for up to 3 months and roast from thawed.', ARRAY['Grill: Skewer and grill 5 minutes a side over high heat.','Gluten-free: Serve as a bowl over rice with salad instead of flatbread.','Dairy-free: Skip the yoghurt and use extra oil and lemon.']::TEXT[], ARRAY['Dairy','Gluten','Sesame']::TEXT[]),
('lobster-roll', 'Lobster Roll', 'Cold lobster barely dressed in lemon mayo, piled into a split-top bun toasted in butter on both sides.', 'https://img.rocket.new/generatedImages/rocket_gen_img_1dce2cdca-1779265932053.png', 'Classic New England lobster roll with mayo and celery on a toasted bun', 'Maria Chen', '@mariachencooks', 'https://images.unsplash.com/photo-1677229888051-211da3f34219', 'Portrait of food creator Maria Chen', '20 min', '—', '20 min', 20, 0, 20, 4, 'Medium', 'American', 'Lunch', 'Main Course', ARRAY['Seafood','Classic','Summer','Special Occasion']::TEXT[], 5.0, 304, 2620, 512, 32, 34, 26, 2, '[{"amount":"1.5","unit":"lb","item":"cooked lobster meat, chilled and chunked"},{"amount":"4","unit":"tbsp","item":"mayonnaise"},{"amount":"1","unit":"tbsp","item":"lemon juice"},{"amount":"1","unit":"stalk","item":"celery, very finely diced"},{"amount":"2","unit":"tbsp","item":"chopped chives"},{"amount":"","unit":"","item":"Pinch of cayenne"},{"amount":"4","unit":"","item":"split-top brioche buns"},{"amount":"4","unit":"tbsp","item":"butter, softened"},{"amount":"","unit":"","item":"Flaky salt and black pepper"},{"amount":"","unit":"","item":"Lemon wedges"}]'::JSONB, '[{"step":1,"title":"Keep the chunks large","instruction":"Cut the lobster into large bite-sized pieces, keeping the claw meat as whole as possible. Shredded lobster loses the texture you paid for."},{"step":2,"title":"Dress lightly","instruction":"Fold the lobster with just enough mayonnaise to coat, plus the lemon juice, celery, chives, cayenne, salt, and pepper. It should look barely dressed.","tip":"Under-dress it. The lobster is the point, not the mayonnaise."},{"step":3,"title":"Chill the filling","instruction":"Refrigerate 20 minutes so the flavours settle and the filling firms up."},{"step":4,"title":"Butter the sides of the bun","instruction":"Spread softened butter on the flat outer sides of each split-top bun and toast in a dry pan for 2 minutes a side until deep golden and crisp.","tip":"Toasting the flat sides is what a split-top bun is for. This is the whole reason the roll works."},{"step":5,"title":"Fill and serve","instruction":"Pile the filling into the warm buns, add flaky salt and more chives, and serve with lemon wedges."}]'::JSONB, 'This is the Maine style, served cold with mayonnaise; the Connecticut style is warm lobster in melted butter with no mayonnaise at all, and is equally good. If buying live lobster, steam 8 minutes per pound and chill fully before picking.', ARRAY['Cheaper: Langoustine, crab, or good shrimp make an excellent roll on the same method.','No split-top buns: Trim the crusts off thick white bread rolls to make flat sides.','Make-ahead: The filling keeps a day; toast the buns to order.']::TEXT[], ARRAY['Shellfish','Egg','Gluten','Dairy','Celery']::TEXT[]),
('butter-chicken', 'Butter Chicken', 'Marinated chicken in a tomato and cashew gravy finished with butter and cream — milder and richer than tikka masala.', 'https://img.rocket.new/generatedImages/rocket_gen_img_18c6478cb-1772187609323.png', 'Creamy butter chicken curry with tender chicken pieces and aromatic spices', 'Aisha Sharma', '@aishasharmaspice', '', '', '25 min', '25 min', '50 min', 25, 25, 50, 6, 'Medium', 'Indian', 'Dinner', 'Main Course', ARRAY['Curry','Comfort','Crowd Pleaser','Gluten-Free']::TEXT[], 4.9, 968, 1505, 648, 42, 22, 44, 3, '[{"amount":"2","unit":"lb","item":"boneless chicken thighs, chunked"},{"amount":"1","unit":"cup","item":"plain yoghurt"},{"amount":"2","unit":"tbsp","item":"lemon juice"},{"amount":"2","unit":"tbsp","item":"garam masala"},{"amount":"1","unit":"tbsp","item":"ground cumin"},{"amount":"1","unit":"tsp","item":"turmeric"},{"amount":"1","unit":"tsp","item":"Kashmiri chilli powder"},{"amount":"6","unit":"cloves","item":"garlic, minced"},{"amount":"2","unit":"inch","item":"ginger, grated"},{"amount":"6","unit":"tbsp","item":"butter"},{"amount":"1","unit":"","item":"onion, diced"},{"amount":"28","unit":"oz","item":"crushed tomatoes"},{"amount":"0.5","unit":"cup","item":"raw cashews"},{"amount":"1","unit":"cup","item":"heavy cream"},{"amount":"1","unit":"tbsp","item":"honey"},{"amount":"1","unit":"tsp","item":"dried fenugreek leaves"},{"amount":"","unit":"","item":"Salt"}]'::JSONB, '[{"step":1,"title":"Marinate","instruction":"Mix the yoghurt, lemon juice, half the spices, and half the garlic and ginger. Coat the chicken and refrigerate at least 4 hours."},{"step":2,"title":"Char the chicken","instruction":"Grill the chicken on a tray under a hot broiler for 12 minutes until blackened at the edges. Keep every drop of juice from the tray.","tip":"The char is what gives butter chicken its smoky backbone. Pale chicken makes a flat curry."},{"step":3,"title":"Soak the cashews","instruction":"Soak the cashews in boiling water for 15 minutes. They blend into the gravy and are what makes it velvety without flour."},{"step":4,"title":"Build the gravy","instruction":"Melt 4 tbsp butter, cook the onion 8 minutes, add the remaining garlic, ginger, and spices for 1 minute, then the tomatoes. Simmer 20 minutes until darkened."},{"step":5,"title":"Blend completely smooth","instruction":"Add the drained cashews and blend the sauce until silky — a full 2 minutes. Butter chicken should have no texture at all.","tip":"This is what separates butter chicken from tikka masala. Blend it further than feels necessary."},{"step":6,"title":"Finish rich","instruction":"Return to the pan with the chicken and its juices, simmer 10 minutes, then stir in the cream, remaining butter, honey, and crushed fenugreek off the boil."}]'::JSONB, 'Dried fenugreek leaves (kasoori methi) are what make this taste like a restaurant version — crush them between your palms as you add them. Kashmiri chilli gives colour without much heat.', ARRAY['Dairy-free: Coconut milk and oil in place of cream and butter.','Vegetarian: Paneer or roasted cauliflower, added at the final simmer.','Make-ahead: The gravy freezes for 3 months; add fresh cream on reheating.']::TEXT[], ARRAY['Dairy','Tree Nut']::TEXT[]),
('banana-pancakes', 'Banana Pancakes', 'Mashed banana folded into the batter for pancakes that are sweet enough to need very little syrup.', 'https://img.rocket.new/generatedImages/rocket_gen_img_1785648c2-1770310514851.png', 'Golden banana pancakes stacked with maple syrup and sliced bananas', 'Priya Nair', '@priyanairkitchen', '', '', '8 min', '7 min', '15 min', 8, 7, 15, 4, 'Easy', 'American', 'Breakfast', 'Breakfast', ARRAY['Vegetarian','Family','Quick','Kid Friendly']::TEXT[], 5.0, 1784, 7968, 386, 10, 58, 13, 3, '[{"amount":"1.5","unit":"cups","item":"all-purpose flour"},{"amount":"2","unit":"tsp","item":"baking powder"},{"amount":"2","unit":"tbsp","item":"sugar"},{"amount":"0.5","unit":"tsp","item":"salt"},{"amount":"0.5","unit":"tsp","item":"cinnamon"},{"amount":"2","unit":"","item":"very ripe bananas, mashed"},{"amount":"1.25","unit":"cups","item":"milk"},{"amount":"1","unit":"","item":"egg"},{"amount":"3","unit":"tbsp","item":"melted butter"},{"amount":"1","unit":"tsp","item":"vanilla extract"},{"amount":"","unit":"","item":"Butter for the pan"}]'::JSONB, '[{"step":1,"title":"Mash the banana properly","instruction":"Mash the bananas until almost smooth. Large lumps stay raw and gummy in the middle of the pancake."},{"step":2,"title":"Combine wet and dry separately","instruction":"Whisk the dry ingredients in one bowl and the banana, milk, egg, melted butter, and vanilla in another."},{"step":3,"title":"Mix minimally","instruction":"Fold together until just combined — lumpy batter is correct. Overmixing gives tough, flat pancakes."},{"step":4,"title":"Rest 10 minutes","instruction":"Let the batter sit so the flour hydrates and the baking powder activates."},{"step":5,"title":"Cook lower than usual","instruction":"Cook on medium-low in a buttered pan, 3 minutes a side. The banana sugars brown faster than plain batter, so a lower heat is needed.","tip":"Banana pancakes burn more easily than plain ones. Turn the heat down a notch."}]'::JSONB, 'The riper the bananas the sweeter the pancakes and the less sugar they need. These are slightly denser than buttermilk pancakes because of the fruit, which is normal.', ARRAY['Two-ingredient version: Just banana and egg, blended — thin, eggy, but gluten-free and fast.','Add: Walnuts, chocolate chips, or blueberries scattered onto the wet side.','Freeze: Cooked pancakes freeze well; reheat in a toaster.']::TEXT[], ARRAY['Gluten','Dairy','Egg']::TEXT[]),
('smoked-salmon-bagel', 'Smoked Salmon Bagel', 'A properly toasted bagel, seasoned cream cheese, and cold-smoked salmon with all the trimmings.', 'https://images.unsplash.com/photo-1680602573288-5a8fa0ed397d', 'Everything bagel with cream cheese, smoked salmon, capers, and red onion', 'Maria Chen', '@mariachencooks', 'https://images.unsplash.com/photo-1677229888051-211da3f34219', 'Portrait of food creator Maria Chen', '10 min', '—', '10 min', 10, 0, 10, 2, 'Easy', 'American', 'Breakfast', 'Breakfast', ARRAY['Seafood','No-Cook','Brunch','Quick']::TEXT[], 4.7, 817, 6507, 512, 28, 48, 22, 2, '[{"amount":"2","unit":"","item":"everything bagels, split"},{"amount":"6","unit":"oz","item":"cold-smoked salmon"},{"amount":"5","unit":"oz","item":"cream cheese"},{"amount":"1","unit":"tbsp","item":"lemon juice"},{"amount":"2","unit":"tbsp","item":"chopped dill"},{"amount":"0.25","unit":"","item":"red onion, very thinly sliced"},{"amount":"1","unit":"tbsp","item":"capers"},{"amount":"4","unit":"slices","item":"tomato"},{"amount":"","unit":"","item":"Black pepper and lemon wedges"}]'::JSONB, '[{"step":1,"title":"Toast cut-side down","instruction":"Toast the bagel halves until the cut faces are properly golden and crisp. A warm but untoasted bagel goes soggy under the cream cheese."},{"step":2,"title":"Season the cream cheese","instruction":"Beat the cream cheese with the lemon juice, half the dill, and plenty of black pepper.","tip":"Straight-from-the-tub cream cheese tastes flat here. The lemon and dill do most of the work."},{"step":3,"title":"Spread thickly","instruction":"Spread generously right to the edges while the bagel is still warm."},{"step":4,"title":"Layer in order","instruction":"Tomato first, then the salmon in loose folds, then the onion and capers. Tomato underneath keeps the salmon from sliding."},{"step":5,"title":"Finish","instruction":"Top with the remaining dill, cracked pepper, and a squeeze of lemon."}]'::JSONB, 'Let the salmon sit out for 10 minutes before assembling; fridge-cold smoked salmon is firm and muted. Cold-smoked (silky, translucent) is what this needs — hot-smoked flakes apart and behaves differently.', ARRAY['Add: A soft-boiled egg or sliced avocado.','Dairy-free: Whipped avocado or plant cream cheese.','Open-faced: Serve as two halves rather than a sandwich, which is easier to eat.']::TEXT[], ARRAY['Fish','Gluten','Dairy']::TEXT[]),
('greek-yogurt-parfait', 'Greek Yogurt Parfait', 'Thick yoghurt layered with fruit and granola, assembled so the granola stays crunchy.', 'https://images.unsplash.com/photo-1691455653742-ea1aded33376', 'Layered Greek yogurt parfait with granola, fresh berries, and honey in a glass', 'Sofia Patel', '@sofiapatelkitchen', 'https://images.unsplash.com/photo-1716947674021-1b8b696325c7', 'Portrait of food creator Sofia Patel', '5 min', '—', '5 min', 5, 0, 5, 2, 'Easy', 'Greek', 'Breakfast', 'Breakfast', ARRAY['High Protein','No-Cook','Quick','Healthy']::TEXT[], 4.5, 1710, 6885, 368, 22, 46, 11, 5, '[{"amount":"2","unit":"cups","item":"thick Greek yoghurt"},{"amount":"2","unit":"tbsp","item":"honey"},{"amount":"0.5","unit":"tsp","item":"vanilla extract"},{"amount":"1","unit":"cup","item":"mixed berries"},{"amount":"0.75","unit":"cup","item":"granola"},{"amount":"2","unit":"tbsp","item":"chopped nuts"},{"amount":"1","unit":"tsp","item":"chia seeds"},{"amount":"","unit":"","item":"Mint to garnish"}]'::JSONB, '[{"step":1,"title":"Use full-fat strained yoghurt","instruction":"Thick Greek yoghurt holds distinct layers. Thin or low-fat yoghurt bleeds into the fruit and turns the whole thing to slush."},{"step":2,"title":"Sweeten the yoghurt itself","instruction":"Stir the honey and vanilla through the yoghurt rather than drizzling on top, so every spoonful is seasoned."},{"step":3,"title":"Layer in a clear glass","instruction":"Alternate yoghurt, berries, and granola in a tall glass, starting and finishing with yoghurt."},{"step":4,"title":"Keep granola out of the middle if making ahead","instruction":"If assembling more than 20 minutes early, keep all the granola on top or in a separate pot. Buried granola goes soft fast.","tip":"This is the only real trick. Granola in contact with yoghurt is soggy within half an hour."},{"step":5,"title":"Finish","instruction":"Top with the nuts, chia seeds, and mint."}]'::JSONB, 'Frozen berries work and release a little syrup as they thaw, which is quite good here. Assemble the yoghurt and fruit layers the night before and add granola in the morning.', ARRAY['Vegan: Coconut or soy yoghurt, thick varieties only, with maple syrup.','Higher protein: Skyr or a scoop of protein powder stirred into the yoghurt.','Savoury swap: Not this one. Some things should stay sweet.']::TEXT[], ARRAY['Dairy','Gluten','Tree Nut']::TEXT[]),
('breakfast-hash', 'Breakfast Hash', 'Potatoes par-boiled then fried hard with sausage and peppers, with eggs cracked in at the end.', 'https://images.unsplash.com/photo-1729450411363-ba702747e240', 'Crispy potato breakfast hash with peppers, onions, and fried eggs on top', 'Jake Torres', '@jaketorrescooks', 'https://images.unsplash.com/photo-1572015837827-01671d41e102', 'Portrait of food creator Jake Torres', '10 min', '15 min', '25 min', 10, 15, 25, 4, 'Easy', 'American', 'Breakfast', 'Breakfast', ARRAY['One-Pan','Hearty','Family','Gluten-Free']::TEXT[], 4.7, 1883, 8194, 532, 24, 42, 30, 5, '[{"amount":"2","unit":"lb","item":"potatoes, diced"},{"amount":"12","unit":"oz","item":"breakfast sausage"},{"amount":"1","unit":"","item":"onion, diced"},{"amount":"1","unit":"","item":"red pepper, diced"},{"amount":"3","unit":"tbsp","item":"neutral oil"},{"amount":"1","unit":"tsp","item":"smoked paprika"},{"amount":"4","unit":"large","item":"eggs"},{"amount":"2","unit":"","item":"scallions, sliced"},{"amount":"","unit":"","item":"Salt, pepper, and hot sauce"}]'::JSONB, '[{"step":1,"title":"Par-boil the potatoes","instruction":"Boil the diced potatoes for 6 minutes until just tender at the edges, then drain and steam-dry in the colander for 5 minutes.","tip":"Par-boiling then drying is what gives crisp outsides and fluffy centres. Raw potato in the pan takes forever and burns."},{"step":2,"title":"Brown the sausage","instruction":"Cook the sausage in the oil, breaking it up, until browned. Remove, leaving the fat."},{"step":3,"title":"Fry the potatoes undisturbed","instruction":"Add the potatoes in one layer and leave them completely alone for 6 minutes before turning. Repeat twice.","tip":"Every time you stir, you interrupt the crust. Leave them alone."},{"step":4,"title":"Add vegetables","instruction":"Add the onion, pepper, and paprika and cook 5 minutes, then return the sausage."},{"step":5,"title":"Crack in the eggs","instruction":"Make four wells, crack an egg into each, cover, and cook 4 minutes until the whites set and the yolks still run. Top with scallions."}]'::JSONB, 'A wide, heavy pan matters more than anything else here — a crowded pan steams the potatoes instead of frying them. Use two pans if cooking for more than four.', ARRAY['Vegetarian: Halloumi or black beans in place of the sausage.','Sweet potato: Works well; par-boil for 4 minutes only.','Leftovers: Any roast vegetables can go in.']::TEXT[], ARRAY['Egg']::TEXT[]),
('crepes', 'Crepes', 'A thin batter rested for an hour, cooked in a barely greased pan, sweet or savoury.', 'https://images.unsplash.com/photo-1731185168371-d7da504f3df2', 'Thin golden crepes folded with strawberries and whipped cream on a white plate', 'Sofia Romano', '@sofiaromanoeats', '', '', '10 min', '20 min', '30 min', 10, 20, 30, 4, 'Medium', 'French', 'Breakfast', 'Breakfast', ARRAY['Classic','Vegetarian','Brunch','Make-Ahead']::TEXT[], 5.0, 591, 858, 286, 9, 34, 12, 1, '[{"amount":"1","unit":"cup","item":"all-purpose flour"},{"amount":"2","unit":"large","item":"eggs"},{"amount":"1.25","unit":"cups","item":"whole milk"},{"amount":"3","unit":"tbsp","item":"melted butter"},{"amount":"1","unit":"tbsp","item":"sugar"},{"amount":"","unit":"","item":"Pinch of salt"},{"amount":"","unit":"","item":"Butter for the pan"},{"amount":"","unit":"","item":"Lemon, sugar, jam, or Nutella to serve"}]'::JSONB, '[{"step":1,"title":"Blend the batter smooth","instruction":"Blend all the batter ingredients for 30 seconds until completely smooth and the consistency of single cream."},{"step":2,"title":"Rest one hour","instruction":"Rest the batter in the fridge for at least an hour. This lets the gluten relax and the bubbles subside, giving tender crepes rather than rubbery ones.","tip":"The rest is the difference between crepes and thin rubbery pancakes. An hour minimum."},{"step":3,"title":"Barely grease the pan","instruction":"Heat a non-stick pan over medium and wipe with a butter-soaked piece of kitchen paper. Too much butter makes the crepe fry and go lacy."},{"step":4,"title":"Pour and swirl fast","instruction":"Pour a scant quarter cup into the centre and immediately tilt and swirl the pan so the batter runs to the edges in a thin, even layer."},{"step":5,"title":"Cook briefly","instruction":"Cook 45 seconds until the edges lift and the underside is golden in patches, then flip and cook 20 seconds more.","tip":"The first crepe always fails. That is normal — it is calibrating the pan."},{"step":6,"title":"Stack and serve","instruction":"Stack on a plate as you go; they steam each other soft. Serve with lemon and sugar, or fill as you like."}]'::JSONB, 'The batter keeps 2 days in the fridge and is arguably better on day two. Cooked crepes stack and refrigerate for 3 days, or freeze with parchment between them.', ARRAY['Savoury: Omit the sugar and fill with ham, cheese, and egg.','Gluten-free: Buckwheat flour makes traditional galettes.','Dairy-free: Any plant milk and oil in place of the butter.']::TEXT[], ARRAY['Gluten','Dairy','Egg']::TEXT[]),
('granola-from-scratch', 'Granola from Scratch', 'Oats baked low with maple and oil, pressed flat and left undisturbed so it sets in big clusters.', 'https://images.unsplash.com/photo-1498560966227-924b32ce2feb', 'Crunchy homemade granola with oats, nuts, seeds, and dried fruit on a baking sheet', 'Emma Walsh', '@emmawalshbakes', '', '', '10 min', '25 min', '35 min', 10, 25, 35, 12, 'Easy', 'Modern', 'Breakfast', 'Breakfast', ARRAY['Vegan-Adaptable','Meal Prep','Make-Ahead','Budget']::TEXT[], 4.8, 1000, 7133, 312, 7, 38, 15, 5, '[{"amount":"4","unit":"cups","item":"rolled oats"},{"amount":"1.5","unit":"cups","item":"mixed nuts, roughly chopped"},{"amount":"0.5","unit":"cup","item":"pumpkin seeds"},{"amount":"0.5","unit":"cup","item":"maple syrup"},{"amount":"0.33","unit":"cup","item":"neutral or coconut oil"},{"amount":"1","unit":"tsp","item":"vanilla extract"},{"amount":"1","unit":"tsp","item":"ground cinnamon"},{"amount":"0.5","unit":"tsp","item":"salt"},{"amount":"1","unit":"","item":"egg white (for clusters)"},{"amount":"1","unit":"cup","item":"dried fruit"}]'::JSONB, '[{"step":1,"title":"Mix thoroughly","instruction":"Toss the oats, nuts, seeds, cinnamon, and salt together, then pour over the maple syrup, oil, and vanilla and mix until every oat looks glossy."},{"step":2,"title":"Add the egg white for clusters","instruction":"Whisk the egg white to a loose foam and fold it through. It acts as a binder and is the reliable way to get big clusters.","tip":"This is the trick. Without a binder, granola stays loose and sandy."},{"step":3,"title":"Press it flat","instruction":"Tip onto a lined tray and press down firmly with a spatula into a compact, even slab."},{"step":4,"title":"Bake low and slow","instruction":"Bake at 300°F (150°C) for 35–40 minutes. Rotate the tray once but do not stir.","tip":"Stirring breaks the clusters apart. Resist it entirely."},{"step":5,"title":"Cool completely undisturbed","instruction":"Leave it on the tray until fully cool — it crisps as it cools and only then can be broken into chunks. Fold in the dried fruit afterwards."}]'::JSONB, 'Granola is soft straight out of the oven and hardens on cooling, so do not be tempted to bake it longer. Dried fruit added before baking turns to leather; add it at the end. Keeps a month airtight.', ARRAY['Vegan: Skip the egg white and use 2 tablespoons of aquafaba, or accept looser granola.','Nut-free: Double the seeds — sunflower, pumpkin, and sesame.','Lower sugar: Cut the maple to a third of a cup; clusters will be smaller.']::TEXT[], ARRAY['Tree Nut']::TEXT[]),
('breakfast-quesadilla', 'Breakfast Quesadilla', 'Scrambled eggs, cheese, and bacon folded into a tortilla and crisped in a dry pan.', 'https://img.rocket.new/generatedImages/rocket_gen_img_10b8ab986-1777253207789.png', 'Crispy breakfast quesadilla filled with scrambled eggs, cheese, and salsa', 'Carlos Mendez', '@carlosmendezcooks', '', '', '5 min', '10 min', '15 min', 5, 10, 15, 2, 'Easy', 'Mexican', 'Breakfast', 'Breakfast', ARRAY['Quick','Family','Kid Friendly']::TEXT[], 5.0, 94, 4681, 512, 26, 34, 30, 3, '[{"amount":"2","unit":"","item":"large flour tortillas"},{"amount":"4","unit":"large","item":"eggs"},{"amount":"2","unit":"tbsp","item":"butter"},{"amount":"1.5","unit":"cups","item":"grated cheddar"},{"amount":"4","unit":"slices","item":"bacon, cooked and chopped"},{"amount":"2","unit":"","item":"scallions, sliced"},{"amount":"","unit":"","item":"Salt and pepper"},{"amount":"","unit":"","item":"Salsa and sour cream to serve"}]'::JSONB, '[{"step":1,"title":"Scramble soft and underdone","instruction":"Melt the butter over low heat and stir the beaten eggs constantly, pulling the pan off the heat periodically. Stop while they still look wet — they finish cooking inside the quesadilla.","tip":"Fully cooked eggs go rubbery once the quesadilla cooks. Take them off early."},{"step":2,"title":"Cheese against the tortilla","instruction":"Scatter cheese onto one half of each tortilla, then the eggs, bacon, and scallions, then more cheese before folding."},{"step":3,"title":"Dry pan, medium heat","instruction":"Cook in a dry pan — no oil — for 3 minutes a side, pressing gently, until blistered and the cheese has melted."},{"step":4,"title":"Rest before cutting","instruction":"Rest 1 minute so the cheese sets, then cut into wedges and serve with salsa and sour cream."}]'::JSONB, 'The cheese layers on both sides are structural, not just flavour — they glue the tortilla shut. Grate your own for a smoother melt.', ARRAY['Vegetarian: Black beans and sautéed peppers in place of bacon.','Meal prep: Assemble and refrigerate overnight; cook from cold.','Air fryer: 380°F for 6 minutes, flipping once.']::TEXT[], ARRAY['Egg','Dairy','Gluten']::TEXT[]),
('waffles', 'Waffles', 'A batter with whipped whites folded in, cooked in a hot iron until the steam stops. Crisp outside, light inside.', 'https://images.unsplash.com/photo-1504511483610-0de49de55733', 'Crispy golden waffles with fresh berries, whipped cream, and maple syrup', 'Emma Walsh', '@emmawalshbakes', '', '', '10 min', '15 min', '25 min', 10, 15, 25, 4, 'Easy', 'American', 'Breakfast', 'Breakfast', ARRAY['Brunch','Family','Vegetarian','Freezer-Friendly']::TEXT[], 4.7, 1464, 5697, 428, 11, 52, 19, 2, '[{"amount":"2","unit":"cups","item":"all-purpose flour"},{"amount":"2","unit":"tbsp","item":"sugar"},{"amount":"1","unit":"tbsp","item":"baking powder"},{"amount":"0.5","unit":"tsp","item":"salt"},{"amount":"2","unit":"large","item":"eggs, separated"},{"amount":"1.75","unit":"cups","item":"buttermilk"},{"amount":"0.5","unit":"cup","item":"melted butter"},{"amount":"1","unit":"tsp","item":"vanilla extract"},{"amount":"","unit":"","item":"Maple syrup and butter to serve"}]'::JSONB, '[{"step":1,"title":"Separate the eggs","instruction":"Whisk the yolks with the buttermilk, melted butter, and vanilla. Keep the whites in a clean, dry bowl."},{"step":2,"title":"Whip the whites","instruction":"Beat the whites to soft peaks. This is what gives waffles their lightness — a straight-mixed batter comes out dense.","tip":"Whipping the whites separately is the single upgrade that makes home waffles good."},{"step":3,"title":"Combine, then fold","instruction":"Mix the wet into the dry until just combined, then fold in the whipped whites in two additions, keeping as much air as possible."},{"step":4,"title":"Heat the iron fully","instruction":"Preheat the waffle iron completely. Pouring onto a lukewarm iron gives pale, soft waffles that stick."},{"step":5,"title":"Cook until the steam stops","instruction":"Pour, close, and cook without opening. When the steam escaping from the sides slows to almost nothing, the waffle is done — usually 4–5 minutes.","tip":"Steam is the timer. Opening early tears the waffle in half."},{"step":6,"title":"Hold on a rack","instruction":"Keep cooked waffles on a rack in a 200°F oven, never stacked on a plate, or they steam themselves soggy."}]'::JSONB, 'Waffles freeze extremely well — cool completely, freeze flat, then reheat straight from frozen in a toaster. They come out as good as fresh.', ARRAY['Extra crisp: Replace a quarter cup of the flour with cornstarch.','Savoury: Skip the sugar, add cheddar and chives, top with fried chicken.','Dairy-free: Plant milk with a tablespoon of lemon juice, and oil for butter.']::TEXT[], ARRAY['Gluten','Dairy','Egg']::TEXT[]),
('egg-white-omelette', 'Egg White Omelette', 'Whites cooked low and slow with vegetables, seasoned properly so it does not taste of nothing.', 'https://img.rocket.new/generatedImages/rocket_gen_img_1c0d2fe9b-1772308581512.png', 'Fluffy egg white omelette with spinach, mushrooms, and feta cheese', 'Sofia Patel', '@sofiapatelkitchen', 'https://images.unsplash.com/photo-1716947674021-1b8b696325c7', 'Portrait of food creator Sofia Patel', '5 min', '5 min', '10 min', 5, 5, 10, 1, 'Easy', 'Modern', 'Breakfast', 'Breakfast', ARRAY['High Protein','Low Fat','Gluten-Free','Quick']::TEXT[], 4.8, 1820, 6636, 186, 24, 8, 6, 2, '[{"amount":"5","unit":"","item":"egg whites"},{"amount":"1","unit":"tsp","item":"olive oil"},{"amount":"1","unit":"handful","item":"spinach"},{"amount":"0.25","unit":"cup","item":"cherry tomatoes, halved"},{"amount":"2","unit":"tbsp","item":"crumbled feta"},{"amount":"1","unit":"","item":"scallion, sliced"},{"amount":"0.25","unit":"tsp","item":"garlic powder"},{"amount":"","unit":"","item":"Salt, black pepper, and chives"}]'::JSONB, '[{"step":1,"title":"Season more than feels right","instruction":"Egg whites are bland on their own. Salt, pepper, and garlic powder are doing real work here, so be generous.","tip":"Under-seasoning is why egg white omelettes have a reputation for tasting of nothing."},{"step":2,"title":"Cook the vegetables first","instruction":"Wilt the spinach and soften the tomatoes in the oil for 2 minutes, then set aside. Raw vegetables release water into the whites."},{"step":3,"title":"Whisk until frothy","instruction":"Whisk the whites hard for 30 seconds until light and foamy. The air makes for a more tender omelette."},{"step":4,"title":"Low heat only","instruction":"Pour into the pan over low heat and cook slowly, drawing the set edges in and tilting to let liquid run underneath.","tip":"High heat turns whites rubbery almost instantly. Low and patient."},{"step":5,"title":"Fill and fold","instruction":"When the top is just set, add the vegetables and feta to one half, fold over, and slide out. Top with chives."}]'::JSONB, 'Whites set at a lower temperature than yolks, which is exactly why the heat has to stay low. Adding one whole egg to the whites improves flavour and texture considerably if you are willing.', ARRAY['Dairy-free: Skip the feta and add avocado after folding.','Meal prep: Bake the same mixture in muffin tins for 20 minutes at 350°F.','Boost: A tablespoon of cottage cheese whisked into the whites adds creaminess.']::TEXT[], ARRAY['Egg','Dairy']::TEXT[]),
('chia-seed-pudding', 'Chia Seed Pudding', 'Chia soaked in milk overnight with a second whisk to break the clumps. Five minutes of work.', 'https://images.unsplash.com/photo-1629180050285-7c56c6671f19', 'Thick chia seed pudding with coconut milk and fresh mango topping', 'Aisha Sharma', '@aishasharmaspice', '', '', '5 min', '—', '5 min', 5, 0, 5, 2, 'Easy', 'Modern', 'Breakfast', 'Breakfast', ARRAY['Vegan-Adaptable','Gluten-Free','Make-Ahead','High Fibre']::TEXT[], 4.5, 1396, 3987, 286, 9, 32, 15, 13, '[{"amount":"0.33","unit":"cup","item":"chia seeds"},{"amount":"1.25","unit":"cups","item":"milk of choice"},{"amount":"2","unit":"tbsp","item":"maple syrup"},{"amount":"0.5","unit":"tsp","item":"vanilla extract"},{"amount":"","unit":"","item":"Pinch of salt"},{"amount":"","unit":"","item":"Fresh fruit, nuts, and nut butter to top"}]'::JSONB, '[{"step":1,"title":"Get the ratio right","instruction":"Roughly one part chia to four parts liquid by volume. More chia sets it stiff; less leaves it runny."},{"step":2,"title":"Whisk once","instruction":"Whisk the chia, milk, maple syrup, vanilla, and salt together thoroughly."},{"step":3,"title":"Whisk again after 10 minutes","instruction":"Wait 10 minutes, then whisk hard a second time. Chia clumps immediately on contact with liquid and this second whisk is what gives an even set.","tip":"The second whisk is the whole recipe. Skip it and you get a lumpy layer with liquid on top."},{"step":4,"title":"Chill at least 4 hours","instruction":"Refrigerate 4 hours or overnight until thick enough to hold a spoon."},{"step":5,"title":"Top and serve","instruction":"Loosen with a splash of milk if too thick, then add fruit, nuts, and nut butter."}]'::JSONB, 'Keeps 5 days refrigerated and the texture improves on day two. If it sets stiffer than you like, stir in milk rather than starting over.', ARRAY['Chocolate: Two tablespoons of cocoa powder whisked in at the start.','Vegan: Any plant milk; coconut milk gives the richest result.','Meal prep: Make four jars at once for the week.']::TEXT[], ARRAY['Dairy']::TEXT[])
