INSERT INTO public.recipes (slug, title, description, image, image_alt, creator_name, creator_handle, creator_image, creator_alt, prep_time, cook_time, total_time, prep_minutes, cook_minutes, total_minutes, servings, difficulty, cuisine, meal_type, category, tags, rating, reviews, cooks, calories, protein, carbs, fat, fiber, ingredients, steps, notes, tips, allergens) VALUES
('breakfast-sandwich', 'Breakfast Sandwich', 'A folded egg, melted cheese, and crisp bacon on a toasted muffin. Better than the drive-through version.', 'https://images.unsplash.com/photo-1715571105432-83466f853994', 'Toasted English muffin breakfast sandwich with egg, cheese, and bacon', 'Jake Torres', '@jaketorrescooks', 'https://images.unsplash.com/photo-1572015837827-01671d41e102', 'Portrait of food creator Jake Torres', '5 min', '10 min', '15 min', 5, 10, 15, 2, 'Easy', 'American', 'Breakfast', 'Breakfast', ARRAY['Quick','High Protein','Meal Prep']::TEXT[], 4.6, 69, 3858, 482, 24, 32, 28, 2, '[{"amount":"2","unit":"","item":"English muffins, split"},{"amount":"4","unit":"large","item":"eggs"},{"amount":"4","unit":"slices","item":"American or cheddar cheese"},{"amount":"4","unit":"slices","item":"bacon"},{"amount":"2","unit":"tbsp","item":"butter"},{"amount":"","unit":"","item":"Salt, pepper, and hot sauce"}]'::JSONB, '[{"step":1,"title":"Crisp the bacon first","instruction":"Cook the bacon until crisp and set aside, leaving the fat in the pan."},{"step":2,"title":"Toast the muffins in the fat","instruction":"Toast the split muffins cut-side down in the bacon fat for 2 minutes until golden. This is a significant upgrade over a toaster.","tip":"Toasting in bacon fat costs nothing and makes the sandwich taste twice as good."},{"step":3,"title":"Cook the eggs in a ring","instruction":"Pour the beaten eggs into a buttered ring mould or a small square pan over low heat, so they cook into a compact shape that fits the muffin."},{"step":4,"title":"Fold and melt","instruction":"When just set, fold the egg into a square, lay the cheese on top, and cover for 30 seconds to melt."},{"step":5,"title":"Assemble hot","instruction":"Stack muffin, egg, cheese, bacon, hot sauce, and lid. Press gently and eat immediately."}]'::JSONB, 'For meal prep, cook a dozen eggs in a muffin tin at 350°F for 15 minutes, assemble the sandwiches, wrap in foil, and freeze. Reheat from frozen for 90 seconds in the microwave then 5 minutes in a hot oven to re-crisp.', ARRAY['Vegetarian: Fried halloumi or a hash brown in place of bacon.','Sausage: A flattened sausage patty instead of bacon.','Bagel or croissant: Both work; croissant needs no butter.']::TEXT[], ARRAY['Egg','Dairy','Gluten']::TEXT[]),
('smoothie-bowl', 'Smoothie Bowl', 'A thick frozen-fruit base spooned rather than drunk, built to hold toppings.', 'https://images.unsplash.com/photo-1635341083002-67e6fa3c5f4b', 'Thick smoothie bowl with mixed berries, granola, and coconut flakes', 'Aisha Sharma', '@aishasharmaspice', '', '', '10 min', '—', '10 min', 10, 0, 10, 2, 'Easy', 'Modern', 'Breakfast', 'Breakfast', ARRAY['Vegan-Adaptable','Gluten-Free','No-Cook','Healthy']::TEXT[], 4.9, 1179, 5260, 358, 10, 54, 13, 9, '[{"amount":"2","unit":"","item":"frozen bananas"},{"amount":"1.5","unit":"cups","item":"frozen mango or berries"},{"amount":"0.33","unit":"cup","item":"Greek or coconut yoghurt"},{"amount":"3","unit":"tbsp","item":"milk of choice"},{"amount":"1","unit":"tbsp","item":"almond butter"},{"amount":"1","unit":"tbsp","item":"honey or maple syrup"},{"amount":"","unit":"","item":"Granola, fresh fruit, coconut flakes, and seeds to top"}]'::JSONB, '[{"step":1,"title":"Everything frozen","instruction":"All the fruit goes in frozen. Fresh fruit plus ice makes a watery base that separates within minutes."},{"step":2,"title":"Minimal liquid","instruction":"Add only 3 tablespoons of milk to start. You can always add more; you cannot take it out.","tip":"Restraint with the liquid is the entire technique."},{"step":3,"title":"Blend with a tamper","instruction":"Blend on low, stopping repeatedly to push the mixture into the blades. It should move like soft-serve."},{"step":4,"title":"Chill the bowls","instruction":"Use bowls straight from the freezer — it buys several extra minutes before the base softens."},{"step":5,"title":"Top and eat immediately","instruction":"Smooth the surface, arrange the toppings in rows, and eat right away."}]'::JSONB, 'If your blender struggles, let the frozen fruit sit out for exactly three minutes — any longer and you lose the thickness. A food processor often handles this better than a jug blender.', ARRAY['Vegan: Coconut yoghurt and maple syrup.','Higher protein: A scoop of protein powder or a spoonful of silken tofu.','Green: Add spinach — it changes the colour but not the flavour.']::TEXT[], ARRAY['Tree Nut']::TEXT[]),
('lemon-ricotta-pancakes', 'Lemon Ricotta Pancakes', 'Ricotta folded into the batter with whipped whites for pancakes that are almost soufflé-like.', 'https://img.rocket.new/generatedImages/rocket_gen_img_1791e4fa0-1772289647107.png', 'Fluffy lemon ricotta pancakes with powdered sugar and fresh lemon zest', 'Sofia Romano', '@sofiaromanoeats', '', '', '12 min', '13 min', '25 min', 12, 13, 25, 4, 'Easy', 'Italian', 'Breakfast', 'Breakfast', ARRAY['Brunch','Vegetarian','Special Occasion']::TEXT[], 5.0, 1586, 1283, 386, 16, 42, 17, 2, '[{"amount":"1","unit":"cup","item":"all-purpose flour"},{"amount":"1","unit":"cup","item":"whole-milk ricotta"},{"amount":"0.75","unit":"cup","item":"milk"},{"amount":"3","unit":"large","item":"eggs, separated"},{"amount":"2","unit":"tbsp","item":"sugar"},{"amount":"2","unit":"tsp","item":"baking powder"},{"amount":"2","unit":"","item":"lemons (zest and juice)"},{"amount":"0.5","unit":"tsp","item":"salt"},{"amount":"","unit":"","item":"Butter for the pan"},{"amount":"","unit":"","item":"Berries and powdered sugar to serve"}]'::JSONB, '[{"step":1,"title":"Drain the ricotta","instruction":"If the ricotta looks wet, drain it in a sieve for 15 minutes. Excess whey makes a loose batter that will not hold."},{"step":2,"title":"Mix the base","instruction":"Whisk the ricotta, milk, egg yolks, sugar, lemon zest, and juice, then fold in the flour, baking powder, and salt until just combined."},{"step":3,"title":"Whip the whites","instruction":"Beat the whites to soft peaks — glossy and holding a shape that flops slightly at the tip."},{"step":4,"title":"Fold in two stages","instruction":"Fold a third of the whites in to loosen the batter, then fold the rest through gently. The batter should look airy and slightly streaky.","tip":"Fold, do not stir. The air in the whites is what makes these different from ordinary pancakes."},{"step":5,"title":"Cook low and slow","instruction":"Cook on medium-low in butter, 3–4 minutes a side. These are thicker and more delicate than standard pancakes and need lower heat and a careful flip."}]'::JSONB, 'These are noticeably softer and more custardy in the centre than buttermilk pancakes — that is correct, not underdone. Serve immediately; they deflate as they sit.', ARRAY['Cottage cheese: Blended smooth, it substitutes for ricotta.','Savoury: Skip the sugar and lemon, add herbs and parmesan.','Do not make ahead: The whipped whites collapse. Cook straight away.']::TEXT[], ARRAY['Gluten','Dairy','Egg']::TEXT[]),
('huevos-rancheros', 'Huevos Rancheros', 'Fried tortillas topped with beans, eggs, and a charred tomato salsa.', 'https://img.rocket.new/generatedImages/rocket_gen_img_1e54a3842-1783627091192.png', 'Huevos rancheros with fried eggs, salsa roja, and crispy tortillas', 'Rosa Gutierrez', '@rosagutierrezcocina', '', '', '10 min', '10 min', '20 min', 10, 10, 20, 4, 'Easy', 'Mexican', 'Breakfast', 'Breakfast', ARRAY['Vegetarian','Gluten-Free','Hearty','Family']::TEXT[], 4.7, 61, 4896, 462, 19, 44, 24, 9, '[{"amount":"8","unit":"","item":"corn tortillas"},{"amount":"4","unit":"large","item":"eggs"},{"amount":"1","unit":"can","item":"refried or black beans"},{"amount":"4","unit":"","item":"tomatoes, halved"},{"amount":"1","unit":"","item":"onion, halved"},{"amount":"2","unit":"","item":"jalapeños"},{"amount":"3","unit":"cloves","item":"garlic, unpeeled"},{"amount":"3","unit":"tbsp","item":"neutral oil"},{"amount":"1","unit":"","item":"lime, juiced"},{"amount":"0.5","unit":"cup","item":"crumbled cotija or feta"},{"amount":"1","unit":"","item":"avocado, sliced"},{"amount":"","unit":"","item":"Cilantro and salt"}]'::JSONB, '[{"step":1,"title":"Char the salsa vegetables","instruction":"Dry-roast the tomatoes, onion, jalapeños, and garlic in a hot pan for 10 minutes, turning, until blackened in patches all over.","tip":"Charring, not simmering, is what gives ranchero salsa its smoky depth."},{"step":2,"title":"Blend the salsa","instruction":"Peel the garlic and blend everything with the lime juice and salt to a coarse sauce. Simmer 5 minutes to thicken."},{"step":3,"title":"Fry the tortillas","instruction":"Fry each tortilla in oil for 30 seconds a side until it firms up but stays pliable — crisp enough to hold the toppings without shattering."},{"step":4,"title":"Warm the beans","instruction":"Heat the beans with a splash of water until spreadable."},{"step":5,"title":"Fry the eggs","instruction":"Fry the eggs in the remaining oil with crisp edges and runny yolks."},{"step":6,"title":"Build","instruction":"Two tortillas per plate, beans spread over, an egg on each, salsa spooned around, then cheese, avocado, and cilantro."}]'::JSONB, 'The salsa keeps 5 days and freezes well, which makes weekday versions of this fast. Tinned fire-roasted tomatoes are a decent shortcut if you do not want to char your own.', ARRAY['Vegan: Skip the eggs and cheese; add crisped tofu and extra avocado.','Heat: Leave the jalapeño seeds in for a hotter salsa.','Divorciados: Serve one egg with red salsa and one with green.']::TEXT[], ARRAY['Egg','Dairy']::TEXT[]),
('bircher-muesli', 'Bircher Muesli', 'Oats soaked overnight in apple juice and yoghurt with grated apple. The Swiss original, not sweetened porridge.', 'https://img.rocket.new/generatedImages/rocket_gen_img_108d043bd-1773910722617.png', 'Swiss bircher muesli with soaked oats, apple, and yogurt', 'Emma Walsh', '@emmawalshbakes', '', '', '5 min', '—', '5 min', 5, 0, 5, 4, 'Easy', 'Swiss', 'Breakfast', 'Breakfast', ARRAY['Make-Ahead','No-Cook','Healthy','Vegetarian']::TEXT[], 4.3, 377, 2446, 342, 11, 52, 11, 7, '[{"amount":"2","unit":"cups","item":"rolled oats"},{"amount":"1.5","unit":"cups","item":"apple juice"},{"amount":"1","unit":"cup","item":"Greek yoghurt"},{"amount":"2","unit":"","item":"apples, grated with skin"},{"amount":"1","unit":"tbsp","item":"lemon juice"},{"amount":"0.33","unit":"cup","item":"raisins"},{"amount":"0.33","unit":"cup","item":"chopped hazelnuts"},{"amount":"2","unit":"tbsp","item":"honey"},{"amount":"0.5","unit":"tsp","item":"cinnamon"},{"amount":"","unit":"","item":"Fresh berries to serve"}]'::JSONB, '[{"step":1,"title":"Soak overnight in juice","instruction":"Combine the oats, apple juice, and raisins and refrigerate overnight. Apple juice rather than milk is what makes this bircher rather than overnight oats."},{"step":2,"title":"Grate the apple fresh","instruction":"Grate the apples with their skins in the morning and toss immediately with the lemon juice to stop them browning.","tip":"Grate the apple fresh. Grated overnight it goes brown and loses all its texture."},{"step":3,"title":"Fold everything together","instruction":"Stir the yoghurt, grated apple, honey, and cinnamon through the soaked oats."},{"step":4,"title":"Adjust the consistency","instruction":"It should be loose and spoonable. Add more juice or yoghurt if it has set too thick overnight."},{"step":5,"title":"Top and serve","instruction":"Divide into bowls and top with the hazelnuts and berries."}]'::JSONB, 'The traditional version uses condensed milk and far less yoghurt, and the apple is the dominant flavour rather than an add-in. Keeps 3 days, though the apple is best added daily.', ARRAY['Vegan: Coconut yoghurt and maple syrup in place of honey.','Nut-free: Sunflower and pumpkin seeds.','Fruit: Grated pear, or berries folded through.']::TEXT[], ARRAY['Dairy','Tree Nut']::TEXT[]),
('breakfast-tacos', 'Breakfast Tacos', 'Soft scrambled eggs, potato, and cheese in charred corn tortillas with salsa.', 'https://img.rocket.new/generatedImages/rocket_gen_img_116ccbc83-1772393582608.png', 'Soft breakfast tacos with scrambled eggs, chorizo, and pico de gallo', 'Carlos Mendez', '@carlosmendezcooks', '', '', '10 min', '10 min', '20 min', 10, 10, 20, 4, 'Easy', 'Mexican', 'Breakfast', 'Breakfast', ARRAY['Quick','Family','Gluten-Free-Adaptable']::TEXT[], 5.0, 917, 736, 438, 20, 38, 24, 4, '[{"amount":"8","unit":"","item":"corn tortillas"},{"amount":"8","unit":"large","item":"eggs"},{"amount":"2","unit":"tbsp","item":"butter"},{"amount":"2","unit":"","item":"potatoes, diced small"},{"amount":"8","unit":"oz","item":"chorizo, crumbled"},{"amount":"1","unit":"cup","item":"grated cheddar"},{"amount":"2","unit":"tbsp","item":"neutral oil"},{"amount":"0.5","unit":"cup","item":"salsa verde"},{"amount":"1","unit":"","item":"avocado, sliced"},{"amount":"","unit":"","item":"Cilantro, lime, and salt"}]'::JSONB, '[{"step":1,"title":"Crisp the potato","instruction":"Fry the diced potato in the oil for 12 minutes, turning rarely, until crisp and golden. Season and set aside."},{"step":2,"title":"Brown the chorizo","instruction":"Cook the chorizo in the same pan until the edges crisp and the fat renders red. Remove, leaving some fat behind."},{"step":3,"title":"Scramble low","instruction":"Melt the butter over low heat and stir the eggs constantly, taking the pan off the heat now and then. Pull them while glossy and slightly underdone.","tip":"Low and slow gives soft curds. High heat gives dry, squeaky eggs."},{"step":4,"title":"Char the tortillas","instruction":"Toast the tortillas directly over a gas flame or in a dry pan for 20 seconds a side until blistered and pliable."},{"step":5,"title":"Build fast","instruction":"Fill each tortilla with potato, chorizo, eggs, and cheese, then top with salsa verde, avocado, cilantro, and lime."}]'::JSONB, 'Everything except the eggs can be cooked ahead; scramble to order. Double up the tortillas if they are thin, which is standard practice in Texas.', ARRAY['Vegetarian: Black beans and roasted peppers in place of chorizo.','Meal prep: Wrap assembled tacos in foil and refrigerate; reheat in the oven.','Flour tortillas: Equally traditional depending on who you ask.']::TEXT[], ARRAY['Egg','Dairy']::TEXT[]),
('dutch-baby-pancake', 'Dutch Baby Pancake', 'A single giant pancake that puffs dramatically in a preheated cast iron pan.', 'https://images.unsplash.com/photo-1586195833982-47e978de8f40', 'Puffed Dutch baby pancake with lemon juice, powdered sugar, and berries', 'Sofia Romano', '@sofiaromanoeats', '', '', '10 min', '15 min', '25 min', 10, 15, 25, 4, 'Easy', 'German', 'Breakfast', 'Breakfast', ARRAY['Brunch','Vegetarian','Showstopper','One-Pan']::TEXT[], 4.9, 833, 4599, 312, 11, 34, 14, 1, '[{"amount":"3","unit":"large","item":"eggs, room temperature"},{"amount":"0.5","unit":"cup","item":"whole milk, room temperature"},{"amount":"0.5","unit":"cup","item":"all-purpose flour"},{"amount":"1","unit":"tbsp","item":"sugar"},{"amount":"0.5","unit":"tsp","item":"vanilla extract"},{"amount":"","unit":"","item":"Pinch of salt"},{"amount":"3","unit":"tbsp","item":"butter"},{"amount":"","unit":"","item":"Lemon, powdered sugar, and berries to serve"}]'::JSONB, '[{"step":1,"title":"Room temperature ingredients","instruction":"Cold eggs and milk will not rise properly. Take them out 45 minutes ahead or warm the milk slightly.","tip":"This is the most common reason a Dutch baby fails to puff."},{"step":2,"title":"Blend the batter","instruction":"Blend everything except the butter for 30 seconds until completely smooth and quite thin. Rest 15 minutes."},{"step":3,"title":"Preheat the pan with the butter in it","instruction":"Put a 10-inch cast iron pan in the oven at 425°F (220°C) for 15 minutes. Add the butter and return for 2 minutes until it foams and just starts to brown.","tip":"The pan must be blazing hot. The batter should sizzle audibly as it goes in."},{"step":4,"title":"Pour and shut the door","instruction":"Pour the batter straight into the hot buttered pan and return to the oven immediately. Do not open the door for 18 minutes.","tip":"Opening the oven drops the temperature and the pancake collapses instantly."},{"step":5,"title":"Bake until dramatic","instruction":"Bake 18–20 minutes until it has climbed the sides of the pan and is deep golden."},{"step":6,"title":"Serve immediately","instruction":"It deflates within a minute of leaving the oven, which is entirely normal. Dust with sugar, squeeze lemon over, and serve straight from the pan."}]'::JSONB, 'The dramatic puff is steam, not a raising agent, which is why the hot pan and thin batter matter so much. It will always sink — that is part of the dish.', ARRAY['Savoury: Skip the sugar and vanilla, add herbs, and top with ham and gruyere.','Fruit: Lay sliced apple or pear in the buttered pan before pouring.','Size: Halve the recipe for an 8-inch pan; the timings stay the same.']::TEXT[], ARRAY['Gluten','Dairy','Egg']::TEXT[]),
('protein-smoothie', 'Protein Smoothie', 'A balanced smoothie that actually keeps you full — protein, fat, and fibre rather than just fruit.', 'https://images.unsplash.com/photo-1584587715439-8ae6d53228a2', 'Thick protein smoothie with banana, peanut butter, and chocolate protein powder', 'Priya Nair', '@priyanairkitchen', '', '', '5 min', '—', '5 min', 5, 0, 5, 1, 'Easy', 'Modern', 'Breakfast', 'Beverage', ARRAY['High Protein','Quick','No-Cook','Gluten-Free']::TEXT[], 4.7, 637, 6745, 412, 34, 38, 14, 8, '[{"amount":"1","unit":"scoop","item":"vanilla or chocolate protein powder"},{"amount":"1","unit":"","item":"frozen banana"},{"amount":"1","unit":"cup","item":"milk of choice"},{"amount":"2","unit":"tbsp","item":"peanut butter"},{"amount":"1","unit":"tbsp","item":"chia seeds"},{"amount":"1","unit":"handful","item":"spinach"},{"amount":"0.5","unit":"tsp","item":"cinnamon"},{"amount":"","unit":"","item":"Ice cubes"}]'::JSONB, '[{"step":1,"title":"Liquid in first","instruction":"Always add the milk to the blender first. It gets the blades moving and stops powder caking against the bottom.","tip":"Liquid first, powder last. This is why smoothies come out lumpy."},{"step":2,"title":"Soft ingredients next","instruction":"Add the spinach, peanut butter, chia, and cinnamon."},{"step":3,"title":"Frozen last","instruction":"Put the frozen banana and ice on top, so their weight pushes everything down into the blades."},{"step":4,"title":"Blend long","instruction":"Blend a full 60 seconds. Protein powder and chia both need time to disperse or you get a gritty texture."},{"step":5,"title":"Check thickness","instruction":"Add more milk to thin or more ice to thicken, then blend 10 seconds more."}]'::JSONB, 'The protein powder should go in with the wet ingredients rather than sitting on top of the frozen fruit, where it tends to clump. Spinach is undetectable at this quantity.', ARRAY['No protein powder: Greek yoghurt, silken tofu, or cottage cheese all add protein.','Nut-free: Sunflower seed butter or tahini.','Prep: Freeze bags of banana, spinach, and seeds; tip one in with milk each morning.']::TEXT[], ARRAY['Dairy','Peanut']::TEXT[]),
('veggie-frittata', 'Veggie Frittata', 'Eggs and vegetables started on the hob and finished under the grill. Good hot, warm, or cold.', 'https://img.rocket.new/generatedImages/rocket_gen_img_15021d1d2-1782939122129.png', 'Baked veggie frittata with zucchini, bell peppers, and goat cheese', 'Marco Rossi', '@marcorossicucina', '', '', '12 min', '18 min', '30 min', 12, 18, 30, 6, 'Easy', 'Italian', 'Breakfast', 'Breakfast', ARRAY['Vegetarian','Gluten-Free','Meal Prep','One-Pan']::TEXT[], 4.4, 974, 1480, 268, 17, 9, 19, 2, '[{"amount":"10","unit":"large","item":"eggs"},{"amount":"0.33","unit":"cup","item":"whole milk"},{"amount":"1","unit":"","item":"red pepper, diced"},{"amount":"1","unit":"","item":"courgette, diced"},{"amount":"5","unit":"oz","item":"spinach"},{"amount":"1","unit":"","item":"onion, diced"},{"amount":"3","unit":"cloves","item":"garlic, minced"},{"amount":"4","unit":"oz","item":"feta, crumbled"},{"amount":"0.33","unit":"cup","item":"grated parmesan"},{"amount":"3","unit":"tbsp","item":"olive oil"},{"amount":"","unit":"","item":"Salt, pepper, and fresh basil"}]'::JSONB, '[{"step":1,"title":"Cook the vegetables dry","instruction":"Cook the onion, pepper, and courgette in the oil for 8 minutes until softened and any liquid has evaporated. Add the garlic, then the spinach until wilted, and squeeze out excess moisture.","tip":"Wet vegetables make a watery frittata that will not set properly."},{"step":2,"title":"Whisk thoroughly","instruction":"Beat the eggs with the milk, salt, and pepper for a full 30 seconds until completely uniform and slightly frothy."},{"step":3,"title":"Pour over low heat","instruction":"Spread the vegetables evenly in an oven-safe pan, pour the eggs over, and scatter the cheeses. Cook on low for 8 minutes without stirring.","tip":"Low heat is essential. High heat sets the base into rubber before the top cooks."},{"step":4,"title":"Finish under the grill","instruction":"Once the edges are set and the centre still wobbles, put the pan under a hot grill for 3–4 minutes until puffed and golden."},{"step":5,"title":"Rest before slicing","instruction":"Rest 5 minutes — it sets fully and releases from the pan far more cleanly."}]'::JSONB, 'A frittata is done when the centre barely jiggles; carryover heat finishes it. Overcooked eggs weep water onto the plate. Keeps 4 days and is genuinely good cold, which makes it excellent for lunchboxes.', ARRAY['Add: Any leftover roast vegetables, cooked potato, or cured meat.','Dairy-free: Skip the cheeses and add olives and sun-dried tomatoes for savouriness.','Muffin tin: Bake the mixture in cups at 350°F for 20 minutes.']::TEXT[], ARRAY['Egg','Dairy']::TEXT[]),
('cinnamon-french-toast-sticks', 'Cinnamon French Toast Sticks', 'French toast cut into batons, fried, and rolled in cinnamon sugar for dipping.', 'https://img.rocket.new/generatedImages/rocket_gen_img_17f60aed6-1785351748859.png', 'Cinnamon sugar French toast sticks with maple syrup for dipping', 'Emma Walsh', '@emmawalshbakes', '', '', '8 min', '7 min', '15 min', 8, 7, 15, 4, 'Easy', 'American', 'Breakfast', 'Breakfast', ARRAY['Kid Friendly','Quick','Family','Freezer-Friendly']::TEXT[], 4.9, 1716, 8934, 412, 12, 52, 17, 2, '[{"amount":"8","unit":"thick slices","item":"day-old brioche or white bread"},{"amount":"4","unit":"large","item":"eggs"},{"amount":"0.75","unit":"cup","item":"whole milk"},{"amount":"2","unit":"tsp","item":"vanilla extract"},{"amount":"1","unit":"tsp","item":"ground cinnamon"},{"amount":"","unit":"","item":"Pinch of salt"},{"amount":"4","unit":"tbsp","item":"butter"},{"amount":"0.33","unit":"cup","item":"granulated sugar"},{"amount":"1","unit":"tbsp","item":"cinnamon for coating"},{"amount":"","unit":"","item":"Maple syrup for dipping"}]'::JSONB, '[{"step":1,"title":"Cut before soaking","instruction":"Cut each slice into three batons first. Soaking whole slices and cutting after gives you soggy, collapsing sticks."},{"step":2,"title":"Use stale bread","instruction":"Day-old bread holds its shape. Fresh bread turns to mush in the custard.","tip":"If the bread is fresh, dry the batons in a 300°F oven for 6 minutes first."},{"step":3,"title":"Soak briefly","instruction":"Whisk the eggs, milk, vanilla, cinnamon, and salt. Roll each baton through for about 10 seconds — much less than a full slice needs."},{"step":4,"title":"Fry on all sides","instruction":"Cook in butter over medium heat, turning to brown all four sides, about 6 minutes total."},{"step":5,"title":"Roll in cinnamon sugar","instruction":"Toss the hot sticks in the combined sugar and cinnamon straight out of the pan, so it sticks."}]'::JSONB, 'These freeze extremely well — cool completely, freeze on a tray, then bag. Reheat from frozen in an air fryer at 375°F for 6 minutes and they come back crisp.', ARRAY['Baked: 400°F for 15 minutes on a rack, turning once.','Dips: Maple syrup, chocolate sauce, or berry compote.','Dairy-free: Oat milk and oil in place of milk and butter.']::TEXT[], ARRAY['Gluten','Dairy','Egg']::TEXT[]),
('breakfast-pizza', 'Breakfast Pizza', 'Pizza base with a garlic cream sauce, bacon, cheese, and eggs cracked on in the last few minutes.', 'https://img.rocket.new/generatedImages/rocket_gen_img_174aff7da-1772174615900.png', 'Breakfast pizza with scrambled eggs, bacon, cheese, and hash brown crust', 'Jake Torres', '@jaketorrescooks', 'https://images.unsplash.com/photo-1572015837827-01671d41e102', 'Portrait of food creator Jake Torres', '10 min', '15 min', '25 min', 10, 15, 25, 4, 'Easy', 'American', 'Breakfast', 'Breakfast', ARRAY['Brunch','Family','Weekend']::TEXT[], 4.2, 1163, 7564, 612, 28, 52, 32, 3, '[{"amount":"1","unit":"","item":"pizza base or 1 lb pizza dough"},{"amount":"0.5","unit":"cup","item":"crème fraîche or cream cheese"},{"amount":"2","unit":"cloves","item":"garlic, grated"},{"amount":"2","unit":"cups","item":"grated mozzarella"},{"amount":"6","unit":"slices","item":"bacon, cooked and chopped"},{"amount":"4","unit":"large","item":"eggs"},{"amount":"2","unit":"","item":"scallions, sliced"},{"amount":"2","unit":"tbsp","item":"olive oil"},{"amount":"","unit":"","item":"Salt, pepper, and chilli flakes"}]'::JSONB, '[{"step":1,"title":"Preheat properly","instruction":"Heat the oven with a stone or heavy tray inside at 475°F (245°C) for at least 20 minutes."},{"step":2,"title":"Use a cream base","instruction":"Mix the crème fraîche with the garlic, salt, and pepper and spread thinly. Tomato sauce clashes with eggs; a cream base is what makes this work."},{"step":3,"title":"Part-bake first","instruction":"Top with cheese and bacon and bake 8 minutes before the eggs go anywhere near it.","tip":"Eggs added at the start end up leathery. They need only the final few minutes."},{"step":4,"title":"Add eggs in wells","instruction":"Pull the pizza out, make four shallow wells in the cheese, and crack an egg into each."},{"step":5,"title":"Finish","instruction":"Return for 5–6 minutes until the whites are set and the yolks still run. Top with scallions, chilli flakes, and pepper."}]'::JSONB, 'Crack each egg into a small bowl first and slide it on, rather than cracking directly onto the pizza where it can run off the edge. Cook slightly longer if you prefer firm yolks, but the runny yolk acts as a sauce.', ARRAY['Vegetarian: Sautéed mushrooms and spinach in place of bacon.','Naan or flatbread: Works as a fast base; reduce the part-bake to 4 minutes.','Sausage: Crumbled and pre-cooked breakfast sausage instead of bacon.']::TEXT[], ARRAY['Gluten','Dairy','Egg']::TEXT[]),
('matcha-latte', 'Matcha Latte', 'Matcha sifted and whisked into a smooth paste before the milk goes in, so it never clumps.', 'https://img.rocket.new/generatedImages/rocket_gen_img_1110273b2-1772210749281.png', 'Creamy matcha latte with oat milk and a dusting of matcha powder', 'Yuna Kim', '@yunakimkitchen', '', '', '5 min', '—', '5 min', 5, 0, 5, 1, 'Easy', 'Japanese', 'Drink', 'Beverage', ARRAY['Quick','Vegetarian','Caffeine']::TEXT[], 4.6, 247, 5671, 128, 6, 14, 5, 1, '[{"amount":"2","unit":"tsp","item":"ceremonial grade matcha powder"},{"amount":"2","unit":"oz","item":"water at 175°F"},{"amount":"8","unit":"oz","item":"milk of choice"},{"amount":"1","unit":"tsp","item":"honey or maple syrup"},{"amount":"","unit":"","item":"Ice if serving cold"}]'::JSONB, '[{"step":1,"title":"Sift the matcha","instruction":"Push the matcha through a fine sieve into your bowl or cup. Matcha clumps in the tin and those clumps will never whisk out.","tip":"Sifting takes ten seconds and is the difference between smooth and gritty."},{"step":2,"title":"Use water below boiling","instruction":"Heat the water to about 175°F (80°C) — just before simmering. Boiling water scorches matcha and makes it bitter and astringent.","tip":"If it boils, let it stand two minutes before using."},{"step":3,"title":"Whisk to a paste","instruction":"Add the hot water and whisk briskly in a W or M motion — not circles — for 20 seconds until smooth and frothy on top."},{"step":4,"title":"Sweeten the paste","instruction":"Stir the honey into the matcha concentrate now, while it is hot, so it dissolves fully."},{"step":5,"title":"Add milk","instruction":"Pour over steamed hot milk, or over ice and cold milk for an iced latte."}]'::JSONB, 'Ceremonial grade is noticeably smoother and sweeter than culinary grade, which is intended for baking and tastes harsh on its own. A bamboo whisk (chasen) works best but a small metal whisk or a milk frother will do.', ARRAY['Vegan: Oat milk froths best and complements matcha well.','Iced: Make the paste with half the water, then pour over ice and cold milk.','Storage: Keep matcha sealed in the dark; it oxidises and dulls within weeks of opening.']::TEXT[], ARRAY['Dairy']::TEXT[]),
('egg-muffins', 'Egg Muffins', 'Baked egg cups with vegetables and cheese, made a dozen at a time for the week.', 'https://images.unsplash.com/photo-1718307495601-5231e6290d8a', 'Mini egg muffins with vegetables and cheese baked in a muffin tin', 'Sofia Patel', '@sofiapatelkitchen', 'https://images.unsplash.com/photo-1716947674021-1b8b696325c7', 'Portrait of food creator Sofia Patel', '10 min', '15 min', '25 min', 10, 15, 25, 6, 'Easy', 'Modern', 'Breakfast', 'Breakfast', ARRAY['Meal Prep','High Protein','Gluten-Free','Low Carb']::TEXT[], 4.7, 1312, 6484, 186, 15, 4, 12, 1, '[{"amount":"10","unit":"large","item":"eggs"},{"amount":"0.25","unit":"cup","item":"milk"},{"amount":"1","unit":"","item":"red pepper, finely diced"},{"amount":"4","unit":"oz","item":"spinach, wilted and squeezed"},{"amount":"4","unit":"","item":"scallions, sliced"},{"amount":"1","unit":"cup","item":"grated cheddar"},{"amount":"4","unit":"slices","item":"bacon, cooked and chopped"},{"amount":"","unit":"","item":"Salt, pepper, and paprika"}]'::JSONB, '[{"step":1,"title":"Grease very well","instruction":"Grease a 12-cup muffin tin thoroughly, including the top surface, or use silicone cups. Egg sticks ferociously.","tip":"Silicone cups are worth buying for this alone."},{"step":2,"title":"Dry the fillings","instruction":"Squeeze all the water out of the wilted spinach and cook off any liquid from the pepper. Wet fillings make the muffins collapse and weep."},{"step":3,"title":"Whisk the eggs well","instruction":"Beat the eggs with the milk, salt, and pepper for 30 seconds until completely uniform."},{"step":4,"title":"Fill two-thirds","instruction":"Divide the fillings between the cups, then pour the egg over to two-thirds full. They rise considerably and then settle."},{"step":5,"title":"Bake moderate","instruction":"Bake at 350°F (175°C) for 20–22 minutes until just set and puffed. They will sink as they cool, which is normal."},{"step":6,"title":"Cool before removing","instruction":"Cool 5 minutes in the tin, then run a knife around each and lift out."}]'::JSONB, 'Keeps 5 days refrigerated or 2 months frozen. Reheat for 30 seconds in the microwave. Overbaking makes them rubbery and weepy, so pull them the moment the centres set.', ARRAY['Vegetarian: Mushrooms, sun-dried tomato, and feta.','Dairy-free: Skip the cheese and milk; add nutritional yeast.','Variety: Divide the plain egg mixture over different fillings in each cup.']::TEXT[], ARRAY['Egg','Dairy']::TEXT[]),
('peanut-butter-banana-toast', 'Peanut Butter Banana Toast', 'Good toast, thick peanut butter, banana, and a scatter of salt and seeds.', 'https://images.unsplash.com/photo-1706277909579-d0e489b41808', 'Thick toast with peanut butter, banana slices, honey, and chia seeds', 'Priya Nair', '@priyanairkitchen', '', '', '5 min', '—', '5 min', 5, 0, 5, 2, 'Easy', 'American', 'Breakfast', 'Breakfast', ARRAY['Quick','Vegetarian','Budget','Kid Friendly']::TEXT[], 4.5, 938, 524, 386, 13, 46, 18, 7, '[{"amount":"4","unit":"slices","item":"good wholegrain or sourdough bread"},{"amount":"6","unit":"tbsp","item":"natural peanut butter"},{"amount":"2","unit":"","item":"bananas, sliced"},{"amount":"1","unit":"tbsp","item":"honey or maple syrup"},{"amount":"1","unit":"tsp","item":"chia seeds"},{"amount":"0.5","unit":"tsp","item":"ground cinnamon"},{"amount":"","unit":"","item":"Flaky sea salt"}]'::JSONB, '[{"step":1,"title":"Toast well","instruction":"Toast the bread until firmly crisp. Peanut butter is heavy and soft toast bends under it."},{"step":2,"title":"Spread while warm","instruction":"Spread the peanut butter onto the hot toast so it softens and spreads evenly rather than tearing the surface."},{"step":3,"title":"Slice the banana thin","instruction":"Slice on a slight diagonal for more surface area and better coverage."},{"step":4,"title":"Finish with salt","instruction":"Drizzle the honey, then add the chia seeds, cinnamon, and a small pinch of flaky salt.","tip":"The salt is what makes this taste finished rather than like a child''s snack."}]'::JSONB, 'Natural peanut butter (just peanuts and salt) tastes considerably better here than the sweetened kind, since there is already honey on top. Stir the separated oil back in rather than pouring it off.', ARRAY['Nut-free: Sunflower seed butter or tahini.','Add: Cacao nibs, hemp seeds, or a few berries.','Higher protein: A layer of Greek yoghurt under the peanut butter.']::TEXT[], ARRAY['Peanut','Gluten']::TEXT[]),
('steak-and-eggs', 'Steak and Eggs', 'A properly seared steak with fried eggs. High protein, twenty minutes, no sides required.', 'https://img.rocket.new/generatedImages/rocket_gen_img_1db10218f-1772446279214.png', 'Classic steak and eggs with sautéed mushrooms and toast', 'Jake Torres', '@jaketorrescooks', 'https://images.unsplash.com/photo-1572015837827-01671d41e102', 'Portrait of food creator Jake Torres', '5 min', '15 min', '20 min', 5, 15, 20, 2, 'Medium', 'American', 'Breakfast', 'Breakfast', ARRAY['High Protein','Low Carb','Gluten-Free','Quick']::TEXT[], 4.9, 971, 1449, 648, 52, 3, 48, 0, '[{"amount":"2","unit":"","item":"sirloin or ribeye steaks (8 oz each)"},{"amount":"4","unit":"large","item":"eggs"},{"amount":"2","unit":"tbsp","item":"neutral oil"},{"amount":"2","unit":"tbsp","item":"butter"},{"amount":"2","unit":"cloves","item":"garlic, smashed"},{"amount":"1","unit":"sprig","item":"rosemary"},{"amount":"","unit":"","item":"Salt, coarse black pepper, and hot sauce"}]'::JSONB, '[{"step":1,"title":"Temper and dry","instruction":"Take the steaks out 40 minutes ahead and pat them completely dry. Cold, damp steak will not sear.","tip":"Room temperature and bone dry. Both are required."},{"step":2,"title":"Season heavily just before cooking","instruction":"Salt and pepper generously right as the pan heats, not earlier."},{"step":3,"title":"Sear hard","instruction":"Heat the oil in a cast iron pan until smoking and sear the steaks 3 minutes per side without moving them."},{"step":4,"title":"Baste with butter","instruction":"Add the butter, garlic, and rosemary, tilt the pan, and spoon the foaming butter over the steaks for 60 seconds."},{"step":5,"title":"Rest the steak, fry the eggs","instruction":"Rest the steaks on a warm plate for 8 minutes. Meanwhile fry the eggs in the same pan, in the steak fat, until the edges are crisp and the yolks runny.","tip":"Frying the eggs in the steak pan is the whole point. Do not wash it in between."},{"step":6,"title":"Serve","instruction":"Slice the steak against the grain, top with the eggs, and add hot sauce and cracked pepper."}]'::JSONB, 'Pull the steak at 125°F for medium-rare; it climbs another five degrees while resting. The eight-minute rest is not optional — cutting early loses the juice onto the board.', ARRAY['Cheaper cut: Flat iron or bavette, sliced thin against the grain.','Add: Grilled tomato, mushrooms, or a hash brown.','Ventilation: This produces a lot of smoke. Open a window first.']::TEXT[], ARRAY['Egg','Dairy']::TEXT[]),
('coconut-flour-pancakes', 'Coconut Flour Pancakes', 'Grain-free pancakes built around coconut flour, which behaves nothing like wheat flour.', 'https://img.rocket.new/generatedImages/rocket_gen_img_1c1966aab-1767129915183.png', 'Light and fluffy coconut flour pancakes with fresh berries and maple syrup', 'Aisha Sharma', '@aishasharmaspice', '', '', '8 min', '12 min', '20 min', 8, 12, 20, 3, 'Easy', 'Modern', 'Breakfast', 'Breakfast', ARRAY['Gluten-Free','Low Carb','Keto','Vegetarian']::TEXT[], 4.3, 390, 7446, 286, 14, 16, 19, 7, '[{"amount":"0.5","unit":"cup","item":"coconut flour"},{"amount":"6","unit":"large","item":"eggs"},{"amount":"0.5","unit":"cup","item":"coconut milk"},{"amount":"2","unit":"tbsp","item":"melted coconut oil"},{"amount":"1","unit":"tbsp","item":"maple syrup"},{"amount":"1","unit":"tsp","item":"vanilla extract"},{"amount":"1","unit":"tsp","item":"baking powder"},{"amount":"0.5","unit":"tsp","item":"salt"},{"amount":"","unit":"","item":"Butter for the pan"},{"amount":"","unit":"","item":"Berries and syrup to serve"}]'::JSONB, '[{"step":1,"title":"Respect the absorbency","instruction":"Coconut flour absorbs about four times more liquid than wheat flour, which is why this needs six eggs for half a cup of flour. Do not scale it like a normal recipe.","tip":"This is the one thing to understand. Coconut flour is not a one-to-one substitute for anything."},{"step":2,"title":"Whisk and rest","instruction":"Whisk everything together until smooth, then rest 5 minutes. The batter thickens dramatically as the flour hydrates."},{"step":3,"title":"Adjust after resting","instruction":"If it has set too thick to pour, loosen with a splash of coconut milk. It should be thick but spoonable."},{"step":4,"title":"Cook small and low","instruction":"Make small pancakes, about 3 inches, over low heat. These are fragile and a large one will break when flipped.","tip":"Small and low. Large coconut flour pancakes fall apart every time."},{"step":5,"title":"Flip once, carefully","instruction":"Cook 3 minutes until the edges set and bubbles form, then flip gently and cook 2 minutes more."}]'::JSONB, 'These are denser and more custardy than wheat pancakes — that is the nature of coconut flour, not a fault. They are also considerably more filling, so three per person is usually plenty.', ARRAY['Dairy-free: Already is, if you cook in coconut oil.','Sweetness: Coconut flour is naturally sweet; you may need no syrup at all.','Storage: Keep coconut flour sealed — it absorbs moisture from the air and clumps.']::TEXT[], ARRAY['Egg','Coconut','Dairy']::TEXT[]),
('breakfast-casserole', 'Breakfast Casserole', 'Bread, eggs, sausage, and cheese assembled the night before and baked in the morning.', 'https://images.unsplash.com/photo-1559095253-30e69b68344e', 'Hearty breakfast casserole with sausage, eggs, cheese, and hash browns', 'Rosa Gutierrez', '@rosagutierrezcocina', '', '', '20 min', '40 min', '1 hr', 20, 40, 60, 8, 'Easy', 'American', 'Breakfast', 'Breakfast', ARRAY['Make-Ahead','Family','Crowd Pleaser','Holiday']::TEXT[], 4.3, 641, 3220, 512, 26, 32, 32, 2, '[{"amount":"1","unit":"lb","item":"breakfast sausage"},{"amount":"10","unit":"cups","item":"day-old bread, cubed"},{"amount":"10","unit":"large","item":"eggs"},{"amount":"3","unit":"cups","item":"whole milk"},{"amount":"1","unit":"","item":"onion, diced"},{"amount":"1","unit":"","item":"red pepper, diced"},{"amount":"3","unit":"cups","item":"grated cheddar"},{"amount":"1","unit":"tsp","item":"dry mustard"},{"amount":"0.5","unit":"tsp","item":"nutmeg"},{"amount":"2","unit":"","item":"scallions, sliced"},{"amount":"","unit":"","item":"Salt and black pepper"}]'::JSONB, '[{"step":1,"title":"Use stale bread","instruction":"Day-old or oven-dried bread cubes soak up the custard without collapsing. Fresh bread turns to paste.","tip":"If your bread is fresh, dry the cubes at 300°F for 10 minutes."},{"step":2,"title":"Brown the sausage and vegetables","instruction":"Cook the sausage until browned, then the onion and pepper for 5 minutes. Drain off excess fat."},{"step":3,"title":"Layer","instruction":"Spread half the bread in a greased dish, then half the sausage mixture and cheese. Repeat."},{"step":4,"title":"Pour the custard over","instruction":"Whisk the eggs, milk, mustard, nutmeg, salt, and pepper and pour evenly over the whole dish. Press down so every cube is submerged."},{"step":5,"title":"Rest overnight","instruction":"Cover and refrigerate at least 4 hours, ideally overnight. This is what lets the bread absorb the custard fully.","tip":"The overnight soak is the entire point. A quick assembly bakes into dry bread with egg around it."},{"step":6,"title":"Bake from cold","instruction":"Bake uncovered at 350°F (175°C) for 55–65 minutes until puffed, golden, and set at the centre. Rest 10 minutes before cutting."}]'::JSONB, 'Take it out of the fridge 30 minutes before baking so it heats evenly. If the top browns before the centre sets, tent with foil. A knife inserted in the middle should come out clean.', ARRAY['Vegetarian: Mushrooms and spinach in place of the sausage; squeeze the spinach dry.','Freezer: Freeze assembled and unbaked for 2 months; thaw overnight and bake as normal.','Croissant version: Use torn croissants instead of bread for something much richer.']::TEXT[], ARRAY['Gluten','Egg','Dairy']::TEXT[]),
('blueberry-scones', 'Blueberry Scones', 'Cold butter, minimal handling, and a hot oven. Craggy outside, tender inside.', 'https://img.rocket.new/generatedImages/rocket_gen_img_1470b0d3e-1784881969919.png', 'Flaky blueberry scones with lemon glaze on a baking sheet', 'Emma Walsh', '@emmawalshbakes', '', '', '15 min', '20 min', '35 min', 15, 20, 35, 8, 'Easy', 'British', 'Breakfast', 'Baked Goods', ARRAY['Baking','Vegetarian','Brunch','Quick']::TEXT[], 4.6, 135, 5313, 342, 6, 44, 16, 2, '[{"amount":"2.5","unit":"cups","item":"all-purpose flour"},{"amount":"0.5","unit":"cup","item":"granulated sugar"},{"amount":"1","unit":"tbsp","item":"baking powder"},{"amount":"0.5","unit":"tsp","item":"salt"},{"amount":"0.75","unit":"cup","item":"very cold butter, cubed"},{"amount":"0.75","unit":"cup","item":"cold heavy cream"},{"amount":"1","unit":"","item":"egg"},{"amount":"1","unit":"tsp","item":"vanilla extract"},{"amount":"1.25","unit":"cups","item":"blueberries"},{"amount":"","unit":"","item":"Demerara sugar and cream for the tops"}]'::JSONB, '[{"step":1,"title":"Keep the butter frozen-cold","instruction":"Cube the butter and freeze it for 15 minutes. Cold butter melts in the oven and leaves steam pockets, which is what makes scones flaky.","tip":"If the butter softens at any point, put the whole bowl in the fridge for ten minutes."},{"step":2,"title":"Rub in coarsely","instruction":"Rub or cut the butter into the dry ingredients until you have pieces ranging from breadcrumb to pea size. Do not go further."},{"step":3,"title":"Add liquid minimally","instruction":"Whisk the cream, egg, and vanilla and add all at once. Stir with a fork just until a shaggy dough forms with dry patches remaining.","tip":"Overworked scone dough bakes hard and flat. Stop while it still looks unfinished."},{"step":4,"title":"Fold in berries by hand","instruction":"Tip onto a floured surface, scatter the blueberries over, and fold the dough over itself three or four times only."},{"step":5,"title":"Cut cleanly","instruction":"Pat into a 1-inch thick round and cut into 8 wedges with a sharp knife pressed straight down. Twisting the cutter seals the edges and stops them rising."},{"step":6,"title":"Chill then bake hot","instruction":"Freeze the cut scones for 15 minutes, then brush with cream, scatter demerara, and bake at 400°F (205°C) for 20–22 minutes until golden."}]'::JSONB, 'The freeze before baking is what gives a high rise and defined layers. Frozen blueberries work and bleed less than fresh if you do not thaw them.', ARRAY['Make-ahead: Freeze cut unbaked scones for 2 months; bake from frozen, adding 5 minutes.','Glaze: Powdered sugar with lemon juice, drizzled once cool.','Savoury: Drop the sugar to a tablespoon, add cheddar and chives.']::TEXT[], ARRAY['Gluten','Dairy','Egg']::TEXT[]),
('savory-oatmeal', 'Savory Oatmeal', 'Oats cooked in stock rather than milk, topped with a soft egg, chilli oil, and scallions.', 'https://img.rocket.new/generatedImages/rocket_gen_img_184f555da-1772765907328.png', 'Savory oatmeal with soft-boiled egg, soy sauce, and sesame oil', 'Lin Wei', '@linweiwok', '', '', '5 min', '10 min', '15 min', 5, 10, 15, 2, 'Easy', 'Chinese', 'Breakfast', 'Breakfast', ARRAY['Budget','Quick','High Fibre','Vegetarian-Adaptable']::TEXT[], 4.7, 255, 8424, 386, 17, 46, 16, 7, '[{"amount":"1","unit":"cup","item":"rolled oats"},{"amount":"2.5","unit":"cups","item":"chicken or vegetable stock"},{"amount":"1","unit":"tbsp","item":"soy sauce"},{"amount":"1","unit":"tsp","item":"toasted sesame oil"},{"amount":"2","unit":"large","item":"eggs"},{"amount":"2","unit":"tbsp","item":"chilli crisp"},{"amount":"2","unit":"","item":"scallions, sliced"},{"amount":"1","unit":"handful","item":"spinach"},{"amount":"2","unit":"tbsp","item":"toasted sesame seeds"},{"amount":"","unit":"","item":"White pepper"}]'::JSONB, '[{"step":1,"title":"Cook in stock, not water","instruction":"Simmer the oats in stock for 6 minutes, stirring, until thick and creamy. Stock rather than water or milk is the whole shift here.","tip":"Once you have had oats cooked in stock, sweet porridge starts to seem like the odd version."},{"step":2,"title":"Season while cooking","instruction":"Stir in the soy sauce and white pepper as it thickens, so it seasons through rather than sitting on top."},{"step":3,"title":"Wilt greens in","instruction":"Add the spinach in the last minute and stir until collapsed."},{"step":4,"title":"Soft-boil the eggs","instruction":"Boil the eggs 6.5 minutes, then ice and peel. The jammy yolk becomes part of the sauce."},{"step":5,"title":"Top generously","instruction":"Spoon into bowls, halve the eggs on top, and finish with chilli crisp, scallions, sesame seeds, and a drizzle of sesame oil."}]'::JSONB, 'Oats keep thickening as they sit, so pull them slightly looser than you want. This is closer to congee than to porridge in spirit, and takes a fraction of the time.', ARRAY['Vegan: Vegetable stock and crisped tofu or mushrooms in place of the egg.','Add: Leftover roast chicken, kimchi, or a spoonful of miso.','Steel-cut: Better texture but needs 25 minutes.']::TEXT[], ARRAY['Gluten','Egg','Soy','Sesame']::TEXT[]),
('croissant-sandwich', 'Croissant Sandwich', 'A split croissant warmed through, filled with egg, ham, and melted cheese.', 'https://images.unsplash.com/photo-1696721497013-e90103a41bf3', 'Buttery croissant sandwich with ham, brie, and Dijon mustard', 'Sofia Romano', '@sofiaromanoeats', '', '', '5 min', '5 min', '10 min', 5, 5, 10, 2, 'Easy', 'French', 'Breakfast', 'Breakfast', ARRAY['Quick','Brunch','Indulgent']::TEXT[], 4.3, 1888, 4104, 582, 26, 38, 36, 2, '[{"amount":"2","unit":"","item":"large butter croissants"},{"amount":"4","unit":"large","item":"eggs"},{"amount":"4","unit":"slices","item":"good ham"},{"amount":"4","unit":"slices","item":"gruyere or cheddar"},{"amount":"2","unit":"tbsp","item":"butter"},{"amount":"1","unit":"tbsp","item":"Dijon mustard"},{"amount":"","unit":"","item":"Salt, pepper, and chives"}]'::JSONB, '[{"step":1,"title":"Warm the croissants first","instruction":"Split and warm the croissants in a 350°F oven for 4 minutes. A cold croissant is dense and slightly waxy; warm, it turns flaky again.","tip":"Four minutes in the oven transforms a shop-bought croissant."},{"step":2,"title":"Scramble softly","instruction":"Melt the butter over low heat and stir the eggs constantly, pulling the pan off the heat now and then. Stop while still glossy."},{"step":3,"title":"Mustard the base","instruction":"Spread a thin layer of Dijon on the bottom half. It cuts the richness of butter, cheese, and egg."},{"step":4,"title":"Layer and melt","instruction":"Stack ham, eggs, and cheese, then return the open sandwich to the oven for 3 minutes until the cheese melts."},{"step":5,"title":"Close and press","instruction":"Add the lid, press gently, and serve at once with chives and cracked pepper."}]'::JSONB, 'Day-old croissants are actually preferable here, since they hold up better to the filling and revive well in the oven. Griddling the closed sandwich for a minute a side gives a croque-monsieur effect.', ARRAY['Vegetarian: Roasted mushrooms or avocado in place of the ham.','Sweet: Skip the savoury filling; fill with jam and mascarpone.','Make-ahead: Assemble cold, wrap, and bake at 350°F for 12 minutes.']::TEXT[], ARRAY['Gluten','Dairy','Egg']::TEXT[])
