INSERT INTO public.recipes (slug, title, description, image, image_alt, creator_name, creator_handle, creator_image, creator_alt, prep_time, cook_time, total_time, prep_minutes, cook_minutes, total_minutes, servings, difficulty, cuisine, meal_type, category, tags, rating, reviews, cooks, calories, protein, carbs, fat, fiber, ingredients, steps, notes, tips, allergens) VALUES
('acai-smoothie', 'Açaí Smoothie', 'A drinkable açaí smoothie — looser than the bowl version, ready in five minutes.', 'https://images.unsplash.com/photo-1561997315-6d0610a96b9c', 'Thick açaí smoothie with banana, almond milk, and honey', 'Aisha Sharma', '@aishasharmaspice', '', '', '5 min', '—', '5 min', 5, 0, 5, 2, 'Easy', 'Brazilian', 'Breakfast', 'Beverage', ARRAY['Vegan-Adaptable','Gluten-Free','Quick','Healthy']::TEXT[], 4.9, 1713, 9220, 286, 5, 52, 8, 8, '[{"amount":"2","unit":"packs","item":"frozen unsweetened açaí purée"},{"amount":"1","unit":"","item":"frozen banana"},{"amount":"1","unit":"cup","item":"frozen mixed berries"},{"amount":"1","unit":"cup","item":"apple juice or coconut water"},{"amount":"0.5","unit":"cup","item":"Greek or coconut yoghurt"},{"amount":"1","unit":"tbsp","item":"honey or agave"},{"amount":"1","unit":"tbsp","item":"chia seeds"}]'::JSONB, '[{"step":1,"title":"Break up the açaí","instruction":"Run the sealed packs under warm water for 10 seconds and snap into pieces before blending."},{"step":2,"title":"Liquid first","instruction":"Add the juice to the blender first so the blades can move freely."},{"step":3,"title":"Add the rest and blend","instruction":"Add the açaí, banana, berries, yoghurt, honey, and chia and blend 45 seconds until smooth."},{"step":4,"title":"Adjust","instruction":"Add more juice for a thinner drink or more frozen fruit to thicken. Unsweetened açaí is tart, so taste before adding more sweetener."}]'::JSONB, 'This is the same base as the bowl with roughly three times the liquid. Unsweetened açaí packs are worth seeking out — the sweetened kind makes the whole thing cloying.', ARRAY['Vegan: Coconut yoghurt and agave.','Higher protein: A scoop of vanilla protein powder.','No açaí: A cup of frozen blueberries and blackberries gives a similar profile.']::TEXT[], ARRAY[]::TEXT[]),
('loaded-avocado-toast', 'Loaded Avocado Toast', 'Avocado toast with everything on it — egg, feta, tomatoes, chilli, and seeds.', 'https://img.rocket.new/generatedImages/rocket_gen_img_18e6c1a9c-1772204197800.png', 'Loaded avocado toast with cherry tomatoes, microgreens, and everything bagel seasoning', 'Emma Walsh', '@emmawalshbakes', '', '', '10 min', '5 min', '15 min', 10, 5, 15, 2, 'Easy', 'Modern', 'Breakfast', 'Breakfast', ARRAY['Vegetarian','Brunch','Healthy','Quick']::TEXT[], 5.0, 1290, 2008, 512, 20, 38, 32, 11, '[{"amount":"4","unit":"thick slices","item":"sourdough bread"},{"amount":"2","unit":"","item":"ripe avocados"},{"amount":"2","unit":"large","item":"eggs"},{"amount":"1","unit":"tbsp","item":"lemon juice"},{"amount":"0.5","unit":"cup","item":"cherry tomatoes, halved"},{"amount":"2","unit":"oz","item":"feta, crumbled"},{"amount":"1","unit":"tbsp","item":"everything bagel seasoning"},{"amount":"1","unit":"tsp","item":"chilli flakes"},{"amount":"2","unit":"tbsp","item":"olive oil"},{"amount":"1","unit":"clove","item":"garlic, halved"},{"amount":"","unit":"","item":"Flaky salt, black pepper, and microgreens"}]'::JSONB, '[{"step":1,"title":"Toast hard and rub with garlic","instruction":"Toast the sourdough until properly crisp, then rub the cut garlic clove across the hot surface and drizzle with oil."},{"step":2,"title":"Season the avocado","instruction":"Mash the avocado with the lemon juice, a generous pinch of flaky salt, and black pepper. Taste it before it goes on the toast.","tip":"Seasoning the avocado properly is the difference between this and a bland trend dish."},{"step":3,"title":"Blister the tomatoes","instruction":"Sear the cherry tomatoes cut-side down in a dry hot pan for 3 minutes until they collapse and caramelise."},{"step":4,"title":"Fry or poach the eggs","instruction":"Cook the eggs to your preference, keeping the yolks runny so they act as a sauce."},{"step":5,"title":"Layer and finish","instruction":"Spread the avocado thickly, add tomatoes, feta, and the egg, then finish with bagel seasoning, chilli flakes, greens, and more salt."}]'::JSONB, 'The avocado should be ripe enough to yield to gentle pressure at the stem end. Under-ripe avocado tastes grassy and no amount of seasoning fixes it.', ARRAY['Add protein: Smoked salmon, crisp bacon, or a spoonful of hummus underneath.','Vegan: Skip the egg and feta; add crisped chickpeas and tahini.','Gluten-free: Any sturdy GF bread, toasted well.']::TEXT[], ARRAY['Gluten','Egg','Dairy']::TEXT[]),
('breakfast-bowl', 'Breakfast Bowl', 'Grains, greens, roast vegetables, and a soft egg with a herby dressing. A savoury start built for meal prep.', 'https://images.unsplash.com/photo-1575732957508-da0f9f379b5e', 'Nourishing breakfast bowl with quinoa, roasted vegetables, and a poached egg', 'Priya Nair', '@priyanairkitchen', '', '', '15 min', '5 min', '20 min', 15, 5, 20, 4, 'Easy', 'Modern', 'Breakfast', 'Breakfast', ARRAY['Meal Prep','Balanced','Vegetarian','Gluten-Free-Adaptable']::TEXT[], 4.8, 225, 3268, 486, 20, 48, 24, 9, '[{"amount":"2","unit":"cups","item":"cooked quinoa or brown rice"},{"amount":"1","unit":"","item":"sweet potato, cubed"},{"amount":"1","unit":"can","item":"chickpeas, drained and dried"},{"amount":"2","unit":"tbsp","item":"olive oil"},{"amount":"1","unit":"tsp","item":"smoked paprika"},{"amount":"4","unit":"large","item":"eggs"},{"amount":"4","unit":"cups","item":"baby spinach"},{"amount":"1","unit":"","item":"avocado, sliced"},{"amount":"0.33","unit":"cup","item":"Greek yoghurt"},{"amount":"1","unit":"tbsp","item":"lemon juice"},{"amount":"2","unit":"tbsp","item":"chopped dill"},{"amount":"1","unit":"clove","item":"garlic, grated"},{"amount":"","unit":"","item":"Salt, pepper, and chilli flakes"}]'::JSONB, '[{"step":1,"title":"Roast for texture","instruction":"Toss the sweet potato and chickpeas with the oil, paprika, and salt and roast at 425°F (220°C) for 25 minutes until browned and the chickpeas have started to crisp.","tip":"Spread across two trays if it looks crowded — crisp edges are what make this bowl worth eating."},{"step":2,"title":"Make the dressing","instruction":"Whisk the yoghurt, lemon juice, dill, garlic, salt, and pepper, loosening with water until pourable."},{"step":3,"title":"Soft-boil the eggs","instruction":"Boil the eggs for 6.5 minutes, then plunge into ice water and peel. Jammy yolks act as a second sauce."},{"step":4,"title":"Wilt the spinach","instruction":"Toss the spinach through the hot roast vegetables straight from the oven so it wilts without needing a separate pan."},{"step":5,"title":"Assemble","instruction":"Build bowls with grains, the roast mixture, avocado, and halved eggs. Spoon the dressing over and add chilli flakes."}]'::JSONB, 'Store the components separately for meal prep — everything except the avocado keeps 4 days. Boil the eggs fresh each morning or store them peeled in cold water.', ARRAY['Vegan: Skip the egg, use a tahini dressing, and add extra chickpeas.','Grain-free: Serve over more greens or cauliflower rice.','Add: Any leftover roast vegetables slot straight in.']::TEXT[], ARRAY['Egg','Dairy']::TEXT[]),
('sourdough-french-toast', 'Sourdough French Toast', 'Tangy sourdough soaked in vanilla custard, which balances the sweetness better than brioche does.', 'https://images.unsplash.com/photo-1623375477518-9d04f307e82b', 'Thick sourdough French toast with caramelized bananas and maple syrup', 'Marco Rossi', '@marcorossicucina', '', '', '8 min', '12 min', '20 min', 8, 12, 20, 4, 'Easy', 'American', 'Breakfast', 'Breakfast', ARRAY['Brunch','Vegetarian','Quick']::TEXT[], 4.2, 516, 5618, 432, 16, 48, 19, 3, '[{"amount":"8","unit":"thick slices","item":"day-old sourdough"},{"amount":"4","unit":"large","item":"eggs"},{"amount":"1","unit":"cup","item":"whole milk"},{"amount":"0.25","unit":"cup","item":"heavy cream"},{"amount":"2","unit":"tbsp","item":"brown sugar"},{"amount":"2","unit":"tsp","item":"vanilla extract"},{"amount":"1","unit":"tsp","item":"cinnamon"},{"amount":"","unit":"","item":"Pinch of salt"},{"amount":"4","unit":"tbsp","item":"butter"},{"amount":"","unit":"","item":"Maple syrup, berries, and crème fraîche to serve"}]'::JSONB, '[{"step":1,"title":"Cut thick","instruction":"Cut the sourdough at least an inch thick. Thin slices go limp and fall apart in the custard."},{"step":2,"title":"Whisk the eggs first","instruction":"Beat the eggs alone until uniform before adding the milk, cream, sugar, vanilla, cinnamon, and salt. Unbeaten white cooks into rubbery streaks."},{"step":3,"title":"Soak longer than brioche","instruction":"Sourdough is denser and drier, so give it 30 seconds a side rather than the usual 20.","tip":"Press gently as it soaks — you want the custard right into the centre."},{"step":4,"title":"Fry on medium","instruction":"Cook in butter for 3–4 minutes a side until deep golden and slightly puffed."},{"step":5,"title":"Rest on a rack","instruction":"Rest on a wire rack rather than a plate so the underside stays crisp, and serve with syrup, berries, and crème fraîche."}]'::JSONB, 'The sourness of the bread is the point here — it cuts the sweetness of the custard and syrup in a way that brioche does not. Wipe the pan between batches so burnt butter does not turn the later slices bitter.', ARRAY['Savoury: Skip the sugar and cinnamon; top with a fried egg and bacon.','Dairy-free: Oat milk and coconut cream; fry in oil.','Overnight: Soak the slices in a dish in the fridge and fry in the morning.']::TEXT[], ARRAY['Gluten','Dairy','Egg']::TEXT[]),
('breakfast-pita', 'Breakfast Pita', 'Warm pita stuffed with eggs, hummus, and salad — a Middle Eastern take on a breakfast sandwich.', 'https://images.unsplash.com/photo-1701386196596-5d9ec133fa81', 'Toasted pita filled with scrambled eggs, feta, and fresh herbs', 'Leila Hassan', '@leilahassantable', '', '', '10 min', '5 min', '15 min', 10, 5, 15, 2, 'Easy', 'Middle Eastern', 'Breakfast', 'Breakfast', ARRAY['Quick','Vegetarian','High Protein']::TEXT[], 4.7, 604, 3253, 462, 20, 48, 22, 8, '[{"amount":"2","unit":"","item":"pita breads"},{"amount":"4","unit":"large","item":"eggs"},{"amount":"0.5","unit":"cup","item":"hummus"},{"amount":"2","unit":"tbsp","item":"olive oil"},{"amount":"1","unit":"","item":"tomato, diced"},{"amount":"0.5","unit":"","item":"cucumber, diced"},{"amount":"0.25","unit":"","item":"red onion, thinly sliced"},{"amount":"2","unit":"tbsp","item":"chopped parsley"},{"amount":"1","unit":"tbsp","item":"lemon juice"},{"amount":"2","unit":"tbsp","item":"tahini sauce"},{"amount":"1","unit":"tsp","item":"za''atar"},{"amount":"","unit":"","item":"Salt, pepper, and pickles"}]'::JSONB, '[{"step":1,"title":"Warm the pita properly","instruction":"Heat the pita directly over a flame or in a dry pan for 20 seconds a side until it puffs and softens. Cold pita cracks when you open it.","tip":"A puffed pita opens into a clean pocket. A cold one tears."},{"step":2,"title":"Make a quick salad","instruction":"Toss the tomato, cucumber, onion, and parsley with the lemon juice, olive oil, and salt."},{"step":3,"title":"Scramble or fry the eggs","instruction":"Cook the eggs softly — scrambled over low heat, or fried with runny yolks."},{"step":4,"title":"Line the pocket with hummus","instruction":"Spread hummus inside the pita first. It acts as a barrier that stops the salad juices making the bread soggy."},{"step":5,"title":"Fill and finish","instruction":"Add the eggs, salad, and pickles, then drizzle with tahini and dust with za''atar."}]'::JSONB, 'Za''atar is worth buying for this — it is what makes the sandwich taste specifically Levantine rather than generic. Shop-bought hummus is entirely fine here.', ARRAY['Add: Falafel, halloumi, or shakshuka sauce.','Vegan: Skip the eggs and add extra falafel or crisped chickpeas.','Meal prep: Prepare the salad and hummus ahead; cook the eggs to order.']::TEXT[], ARRAY['Gluten','Egg','Sesame']::TEXT[]),
('corn-fritters', 'Corn Fritters', 'Sweetcorn fritters bound with a minimal batter so they taste of corn rather than pancake.', 'https://images.unsplash.com/photo-1583503654530-a4ca08800292', 'Golden corn fritters with sour cream and fresh chives', 'Carlos Mendez', '@carlosmendezcooks', '', '', '10 min', '10 min', '20 min', 10, 10, 20, 4, 'Easy', 'American', 'Breakfast', 'Breakfast', ARRAY['Vegetarian','Quick','Family','Brunch']::TEXT[], 5.0, 1048, 2802, 312, 10, 38, 14, 3, '[{"amount":"3","unit":"cups","item":"sweetcorn kernels (fresh or frozen, thawed)"},{"amount":"0.75","unit":"cup","item":"all-purpose flour"},{"amount":"2","unit":"large","item":"eggs"},{"amount":"0.33","unit":"cup","item":"milk"},{"amount":"1","unit":"tsp","item":"baking powder"},{"amount":"4","unit":"","item":"scallions, sliced"},{"amount":"0.5","unit":"cup","item":"grated cheddar"},{"amount":"1","unit":"","item":"red chilli, minced"},{"amount":"0.25","unit":"cup","item":"chopped cilantro"},{"amount":"","unit":"","item":"Neutral oil for frying"},{"amount":"","unit":"","item":"Salt, pepper, and sour cream to serve"}]'::JSONB, '[{"step":1,"title":"Dry the corn","instruction":"Pat the corn dry thoroughly. Wet corn makes a loose batter that spreads and steams instead of frying."},{"step":2,"title":"Blitz a third of it","instruction":"Pulse a third of the corn in a processor until roughly broken down and stir it back in. This releases starch that binds the fritters without more flour.","tip":"This is what lets you keep the batter minimal and the corn flavour dominant."},{"step":3,"title":"Mix minimally","instruction":"Combine the eggs, milk, flour, and baking powder, then fold in all the corn, scallions, cheese, chilli, and cilantro. Season well."},{"step":4,"title":"Fry in shallow oil","instruction":"Heat a few millimetres of oil over medium-high and drop in heaped spoonfuls, flattening slightly. Cook 3 minutes a side until deep golden."},{"step":5,"title":"Drain on a rack","instruction":"Drain on a wire rack rather than paper, so the bases stay crisp. Serve with sour cream."}]'::JSONB, 'Fresh corn cut from the cob is noticeably better than frozen, but frozen works well if thoroughly thawed and dried. The batter should look like corn barely held together, not like pancake batter with corn in it.', ARRAY['Add: Crumbled feta, bacon, or jalapeño.','Gluten-free: Chickpea flour works and adds flavour.','Make-ahead: Cooked fritters reheat well at 375°F for 8 minutes.']::TEXT[], ARRAY['Gluten','Egg','Dairy']::TEXT[]),
('ricotta-toast', 'Ricotta Toast', 'Whipped ricotta on good toast, sweet or savoury. Ten minutes, mostly whisking.', 'https://img.rocket.new/generatedImages/rocket_gen_img_1f67ffc13-1772617055021.png', 'Thick toast with whipped ricotta, honey, and fresh figs', 'Sofia Romano', '@sofiaromanoeats', '', '', '10 min', '—', '10 min', 10, 0, 10, 2, 'Easy', 'Italian', 'Breakfast', 'Breakfast', ARRAY['Vegetarian','Quick','Brunch']::TEXT[], 4.9, 1199, 2702, 386, 16, 38, 19, 3, '[{"amount":"4","unit":"slices","item":"sourdough bread"},{"amount":"1","unit":"cup","item":"whole-milk ricotta"},{"amount":"2","unit":"tbsp","item":"olive oil"},{"amount":"1","unit":"tbsp","item":"lemon juice"},{"amount":"1","unit":"tsp","item":"lemon zest"},{"amount":"2","unit":"tbsp","item":"honey"},{"amount":"1","unit":"cup","item":"fresh figs or berries"},{"amount":"2","unit":"tbsp","item":"toasted pistachios"},{"amount":"","unit":"","item":"Flaky salt and black pepper"},{"amount":"","unit":"","item":"Mint"}]'::JSONB, '[{"step":1,"title":"Whip the ricotta","instruction":"Beat the ricotta with the olive oil, lemon juice, zest, and a pinch of salt for 2 minutes until noticeably lighter, smoother, and almost mousse-like.","tip":"Whipping is the whole difference. Spooned straight from the tub, ricotta is grainy and dull."},{"step":2,"title":"Drain if wet","instruction":"If the ricotta is watery, drain it in a sieve for 15 minutes first, or the toast will go soggy."},{"step":3,"title":"Toast well","instruction":"Toast the sourdough until crisp and drizzle with a little olive oil."},{"step":4,"title":"Spread thickly","instruction":"Pile the whipped ricotta on generously — this is not a scraping."},{"step":5,"title":"Top and season","instruction":"Add the fruit, honey, pistachios, mint, flaky salt, and cracked pepper. The salt and pepper on a sweet version are what make it interesting."}]'::JSONB, 'Whole-milk ricotta is essential; the low-fat kind is chalky and will not whip. This works equally well savoury — skip the honey and fruit and top with roast tomatoes, chilli, and basil.', ARRAY['Savoury: Roast tomatoes, olive oil, chilli flakes, and basil.','Autumn: Roast grapes or sliced pear with thyme.','Make-ahead: Whipped ricotta keeps 3 days refrigerated.']::TEXT[], ARRAY['Dairy','Gluten']::TEXT[]),
('breakfast-galette', 'Breakfast Galette', 'A free-form pastry base folded around eggs, cheese, and greens. Rustic by design, so it is hard to get wrong.', 'https://img.rocket.new/generatedImages/rocket_gen_img_19d5c328b-1785351134901.png', 'Rustic breakfast galette with eggs, cheese, and vegetables in a flaky crust', 'Emma Walsh', '@emmawalshbakes', '', '', '20 min', '10 min', '30 min', 20, 10, 30, 6, 'Medium', 'French', 'Breakfast', 'Breakfast', ARRAY['Baking','Brunch','Vegetarian','Showstopper']::TEXT[], 4.3, 1147, 1355, 462, 16, 34, 30, 2, '[{"amount":"1","unit":"","item":"shortcrust pastry sheet (or homemade)"},{"amount":"5","unit":"large","item":"eggs"},{"amount":"1","unit":"cup","item":"grated gruyere"},{"amount":"5","unit":"oz","item":"spinach, wilted and squeezed dry"},{"amount":"1","unit":"","item":"onion, sliced and caramelised"},{"amount":"0.33","unit":"cup","item":"crème fraîche"},{"amount":"2","unit":"cloves","item":"garlic, minced"},{"amount":"1","unit":"tbsp","item":"Dijon mustard"},{"amount":"","unit":"","item":"Salt, pepper, nutmeg, and thyme"}]'::JSONB, '[{"step":1,"title":"Keep the pastry cold","instruction":"Work quickly and keep the pastry chilled. Warm pastry loses its layers and turns greasy in the oven."},{"step":2,"title":"Leave a wide border","instruction":"Roll the pastry onto a lined tray and spread the Dijon and crème fraîche across the centre, leaving a clear 2-inch border all round."},{"step":3,"title":"Dry the fillings","instruction":"Squeeze every drop of water from the spinach. A wet filling makes the base soggy and can split the pastry.","tip":"This is the main way galettes fail. Squeeze harder than feels necessary."},{"step":4,"title":"Fill and fold","instruction":"Layer the spinach, caramelised onion, garlic, and most of the cheese in the middle, then fold the border up and over in overlapping pleats."},{"step":5,"title":"Part-bake before the eggs","instruction":"Bake at 400°F (205°C) for 20 minutes, until the pastry is set and turning golden."},{"step":6,"title":"Add eggs and finish","instruction":"Make wells in the filling, crack the eggs in, scatter the remaining cheese, and bake 10 minutes more until the whites set and the yolks still run."}]'::JSONB, 'Cracking each egg into a small bowl first and sliding it in gives much more control than cracking directly onto the galette. Shop-bought all-butter pastry works perfectly well here.', ARRAY['Sweet version: Same method with fruit, sugar, and no eggs.','Make-ahead: Assemble up to the part-bake, refrigerate, then bake to order.','Add: Bacon lardons, mushrooms, or roasted squash.']::TEXT[], ARRAY['Gluten','Dairy','Egg']::TEXT[]),
('mango-lassi', 'Mango Lassi', 'Ripe mango blended with yoghurt and a pinch of cardamom. Three ingredients, five minutes.', 'https://img.rocket.new/generatedImages/rocket_gen_img_1bfe36b80-1773120125817.png', 'Creamy mango lassi with yogurt, cardamom, and fresh mango', 'Aisha Sharma', '@aishasharmaspice', '', '', '5 min', '—', '5 min', 5, 0, 5, 2, 'Easy', 'Indian', 'Drink', 'Beverage', ARRAY['Vegetarian','Gluten-Free','Quick','No-Cook']::TEXT[], 4.4, 244, 4423, 242, 8, 46, 4, 3, '[{"amount":"2","unit":"","item":"ripe mangoes, peeled and cubed (or 1.5 cups pulp)"},{"amount":"1","unit":"cup","item":"plain full-fat yoghurt"},{"amount":"0.5","unit":"cup","item":"cold milk"},{"amount":"2","unit":"tbsp","item":"sugar or honey"},{"amount":"0.25","unit":"tsp","item":"ground cardamom"},{"amount":"","unit":"","item":"Pinch of salt"},{"amount":"","unit":"","item":"Ice cubes"},{"amount":"","unit":"","item":"Chopped pistachios to garnish"}]'::JSONB, '[{"step":1,"title":"Use ripe or tinned mango","instruction":"Alphonso or Kesar mango pulp from a tin is genuinely excellent here and more reliable than under-ripe fresh fruit."},{"step":2,"title":"Blend smooth","instruction":"Blend the mango, yoghurt, milk, sugar, cardamom, and salt for 45 seconds until completely smooth."},{"step":3,"title":"Add the salt","instruction":"The pinch of salt is not optional — it sharpens the mango and stops the drink tasting flat and one-dimensional.","tip":"A pinch of salt in sweet drinks does the same job as in cooking. It makes the fruit taste more like itself."},{"step":4,"title":"Adjust thickness","instruction":"Add more milk for a thinner lassi or more yoghurt for a thicker one. It should pour like single cream."},{"step":5,"title":"Serve very cold","instruction":"Pour over ice and garnish with pistachios and a dusting of cardamom."}]'::JSONB, 'Full-fat yoghurt makes a considerably better lassi than low-fat, which comes out thin and sour. Cardamom is traditional but a pinch of saffron soaked in warm milk is the luxury version.', ARRAY['Vegan: Coconut or cashew yoghurt with plant milk.','Salty lassi: Skip the sugar and mango; add cumin, salt, and mint.','Frozen mango: Works well and makes the lassi thicker; skip the ice.']::TEXT[], ARRAY['Dairy']::TEXT[]),
('breakfast-flatbread', 'Breakfast Flatbread', 'Flatbread topped with labneh, eggs, and za''atar, baked until the edges crisp.', 'https://img.rocket.new/generatedImages/rocket_gen_img_1029ee0af-1767513117603.png', 'Crispy flatbread topped with hummus, eggs, and za''atar', 'Leila Hassan', '@leilahassantable', '', '', '10 min', '10 min', '20 min', 10, 10, 20, 4, 'Easy', 'Middle Eastern', 'Breakfast', 'Breakfast', ARRAY['Vegetarian','Quick','Brunch']::TEXT[], 4.5, 1490, 396, 432, 18, 42, 22, 4, '[{"amount":"2","unit":"","item":"large flatbreads or naan"},{"amount":"0.75","unit":"cup","item":"labneh or thick Greek yoghurt"},{"amount":"4","unit":"large","item":"eggs"},{"amount":"2","unit":"tbsp","item":"olive oil"},{"amount":"2","unit":"cloves","item":"garlic, grated"},{"amount":"1","unit":"cup","item":"cherry tomatoes, halved"},{"amount":"2","unit":"tbsp","item":"za''atar"},{"amount":"2","unit":"oz","item":"feta, crumbled"},{"amount":"0.25","unit":"cup","item":"fresh mint and parsley"},{"amount":"","unit":"","item":"Salt, pepper, and chilli flakes"}]'::JSONB, '[{"step":1,"title":"Pre-crisp the base","instruction":"Brush the flatbreads with oil and bake at 425°F (220°C) for 5 minutes before topping.","tip":"Untoasted flatbread goes limp under the yoghurt. Five minutes fixes it."},{"step":2,"title":"Season the labneh","instruction":"Mix the labneh with the grated garlic, salt, and pepper, then spread over the part-baked bases leaving a clear border."},{"step":3,"title":"Add tomatoes and bake","instruction":"Scatter the tomatoes over and return to the oven for 6 minutes."},{"step":4,"title":"Crack in the eggs","instruction":"Make wells, slide an egg into each, and bake 6–7 minutes more until the whites are set and yolks runny."},{"step":5,"title":"Finish generously","instruction":"Scatter the feta, za''atar, herbs, and chilli flakes and drizzle with olive oil."}]'::JSONB, 'Labneh is strained yoghurt and thicker than Greek yoghurt — if using yoghurt, drain it in a sieve for 30 minutes first or it will run. Za''atar goes on after baking, since it burns easily.', ARRAY['Add: Sujuk, lamb mince, or roasted peppers.','Vegan: Plant yoghurt and skip the eggs; add crisped chickpeas.','Speed: A tortilla base cuts the total time to 12 minutes.']::TEXT[], ARRAY['Gluten','Dairy','Egg','Sesame']::TEXT[]),
('oat-waffles', 'Oat Waffles', 'Waffles made entirely from blended oats — no wheat flour, and crisper than you would expect.', 'https://images.unsplash.com/photo-1553699950-29a94e732d8d', 'Crispy oat waffles with fresh berries and a drizzle of honey', 'Priya Nair', '@priyanairkitchen', '', '', '10 min', '15 min', '25 min', 10, 15, 25, 4, 'Easy', 'Modern', 'Breakfast', 'Breakfast', ARRAY['Gluten-Free-Adaptable','High Fibre','Family','Freezer-Friendly']::TEXT[], 4.7, 1790, 2864, 346, 13, 46, 12, 6, '[{"amount":"2.5","unit":"cups","item":"rolled oats"},{"amount":"2","unit":"large","item":"eggs"},{"amount":"1.5","unit":"cups","item":"milk of choice"},{"amount":"3","unit":"tbsp","item":"melted butter or oil"},{"amount":"2","unit":"tbsp","item":"maple syrup"},{"amount":"1","unit":"tbsp","item":"baking powder"},{"amount":"1","unit":"tsp","item":"vanilla extract"},{"amount":"1","unit":"tsp","item":"cinnamon"},{"amount":"0.5","unit":"tsp","item":"salt"},{"amount":"","unit":"","item":"Berries and syrup to serve"}]'::JSONB, '[{"step":1,"title":"Blend the oats to flour first","instruction":"Blend the dry oats alone for 30 seconds until they become a fine flour. Blending everything together leaves a gritty texture.","tip":"Oats first, on their own. This step is what makes these work."},{"step":2,"title":"Add the rest and blend","instruction":"Add the eggs, milk, melted butter, syrup, baking powder, vanilla, cinnamon, and salt and blend until smooth."},{"step":3,"title":"Rest 10 minutes","instruction":"Let the batter stand. Oat flour absorbs liquid slowly and thickens noticeably in this time."},{"step":4,"title":"Heat the iron fully","instruction":"Preheat the waffle iron completely and grease it well — oat batter sticks more than wheat batter does."},{"step":5,"title":"Cook longer than usual","instruction":"Cook 5–6 minutes, until the steam has almost stopped. Oat waffles need longer than wheat ones to crisp up properly.","tip":"Pulling them early gives a soft, bendy waffle. Wait for the steam to stop."}]'::JSONB, 'These freeze and toast beautifully, which is the main reason to make a double batch. Use certified gluten-free oats if that matters — oats are naturally GF but usually cross-contaminated.', ARRAY['Vegan: Two flax eggs and plant milk; slightly softer but good.','Savoury: Skip the syrup and cinnamon; add cheese and chives.','Pancakes: The same batter works, cooked on medium-low.']::TEXT[], ARRAY['Egg','Dairy']::TEXT[]),
('quesadillas', 'Quesadillas', 'Cheese on both faces so the tortilla seals shut, cooked in a dry pan until blistered.', 'https://images.unsplash.com/photo-1665685278312-89d9f47bb748', 'Crispy cheese quesadillas with salsa and sour cream on a plate', 'Rosa Gutierrez', '@rosagutierrezcocina', '', '', '5 min', '10 min', '15 min', 5, 10, 15, 4, 'Easy', 'Mexican', 'Lunch', 'Main Course', ARRAY['Quick','Budget','Kid Friendly','Vegetarian']::TEXT[], 4.3, 1397, 5031, 468, 21, 38, 26, 3, '[{"amount":"4","unit":"","item":"large flour tortillas"},{"amount":"3","unit":"cups","item":"grated Monterey Jack and cheddar"},{"amount":"1","unit":"","item":"red pepper, thinly sliced"},{"amount":"0.5","unit":"","item":"onion, thinly sliced"},{"amount":"1","unit":"tsp","item":"ground cumin"},{"amount":"1","unit":"tbsp","item":"neutral oil"},{"amount":"0.25","unit":"cup","item":"chopped cilantro"},{"amount":"","unit":"","item":"Salsa, sour cream, and guacamole to serve"}]'::JSONB, '[{"step":1,"title":"Cook the vegetables first","instruction":"Soften the pepper and onion in the oil with the cumin for 5 minutes. Raw vegetables release water inside the quesadilla and make it soggy."},{"step":2,"title":"Cheese on both sides of the filling","instruction":"Scatter cheese onto half the tortilla, add the filling, then more cheese on top before folding. The cheese is the glue.","tip":"Filling touching the tortilla is why quesadillas fall apart when you cut them."},{"step":3,"title":"Dry pan, medium heat","instruction":"Cook in a dry pan with no oil. Oil makes the surface greasy rather than crisp and blistered."},{"step":4,"title":"Be patient","instruction":"Cook 4 minutes a side, pressing gently, until browned in patches and the cheese has fully melted. High heat browns the outside before the middle melts."},{"step":5,"title":"Rest before cutting","instruction":"Rest 2 minutes so the cheese sets, then cut into wedges."}]'::JSONB, 'Grate the cheese yourself — pre-grated is coated in starch that stops it melting smoothly. A mix of a good melting cheese and a sharp one gives the best result.', ARRAY['Add protein: Shredded chicken, chorizo, or black beans.','Make-ahead: Assemble and refrigerate a day; cook from cold.','Air fryer: 380°F for 6 minutes, flipping once.']::TEXT[], ARRAY['Gluten','Dairy']::TEXT[]),
('tuna-salad-sandwich', 'Tuna Salad Sandwich', 'Tinned tuna dressed properly with celery, lemon, and herbs, on bread that can take it.', 'https://images.unsplash.com/photo-1659589967239-ac53f6f24c75', 'Classic tuna salad sandwich on toasted bread with lettuce and tomato', 'Emma Walsh', '@emmawalshbakes', '', '', '10 min', '—', '10 min', 10, 0, 10, 4, 'Easy', 'American', 'Lunch', 'Main Course', ARRAY['Quick','Budget','High Protein','No-Cook']::TEXT[], 4.4, 1732, 3219, 412, 26, 32, 20, 3, '[{"amount":"2","unit":"cans","item":"tuna in olive oil, drained"},{"amount":"4","unit":"tbsp","item":"mayonnaise"},{"amount":"1","unit":"tbsp","item":"Dijon mustard"},{"amount":"2","unit":"stalks","item":"celery, finely diced"},{"amount":"0.25","unit":"","item":"red onion, finely diced"},{"amount":"2","unit":"tbsp","item":"capers"},{"amount":"1","unit":"tbsp","item":"lemon juice"},{"amount":"2","unit":"tbsp","item":"chopped dill"},{"amount":"8","unit":"slices","item":"good bread"},{"amount":"","unit":"","item":"Lettuce, tomato, salt, and black pepper"}]'::JSONB, '[{"step":1,"title":"Use tuna in oil","instruction":"Oil-packed tuna is far more flavourful and less dry than water-packed. Drain it but do not press it bone dry."},{"step":2,"title":"Flake, do not mash","instruction":"Break the tuna into flakes with a fork, keeping some texture. Mashed tuna turns into paste.","tip":"Chunks make a much better sandwich than a uniform spread."},{"step":3,"title":"Add crunch","instruction":"Fold in the celery and red onion. The crunch is what keeps the filling from being one-note and heavy."},{"step":4,"title":"Dress and season","instruction":"Stir in the mayonnaise, Dijon, capers, lemon juice, dill, salt, and plenty of black pepper. Taste — it usually needs more lemon than you expect."},{"step":5,"title":"Build on sturdy bread","instruction":"Layer lettuce first as a barrier, then the tuna, then tomato. Lettuce underneath stops the bread going soggy."}]'::JSONB, 'The filling keeps 3 days refrigerated and is better after an hour as the flavours settle. Assemble sandwiches to order rather than in advance.', ARRAY['Lighter: Swap half the mayonnaise for Greek yoghurt.','Melt: Top with cheese and grill open-faced for a tuna melt.','Gluten-free: Serve in lettuce cups or on GF bread.']::TEXT[], ARRAY['Fish','Egg','Gluten','Mustard','Celery']::TEXT[]),
('stir-fry-vegetables', 'Stir-Fry Vegetables', 'Vegetables cooked hard and fast in order of density, with the sauce added at the very end.', 'https://images.unsplash.com/photo-1695487528543-347c15018fd6', 'Colorful stir-fried vegetables with garlic and soy sauce in a wok', 'Maria Chen', '@mariachencooks', 'https://images.unsplash.com/photo-1677229888051-211da3f34219', 'Portrait of food creator Maria Chen', '12 min', '3 min', '15 min', 12, 3, 15, 4, 'Easy', 'Chinese', 'Dinner', 'Side Dish', ARRAY['Vegan-Adaptable','Quick','Healthy','Budget']::TEXT[], 5.0, 367, 9221, 186, 6, 20, 9, 5, '[{"amount":"2","unit":"tbsp","item":"neutral oil"},{"amount":"1","unit":"","item":"broccoli head, in small florets"},{"amount":"2","unit":"","item":"carrots, thinly sliced on the diagonal"},{"amount":"1","unit":"","item":"red pepper, sliced"},{"amount":"6","unit":"oz","item":"mangetout"},{"amount":"4","unit":"oz","item":"shiitake mushrooms, sliced"},{"amount":"3","unit":"cloves","item":"garlic, minced"},{"amount":"1","unit":"inch","item":"ginger, grated"},{"amount":"3","unit":"tbsp","item":"soy sauce"},{"amount":"1","unit":"tbsp","item":"oyster sauce"},{"amount":"1","unit":"tsp","item":"toasted sesame oil"},{"amount":"1","unit":"tsp","item":"cornstarch"},{"amount":"3","unit":"tbsp","item":"water"},{"amount":"","unit":"","item":"Scallions and sesame seeds"}]'::JSONB, '[{"step":1,"title":"Prep everything first","instruction":"Cut all the vegetables and mix the sauce before the pan goes on. A stir-fry takes six minutes and there is no time to chop mid-cook.","tip":"Everything within arm''s reach before the heat goes on. This is the whole discipline of stir-frying."},{"step":2,"title":"Mix the sauce in advance","instruction":"Whisk the soy sauce, oyster sauce, sesame oil, cornstarch, and water together."},{"step":3,"title":"Get the pan properly hot","instruction":"Heat a wok or wide pan over the highest heat until the oil shimmers and just begins to smoke."},{"step":4,"title":"Add by density","instruction":"Carrots and broccoli first for 2 minutes, then pepper and mushrooms for 2 minutes, then mangetout for 1 minute. Keep everything moving.","tip":"Adding everything at once gives you burnt mangetout and raw carrot."},{"step":5,"title":"Aromatics late","instruction":"Add the garlic and ginger for the final 30 seconds only — added early they burn in the high heat."},{"step":6,"title":"Sauce at the end","instruction":"Pour the sauce around the rim of the pan and toss for 45 seconds until it thickens and coats. Finish with scallions and sesame seeds."}]'::JSONB, 'Cook in two batches if your burner is weak or the pan is small — a crowded pan drops in temperature and the vegetables steam into a soggy pile. Vegetables should stay bright and slightly crunchy.', ARRAY['Vegan: Use a vegetarian stir-fry sauce or mushroom sauce in place of oyster sauce.','Add protein: Cook chicken, beef, or tofu first, remove, and return at the end.','Gluten-free: Tamari and a GF oyster sauce.']::TEXT[], ARRAY['Soy','Sesame','Gluten']::TEXT[]),
('greek-salad', 'Greek Salad', 'No lettuce — just tomato, cucumber, onion, olives, and a slab of feta, dressed simply.', 'https://images.unsplash.com/photo-1727618534372-ddc94e872d04', 'Fresh Greek salad with cucumber, tomatoes, olives, feta, and oregano', 'Sofia Patel', '@sofiapatelkitchen', 'https://images.unsplash.com/photo-1716947674021-1b8b696325c7', 'Portrait of food creator Sofia Patel', '10 min', '—', '10 min', 10, 0, 10, 4, 'Easy', 'Greek', 'Lunch', 'Salad', ARRAY['Vegetarian','No-Cook','Gluten-Free','Summer']::TEXT[], 4.5, 401, 4763, 286, 9, 14, 22, 3, '[{"amount":"4","unit":"","item":"ripe tomatoes, cut into wedges"},{"amount":"1","unit":"","item":"cucumber, thickly sliced"},{"amount":"1","unit":"","item":"green pepper, sliced"},{"amount":"0.5","unit":"","item":"red onion, thinly sliced"},{"amount":"0.75","unit":"cup","item":"Kalamata olives"},{"amount":"7","unit":"oz","item":"block feta"},{"amount":"4","unit":"tbsp","item":"extra virgin olive oil"},{"amount":"1","unit":"tbsp","item":"red wine vinegar"},{"amount":"1","unit":"tsp","item":"dried oregano"},{"amount":"","unit":"","item":"Salt and black pepper"}]'::JSONB, '[{"step":1,"title":"No lettuce","instruction":"A traditional horiatiki contains no leaves at all. Lettuce dilutes it and goes limp in the dressing."},{"step":2,"title":"Cut everything chunky","instruction":"Cut the vegetables into large, rustic pieces. Fine dicing turns this into a salsa."},{"step":3,"title":"Salt the tomatoes first","instruction":"Salt the tomato wedges and leave 10 minutes. They release juice that becomes part of the dressing.","tip":"That tomato juice mixing with the olive oil is the actual dressing. Do not drain it away."},{"step":4,"title":"Feta goes on whole","instruction":"Place the feta on top as a single slab rather than crumbling it, then drizzle with oil and dust with oregano."},{"step":5,"title":"Dress at the table","instruction":"Add the olive oil, vinegar, and pepper just before serving and toss lightly, leaving the feta on top."}]'::JSONB, 'Use block feta in brine rather than pre-crumbled, and good ripe tomatoes — with this few ingredients there is nowhere to hide. Serve with bread to mop up the juices at the bottom.', ARRAY['Vegan: A plant feta, or skip it and add extra olives and capers.','Add: Capers, fresh dill, or a pinch of chilli flakes.','Do not make ahead: It weeps within 20 minutes of dressing.']::TEXT[], ARRAY['Dairy']::TEXT[]),
('chicken-caesar-wrap', 'Chicken Caesar Wrap', 'Grilled chicken, crisp romaine, parmesan, and a proper anchovy Caesar dressing in a tortilla.', 'https://images.unsplash.com/photo-1666819476544-38ea4e57a3d0', 'Grilled chicken Caesar wrap with romaine, parmesan, and Caesar dressing', 'Jake Torres', '@jaketorrescooks', 'https://images.unsplash.com/photo-1572015837827-01671d41e102', 'Portrait of food creator Jake Torres', '15 min', '5 min', '20 min', 15, 5, 20, 4, 'Easy', 'American', 'Lunch', 'Main Course', ARRAY['Quick','High Protein','Meal Prep']::TEXT[], 5.0, 421, 5236, 582, 38, 42, 28, 3, '[{"amount":"2","unit":"","item":"chicken breasts"},{"amount":"4","unit":"","item":"large flour tortillas"},{"amount":"1","unit":"","item":"romaine lettuce, shredded"},{"amount":"0.75","unit":"cup","item":"grated parmesan"},{"amount":"1","unit":"cup","item":"croutons"},{"amount":"4","unit":"tbsp","item":"mayonnaise"},{"amount":"4","unit":"","item":"anchovy fillets, minced"},{"amount":"1","unit":"clove","item":"garlic, grated"},{"amount":"1","unit":"tbsp","item":"lemon juice"},{"amount":"1","unit":"tsp","item":"Dijon mustard"},{"amount":"1","unit":"tbsp","item":"olive oil"},{"amount":"","unit":"","item":"Salt and black pepper"}]'::JSONB, '[{"step":1,"title":"Use the anchovies","instruction":"Mash the anchovies with the garlic into a paste. This is what makes a Caesar taste like a Caesar — it will not taste fishy, just deeply savoury.","tip":"Skipping the anchovies is why homemade Caesar dressing usually tastes flat."},{"step":2,"title":"Make the dressing","instruction":"Whisk the anchovy paste with the mayonnaise, lemon juice, Dijon, half the parmesan, and plenty of black pepper."},{"step":3,"title":"Cook the chicken","instruction":"Season and sear the chicken in oil for 6 minutes a side until 165°F internal. Rest 5 minutes before slicing."},{"step":4,"title":"Dress the lettuce only","instruction":"Toss the shredded romaine with the dressing just before assembling. Dressed lettuce goes limp within minutes."},{"step":5,"title":"Roll tight","instruction":"Warm the tortillas briefly, lay the filling slightly below centre, fold in the sides, and roll firmly. Cut on the diagonal."}]'::JSONB, 'For packed lunches, keep the dressing separate and combine at the last minute, or the wrap turns soggy. Rotisserie chicken makes this a five-minute assembly job.', ARRAY['Vegetarian: Crispy chickpeas or halloumi in place of the chicken; use a vegetarian Worcestershire and skip the anchovy.','Lighter: Swap half the mayonnaise for Greek yoghurt.','Salad version: Skip the wrap entirely and serve as a classic Caesar.']::TEXT[], ARRAY['Gluten','Egg','Fish','Dairy','Mustard']::TEXT[]),
('tomato-soup', 'Tomato Soup', 'Tinned tomatoes, onion, and stock simmered and blended smooth. The version that belongs with grilled cheese.', 'https://images.unsplash.com/photo-1616537380218-372f4d2830ee', 'Creamy tomato soup with fresh basil and a swirl of cream in a bowl', 'Emma Walsh', '@emmawalshbakes', '', '', '8 min', '17 min', '25 min', 8, 17, 25, 4, 'Easy', 'American', 'Lunch', 'Soup', ARRAY['Vegetarian','Comfort','Budget','Freezer-Friendly']::TEXT[], 4.3, 1173, 4410, 242, 6, 26, 14, 4, '[{"amount":"3","unit":"tbsp","item":"butter"},{"amount":"1","unit":"","item":"onion, diced"},{"amount":"4","unit":"cloves","item":"garlic, minced"},{"amount":"2","unit":"tbsp","item":"tomato paste"},{"amount":"28","unit":"oz","item":"tinned whole tomatoes"},{"amount":"2","unit":"cups","item":"vegetable stock"},{"amount":"1","unit":"tsp","item":"sugar"},{"amount":"0.33","unit":"cup","item":"heavy cream"},{"amount":"0.25","unit":"cup","item":"fresh basil"},{"amount":"","unit":"","item":"Salt and black pepper"}]'::JSONB, '[{"step":1,"title":"Soften the onion properly","instruction":"Cook the onion in the butter for 8 minutes until soft and translucent. Rushing this leaves a raw onion edge in the finished soup."},{"step":2,"title":"Darken the tomato paste","instruction":"Add the garlic and tomato paste and cook 2 minutes until the paste turns brick red. This removes its tinny taste and deepens the flavour.","tip":"Two minutes of frying the paste makes a noticeable difference."},{"step":3,"title":"Simmer","instruction":"Add the tomatoes, stock, and sugar, breaking the tomatoes up with a spoon. Simmer 20 minutes."},{"step":4,"title":"Blend thoroughly","instruction":"Blend until completely smooth — a full two minutes. Under-blended tomato soup has a grainy, pulpy texture."},{"step":5,"title":"Finish off the heat","instruction":"Stir in the cream and torn basil off the heat and season. Boiling after the cream goes in can split it."}]'::JSONB, 'A pinch of sugar balances the acidity of tinned tomatoes; taste before adding more cream, which is the usual overcorrection. Freezes for 3 months — freeze before adding cream.', ARRAY['Vegan: Coconut cream or a cashew cream, and oil in place of butter.','Roasted version: Roast the tinned tomatoes at 425°F for 25 minutes first for more depth.','Serve: Grilled cheese, cut into soldiers.']::TEXT[], ARRAY['Dairy']::TEXT[]),
('scrambled-eggs', 'Scrambled Eggs', 'Low heat, constant movement, and pulled off early. The whole technique in three rules.', 'https://img.rocket.new/generatedImages/rocket_gen_img_1c29c00e3-1765572953934.png', 'Perfectly soft scrambled eggs with chives and butter on toast', 'Marco Rossi', '@marcorossicucina', '', '', '2 min', '8 min', '10 min', 2, 8, 10, 2, 'Easy', 'French', 'Breakfast', 'Breakfast', ARRAY['Quick','Vegetarian','Gluten-Free','Classic']::TEXT[], 4.5, 742, 1775, 286, 18, 2, 23, 0, '[{"amount":"5","unit":"large","item":"eggs"},{"amount":"2","unit":"tbsp","item":"butter"},{"amount":"1","unit":"tbsp","item":"crème fraîche"},{"amount":"","unit":"","item":"Salt and white pepper"},{"amount":"","unit":"","item":"Chives to finish"},{"amount":"","unit":"","item":"Buttered toast to serve"}]'::JSONB, '[{"step":1,"title":"Beat thoroughly","instruction":"Whisk the eggs until completely uniform with no streaks of white. Streaks cook into rubbery ribbons."},{"step":2,"title":"Salt at the end, not the start","instruction":"Salt added to raw eggs and left to sit draws out water and makes them weep. Season as they finish.","tip":"Salt at the end. This is the fix for watery scrambled eggs."},{"step":3,"title":"Low heat, always","instruction":"Melt the butter in a cold pan over low heat and add the eggs. Never use medium or high — heat is what turns scrambled eggs to rubber."},{"step":4,"title":"Stir constantly","instruction":"Stir continuously with a spatula, scraping the base and pulling the pan off the heat every 20 seconds or so. It takes 4–5 minutes and looks like nothing is happening until suddenly it does."},{"step":5,"title":"Pull them underdone","instruction":"Take them off the heat while they still look glossy and slightly runny. The residual heat finishes them on the way to the plate.","tip":"If they look perfect in the pan, they will be overcooked on the plate."},{"step":6,"title":"Finish","instruction":"Stir in the crème fraîche to stop the cooking, season, and serve immediately on buttered toast with chives."}]'::JSONB, 'Adding milk is common and unnecessary — it thins the eggs and makes them more likely to weep. A spoonful of crème fraîche at the end adds richness and halts the cooking at the same time.', ARRAY['Dairy-free: Olive oil in place of butter; skip the crème fraîche.','Add: Smoked salmon, chives, or grated cheese folded in at the very end.','Speed version: Medium-low and 2 minutes still beats high heat, if you are in a hurry.']::TEXT[], ARRAY['Egg','Dairy']::TEXT[]),
('blt-sandwich', 'BLT Sandwich', 'Crisp bacon, ripe tomato, cold lettuce, good mayonnaise, toasted bread. Nowhere to hide.', 'https://images.unsplash.com/photo-1618650180691-e53a882fb3c0', 'Classic BLT sandwich with crispy bacon, lettuce, and tomato on toasted bread', 'Jake Torres', '@jaketorrescooks', 'https://images.unsplash.com/photo-1572015837827-01671d41e102', 'Portrait of food creator Jake Torres', '10 min', '5 min', '15 min', 10, 5, 15, 2, 'Easy', 'American', 'Lunch', 'Main Course', ARRAY['Classic','Quick','Summer']::TEXT[], 4.6, 364, 4436, 512, 18, 34, 34, 3, '[{"amount":"8","unit":"slices","item":"streaky bacon"},{"amount":"4","unit":"slices","item":"good white or sourdough bread"},{"amount":"2","unit":"","item":"ripe tomatoes, thickly sliced"},{"amount":"4","unit":"leaves","item":"crisp iceberg or romaine"},{"amount":"4","unit":"tbsp","item":"good mayonnaise"},{"amount":"","unit":"","item":"Flaky salt and coarse black pepper"}]'::JSONB, '[{"step":1,"title":"Cook the bacon flat and crisp","instruction":"Bake the bacon on a rack at 400°F (205°C) for 18 minutes rather than frying it. It cooks flat, crisps evenly, and does not curl.","tip":"Oven bacon is flatter and crisper, which matters enormously in a sandwich."},{"step":2,"title":"Salt the tomatoes","instruction":"Slice the tomatoes thickly, lay them on paper, and salt them. Leave 10 minutes — they season through and shed the water that would otherwise soak the bread."},{"step":3,"title":"Toast the bread properly","instruction":"Toast until firmly crisp on both sides. Soft bread collapses under the filling."},{"step":4,"title":"Mayonnaise on every surface","instruction":"Spread mayonnaise on all four inner faces. It is both flavour and a waterproof barrier against the tomato.","tip":"Mayonnaise on both slices, edge to edge. This is what keeps the sandwich intact."},{"step":5,"title":"Layer in the right order","instruction":"Lettuce against the bottom slice, then bacon, then tomato, then lettuce again, then the lid. Lettuce top and bottom keeps the tomato away from the bread."},{"step":6,"title":"Cut and eat immediately","instruction":"Press gently, cut on the diagonal, and eat straight away."}]'::JSONB, 'This is entirely dependent on tomato quality, so it is a summer sandwich. Out of season, use good cherry tomatoes halved rather than pale beefsteak.', ARRAY['Add: Avocado, a fried egg, or a slice of sharp cheddar.','BLAT: Avocado makes it a BLAT and it is a genuine improvement.','Vegetarian: Smoked tempeh or well-crisped mushrooms.']::TEXT[], ARRAY['Gluten','Egg']::TEXT[]),
('hummus-veggie-plate', 'Hummus & Veggie Plate', 'Home-made hummus, properly smooth, with raw vegetables and warm pita.', 'https://images.unsplash.com/photo-1709551665288-d350b7445ae7', 'Creamy hummus with fresh cut vegetables and warm pita bread on a platter', 'Leila Hassan', '@leilahassantable', '', '', '10 min', '—', '10 min', 10, 0, 10, 6, 'Easy', 'Middle Eastern', 'Snack', 'Appetizer', ARRAY['Vegan','No-Cook','Party Food','Healthy']::TEXT[], 4.7, 1857, 9333, 286, 10, 32, 14, 8, '[{"amount":"2","unit":"cans","item":"chickpeas, drained"},{"amount":"0.5","unit":"cup","item":"tahini"},{"amount":"0.33","unit":"cup","item":"lemon juice"},{"amount":"2","unit":"cloves","item":"garlic"},{"amount":"0.5","unit":"tsp","item":"ground cumin"},{"amount":"4","unit":"tbsp","item":"ice water"},{"amount":"3","unit":"tbsp","item":"olive oil"},{"amount":"","unit":"","item":"Salt"},{"amount":"","unit":"","item":"Carrots, cucumber, peppers, and radishes"},{"amount":"","unit":"","item":"Warm pita"},{"amount":"","unit":"","item":"Paprika and parsley to garnish"}]'::JSONB, '[{"step":1,"title":"Whip the tahini first","instruction":"Blend the tahini, lemon juice, and garlic alone for 60 seconds before anything else. It seizes and then turns pale and fluffy — this is the base of smooth hummus.","tip":"Tahini and lemon first, on their own. This one step transforms the texture."},{"step":2,"title":"Peel the chickpeas (optional)","instruction":"For genuinely silky hummus, pinch the skins off the chickpeas. It takes ten minutes and is the difference between good and exceptional."},{"step":3,"title":"Blend long","instruction":"Add the chickpeas, cumin, and salt and blend a full 3 minutes, scraping down. Most people stop far too early."},{"step":4,"title":"Add ice water","instruction":"With the motor running, add the ice water a tablespoon at a time. Cold water is what makes hummus light and pale rather than dense and beige.","tip":"Ice water, not room temperature. It genuinely changes the colour and texture."},{"step":5,"title":"Serve with a well","instruction":"Spread into a shallow bowl, make a swirl with the back of a spoon, and pool olive oil in it. Dust with paprika and parsley and surround with vegetables and warm pita."}]'::JSONB, 'Hummus thickens in the fridge; loosen with a splash of water and stir before serving. Keeps 5 days. Warm the pita — cold pita makes the whole plate feel like an afterthought.', ARRAY['Flavours: Roasted red pepper, caramelised onion, or harissa swirled through.','Gluten-free: Serve with vegetables and GF crackers.','Speed: Skip peeling the chickpeas and blend 2 minutes longer instead.']::TEXT[], ARRAY['Sesame','Gluten']::TEXT[])
