INSERT INTO public.recipes (slug, title, description, image, image_alt, creator_name, creator_handle, creator_image, creator_alt, prep_time, cook_time, total_time, prep_minutes, cook_minutes, total_minutes, servings, difficulty, cuisine, meal_type, category, tags, rating, reviews, cooks, calories, protein, carbs, fat, fiber, ingredients, steps, notes, tips, allergens) VALUES
('smash-burger', 'Smash Burger', 'A loose ball of beef pressed thin onto a screaming griddle for maximum crust. Fifteen minutes.', 'https://img.rocket.new/generatedImages/rocket_gen_img_115ac9fe5-1772550917596.png', 'Crispy smash burger with caramelized onions and special sauce on a bun', 'Jake Torres', '@jaketorrescooks', 'https://images.unsplash.com/photo-1572015837827-01671d41e102', 'Portrait of food creator Jake Torres', '5 min', '10 min', '15 min', 5, 10, 15, 4, 'Easy', 'American', 'Dinner', 'Main Course', ARRAY['Quick','Classic','High Protein']::TEXT[], 4.6, 1730, 9309, 648, 36, 34, 42, 2, '[{"amount":"1.5","unit":"lb","item":"ground beef (80/20)"},{"amount":"8","unit":"slices","item":"American cheese"},{"amount":"4","unit":"","item":"soft potato or brioche buns"},{"amount":"1","unit":"","item":"white onion, very thinly sliced"},{"amount":"4","unit":"tbsp","item":"burger sauce"},{"amount":"8","unit":"slices","item":"dill pickle"},{"amount":"2","unit":"tbsp","item":"butter"},{"amount":"","unit":"","item":"Salt and coarse black pepper"}]'::JSONB, '[{"step":1,"title":"Portion loosely","instruction":"Divide the beef into 8 loose 3 oz balls. Do not compact them — a loose ball spreads thinner and crusts better.","tip":"Never work the meat. Compacted beef makes a dense, springy burger."},{"step":2,"title":"Toast the buns in butter","instruction":"Butter the cut faces and toast in a dry pan until deep golden. This is both flavour and a moisture barrier."},{"step":3,"title":"Get the surface screaming","instruction":"Heat a cast iron pan or griddle over the highest heat until it genuinely smokes."},{"step":4,"title":"Smash once and hard","instruction":"Put a ball on the hot surface and press down firmly with a stiff spatula for 10 seconds until it is about a quarter inch thick. Season heavily.","tip":"One press, held for ten seconds. Pressing again later just squeezes the juice out."},{"step":5,"title":"Scrape, do not lift","instruction":"Cook 90 seconds until the edges are brown and lacy, then get right under the crust with a sharp-edged spatula and scrape it off. That crust is the entire point."},{"step":6,"title":"Cheese and stack","instruction":"Flip, lay on cheese, and cook 30 seconds more. Stack two patties per bun with sauce, onion, and pickles."}]'::JSONB, 'Two thin patties beat one thick one — twice the crust for the same amount of beef. This produces a lot of smoke; open a window and turn the extractor on before you start.', ARRAY['Onions: Press thinly sliced onion into the raw patty before smashing for an Oklahoma-style burger.','Batch: Cook two at a time so the surface stays hot.','Sauce: Equal parts mayonnaise and ketchup with a spoonful of pickle relish.']::TEXT[], ARRAY['Gluten','Dairy','Egg']::TEXT[]),
('teriyaki-salmon', 'Teriyaki Salmon', 'Salmon glazed in a real teriyaki that reduces to a lacquer in the pan. Twenty minutes.', 'https://img.rocket.new/generatedImages/rocket_gen_img_17e323e40-1772187607252.png', 'Glazed teriyaki salmon with steamed rice and sesame seeds', 'Yuki Tanaka', '@yukitanakaumami', '', '', '5 min', '15 min', '20 min', 5, 15, 20, 4, 'Easy', 'Japanese', 'Dinner', 'Main Course', ARRAY['Seafood','Quick','Gluten-Free-Adaptable','High Protein']::TEXT[], 4.5, 148, 1697, 412, 38, 14, 22, 0, '[{"amount":"4","unit":"fillets","item":"salmon, skin on (6 oz each)"},{"amount":"0.33","unit":"cup","item":"soy sauce"},{"amount":"0.25","unit":"cup","item":"mirin"},{"amount":"2","unit":"tbsp","item":"sake"},{"amount":"2","unit":"tbsp","item":"brown sugar"},{"amount":"1","unit":"tsp","item":"grated ginger"},{"amount":"1","unit":"tbsp","item":"neutral oil"},{"amount":"2","unit":"","item":"scallions, sliced"},{"amount":"1","unit":"tbsp","item":"toasted sesame seeds"},{"amount":"","unit":"","item":"Steamed rice to serve"}]'::JSONB, '[{"step":1,"title":"Make the sauce first","instruction":"Combine the soy sauce, mirin, sake, sugar, and ginger. Bottled teriyaki is mostly corn syrup; this takes a minute and is far better."},{"step":2,"title":"Dry the fillets","instruction":"Pat the salmon completely dry. Wet fish will not brown and the glaze will slide off."},{"step":3,"title":"Sear skin-side down","instruction":"Cook skin-side down in the oil over medium-high for 4 minutes without moving it, until the skin is crisp and releases on its own.","tip":"Do not move the fish. It lets go when the skin is ready."},{"step":4,"title":"Flip briefly","instruction":"Turn and cook 2 minutes on the flesh side."},{"step":5,"title":"Reduce the glaze","instruction":"Pour in the sauce and let it bubble for 2–3 minutes, spooning it over the fish, until it thickens into a syrup that coats.","tip":"Watch it closely — the sugar goes from glossy to burnt in under a minute."},{"step":6,"title":"Rest and serve","instruction":"Rest 2 minutes, then serve skin-side up over rice with the pan glaze, scallions, and sesame seeds."}]'::JSONB, 'Pull the salmon at around 125°F for a moist medium. If the glaze thickens too far, a splash of water brings it back. No sake or mirin? Use rice vinegar and an extra teaspoon of sugar.', ARRAY['Gluten-free: Tamari in place of soy sauce.','Oven: Bake at 400°F for 12 minutes, brushing with the reduced glaze twice.','Chicken: The same glaze on thighs, 6 minutes a side.']::TEXT[], ARRAY['Fish','Soy','Sesame']::TEXT[]),
('chicken-stir-fry', 'Chicken Stir Fry', 'Velveted chicken and vegetables cooked hard and fast with the sauce added at the end.', 'https://images.unsplash.com/photo-1571872837344-0bcb9f0dcd24', 'Quick chicken stir fry with colorful vegetables and savory sauce', 'Lin Wei', '@linweiwok', '', '', '15 min', '5 min', '20 min', 15, 5, 20, 4, 'Easy', 'Chinese', 'Dinner', 'Main Course', ARRAY['Quick','High Protein','Family','Balanced']::TEXT[], 4.8, 1695, 2944, 412, 36, 24, 19, 4, '[{"amount":"1.5","unit":"lb","item":"chicken breast or thigh, thinly sliced"},{"amount":"1","unit":"tbsp","item":"cornstarch for the chicken"},{"amount":"1","unit":"tbsp","item":"soy sauce for the chicken"},{"amount":"3","unit":"tbsp","item":"neutral oil"},{"amount":"1","unit":"","item":"broccoli head, in florets"},{"amount":"1","unit":"","item":"red pepper, sliced"},{"amount":"2","unit":"","item":"carrots, thinly sliced"},{"amount":"4","unit":"cloves","item":"garlic, minced"},{"amount":"1","unit":"inch","item":"ginger, grated"},{"amount":"4","unit":"tbsp","item":"soy sauce"},{"amount":"2","unit":"tbsp","item":"oyster sauce"},{"amount":"1","unit":"tbsp","item":"rice vinegar"},{"amount":"1","unit":"tsp","item":"toasted sesame oil"},{"amount":"1","unit":"tsp","item":"cornstarch"},{"amount":"4","unit":"tbsp","item":"water"},{"amount":"","unit":"","item":"Scallions"}]'::JSONB, '[{"step":1,"title":"Velvet the chicken","instruction":"Toss the sliced chicken with a tablespoon each of cornstarch and soy sauce and leave 15 minutes. This coating keeps it tender through high-heat cooking.","tip":"Velveting is why restaurant stir-fried chicken is silky and home versions are often dry."},{"step":2,"title":"Mix the sauce in advance","instruction":"Whisk the soy sauce, oyster sauce, rice vinegar, sesame oil, cornstarch, and water together and set it by the hob."},{"step":3,"title":"Sear the chicken and remove","instruction":"Cook the chicken in 2 tbsp oil over the highest heat in two batches, 3 minutes each, until browned. Remove — it finishes later."},{"step":4,"title":"Vegetables by density","instruction":"Add the remaining oil, then the carrots and broccoli for 3 minutes, then the pepper for 2 minutes. Keep everything moving."},{"step":5,"title":"Aromatics late, sauce last","instruction":"Add the garlic and ginger for 30 seconds, return the chicken, then pour the sauce around the rim of the pan and toss for a minute until it thickens and coats."}]'::JSONB, 'Two batches for the chicken is important — a crowded pan drops in temperature and the meat steams grey instead of browning. Have everything prepped before the heat goes on.', ARRAY['Gluten-free: Tamari and a GF oyster sauce.','Vegetarian: Velvet cubes of firm tofu the same way.','Vegetables: Whatever is in the fridge; just add by cooking time.']::TEXT[], ARRAY['Soy','Sesame','Gluten']::TEXT[]),
('grilled-cheese', 'Grilled Cheese', 'Mayonnaise on the outside instead of butter, low heat, and two cheeses. The technical version.', 'https://images.unsplash.com/photo-1619096252214-ef06c45683e3', 'Golden grilled cheese sandwich with melted cheddar and sourdough bread', 'Emma Walsh', '@emmawalshbakes', '', '', '5 min', '5 min', '10 min', 5, 5, 10, 2, 'Easy', 'American', 'Lunch', 'Main Course', ARRAY['Quick','Comfort','Vegetarian','Kid Friendly']::TEXT[], 4.9, 559, 913, 548, 22, 34, 36, 2, '[{"amount":"4","unit":"slices","item":"good white or sourdough bread"},{"amount":"1.5","unit":"cups","item":"grated sharp cheddar"},{"amount":"0.5","unit":"cup","item":"grated gruyere or mozzarella"},{"amount":"3","unit":"tbsp","item":"mayonnaise"},{"amount":"1","unit":"tbsp","item":"butter"},{"amount":"1","unit":"tsp","item":"Dijon mustard"},{"amount":"","unit":"","item":"Black pepper"}]'::JSONB, '[{"step":1,"title":"Mayonnaise on the outside","instruction":"Spread mayonnaise, not butter, on the outer faces. It has a higher smoke point, spreads evenly on cold bread, and browns more consistently.","tip":"This sounds wrong and is the single best grilled cheese tip there is."},{"step":2,"title":"Use two cheeses","instruction":"Combine a sharp cheese for flavour with a good melter for texture. Cheddar alone can turn oily and split."},{"step":3,"title":"Grate, do not slice","instruction":"Grated cheese melts far faster and more evenly than slices, which matters when you are cooking on low heat."},{"step":4,"title":"Mustard inside","instruction":"Spread a thin layer of Dijon on the inner faces. It cuts the richness and you will not taste it as mustard."},{"step":5,"title":"Low heat, lid on","instruction":"Cook over medium-low for 4 minutes a side, covered for the first half, so the cheese melts fully before the bread over-browns.","tip":"Patience is the whole thing. High heat gives burnt bread around unmelted cheese."},{"step":6,"title":"Rest before cutting","instruction":"Rest 1 minute so the cheese sets slightly, then cut diagonally."}]'::JSONB, 'Pre-grated cheese is coated in starch and melts poorly — grate your own. If the bread browns before the cheese melts, the heat is too high; take the pan off for 30 seconds and lower it.', ARRAY['Add: Caramelised onion, kimchi, sliced apple, or crisp bacon.','Serve: Tomato soup, obviously.','Vegan: Plant cheese, vegan mayonnaise, and a longer covered cook.']::TEXT[], ARRAY['Gluten','Dairy','Egg']::TEXT[]),
('veggie-wrap', 'Veggie Wrap', 'Hummus, roast vegetables, and greens rolled tight — built so it does not fall apart at lunchtime.', 'https://img.rocket.new/generatedImages/rocket_gen_img_1659deaf4-1772094601560.png', 'Fresh veggie wrap with hummus, roasted vegetables, and feta cheese', 'Priya Nair', '@priyanairkitchen', '', '', '10 min', '—', '10 min', 10, 0, 10, 4, 'Easy', 'Mediterranean', 'Lunch', 'Main Course', ARRAY['Vegan-Adaptable','Meal Prep','Healthy','Quick']::TEXT[], 4.7, 1527, 2065, 412, 13, 52, 18, 9, '[{"amount":"4","unit":"","item":"large flour tortillas"},{"amount":"0.75","unit":"cup","item":"hummus"},{"amount":"1","unit":"","item":"red pepper, roasted and sliced"},{"amount":"1","unit":"","item":"courgette, roasted"},{"amount":"1","unit":"","item":"carrot, grated"},{"amount":"1","unit":"","item":"avocado, sliced"},{"amount":"2","unit":"cups","item":"baby spinach"},{"amount":"0.5","unit":"cup","item":"crumbled feta"},{"amount":"2","unit":"tbsp","item":"tahini sauce"},{"amount":"1","unit":"tbsp","item":"lemon juice"},{"amount":"","unit":"","item":"Salt, pepper, and chilli flakes"}]'::JSONB, '[{"step":1,"title":"Warm the tortillas","instruction":"Heat each tortilla for 15 seconds a side in a dry pan. Cold tortillas crack and split when rolled."},{"step":2,"title":"Hummus as the barrier","instruction":"Spread hummus across the whole tortilla, right to the edges. It seals the surface against moisture and acts as glue.","tip":"The hummus layer is structural. It is why the wrap holds together."},{"step":3,"title":"Dry the vegetables","instruction":"Pat the roasted vegetables dry. Any excess oil or moisture will make the wrap fall apart within an hour."},{"step":4,"title":"Layer below centre","instruction":"Pile the filling in a line slightly below the middle, leaving clear margins on all sides. Overfilling is the main cause of blowouts."},{"step":5,"title":"Fold sides then roll tight","instruction":"Fold in the left and right sides first, then roll from the bottom up, tucking firmly as you go."},{"step":6,"title":"Rest seam-down","instruction":"Rest seam-side down for a minute before cutting, or wrap in parchment for a packed lunch."}]'::JSONB, 'For lunchboxes, wrap tightly in parchment and cut through the paper — it holds the whole thing together until it is eaten. Keeps a day; beyond that the tortilla softens.', ARRAY['Vegan: Skip the feta and add extra avocado or olives.','Add protein: Falafel, grilled halloumi, or crisped chickpeas.','Gluten-free: A large GF wrap or collard leaves.']::TEXT[], ARRAY['Gluten','Sesame','Dairy']::TEXT[]),
('fried-rice', 'Fried Rice', 'Cold day-old rice, a screaming pan, and soy added around the rim so it caramelises.', 'https://img.rocket.new/generatedImages/rocket_gen_img_14631f803-1772367083673.png', 'Classic fried rice with vegetables, egg, and soy sauce in a wok', 'Lin Wei', '@linweiwok', '', '', '10 min', '10 min', '20 min', 10, 10, 20, 4, 'Easy', 'Chinese', 'Dinner', 'Main Course', ARRAY['Quick','Budget','Leftovers','Vegetarian-Adaptable']::TEXT[], 4.7, 1313, 8010, 386, 12, 56, 12, 3, '[{"amount":"4","unit":"cups","item":"cooked rice, cold (day-old)"},{"amount":"3","unit":"large","item":"eggs, beaten"},{"amount":"3","unit":"tbsp","item":"neutral oil"},{"amount":"4","unit":"","item":"scallions, whites and greens separated"},{"amount":"3","unit":"cloves","item":"garlic, minced"},{"amount":"1","unit":"cup","item":"frozen peas and carrots"},{"amount":"2","unit":"tbsp","item":"light soy sauce"},{"amount":"1","unit":"tsp","item":"dark soy sauce"},{"amount":"1","unit":"tsp","item":"toasted sesame oil"},{"amount":"0.5","unit":"tsp","item":"white pepper"},{"amount":"","unit":"","item":"Salt"}]'::JSONB, '[{"step":1,"title":"Cold rice only","instruction":"Day-old refrigerated rice is essential. Fresh rice steams and turns to porridge in the pan.","tip":"No cold rice? Spread fresh rice on a tray and freeze 30 minutes to dry the surface."},{"step":2,"title":"Break up every clump","instruction":"Work through the rice with wet hands until the grains are fully separated."},{"step":3,"title":"Scramble the egg first","instruction":"Scramble the beaten egg in a tablespoon of oil until just set, then remove it from the pan."},{"step":4,"title":"Fry the aromatics","instruction":"Add the rest of the oil, then the scallion whites and garlic for 30 seconds, then the peas and carrots for a minute."},{"step":5,"title":"Press and toss the rice","instruction":"Add the rice and press it against the hot pan, then toss. Keep pressing and tossing for 4 minutes on maximum heat until the grains pop and lightly colour.","tip":"Maximum heat throughout. Low heat steams rice instead of frying it."},{"step":6,"title":"Soy around the rim","instruction":"Pour both soy sauces around the edge of the pan so they sizzle and caramelise before hitting the rice. Return the egg, add sesame oil, white pepper, and scallion greens."}]'::JSONB, 'Adding the soy sauce around the rim rather than into the middle is a small thing that makes a real difference — it caramelises on the hot metal instead of pooling and steaming.', ARRAY['Add protein: Char siu, shrimp, or leftover roast chicken.','Vegan: Skip the egg; add crumbled fried tofu.','Batch: Cook in two rounds if your burner is weak.']::TEXT[], ARRAY['Egg','Soy','Sesame']::TEXT[]),
('chicken-salad', 'Chicken Salad', 'Poached chicken shredded into a light dressing with grapes, celery, and tarragon.', 'https://images.unsplash.com/photo-1614187860064-8c0442c793c5', 'Classic chicken salad with celery, mayo, and herbs on lettuce', 'Emma Walsh', '@emmawalshbakes', '', '', '15 min', '—', '15 min', 15, 0, 15, 4, 'Easy', 'American', 'Lunch', 'Salad', ARRAY['High Protein','Make-Ahead','Gluten-Free-Adaptable']::TEXT[], 4.6, 1422, 7831, 386, 32, 12, 24, 2, '[{"amount":"1.5","unit":"lb","item":"chicken breasts"},{"amount":"4","unit":"tbsp","item":"mayonnaise"},{"amount":"2","unit":"tbsp","item":"Greek yoghurt"},{"amount":"1","unit":"tbsp","item":"Dijon mustard"},{"amount":"2","unit":"stalks","item":"celery, finely diced"},{"amount":"1","unit":"cup","item":"red grapes, halved"},{"amount":"0.33","unit":"cup","item":"toasted pecans, chopped"},{"amount":"2","unit":"","item":"scallions, sliced"},{"amount":"1","unit":"tbsp","item":"lemon juice"},{"amount":"1","unit":"tbsp","item":"chopped tarragon"},{"amount":"","unit":"","item":"Salt and black pepper"}]'::JSONB, '[{"step":1,"title":"Poach gently","instruction":"Cover the chicken with cold water, bring to a bare simmer, then turn the heat off entirely and cover for 15 minutes.","tip":"Poaching in residual heat is what keeps the breast tender. Boiling makes it stringy."},{"step":2,"title":"Cool in the liquid","instruction":"Let the chicken cool in its poaching water for 10 minutes; it reabsorbs moisture and stays juicy."},{"step":3,"title":"Shred, do not chop","instruction":"Pull the chicken into rough shreds with two forks. Shredded chicken holds dressing far better than neat dice."},{"step":4,"title":"Mix the dressing separately","instruction":"Whisk the mayonnaise, yoghurt, Dijon, lemon juice, salt, and pepper before it meets the chicken, so it seasons evenly."},{"step":5,"title":"Fold everything together","instruction":"Combine the chicken, dressing, celery, grapes, pecans, scallions, and tarragon. Chill 30 minutes before serving."}]'::JSONB, 'The grapes are not optional in my view — the sweetness and burst of juice cut through the mayonnaise. Keeps 3 days refrigerated and is better after a couple of hours.', ARRAY['Shortcut: Rotisserie chicken works perfectly and skips the poaching.','Lighter: All Greek yoghurt instead of mayonnaise, with an extra squeeze of lemon.','Serve: In sandwiches, lettuce cups, or on crackers.']::TEXT[], ARRAY['Egg','Tree Nut','Mustard','Celery']::TEXT[]),
('garlic-bread', 'Garlic Bread', 'A loaf split, filled with garlic herb butter, wrapped in foil, then opened to crisp.', 'https://images.unsplash.com/photo-1690196471135-72cc6a39ee5b', 'Crispy garlic bread with butter, garlic, and fresh parsley', 'Marco Rossi', '@marcorossicucina', '', '', '8 min', '2 min', '10 min', 8, 2, 10, 6, 'Easy', 'Italian', 'Snack', 'Side Dish', ARRAY['Vegetarian','Quick','Family','Party Food']::TEXT[], 4.7, 1309, 4264, 312, 7, 34, 17, 2, '[{"amount":"1","unit":"","item":"ciabatta or baguette"},{"amount":"0.5","unit":"cup","item":"softened butter"},{"amount":"6","unit":"cloves","item":"garlic, minced"},{"amount":"0.33","unit":"cup","item":"chopped parsley"},{"amount":"0.5","unit":"cup","item":"grated parmesan"},{"amount":"1","unit":"tsp","item":"dried oregano"},{"amount":"","unit":"","item":"Salt and black pepper"},{"amount":"","unit":"","item":"Chilli flakes (optional)"}]'::JSONB, '[{"step":1,"title":"Use raw garlic, minced fine","instruction":"Mince the garlic as finely as you can, or grate it. Chunks of garlic scorch and turn acrid in the oven.","tip":"Fine mince or grated. Chopped garlic burns."},{"step":2,"title":"Make a compound butter","instruction":"Mash the softened butter with the garlic, parsley, half the parmesan, oregano, salt, and pepper until fully combined."},{"step":3,"title":"Cut without going through","instruction":"Slice the loaf at 1-inch intervals but stop just short of the base, so it stays in one piece and holds the butter."},{"step":4,"title":"Push butter into every cut","instruction":"Work the butter right down into each slit rather than spreading it on top, so the inside is buttery, not just the crust."},{"step":5,"title":"Bake wrapped, then open","instruction":"Wrap in foil and bake at 400°F (205°C) for 15 minutes, then open the foil, scatter the remaining parmesan, and bake 6 minutes more until crisp and golden.","tip":"Wrapped first steams the inside soft; opened at the end crisps the top. Both stages matter."}]'::JSONB, 'The compound butter keeps a week refrigerated or freezes for 3 months — worth making a double batch. Ciabatta gives a chewier result, baguette a crisper one.', ARRAY['Cheesy: Pile mozzarella on top for the final 6 minutes.','Vegan: Plant butter and nutritional yeast.','Air fryer: 380°F for 6 minutes, unwrapped.']::TEXT[], ARRAY['Gluten','Dairy']::TEXT[]),
('omelette', 'Omelette', 'A French omelette — low heat, constant agitation, rolled and pale rather than browned.', 'https://img.rocket.new/generatedImages/rocket_gen_img_109193e74-1772618738820.png', 'Fluffy French omelette with herbs, cheese, and mushrooms', 'Marco Rossi', '@marcorossicucina', '', '', '3 min', '7 min', '10 min', 3, 7, 10, 1, 'Easy', 'French', 'Breakfast', 'Breakfast', ARRAY['Quick','Vegetarian','Gluten-Free','Classic']::TEXT[], 4.2, 232, 1023, 312, 19, 2, 26, 0, '[{"amount":"3","unit":"large","item":"eggs"},{"amount":"2","unit":"tbsp","item":"butter"},{"amount":"1","unit":"tbsp","item":"chopped chives"},{"amount":"","unit":"","item":"Salt and white pepper"}]'::JSONB, '[{"step":1,"title":"Beat until completely smooth","instruction":"Whisk the eggs for 30 seconds until absolutely uniform — no streaks of white at all. Streaks show up as pale rubbery patches."},{"step":2,"title":"Low heat, non-stick pan","instruction":"Melt the butter over low heat until it foams but does not colour. A browned omelette is an American omelette, not a French one.","tip":"If the butter browns, the pan is too hot. Start again."},{"step":3,"title":"Agitate constantly","instruction":"Pour in the eggs and immediately stir with a spatula while shaking the pan, keeping the curds tiny and the mixture moving for about 45 seconds."},{"step":4,"title":"Stop and settle","instruction":"When it is mostly set but still wet on top, stop stirring and let it sit for 15 seconds to form a base."},{"step":5,"title":"Roll, do not fold","instruction":"Tilt the pan away from you and use the spatula to roll the omelette over on itself from the far edge, letting it fold into a cigar shape as it slides to the pan edge.","tip":"Roll it out of the pan onto the plate in one motion — the seam ends up underneath."},{"step":6,"title":"Finish","instruction":"Turn onto a plate seam-side down, rub the top with a little butter for shine, and scatter with chives."}]'::JSONB, 'A proper French omelette is pale yellow with no browning at all and slightly runny in the centre (baveuse). It takes practice — the first several will be fine but not beautiful, which is normal.', ARRAY['Fillings: Add cheese or herbs just before rolling; do not overfill.','American style: Higher heat, let it set flat, fill one half and fold over.','Pan: A well-seasoned 8-inch non-stick pan makes this far easier.']::TEXT[], ARRAY['Egg','Dairy']::TEXT[]),
('chickpea-salad', 'Chickpea Salad', 'Chickpeas with cucumber, tomato, herbs, and lemon — better after an hour in the fridge.', 'https://images.unsplash.com/photo-1573147110754-55d038bee946', 'Mediterranean chickpea salad with cucumber, tomatoes, feta, and herbs', 'Leila Hassan', '@leilahassantable', '', '', '10 min', '—', '10 min', 10, 0, 10, 4, 'Easy', 'Middle Eastern', 'Lunch', 'Salad', ARRAY['Vegan','Gluten-Free','Meal Prep','High Fibre']::TEXT[], 4.3, 613, 4028, 312, 12, 38, 13, 10, '[{"amount":"2","unit":"cans","item":"chickpeas, drained and rinsed"},{"amount":"1","unit":"","item":"cucumber, diced"},{"amount":"2","unit":"","item":"tomatoes, diced"},{"amount":"0.5","unit":"","item":"red onion, finely diced"},{"amount":"1","unit":"cup","item":"chopped parsley"},{"amount":"0.5","unit":"cup","item":"chopped mint"},{"amount":"4","unit":"tbsp","item":"extra virgin olive oil"},{"amount":"3","unit":"tbsp","item":"lemon juice"},{"amount":"1","unit":"clove","item":"garlic, grated"},{"amount":"1","unit":"tsp","item":"ground cumin"},{"amount":"","unit":"","item":"Salt and black pepper"}]'::JSONB, '[{"step":1,"title":"Dry the chickpeas","instruction":"Rinse and dry the chickpeas thoroughly. Wet chickpeas dilute the dressing and taste of the tin."},{"step":2,"title":"Crush a few","instruction":"Lightly crush about a quarter of the chickpeas with a fork. They break down slightly and thicken the dressing so it clings.","tip":"This small step is what stops the dressing pooling at the bottom of the bowl."},{"step":3,"title":"Salt the vegetables separately","instruction":"Salt the diced cucumber and tomato and leave 10 minutes, then drain off the liquid they release."},{"step":4,"title":"Whisk the dressing","instruction":"Combine the olive oil, lemon juice, garlic, cumin, salt, and pepper."},{"step":5,"title":"Combine and rest","instruction":"Fold everything together with the herbs and leave at least 30 minutes before eating. The chickpeas absorb the dressing and the flavour improves considerably."}]'::JSONB, 'This is genuinely better on day two, which makes it excellent meal prep. Keeps 4 days; add the herbs fresh each day if you want them bright.', ARRAY['Add: Feta, olives, roasted peppers, or avocado.','Protein: Tinned tuna or shredded chicken folded through.','Serve: On its own, in pita, or over greens.']::TEXT[], ARRAY[]::TEXT[]),
('naan-pizza', 'Naan Pizza', 'Naan as the base, pre-crisped and topped lightly, done in fifteen minutes.', 'https://img.rocket.new/generatedImages/rocket_gen_img_1a8cb9be7-1768485641350.png', 'Quick naan pizza with tomato sauce, mozzarella, and fresh basil', 'Aisha Sharma', '@aishasharmaspice', '', '', '5 min', '10 min', '15 min', 5, 10, 15, 2, 'Easy', 'Fusion', 'Dinner', 'Main Course', ARRAY['Quick','Budget','Family','Vegetarian-Adaptable']::TEXT[], 4.7, 253, 2468, 548, 22, 62, 24, 4, '[{"amount":"2","unit":"","item":"naan breads"},{"amount":"0.5","unit":"cup","item":"passata or pizza sauce"},{"amount":"2","unit":"cups","item":"grated mozzarella"},{"amount":"2","unit":"tbsp","item":"olive oil"},{"amount":"1","unit":"tsp","item":"dried oregano"},{"amount":"0.5","unit":"cup","item":"cherry tomatoes, halved"},{"amount":"","unit":"","item":"Fresh basil, chilli flakes, and black pepper"}]'::JSONB, '[{"step":1,"title":"Pre-bake the naan","instruction":"Brush with oil and bake at 450°F (230°C) for 4 minutes before topping. Untopped pre-baking is what keeps the base from going soggy.","tip":"Four minutes. Skipping it gives a limp centre every time."},{"step":2,"title":"Go light on sauce","instruction":"Spread only a couple of tablespoons per naan. Naan is softer than pizza dough and cannot absorb much liquid."},{"step":3,"title":"Top sparingly","instruction":"Add the cheese, oregano, and tomatoes. Overloading is the most common mistake and it steams the base."},{"step":4,"title":"Bake hot","instruction":"Return for 8 minutes until the cheese bubbles and browns in patches."},{"step":5,"title":"Finish fresh","instruction":"Add basil, chilli flakes, pepper, and a drizzle of oil after it comes out of the oven."}]'::JSONB, 'A preheated tray or stone under the naan gives a noticeably crisper base. Pitta, flatbread, and tortillas all work — tortillas need only 5 minutes total.', ARRAY['Add: Pepperoni, leftover chicken, or roasted vegetables.','Indian-style: Tikka sauce, paneer, red onion, and cilantro.','Air fryer: 380°F for 6 minutes, one at a time.']::TEXT[], ARRAY['Gluten','Dairy']::TEXT[]),
('steak-salad', 'Steak Salad', 'Rested steak sliced thin over leaves with blue cheese and a mustard vinaigrette.', 'https://images.unsplash.com/photo-1614187860064-8c0442c793c5', 'Sliced steak salad with arugula, cherry tomatoes, and balsamic dressing', 'Jake Torres', '@jaketorrescooks', 'https://images.unsplash.com/photo-1572015837827-01671d41e102', 'Portrait of food creator Jake Torres', '15 min', '5 min', '20 min', 15, 5, 20, 4, 'Easy', 'American', 'Lunch', 'Salad', ARRAY['High Protein','Gluten-Free','Low Carb']::TEXT[], 4.9, 1011, 2526, 486, 38, 12, 32, 3, '[{"amount":"1.5","unit":"lb","item":"sirloin or flank steak"},{"amount":"8","unit":"cups","item":"mixed leaves and rocket"},{"amount":"1","unit":"cup","item":"cherry tomatoes, halved"},{"amount":"0.5","unit":"","item":"red onion, thinly sliced"},{"amount":"4","unit":"oz","item":"blue cheese, crumbled"},{"amount":"0.33","unit":"cup","item":"toasted walnuts"},{"amount":"4","unit":"tbsp","item":"olive oil"},{"amount":"2","unit":"tbsp","item":"red wine vinegar"},{"amount":"1","unit":"tbsp","item":"Dijon mustard"},{"amount":"1","unit":"tsp","item":"honey"},{"amount":"1","unit":"tbsp","item":"neutral oil"},{"amount":"","unit":"","item":"Salt and coarse black pepper"}]'::JSONB, '[{"step":1,"title":"Temper and dry the steak","instruction":"Take the steak out 40 minutes ahead and pat it completely dry. Season heavily just before cooking."},{"step":2,"title":"Sear hard","instruction":"Sear in the neutral oil over the highest heat, 3–4 minutes a side for medium-rare, until a dark crust forms."},{"step":3,"title":"Rest properly","instruction":"Rest for a full 10 minutes. Sliced too early, the juice runs out onto the board and the salad goes soggy.","tip":"Ten minutes of rest. This matters more in a salad than on a plate."},{"step":4,"title":"Make the vinaigrette","instruction":"Whisk the olive oil, vinegar, Dijon, honey, salt, and pepper until emulsified and thickened."},{"step":5,"title":"Slice thin, against the grain","instruction":"Identify the grain direction and slice across it as thinly as you can. Flank steak in particular is tough if cut with the grain."},{"step":6,"title":"Assemble at the last moment","instruction":"Toss the leaves, tomatoes, and onion with most of the dressing, top with steak, blue cheese, and walnuts, then spoon the rest over."}]'::JSONB, 'Any resting juice on the board should go straight into the dressing — it is the best-tasting liquid in the kitchen. Serve the steak just warm rather than hot, so it does not wilt the leaves.', ARRAY['Cheese: Feta or shaved parmesan if blue cheese is not for you.','Add: Roasted new potatoes or a soft-boiled egg to make it a fuller meal.','Leftover steak: Works perfectly, sliced cold.']::TEXT[], ARRAY['Dairy','Mustard']::TEXT[]),
('corn-salad', 'Corn Salad', 'Charred sweetcorn with tomato, feta, and lime — the salad that goes with everything grilled.', 'https://images.unsplash.com/photo-1719384966291-9eb1b5005f49', 'Mexican street corn salad with cotija cheese, lime, and chili powder', 'Carlos Mendez', '@carlosmendezcooks', '', '', '10 min', '—', '10 min', 10, 0, 10, 6, 'Easy', 'Mexican', 'Lunch', 'Salad', ARRAY['Vegetarian','Gluten-Free','Summer','BBQ']::TEXT[], 4.5, 770, 6928, 212, 6, 26, 11, 4, '[{"amount":"5","unit":"cups","item":"sweetcorn kernels (fresh or frozen)"},{"amount":"2","unit":"tbsp","item":"neutral oil"},{"amount":"1","unit":"cup","item":"cherry tomatoes, halved"},{"amount":"0.5","unit":"","item":"red onion, finely diced"},{"amount":"1","unit":"","item":"jalapeño, minced"},{"amount":"4","unit":"oz","item":"feta or cotija, crumbled"},{"amount":"0.5","unit":"cup","item":"chopped cilantro"},{"amount":"2","unit":"","item":"limes, juiced"},{"amount":"3","unit":"tbsp","item":"olive oil"},{"amount":"1","unit":"tsp","item":"chilli powder"},{"amount":"","unit":"","item":"Salt and black pepper"}]'::JSONB, '[{"step":1,"title":"Char the corn hard","instruction":"Cook the corn in the neutral oil in a very hot dry pan for 6–8 minutes, stirring rarely, until blackened in patches. It will pop and jump.","tip":"The char is the entire flavour of this salad. Take it further than feels comfortable."},{"step":2,"title":"Cool before mixing","instruction":"Spread the charred corn on a tray to cool for 10 minutes. Hot corn wilts the herbs and melts the cheese into a paste."},{"step":3,"title":"Soak the onion","instruction":"Cover the diced onion in cold water for 5 minutes to soften its raw bite, then drain well."},{"step":4,"title":"Mix the dressing","instruction":"Whisk the lime juice, olive oil, chilli powder, salt, and pepper."},{"step":5,"title":"Combine","instruction":"Fold everything together and rest 15 minutes before serving so the flavours settle."}]'::JSONB, 'Frozen corn works well and chars fine, but dry it thoroughly first or it will steam. Fresh corn cut from the cob in season is noticeably sweeter.', ARRAY['Vegan: Skip the cheese and add diced avocado.','Elote-style: Add a couple of tablespoons of mayonnaise for a creamier version.','Make-ahead: Keeps 3 days; add the herbs fresh.']::TEXT[], ARRAY['Dairy']::TEXT[]),
('fettuccine-alfredo', 'Fettuccine Alfredo', 'Butter, parmesan, and pasta water emulsified into a sauce. No cream in the original.', 'https://images.unsplash.com/photo-1727005217349-66276af3aa7d', 'Creamy fettuccine alfredo with parmesan cheese and fresh parsley', 'Marco Rossi', '@marcorossicucina', '', '', '5 min', '15 min', '20 min', 5, 15, 20, 4, 'Easy', 'Italian', 'Dinner', 'Main Course', ARRAY['Vegetarian','Quick','Comfort','Minimal Ingredients']::TEXT[], 4.2, 1117, 1601, 612, 22, 66, 30, 3, '[{"amount":"1","unit":"lb","item":"fettuccine"},{"amount":"8","unit":"tbsp","item":"unsalted butter, cubed and softened"},{"amount":"2","unit":"cups","item":"finely grated parmigiano reggiano"},{"amount":"","unit":"","item":"Salt for the water"},{"amount":"","unit":"","item":"Coarse black pepper"}]'::JSONB, '[{"step":1,"title":"Use less water","instruction":"Cook the pasta in a wide pan with just enough water to cover, so the water becomes very starchy. That starch is what emulsifies the sauce.","tip":"Starchy pasta water is doing the job cream usually does. Do not use a big stockpot."},{"step":2,"title":"Grate the parmesan finely","instruction":"Grate it as finely as possible and let it come to room temperature. Cold, coarse cheese seizes into strings."},{"step":3,"title":"Warm the serving bowl","instruction":"Warm a large bowl with some of the pasta water and tip it out. A cold bowl makes the butter set instantly."},{"step":4,"title":"Toss butter and pasta first","instruction":"Drain the pasta a minute early and toss it in the warm bowl with the butter and a ladle of pasta water until the butter melts and coats."},{"step":5,"title":"Add cheese off the heat, in stages","instruction":"Add the parmesan in three handfuls, tossing hard and adding pasta water as needed, until a glossy sauce forms.","tip":"Off the heat, in stages, tossing constantly. Dumping it all in at once gives you a stringy clump."},{"step":6,"title":"Serve immediately","instruction":"Finish with black pepper and serve at once — it stiffens as it cools."}]'::JSONB, 'The two failure modes are clumping (cheese too cold or added too fast) and greasiness (not enough starch or not tossed hard enough). If it splits, take it off the heat, add a splash of cool pasta water, and keep tossing.', ARRAY['Cream version: Add half a cup of cream with the butter for the American-style sauce — easier and more forgiving.','Add: Grilled chicken, shrimp, or peas.','Cheese: Real parmigiano reggiano, finely grated. Pre-grated will not emulsify.']::TEXT[], ARRAY['Gluten','Dairy']::TEXT[]),
('beef-tacos', 'Beef Tacos', 'Ground beef browned hard with a proper spice mix rather than a sachet, in charred corn tortillas.', 'https://img.rocket.new/generatedImages/rocket_gen_img_10219b7a4-1772055932983.png', 'Seasoned ground beef tacos with cheese, lettuce, and salsa', 'Rosa Gutierrez', '@rosagutierrezcocina', '', '', '10 min', '10 min', '20 min', 10, 10, 20, 4, 'Easy', 'Mexican', 'Dinner', 'Main Course', ARRAY['Quick','Family','Budget','Gluten-Free-Adaptable']::TEXT[], 4.9, 1690, 1881, 512, 30, 38, 26, 6, '[{"amount":"1.5","unit":"lb","item":"ground beef"},{"amount":"1","unit":"","item":"onion, finely diced"},{"amount":"3","unit":"cloves","item":"garlic, minced"},{"amount":"2","unit":"tsp","item":"chilli powder"},{"amount":"2","unit":"tsp","item":"ground cumin"},{"amount":"1","unit":"tsp","item":"smoked paprika"},{"amount":"1","unit":"tsp","item":"dried oregano"},{"amount":"0.5","unit":"tsp","item":"cayenne"},{"amount":"2","unit":"tbsp","item":"tomato paste"},{"amount":"0.5","unit":"cup","item":"beef stock"},{"amount":"12","unit":"","item":"corn tortillas"},{"amount":"","unit":"","item":"Lettuce, tomato, cheese, sour cream, and lime to serve"}]'::JSONB, '[{"step":1,"title":"Brown, do not stew","instruction":"Cook the beef in a hot dry pan without stirring for the first 3 minutes so it crusts, then break it up and continue until all the liquid has evaporated and it starts to fry.","tip":"Stirring immediately gives you grey, boiled mince. Let it crust first."},{"step":2,"title":"Add the onion after","instruction":"Add the onion once the beef has browned and cook 5 minutes, then the garlic for 30 seconds."},{"step":3,"title":"Bloom the spices in the fat","instruction":"Add all the dried spices and the tomato paste and cook 90 seconds in the rendered fat until fragrant and darkened.","tip":"Spices need fat and heat. Dumped into liquid they stay dusty and raw."},{"step":4,"title":"Add stock and reduce","instruction":"Pour in the stock and simmer 5 minutes until it is glossy and just barely wet — not soupy."},{"step":5,"title":"Char the tortillas","instruction":"Toast the tortillas directly over a flame or in a dry pan for 20 seconds a side until blistered and pliable."},{"step":6,"title":"Build","instruction":"Fill and top with lettuce, tomato, cheese, sour cream, and a squeeze of lime."}]'::JSONB, 'A home-made spice mix costs almost nothing and tastes far better than a sachet, which is mostly salt and cornstarch. The beef keeps 4 days and freezes for 3 months.', ARRAY['Vegetarian: Lentils or a mix of walnuts and mushrooms, browned the same way.','Double up: Thin corn tortillas are usually doubled, which is standard practice.','Heat: Cayenne carries it; adjust to taste.']::TEXT[], ARRAY['Dairy']::TEXT[]),
('mushroom-toast', 'Mushroom Toast', 'Mushrooms browned hard in butter with garlic and thyme, piled onto toast with a soft cheese base.', 'https://img.rocket.new/generatedImages/rocket_gen_img_1fc9b8697-1772468849033.png', 'Sautéed mushrooms on sourdough toast with thyme and parmesan', 'Sofia Romano', '@sofiaromanoeats', '', '', '5 min', '10 min', '15 min', 5, 10, 15, 2, 'Easy', 'French', 'Breakfast', 'Breakfast', ARRAY['Vegetarian','Quick','Brunch','Umami']::TEXT[], 4.9, 1514, 9231, 386, 13, 34, 22, 4, '[{"amount":"12","unit":"oz","item":"mixed mushrooms, torn"},{"amount":"4","unit":"slices","item":"sourdough bread"},{"amount":"3","unit":"tbsp","item":"butter"},{"amount":"1","unit":"tbsp","item":"olive oil"},{"amount":"3","unit":"cloves","item":"garlic, minced"},{"amount":"2","unit":"sprigs","item":"thyme"},{"amount":"2","unit":"tbsp","item":"crème fraîche"},{"amount":"1","unit":"tbsp","item":"lemon juice"},{"amount":"3","unit":"oz","item":"soft goat cheese or ricotta"},{"amount":"","unit":"","item":"Salt, pepper, and parsley"}]'::JSONB, '[{"step":1,"title":"Tear, do not slice","instruction":"Tear the mushrooms into rough pieces by hand. Ragged edges brown far better than clean-cut faces."},{"step":2,"title":"Dry pan first","instruction":"Put the mushrooms into a dry hot pan with no fat at all and cook 4 minutes until they release their water and it evaporates.","tip":"Adding fat first means the mushrooms boil in their own liquid. Dry pan first, always."},{"step":3,"title":"Now add the fat","instruction":"Once the pan is dry again, add the butter and oil and cook 4 minutes more until deeply browned at the edges."},{"step":4,"title":"Aromatics late","instruction":"Add the garlic and thyme for the final minute so they do not burn."},{"step":5,"title":"Finish the pan","instruction":"Off the heat, stir in the crème fraîche and lemon juice to make a light sauce, and season well."},{"step":6,"title":"Build","instruction":"Toast the sourdough, spread with goat cheese, pile the mushrooms on, and finish with parsley and cracked pepper."}]'::JSONB, 'Do not wash mushrooms under the tap — they absorb water and will never brown. Brush them clean with a damp cloth. A mix of varieties gives much more interesting texture than button mushrooms alone.', ARRAY['Vegan: Olive oil, a plant cream, and a cashew or almond ricotta.','Add: A poached egg on top, or a scatter of parmesan.','Upgrade: A splash of sherry or white wine before the crème fraîche.']::TEXT[], ARRAY['Gluten','Dairy']::TEXT[]),
('watermelon-salad', 'Watermelon Salad', 'Cold watermelon with cucumber, mint, and lime. The simplest possible summer salad.', 'https://images.unsplash.com/photo-1573409157844-6a56035363fc', 'Refreshing watermelon salad with feta, mint, and balsamic glaze', 'Leila Hassan', '@leilahassantable', '', '', '10 min', '—', '10 min', 10, 0, 10, 6, 'Easy', 'Mediterranean', 'Lunch', 'Salad', ARRAY['Vegan-Adaptable','No-Cook','Gluten-Free','Summer']::TEXT[], 4.2, 1025, 7208, 128, 2, 24, 4, 2, '[{"amount":"6","unit":"cups","item":"watermelon, cubed and well chilled"},{"amount":"1","unit":"","item":"cucumber, diced"},{"amount":"0.25","unit":"","item":"red onion, thinly sliced"},{"amount":"1","unit":"cup","item":"fresh mint leaves"},{"amount":"2","unit":"","item":"limes, juiced"},{"amount":"2","unit":"tbsp","item":"extra virgin olive oil"},{"amount":"1","unit":"tsp","item":"honey or agave"},{"amount":"","unit":"","item":"Flaky sea salt and black pepper"}]'::JSONB, '[{"step":1,"title":"Chill everything","instruction":"The watermelon and cucumber must be properly cold. Room-temperature melon tastes flat and watery."},{"step":2,"title":"Drain the melon","instruction":"Cube the watermelon and let it drain in a colander for 10 minutes. That juice would flood the plate otherwise — save it and drink it.","tip":"Ten minutes of draining is the difference between a salad and a soup."},{"step":3,"title":"Soften the onion","instruction":"Soak the sliced onion in cold water for 5 minutes to take the raw edge off, then drain and dry."},{"step":4,"title":"Dress lightly","instruction":"Whisk the lime juice, olive oil, and honey. Watermelon needs very little dressing."},{"step":5,"title":"Combine at the last second","instruction":"Toss gently with the mint, add flaky salt and black pepper, and serve immediately."}]'::JSONB, 'The salt is what makes this work — it draws out the melon''s sweetness and stops it tasting one-dimensional. Assemble within a couple of minutes of serving.', ARRAY['Add: Feta, olives, or toasted pistachios.','Herbs: Basil works as well as mint, or use both.','Spicy: A pinch of chilli flakes or Tajín over the top.']::TEXT[], ARRAY[]::TEXT[]),
('chicken-fried-rice', 'Chicken Fried Rice', 'Cold rice, velveted chicken, and egg fried hard in a very hot pan.', 'https://img.rocket.new/generatedImages/rocket_gen_img_14631f803-1772367083673.png', 'Wok-tossed chicken fried rice with vegetables and soy sauce', 'Lin Wei', '@linweiwok', '', '', '15 min', '10 min', '25 min', 15, 10, 25, 4, 'Easy', 'Chinese', 'Dinner', 'Main Course', ARRAY['Quick','High Protein','Family','Leftovers']::TEXT[], 4.6, 1057, 2690, 512, 30, 58, 16, 3, '[{"amount":"4","unit":"cups","item":"cooked rice, cold (day-old)"},{"amount":"1","unit":"lb","item":"chicken thigh, diced small"},{"amount":"1","unit":"tbsp","item":"cornstarch"},{"amount":"1","unit":"tbsp","item":"soy sauce for the chicken"},{"amount":"3","unit":"large","item":"eggs, beaten"},{"amount":"4","unit":"tbsp","item":"neutral oil"},{"amount":"4","unit":"","item":"scallions, whites and greens separated"},{"amount":"3","unit":"cloves","item":"garlic, minced"},{"amount":"1","unit":"cup","item":"frozen peas and carrots"},{"amount":"2","unit":"tbsp","item":"light soy sauce"},{"amount":"1","unit":"tsp","item":"dark soy sauce"},{"amount":"1","unit":"tsp","item":"toasted sesame oil"},{"amount":"0.5","unit":"tsp","item":"white pepper"}]'::JSONB, '[{"step":1,"title":"Velvet the chicken","instruction":"Toss the diced chicken with the cornstarch and a tablespoon of soy sauce and leave 15 minutes. This keeps it tender through the high heat."},{"step":2,"title":"Cold rice, broken up","instruction":"Use day-old refrigerated rice and break every clump apart with wet hands. Fresh rice turns to mush.","tip":"Cold, dry, separated rice. Nothing else works."},{"step":3,"title":"Cook the chicken and remove","instruction":"Fry the chicken in 2 tbsp oil over high heat for 4 minutes until golden and cooked through. Remove."},{"step":4,"title":"Scramble the egg and remove","instruction":"Scramble the egg in a little oil until just set, then set it aside with the chicken."},{"step":5,"title":"Fry the rice hard","instruction":"Add the remaining oil, then the scallion whites, garlic, and peas and carrots for a minute. Add the rice, press it against the pan, and toss for 4 minutes on maximum heat."},{"step":6,"title":"Combine and season","instruction":"Return the chicken and egg, add both soy sauces around the rim of the pan, then the sesame oil, white pepper, and scallion greens. Toss and serve."}]'::JSONB, 'Cooking the chicken and egg separately and returning them at the end keeps each one properly cooked — everything in at once gives you overcooked egg and undercooked chicken.', ARRAY['Vegetarian: Velveted tofu in place of the chicken.','Gluten-free: Tamari for both soy sauces.','Batch: Cook in two rounds if your pan is small.']::TEXT[], ARRAY['Egg','Soy','Sesame']::TEXT[]),
('bruschetta', 'Bruschetta', 'Grilled bread rubbed with raw garlic, topped with tomatoes that have been salted and drained.', 'https://images.unsplash.com/photo-1725464781841-2d6f9ac10fb2', 'Classic bruschetta with diced tomatoes, basil, and olive oil on toasted bread', 'Sofia Romano', '@sofiaromanoeats', '', '', '15 min', '—', '15 min', 15, 0, 15, 6, 'Easy', 'Italian', 'Snack', 'Appetizer', ARRAY['Vegan-Adaptable','Summer','Party Food','Quick']::TEXT[], 4.5, 1519, 9189, 186, 4, 24, 9, 2, '[{"amount":"1","unit":"","item":"ciabatta or rustic loaf, thickly sliced"},{"amount":"6","unit":"","item":"ripe tomatoes, diced"},{"amount":"3","unit":"cloves","item":"garlic (1 minced, 2 halved)"},{"amount":"1","unit":"cup","item":"fresh basil, torn"},{"amount":"5","unit":"tbsp","item":"extra virgin olive oil"},{"amount":"1","unit":"tbsp","item":"balsamic vinegar"},{"amount":"","unit":"","item":"Flaky salt and black pepper"}]'::JSONB, '[{"step":1,"title":"Salt and drain the tomatoes","instruction":"Dice the tomatoes, toss with a teaspoon of salt, and leave in a sieve for 20 minutes. A surprising amount of water drains out.","tip":"This is the whole recipe. Undrained tomatoes turn the bread to mush in seconds."},{"step":2,"title":"Grill the bread properly","instruction":"Grill or griddle the slices until charred at the edges and firmly crisp. Soft bread cannot hold the topping."},{"step":3,"title":"Rub with raw garlic","instruction":"Rub a halved garlic clove firmly across the hot, rough surface of each slice. The bread acts as a grater and takes up exactly the right amount.","tip":"This is the traditional method and it beats mixing garlic into the topping."},{"step":4,"title":"Dress the tomatoes now","instruction":"Mix the drained tomatoes with the minced garlic, basil, olive oil, balsamic, and pepper. Do this at the last minute."},{"step":5,"title":"Top and serve immediately","instruction":"Spoon onto the bread, finish with flaky salt and more oil, and serve within a couple of minutes."}]'::JSONB, 'Serve the topping and bread separately if guests will be grazing — assembled bruschetta is at its best for about five minutes. This lives or dies on tomato quality; out of season use good cherry tomatoes.', ARRAY['Variations: White bean and rosemary, or roasted pepper and anchovy.','Vegan: Already is. Add capers or olives for more depth.','Make-ahead: Grill the bread up to 2 hours early; dress the tomatoes at the last minute.']::TEXT[], ARRAY['Gluten']::TEXT[]),
('egg-drop-soup', 'Egg Drop Soup', 'A clear seasoned broth with egg poured in a thin stream to form silky ribbons.', 'https://img.rocket.new/generatedImages/rocket_gen_img_1258cc50e-1772472349165.png', 'Silky egg drop soup with green onions and sesame oil', 'Lin Wei', '@linweiwok', '', '', '5 min', '10 min', '15 min', 5, 10, 15, 4, 'Easy', 'Chinese', 'Lunch', 'Soup', ARRAY['Quick','Budget','Light','Gluten-Free-Adaptable']::TEXT[], 4.5, 1760, 7340, 112, 8, 6, 6, 0, '[{"amount":"6","unit":"cups","item":"chicken stock"},{"amount":"3","unit":"large","item":"eggs, well beaten"},{"amount":"2","unit":"tbsp","item":"cornstarch"},{"amount":"3","unit":"tbsp","item":"cold water"},{"amount":"1","unit":"tsp","item":"grated ginger"},{"amount":"1","unit":"tbsp","item":"soy sauce"},{"amount":"1","unit":"tsp","item":"toasted sesame oil"},{"amount":"0.5","unit":"tsp","item":"white pepper"},{"amount":"0.25","unit":"tsp","item":"turmeric (for colour)"},{"amount":"3","unit":"","item":"scallions, thinly sliced"},{"amount":"","unit":"","item":"Salt"}]'::JSONB, '[{"step":1,"title":"Thicken the broth first","instruction":"Bring the stock to a simmer with the ginger, soy sauce, white pepper, and turmeric. Mix the cornstarch with the cold water and stir it in, simmering 2 minutes until slightly thickened.","tip":"The broth must be thickened before the egg goes in — that is what suspends the ribbons instead of letting them sink."},{"step":2,"title":"Beat the eggs thoroughly","instruction":"Whisk the eggs until completely uniform. Streaks of white give patchy, uneven ribbons."},{"step":3,"title":"Reduce to the barest simmer","instruction":"Lower the heat until the surface is barely moving. A rolling boil shreds the egg into cloudy fragments."},{"step":4,"title":"Pour thin and slow, while stirring","instruction":"Stir the broth in one direction with a chopstick and pour the egg in a very thin stream from a height. It sets instantly into fine ribbons.","tip":"Thin stream, from height, into moving broth. That combination is what makes the ribbons."},{"step":5,"title":"Stop stirring and finish","instruction":"Turn the heat off immediately, add the sesame oil and scallions, and season with salt."}]'::JSONB, 'The turmeric is purely cosmetic and gives the golden colour of restaurant versions. The whole thing takes ten minutes and is entirely dependent on good stock.', ARRAY['Gluten-free: Tamari in place of soy sauce.','Add: Sweetcorn, tofu, or shredded chicken.','Vegetarian: A good mushroom or vegetable stock.']::TEXT[], ARRAY['Egg','Soy','Sesame']::TEXT[])
