INSERT INTO public.recipes (slug, title, description, image, image_alt, creator_name, creator_handle, creator_image, creator_alt, prep_time, cook_time, total_time, prep_minutes, cook_minutes, total_minutes, servings, difficulty, cuisine, meal_type, category, tags, rating, reviews, cooks, calories, protein, carbs, fat, fiber, ingredients, steps, notes, tips, allergens) VALUES
('prawn-stir-fry', 'Prawn Stir Fry', 'Prawns seared 90 seconds a side with garlic, chilli, and greens. Fifteen minutes start to finish.', 'https://img.rocket.new/generatedImages/rocket_gen_img_114d8b130-1772646989517.png', 'Quick prawn stir fry with garlic, ginger, and vegetables', 'Maria Chen', '@mariachencooks', 'https://images.unsplash.com/photo-1677229888051-211da3f34219', 'Portrait of food creator Maria Chen', '10 min', '5 min', '15 min', 10, 5, 15, 4, 'Easy', 'Chinese', 'Dinner', 'Main Course', ARRAY['Seafood','Quick','High Protein','Low Carb']::TEXT[], 4.4, 1310, 6092, 286, 32, 12, 13, 3, '[{"amount":"1.5","unit":"lb","item":"large prawns, peeled and deveined"},{"amount":"3","unit":"tbsp","item":"neutral oil"},{"amount":"5","unit":"cloves","item":"garlic, sliced"},{"amount":"1","unit":"inch","item":"ginger, julienned"},{"amount":"2","unit":"","item":"red chillies, sliced"},{"amount":"6","unit":"oz","item":"mangetout"},{"amount":"1","unit":"","item":"red pepper, sliced"},{"amount":"3","unit":"tbsp","item":"soy sauce"},{"amount":"1","unit":"tbsp","item":"oyster sauce"},{"amount":"1","unit":"tbsp","item":"rice wine"},{"amount":"1","unit":"tsp","item":"toasted sesame oil"},{"amount":"1","unit":"tsp","item":"cornstarch"},{"amount":"3","unit":"tbsp","item":"water"},{"amount":"","unit":"","item":"Scallions"}]'::JSONB, '[{"step":1,"title":"Dry the prawns thoroughly","instruction":"Pat the prawns completely dry with kitchen paper. Wet prawns steam and turn grey instead of searing.","tip":"Surface water is the enemy. Dry them properly."},{"step":2,"title":"Mix the sauce first","instruction":"Whisk the soy sauce, oyster sauce, rice wine, sesame oil, cornstarch, and water and set it beside the hob."},{"step":3,"title":"Sear the prawns and remove","instruction":"Cook the prawns in 2 tbsp oil over the highest heat for 90 seconds a side until just pink. Remove immediately — they finish later.","tip":"Prawns overcook in seconds. Pull them the moment they curl into a loose C."},{"step":4,"title":"Cook the vegetables","instruction":"Add the remaining oil, then the pepper for 2 minutes and the mangetout for 1 minute, keeping everything moving."},{"step":5,"title":"Aromatics late","instruction":"Add the garlic, ginger, and chilli for 30 seconds only."},{"step":6,"title":"Combine and sauce","instruction":"Return the prawns, pour the sauce around the rim of the pan, and toss for 45 seconds until it thickens and coats. Finish with scallions."}]'::JSONB, 'A prawn curled into a tight O is overcooked; a loose C is right. Frozen prawns are fine — thaw fully and dry very thoroughly.', ARRAY['Gluten-free: Tamari and a GF oyster sauce.','Add: Broccoli, baby corn, or water chestnuts.','Serve: Steamed rice or noodles.']::TEXT[], ARRAY['Shellfish','Soy','Sesame']::TEXT[]),
('cheese-omelette', 'Cheese Omelette', 'A soft omelette with cheese added off the heat so it melts rather than fries.', 'https://images.unsplash.com/photo-1609090817330-8dd9b75af6af', 'Fluffy cheese omelette with cheddar and fresh chives', 'Marco Rossi', '@marcorossicucina', '', '', '3 min', '7 min', '10 min', 3, 7, 10, 1, 'Easy', 'French', 'Breakfast', 'Breakfast', ARRAY['Quick','Vegetarian','Gluten-Free','High Protein']::TEXT[], 4.2, 1464, 9371, 412, 26, 2, 34, 0, '[{"amount":"3","unit":"large","item":"eggs"},{"amount":"2","unit":"tbsp","item":"butter"},{"amount":"0.5","unit":"cup","item":"grated gruyere or sharp cheddar"},{"amount":"1","unit":"tbsp","item":"chopped chives"},{"amount":"","unit":"","item":"Salt and white pepper"}]'::JSONB, '[{"step":1,"title":"Beat until uniform","instruction":"Whisk the eggs for 30 seconds until there are no streaks of white left."},{"step":2,"title":"Grate the cheese finely","instruction":"Fine grating melts fast in the residual heat. Slices or chunks need more heat than the omelette can take before it overcooks."},{"step":3,"title":"Low heat, foaming butter","instruction":"Melt the butter over low heat until it foams without colouring, then pour in the eggs."},{"step":4,"title":"Agitate then settle","instruction":"Stir constantly while shaking the pan for 40 seconds to form small curds, then stop and let it set for 15 seconds."},{"step":5,"title":"Cheese off the heat","instruction":"Take the pan off the heat, scatter the cheese over one half, and let the residual heat melt it for 30 seconds.","tip":"Adding cheese over the flame makes it oily and split. Off the heat, every time."},{"step":6,"title":"Fold and serve","instruction":"Fold over, slide onto a plate, and finish with chives and pepper."}]'::JSONB, 'The omelette should be pale yellow with no browning. If it browns, the heat is too high. Gruyere melts more smoothly than cheddar, which can turn greasy.', ARRAY['Add: Ham, mushrooms, or spinach — cook them first and add with the cheese.','Dairy-free: Olive oil and a good plant cheese, given a little longer to melt.','Pan: A well-seasoned 8-inch non-stick pan makes this far easier.']::TEXT[], ARRAY['Egg','Dairy']::TEXT[]),
('avocado-salad', 'Avocado Salad', 'Avocado, tomato, cucumber, and red onion in a lime dressing. Ten minutes, no cooking.', 'https://images.unsplash.com/photo-1563213356-6b6f69e01a40', 'Fresh avocado salad with cherry tomatoes, red onion, and lime dressing', 'Priya Nair', '@priyanairkitchen', '', '', '10 min', '—', '10 min', 10, 0, 10, 4, 'Easy', 'Mexican', 'Lunch', 'Salad', ARRAY['Vegan','Gluten-Free','No-Cook','Healthy']::TEXT[], 4.9, 1850, 5625, 242, 4, 16, 20, 8, '[{"amount":"3","unit":"","item":"ripe avocados, cubed"},{"amount":"2","unit":"","item":"tomatoes, diced"},{"amount":"1","unit":"","item":"cucumber, diced"},{"amount":"0.5","unit":"","item":"red onion, finely diced"},{"amount":"0.5","unit":"cup","item":"chopped cilantro"},{"amount":"2","unit":"","item":"limes, juiced"},{"amount":"3","unit":"tbsp","item":"extra virgin olive oil"},{"amount":"1","unit":"","item":"jalapeño, minced"},{"amount":"","unit":"","item":"Flaky salt and black pepper"}]'::JSONB, '[{"step":1,"title":"Choose the right avocados","instruction":"They should yield to gentle pressure at the stem end. Under-ripe avocado is grassy and firm; over-ripe turns to mush the moment you fold it."},{"step":2,"title":"Dress the avocado first","instruction":"Cube the avocado and toss it with the lime juice immediately. This both seasons it and slows the browning.","tip":"Lime on the avocado before anything else touches it."},{"step":3,"title":"Drain the wet vegetables","instruction":"Salt the diced tomato and cucumber and leave 10 minutes, then drain off the liquid."},{"step":4,"title":"Soften the onion","instruction":"Soak the diced onion in cold water for 5 minutes, then drain, to take the harsh edge off."},{"step":5,"title":"Fold, do not toss","instruction":"Combine everything gently with a spatula, folding rather than stirring, so the avocado stays in cubes."}]'::JSONB, 'This is best within an hour. The lime slows browning but does not stop it, and the avocado softens as it sits. Make it just before serving.', ARRAY['Add: Black beans and sweetcorn for a fuller salad.','Protein: Grilled shrimp or shredded chicken.','Serve: On its own, with tortilla chips, or alongside anything grilled.']::TEXT[], ARRAY[]::TEXT[]),
('soba-noodle-salad', 'Soba Noodle Salad', 'Cold buckwheat noodles rinsed properly, in a sesame-ginger dressing with crunchy vegetables.', 'https://images.unsplash.com/photo-1626066014976-cd53fe450b3e', 'Cold soba noodle salad with sesame dressing, cucumber, and edamame', 'Yuki Tanaka', '@yukitanakaumami', '', '', '15 min', '5 min', '20 min', 15, 5, 20, 4, 'Easy', 'Japanese', 'Lunch', 'Salad', ARRAY['Vegan-Adaptable','Cold Dish','Meal Prep','Healthy']::TEXT[], 4.3, 1494, 1839, 412, 14, 62, 13, 5, '[{"amount":"10","unit":"oz","item":"dried soba noodles"},{"amount":"3","unit":"tbsp","item":"soy sauce"},{"amount":"2","unit":"tbsp","item":"rice vinegar"},{"amount":"1","unit":"tbsp","item":"toasted sesame oil"},{"amount":"1","unit":"tbsp","item":"maple syrup"},{"amount":"1","unit":"inch","item":"ginger, grated"},{"amount":"1","unit":"clove","item":"garlic, grated"},{"amount":"1","unit":"","item":"cucumber, julienned"},{"amount":"2","unit":"","item":"carrots, julienned"},{"amount":"4","unit":"","item":"scallions, sliced"},{"amount":"1","unit":"cup","item":"edamame"},{"amount":"2","unit":"tbsp","item":"toasted sesame seeds"},{"amount":"","unit":"","item":"Cilantro"}]'::JSONB, '[{"step":1,"title":"Do not salt the water","instruction":"Soba is already salted in production. Salting the water makes the finished noodles unpleasantly salty.","tip":"This is the one soba-specific rule people miss."},{"step":2,"title":"Cook briefly","instruction":"Boil the soba for the packet time, usually 4–5 minutes. They go from perfect to mushy quickly."},{"step":3,"title":"Rinse under cold water","instruction":"Rinse thoroughly under cold running water, rubbing the noodles with your hands, until the water runs clear and the noodles feel cool and slippery rather than sticky.","tip":"Rinsing removes the surface starch. Skip it and you get a solid clump."},{"step":4,"title":"Mix the dressing","instruction":"Whisk the soy sauce, rice vinegar, sesame oil, maple syrup, ginger, and garlic together."},{"step":5,"title":"Toss and rest","instruction":"Toss the drained noodles with the dressing and vegetables, then rest 15 minutes for the flavours to take."},{"step":6,"title":"Finish","instruction":"Top with sesame seeds and cilantro just before serving."}]'::JSONB, 'Keeps 3 days refrigerated, though the noodles absorb dressing as they sit — hold back a few tablespoons to loosen them before serving. Check the packet if you need it gluten-free; many soba are a wheat and buckwheat blend.', ARRAY['Add protein: Crisped tofu, edamame, or poached chicken.','Gluten-free: Look for 100% buckwheat soba.','Warm version: Serve in hot dashi as a noodle soup instead.']::TEXT[], ARRAY['Gluten','Soy','Sesame']::TEXT[]),
('loaded-baked-potato', 'Loaded Baked Potato', 'A potato baked until the skin crackles, split and fluffed, then loaded with cheese, bacon, and sour cream.', 'https://images.unsplash.com/photo-1729450411363-ba702747e240', 'Loaded baked potato with sour cream, cheese, bacon, and chives', 'Jake Torres', '@jaketorrescooks', 'https://images.unsplash.com/photo-1572015837827-01671d41e102', 'Portrait of food creator Jake Torres', '5 min', '10 min', '15 min', 5, 10, 15, 4, 'Easy', 'American', 'Dinner', 'Main Course', ARRAY['Comfort','Budget','Family','Gluten-Free']::TEXT[], 4.9, 1518, 1260, 548, 22, 52, 28, 6, '[{"amount":"4","unit":"large","item":"russet potatoes"},{"amount":"2","unit":"tbsp","item":"neutral oil"},{"amount":"1","unit":"tbsp","item":"coarse salt"},{"amount":"1.5","unit":"cups","item":"grated sharp cheddar"},{"amount":"6","unit":"slices","item":"bacon, cooked and crumbled"},{"amount":"0.5","unit":"cup","item":"sour cream"},{"amount":"4","unit":"tbsp","item":"butter"},{"amount":"4","unit":"","item":"scallions, sliced"},{"amount":"","unit":"","item":"Black pepper"}]'::JSONB, '[{"step":1,"title":"Prick and dry the skin","instruction":"Scrub the potatoes, prick them all over with a fork, and dry them completely."},{"step":2,"title":"Oil and salt the skin","instruction":"Rub with oil and roll in coarse salt. This is what makes the skin crisp and seasoned rather than leathery.","tip":"The salted skin is the best part of a baked potato. Do not wrap it in foil."},{"step":3,"title":"Bake directly on the rack","instruction":"Bake at 425°F (220°C) directly on the oven rack for 55–65 minutes. Foil steams the skin soft; the bare rack lets it crisp all round."},{"step":4,"title":"Check with a skewer","instruction":"It is done when a skewer slides through with no resistance and the skin is visibly crisp and slightly wrinkled."},{"step":5,"title":"Split and fluff immediately","instruction":"Cut a cross in the top and squeeze the ends to push it open, then fluff the inside with a fork. Trapped steam makes the flesh dense if you wait.","tip":"Open it the moment it comes out. Steam has to escape."},{"step":6,"title":"Load","instruction":"Add butter first so it melts in, then cheese, bacon, sour cream, scallions, and plenty of pepper."}]'::JSONB, 'Russets are essential — their high starch content is what gives a fluffy interior. Waxy potatoes stay dense and gluey no matter how long you bake them.', ARRAY['Vegetarian: Skip the bacon; add caramelised onion or chilli beans.','Faster: Microwave 8 minutes, then finish in a 425°F oven for 20 minutes for crisp skin.','Toppings: Chilli, broccoli and cheese, or tuna and sweetcorn.']::TEXT[], ARRAY['Dairy']::TEXT[]),
('tomato-basil-soup', 'Tomato Basil Soup', 'Tinned tomatoes roasted with garlic, blended smooth with basil and a little cream.', 'https://images.unsplash.com/photo-1629978448078-c94a0ab6500f', 'Creamy tomato basil soup with grilled cheese croutons', 'Emma Walsh', '@emmawalshbakes', '', '', '10 min', '15 min', '25 min', 10, 15, 25, 4, 'Easy', 'Italian', 'Lunch', 'Soup', ARRAY['Vegetarian','Comfort','Gluten-Free','Freezer-Friendly']::TEXT[], 4.7, 701, 6295, 262, 6, 26, 15, 4, '[{"amount":"28","unit":"oz","item":"tinned whole tomatoes, drained"},{"amount":"6","unit":"cloves","item":"garlic, unpeeled"},{"amount":"1","unit":"","item":"onion, quartered"},{"amount":"4","unit":"tbsp","item":"olive oil"},{"amount":"2","unit":"cups","item":"vegetable stock"},{"amount":"1","unit":"tsp","item":"sugar"},{"amount":"1","unit":"cup","item":"fresh basil"},{"amount":"0.33","unit":"cup","item":"heavy cream"},{"amount":"","unit":"","item":"Salt and black pepper"},{"amount":"","unit":"","item":"Parmesan to serve"}]'::JSONB, '[{"step":1,"title":"Roast the tomatoes and aromatics","instruction":"Spread the drained tomatoes, garlic cloves, and onion on a tray with the oil, sugar, and salt. Roast at 425°F (220°C) for 30 minutes until caramelised and blackening at the edges.","tip":"Roasting is what makes this taste of tomato rather than tin. It is worth the extra half hour."},{"step":2,"title":"Squeeze out the garlic","instruction":"Squeeze the roasted garlic from its skins — it will be sweet and soft rather than sharp."},{"step":3,"title":"Simmer briefly","instruction":"Tip everything into a pot with the stock and simmer 10 minutes."},{"step":4,"title":"Blend with the basil","instruction":"Add most of the basil and blend a full 2 minutes until completely silky. Blending the basil in rather than adding it at the end gives a deeper, greener flavour."},{"step":5,"title":"Finish with cream","instruction":"Stir in the cream off the heat, season, and serve with the remaining basil torn over and parmesan grated on top."}]'::JSONB, 'Tinned whole tomatoes beat fresh for most of the year since they are picked ripe. If the soup tastes sharp, a pinch more sugar fixes it faster than more cream. Freezes for 3 months before the cream goes in.', ARRAY['Vegan: Coconut or cashew cream, and skip the parmesan.','Serve: Grilled cheese, cut into soldiers.','Texture: Pass through a sieve after blending for a truly velvety soup.']::TEXT[], ARRAY['Dairy']::TEXT[]),
('miso-glazed-salmon', 'Miso Glazed Salmon', 'Salmon marinated in sweet white miso then grilled hard so the glaze caramelises. A simplified take on saikyo yaki.', 'https://img.rocket.new/generatedImages/rocket_gen_img_185162b1d-1772289647722.png', 'Golden miso-glazed salmon fillet on a dark plate with sesame seeds and green onions, Japanese restaurant style plating', 'Yuki Tanaka', '@yukitanakaumami', '', '', '10 min', '15 min', '25 min', 10, 15, 25, 4, 'Easy', 'Japanese', 'Dinner', 'Main Course', ARRAY['Seafood','Umami','Gluten-Free-Adaptable','Healthy']::TEXT[], 4.6, 1545, 6486, 412, 38, 12, 23, 0, '[{"amount":"4","unit":"fillets","item":"salmon, skin on (6 oz each)"},{"amount":"4","unit":"tbsp","item":"white miso paste"},{"amount":"3","unit":"tbsp","item":"mirin"},{"amount":"2","unit":"tbsp","item":"sake"},{"amount":"2","unit":"tbsp","item":"brown sugar"},{"amount":"1","unit":"tbsp","item":"soy sauce"},{"amount":"1","unit":"tsp","item":"grated ginger"},{"amount":"1","unit":"tsp","item":"toasted sesame oil"},{"amount":"2","unit":"","item":"scallions, sliced"},{"amount":"1","unit":"tbsp","item":"toasted sesame seeds"},{"amount":"","unit":"","item":"Steamed rice and greens to serve"}]'::JSONB, '[{"step":1,"title":"Make the marinade","instruction":"Whisk the miso, mirin, sake, sugar, soy sauce, ginger, and sesame oil into a smooth, thick paste. White (shiro) miso is mild and sweet — red miso is far too strong here."},{"step":2,"title":"Marinate at least 4 hours","instruction":"Pat the salmon dry, coat it all over, and refrigerate 4 hours or overnight. The miso both seasons and firms the flesh slightly, which is exactly what you want.","tip":"Overnight is genuinely better. The marinade needs time to penetrate."},{"step":3,"title":"Wipe off the excess","instruction":"Scrape most of the marinade off before cooking, leaving only a thin film. Miso is full of sugar and a thick layer will burn black long before the fish is done.","tip":"This is the step that separates a lacquered glaze from a burnt crust."},{"step":4,"title":"Grill high and close","instruction":"Place skin-side down on a lined tray and grill 6 inches from the element for 8–10 minutes, until the surface is deeply caramelised and blistered in dark patches."},{"step":5,"title":"Check and rest","instruction":"The salmon is ready at about 125°F internal for a moist medium. Rest 3 minutes, then top with scallions and sesame seeds."}]'::JSONB, 'The classic saikyo yaki marinates for two or three days, and if you have the patience it is remarkable. Watch the grill closely in the last two minutes — the sugar goes from bronze to burnt very quickly.', ARRAY['Gluten-free: Tamari in place of soy sauce, and check the miso for barley.','Pan version: Sear 4 minutes skin-side down, then finish under the grill for 3 minutes.','Other fish: Black cod is the traditional choice and is superb; sea bass also works.']::TEXT[], ARRAY['Fish','Soy','Sesame']::TEXT[]),
('pasta-carbonara', 'Pasta Carbonara', 'Eggs, pecorino, and guanciale — no cream. The sauce is a custard made off the heat with pasta water.', 'https://images.unsplash.com/photo-1663721605989-3bdd2c994190', 'Creamy spaghetti carbonara with pancetta, black pepper, and parmesan cheese, twirled on a fork, Italian kitchen', 'Sofia Romano', '@sofiaromanoeats', '', '', '10 min', '10 min', '20 min', 10, 10, 20, 4, 'Medium', 'Italian', 'Dinner', 'Main Course', ARRAY['Classic','Quick','Minimal Ingredients']::TEXT[], 4.4, 253, 6862, 648, 29, 68, 28, 3, '[{"amount":"1","unit":"lb","item":"spaghetti"},{"amount":"7","unit":"oz","item":"guanciale, cut into batons"},{"amount":"4","unit":"large","item":"egg yolks"},{"amount":"1","unit":"whole","item":"egg"},{"amount":"1.5","unit":"cups","item":"finely grated pecorino romano"},{"amount":"1","unit":"tbsp","item":"whole black peppercorns, coarsely crushed"},{"amount":"","unit":"","item":"Salt for the pasta water"}]'::JSONB, '[{"step":1,"title":"Render the guanciale from cold","instruction":"Put the guanciale in a cold pan and bring it up to medium heat. Starting cold renders the fat slowly and leaves the meat crisp rather than tough. Take the pan off the heat once golden.","tip":"That rendered fat is the only fat in the dish. There is no oil and no butter."},{"step":2,"title":"Toast the pepper","instruction":"Crush the peppercorns coarsely and toast them in the guanciale fat for 30 seconds."},{"step":3,"title":"Make the egg and cheese base","instruction":"Whisk the yolks, whole egg, and pecorino together into a thick paste. Loosen it with a couple of tablespoons of warm — not boiling — pasta water.","tip":"Boiling water at this stage scrambles the eggs. Let it stand 30 seconds first."},{"step":4,"title":"Cook the pasta in less water","instruction":"Boil the spaghetti in just enough water to cover, so the water is very starchy. Reserve two cups before draining."},{"step":5,"title":"Combine completely off the heat","instruction":"Take the pan fully off the hob. Add the drained pasta to the guanciale, toss, wait 30 seconds for it to cool slightly, then add the egg mixture and toss hard and continuously.","tip":"Off the heat, always. Direct heat turns carbonara into pasta with scrambled egg in about three seconds."},{"step":6,"title":"Loosen and serve","instruction":"Add pasta water a splash at a time, tossing, until the sauce turns glossy and coats every strand. Serve immediately with more pecorino and pepper."}]'::JSONB, 'If it does scramble, there is no recovery — start the sauce again with fresh yolks. The safest method is to toss in a warm bowl rather than the pan. Guanciale is worth seeking out; pancetta is the acceptable substitute, bacon is a different dish.', ARRAY['No guanciale: Pancetta is the closest. Avoid smoked bacon, which overwhelms the eggs.','Cheese: Pecorino romano is traditional; half parmesan makes it milder.','Do not scale up: Carbonara for eight is much harder than for four. Cook two batches.']::TEXT[], ARRAY['Gluten','Dairy','Egg']::TEXT[]),
('korean-fried-chicken', 'Korean Fried Chicken', 'Double-fried for a crust that stays crisp under a sticky gochujang glaze.', 'https://img.rocket.new/generatedImages/rocket_gen_img_123eb88d3-1783610009334.png', 'Crispy Korean fried chicken glazed with sweet gochujang sauce, sesame seeds, served in a red basket with pickled radish', 'Min-Jun Oh', '@minjunohkitchen', '', '', '20 min', '20 min', '40 min', 20, 20, 40, 4, 'Medium', 'Korean', 'Dinner', 'Main Course', ARRAY['Fried','Spicy','Party Food','Crowd Pleaser']::TEXT[], 4.3, 660, 8571, 712, 42, 52, 36, 2, '[{"amount":"2.5","unit":"lb","item":"chicken wings or boneless thighs"},{"amount":"1","unit":"cup","item":"cornstarch"},{"amount":"0.25","unit":"cup","item":"all-purpose flour"},{"amount":"1","unit":"tsp","item":"salt"},{"amount":"1","unit":"tsp","item":"black pepper"},{"amount":"1","unit":"tsp","item":"garlic powder"},{"amount":"","unit":"","item":"Neutral oil for frying"},{"amount":"3","unit":"tbsp","item":"gochujang"},{"amount":"3","unit":"tbsp","item":"honey"},{"amount":"2","unit":"tbsp","item":"soy sauce"},{"amount":"2","unit":"tbsp","item":"rice vinegar"},{"amount":"4","unit":"cloves","item":"garlic, minced"},{"amount":"1","unit":"tbsp","item":"toasted sesame oil"},{"amount":"1","unit":"tbsp","item":"toasted sesame seeds"},{"amount":"","unit":"","item":"Scallions and pickled radish to serve"}]'::JSONB, '[{"step":1,"title":"Dry the chicken thoroughly","instruction":"Pat every piece completely dry. Any surface moisture turns to steam and softens the coating from the inside."},{"step":2,"title":"Use mostly cornstarch","instruction":"Combine the cornstarch, flour, salt, pepper, and garlic powder. A cornstarch-heavy coating is what gives the characteristic thin, glassy crust rather than a thick craggy one.","tip":"This is not the same as American fried chicken. Cornstarch, not flour, does the work."},{"step":3,"title":"First fry at moderate heat","instruction":"Fry in batches at 325°F (165°C) for 8 minutes, until pale golden and cooked through. Rest on a rack for 10 minutes."},{"step":4,"title":"Second fry hot","instruction":"Raise the oil to 375°F (190°C) and fry each batch again for 3 minutes until deep golden and audibly crisp.","tip":"The double fry is the entire technique. The first cooks it, the second drives out remaining moisture and sets the crust."},{"step":5,"title":"Make the glaze","instruction":"Simmer the gochujang, honey, soy sauce, rice vinegar, garlic, and sesame oil in a wide pan for 3 minutes until slightly thickened and glossy."},{"step":6,"title":"Toss and serve immediately","instruction":"Take the glaze off the heat, add the chicken, and toss to coat. Finish with sesame seeds and scallions and serve at once with pickled radish."}]'::JSONB, 'Resting between the two fries is essential — it lets the interior steam escape so the second fry can crisp the surface properly. Sauced chicken softens within about ten minutes, so glaze it as it goes to the table. The pickled radish is not a garnish; the acid cuts the richness.', ARRAY['Soy garlic version: Skip the gochujang and double the soy sauce, garlic, and honey.','Air fryer: 400°F for 20 minutes, shaking twice. Less crisp but far less oil.','Make-ahead: Do the first fry up to 4 hours early, then do the second fry to order.']::TEXT[], ARRAY['Gluten','Soy','Sesame']::TEXT[])
